/* AIF-C01 question bank — generated by scripts/build.py, do not edit */
window.AIF_QUESTIONS=[{"id":1,"type":"single","answer":["B"],"topic":"responsible","stem":{"en":"A company makes forecasts each quarter to decide how to optimize operations to meet expected demand.\nThe company uses ML models to make these forecasts.\nAn AI practitioner is writing a report about the trained ML models to provide transparency and explainability\nto company stakeholders.\nWhat should the AI practitioner include in the report to meet the transparency and explainability\nrequirements?","zh":"某公司每季度做一次预测，用来决定如何优化运营以满足预期需求。\n该公司使用机器学习模型来做这些预测。\n一位 AI 从业者正在撰写一份关于已训练 ML 模型的报告，以便向公司利益相关者提供透明度和可解释性。\n为满足透明度和可解释性要求，该 AI 从业者应在报告中包含什么？"},"options":[{"key":"A","en":"Code for model training","zh":"模型训练的代码"},{"key":"B","en":"Partial dependence plots (PDPs)","zh":"部分依赖图（PDP）"},{"key":"C","en":"Sample data for training","zh":"用于训练的样本数据"},{"key":"D","en":"Model convergence tables","zh":"模型收敛表"}],"explanation":{"en":"Partial Dependence Plots (PDPs) are a powerful tool for understanding and explaining how the features\nin a machine learning model impact predictions. They are often used to meet transparency and\nexplainability requirements for stakeholders. Let's go over why this is the correct choice, along with why\nthe other options are less suitable:\nPartial Dependence Plots (PDPs)\nPurpose: PDPs show the relationship between a feature (or multiple features) and the model's predicted\noutput, which helps to explain the effect of each feature on the model’s predictions.\nExplainability: By visualizing how each feature influences the prediction, stakeholders can better\nunderstand how the model works and why it makes certain predictions. This level of interpretability is\nessential for gaining trust from non-technical stakeholders.\nTransparency: PDPs improve transparency by providing an intuitive way to analyze and present the\neffects of individual features.","zh":"部分依赖图（PDP）是理解和解释机器学习模型中各特征如何影响预测的有力工具，常用于满足面向利益相关者的透明度和可解释性要求。下面说明为什么这是正确选项，以及其他选项为何不太合适：\n部分依赖图（PDP）\n目的：PDP 展示某个特征（或多个特征）与模型预测输出之间的关系，有助于解释每个特征对模型预测的影响。\n可解释性：通过可视化每个特征如何影响预测，利益相关者可以更好地理解模型如何工作、为什么会做出某些预测。这种可解释性对于赢得非技术背景利益相关者的信任至关重要。\n透明度：PDP 通过提供一种直观的方式来分析和呈现单个特征的影响，从而提升透明度。"},"tip":{"zh":"要向业务方讲清模型怎么用特征做预测 → 选部分依赖图；训练代码和样本数据都不解释模型行为。","en":""},"keywords":["可解释性","部分依赖图","透明度","特征影响"]},{"id":2,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"A law firm wants to build an AI application by using large language models (LLMs). The application will\nread legal documents and extract key points from the documents.\nWhich solution meets these requirements?","zh":"一家律师事务所想使用大型语言模型（LLM）构建一个 AI 应用。该应用将阅读法律文档并从中提取关键要点。\n哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Build an automatic named entity recognition system.","zh":"构建一个自动命名实体识别系统。"},{"key":"B","en":"Create a recommendation engine.","zh":"创建一个推荐引擎。"},{"key":"C","en":"Develop a summarization chatbot.","zh":"开发一个摘要聊天机器人。"},{"key":"D","en":"Develop a multi-language translation system.","zh":"开发一个多语言翻译系统。"}],"explanation":{"en":"A summarization chatbot can effectively read legal documents and generate concise versions that\nhighlight key points. This directly addresses the requirement of extracting essential information, unlike the\nother options, which focus on different tasks.","zh":"摘要聊天机器人能够有效地阅读法律文档并生成突出关键要点的精简版本，这直接满足了提取关键信息的要求；其他选项则侧重不同的任务。"},"tip":{"zh":"“提取关键要点”就是摘要任务，别被“法律文档”带偏去选命名实体识别。","en":""},"keywords":["摘要","LLM 应用","关键信息提取"]},{"id":3,"type":"single","answer":["A"],"topic":"responsible","stem":{"en":"A company wants to classify human genes into 20 categories based on gene characteristics. The\ncompany needs an ML algorithm to document how the inner mechanism of the model affects the output.\nWhich ML algorithm meets these requirements?","zh":"一家公司想根据基因特征把人类基因分为 20 个类别。该公司需要一种 ML 算法，能够记录模型的内部机制是如何影响输出的。\n哪种 ML 算法能满足这些要求？"},"options":[{"key":"A","en":"Decision trees","zh":"决策树"},{"key":"B","en":"Linear regression","zh":"线性回归"},{"key":"C","en":"Logistic regression","zh":"逻辑回归"},{"key":"D","en":"Neural networks","zh":"神经网络"}],"explanation":{"en":"Decision trees provide clear transparency into how the model makes decisions, allowing easy\ndocumentation of how the inner mechanism influences the output. The other options do not offer this level\nof interpretability.","zh":"决策树能清晰透明地展示模型如何做决策，便于记录内部机制如何影响输出。其他选项无法提供这种程度的可解释性。"},"tip":{"zh":"要能说清内部机制怎么得出结果 → 决策树可解释；神经网络是黑盒，排除。","en":""},"keywords":["可解释性","决策树","算法选择"]},{"id":4,"type":"single","answer":["B"],"topic":"eval","stem":{"en":"A company has built an image classification model to predict plant diseases from photos of plant leaves.\nThe company wants to evaluate how many images the model classified correctly.\nWhich evaluation metric should the company use to measure the model's performance?","zh":"一家公司构建了一个图像分类模型，用于根据植物叶片照片预测植物病害。该公司想评估模型正确分类了多少张图像。\n该公司应使用哪种评估指标来衡量模型性能？"},"options":[{"key":"A","en":"R-squared score","zh":"R 平方分数（R-squared）"},{"key":"B","en":"Accuracy","zh":"准确率"},{"key":"C","en":"Root mean squared error (RMSE)","zh":"均方根误差（RMSE）"},{"key":"D","en":"Learning rate","zh":"学习率"}],"explanation":{"en":"Accuracy measures how many images were correctly classified out of the total images, making it the\nappropriate metric for evaluating the performance of an image classification model. The other metrics are\neither not suitable for classification tasks or not used for performance evaluation.","zh":"准确率衡量的是在所有图像中有多少张被正确分类，因此是评估图像分类模型性能的合适指标。其他指标要么不适用于分类任务，要么不用于性能评估。"},"tip":{"zh":"问“分类对了多少张” → 准确率；R 平方和 RMSE 都是回归指标。","en":""},"keywords":["准确率","分类评估","指标选择"]},{"id":5,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"A company is using a pre-trained large language model (LLM) to build a chatbot for product\nrecommendations. The company needs the LLM outputs to be short and written in a specific language.\nWhich solution will align the LLM response quality with the company's expectations?","zh":"一家公司正在使用预训练的大型语言模型（LLM）构建一个用于产品推荐的聊天机器人。该公司需要 LLM 的输出简短，并且用特定的语言书写。\n哪种解决方案能使 LLM 的响应质量符合该公司的预期？"},"options":[{"key":"A","en":"Adjust the prompt.","zh":"调整提示词。"},{"key":"B","en":"Choose an LLM of a different size.","zh":"选择不同规模的 LLM。"},{"key":"C","en":"Increase the temperature.","zh":"提高温度（temperature）参数。"},{"key":"D","en":"Increase the Top K value.","zh":"提高 Top K 值。"}],"explanation":{"en":"Adjusting the prompt allows you to specify the desired length and language of the LLM's responses,\nmaking it suitable for tailoring the output to meet the company's needs. The other options do not directly\ncontrol response length or language.","zh":"调整提示词可以指定 LLM 响应的期望长度和语言，从而把输出定制成符合公司需求的形式。其他选项都不能直接控制响应长度或语言。"},"tip":{"zh":"控制输出长短和语言 → 改提示词；温度、Top K 只影响随机性和多样性。","en":""},"keywords":["提示工程","输出格式控制","temperature"]},{"id":6,"type":"single","answer":["C"],"topic":"sagemaker","stem":{"en":"A company uses Amazon SageMaker for its ML pipeline in a production environment. The company has\nlarge input data sizes up to 1 GB and processing times up to 1 hour. The company needs near real-time\nlatency.\nWhich SageMaker inference option meets these requirements?","zh":"某公司在生产环境中使用 Amazon SageMaker 运行其 ML 流水线。该公司的输入数据量很大，最大可达 1 GB，处理时间最长可达 1 小时。该公司需要接近实时的延迟。\n哪种 SageMaker 推理选项能满足这些要求？"},"options":[{"key":"A","en":"Real-time inference","zh":"实时推理"},{"key":"B","en":"Serverless inference","zh":"无服务器推理"},{"key":"C","en":"Asynchronous inference","zh":"异步推理"},{"key":"D","en":"Batch transform","zh":"批量转换"}],"explanation":{"en":"Asynchronous inference is suitable for handling large input data and long processing times while still\nproviding responses without blocking other requests. It allows for near real-time latency, whereas the other\noptions are less suitable given the input size and processing time constraints.","zh":"异步推理适合处理大数据量和长处理时间，同时仍能返回响应而不阻塞其他请求。它可以提供接近实时的延迟；考虑到输入大小和处理时间的限制，其他选项都不太合适。"},"tip":{"zh":"大输入（1 GB）+ 长耗时（1 小时）+ 要近实时 → 异步推理；批量转换没有实时响应。","en":""},"keywords":["异步推理","大文件","延迟","SageMaker 推理选项"]},{"id":7,"type":"single","answer":["B"],"topic":"general","stem":{"en":"A company is using domain-specific models. The company wants to avoid creating new models from the\nbeginning. The company instead wants to adapt pre-trained models to create models for new, related\ntasks.\nWhich ML strategy meets these requirements?","zh":"一家公司正在使用领域专用模型。该公司希望避免从头创建新模型，而是希望调整预训练模型，为新的、相关的任务创建模型。\n哪种 ML 策略能满足这些要求？"},"options":[{"key":"A","en":"Increase the number of epochs.","zh":"增加轮次（epochs）数量。"},{"key":"B","en":"Use transfer learning.","zh":"使用迁移学习。"},{"key":"C","en":"Decrease the number of epochs.","zh":"减少轮次（epochs）数量。"},{"key":"D","en":"Use unsupervised learning.","zh":"使用无监督学习。"}],"explanation":{"en":"Transfer learning allows the company to adapt pre-trained models for new, related tasks, saving time and\nresources compared to training models from scratch. The other options do not address the goal of reusing\nexisting models.","zh":"迁移学习使公司能够把预训练模型调整为适用于新的相关任务，相比从头训练模型可节省时间和资源。其他选项都没有解决复用已有模型这一目标。"},"tip":{"zh":"复用预训练模型去做新任务 → 迁移学习；调 epoch 数量解决不了复用问题。","en":""},"keywords":["迁移学习","预训练模型","模型复用"]},{"id":8,"type":"single","answer":["A"],"topic":"responsible","stem":{"en":"A company is building a solution to generate images for protective eyewear. The solution must have high\naccuracy and must minimize the risk of incorrect annotations.\nWhich solution will meet these requirements?","zh":"一家公司正在构建一个用于生成护目镜图像的解决方案。该解决方案必须具有高准确率，并且必须尽量减少错误标注的风险。\n哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Human-in-the-loop validation by using Amazon SageMaker Ground Truth Plus","zh":"使用 Amazon SageMaker Ground Truth Plus 进行人在回路验证"},{"key":"B","en":"Data augmentation by using an Amazon Bedrock knowledge base","zh":"使用 Amazon Bedrock 知识库进行数据增强"},{"key":"C","en":"Image recognition by using Amazon Rekognition","zh":"使用 Amazon Rekognition 进行图像识别"},{"key":"D","en":"Data summarization by using Amazon QuickSight Q","zh":"使用 Amazon QuickSight Q 进行数据摘要"}],"explanation":{"en":"Human-in-the-loop validation ensures high accuracy by involving human reviewers to verify and correct\nannotations, minimizing the risk of errors in the generated images. The other options are not directly\nrelevant for ensuring annotation accuracy in image generation.","zh":"人在回路验证通过让人类审核员核验并纠正标注来确保高准确率，从而将生成图像中出现错误的风险降到最低。其他选项与确保图像生成中的标注准确率没有直接关系。"},"tip":{"zh":"要高准确率又要少错标 → 人在回路（Ground Truth Plus）复核，别指望模型自动识别。","en":""},"keywords":["人在回路","数据标注","Ground Truth Plus"]},{"id":9,"type":"single","answer":["A"],"topic":"security","stem":{"en":"A company wants to create a chatbot by using a foundation model (FM) on Amazon Bedrock. The FM\nneeds to access encrypted data that is stored in an Amazon S3 bucket. The data is encrypted with\nAmazon S3 managed keys (SSE-S3).\nThe FM encounters a failure when attempting to access the S3 bucket data.\nWhich solution will meet these requirements?","zh":"一家公司想使用 Amazon Bedrock 上的基础模型（FM）创建一个聊天机器人。该 FM 需要访问存储在 Amazon S3 桶中的加密数据。该数据使用 Amazon S3 托管密钥（SSE-S3）加密。\n该 FM 在尝试访问 S3 桶数据时遇到失败。\n哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Ensure that the role that Amazon Bedrock assumes has permission to decrypt data with the correct encryption key.","zh":"确保 Amazon Bedrock 所代入（assume）的角色具有使用正确加密密钥解密数据的权限。"},{"key":"B","en":"Set the access permissions for the S3 buckets to allow public access to enable access over the internet.","zh":"将 S3 桶的访问权限设置为允许公有访问，以便通过互联网访问。"},{"key":"C","en":"Use prompt engineering techniques to tell the model to look for information in Amazon S3.","zh":"使用提示工程技术告诉模型去 Amazon S3 中查找信息。"},{"key":"D","en":"Ensure that the S3 data does not contain sensitive information.","zh":"确保 S3 数据不包含敏感信息。"}],"explanation":{"en":"The foundation model needs the appropriate permissions to decrypt the encrypted data in the S3 bucket.\nEnsuring that the role used by Amazon Bedrock has permission to access and decrypt the data will\nresolve the access failure. The other options are not suitable for addressing the encryption and permission\nissue.","zh":"基础模型需要具备相应权限才能解密 S3 桶中的加密数据。确保 Amazon Bedrock 使用的角色拥有访问并解密数据的权限，即可解决该访问失败问题。其他选项都不适合解决加密与权限问题。"},"tip":{"zh":"访问加密 S3 失败 → 查 Bedrock 角色有没有解密权限；开公有访问是错误做法。","en":""},"keywords":["IAM 权限","S3 加密","Bedrock 访问控制"]},{"id":10,"type":"single","answer":["A"],"topic":"sagemaker","stem":{"en":"A company wants to use language models to create an application for inference on edge devices. The\ninference must have the lowest latency possible.\nWhich solution will meet these requirements?","zh":"一家公司想使用语言模型创建一个用于在边缘设备上做推理的应用。该推理必须具有尽可能低的延迟。\n哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Deploy optimized small language models (SLMs) on edge devices.","zh":"在边缘设备上部署经过优化的小型语言模型（SLM）。"},{"key":"B","en":"Deploy optimized large language models (LLMs) on edge devices.","zh":"在边缘设备上部署经过优化的大型语言模型（LLM）。"},{"key":"C","en":"Incorporate a centralized small language model (SLM) API for asynchronous communication with edge devices.","zh":"引入一个集中式的小型语言模型（SLM）API，与边缘设备进行异步通信。"},{"key":"D","en":"Incorporate a centralized large language model (LLM) API for asynchronous communication with edge devices.","zh":"引入一个集中式的大型语言模型（LLM）API，与边缘设备进行异步通信。"}],"explanation":{"en":"Deploying optimized small language models (SLMs) directly on edge devices provides low latency for\ninference since the computation happens locally, avoiding the delays associated with network\ncommunication. The other options either increase latency or are less suitable for edge deployment.","zh":"把经过优化的小型语言模型（SLM）直接部署在边缘设备上，可以在本地完成计算，避免网络通信带来的延迟，从而获得低延迟推理。其他选项要么会增加延迟，要么不适合边缘部署。"},"tip":{"zh":"边缘设备要最低延迟 → 本地跑小模型，别走网络 API；异步通信反而更慢。","en":""},"keywords":["边缘推理","低延迟","小型语言模型"]},{"id":11,"type":"single","answer":["A"],"topic":"sagemaker","stem":{"en":"A company wants to build an ML model by using Amazon SageMaker. The company needs to share and\nmanage variables for model development across multiple teams.\nWhich SageMaker feature meets these requirements?","zh":"一家公司想使用 Amazon SageMaker 构建 ML 模型。该公司需要跨多个团队共享并管理用于模型开发的变量。\n哪种 SageMaker 功能能满足这些要求？"},"options":[{"key":"A","en":"Amazon SageMaker Feature Store","zh":"Amazon SageMaker Feature Store"},{"key":"B","en":"Amazon SageMaker Data Wrangler","zh":"Amazon SageMaker Data Wrangler"},{"key":"C","en":"Amazon SageMaker Clarify","zh":"Amazon SageMaker Clarify"},{"key":"D","en":"Amazon SageMaker Model Cards","zh":"Amazon SageMaker Model Cards"}],"explanation":{"en":"Amazon SageMaker Feature Store is a centralized repository for storing and managing features, allowing\nmultiple teams to share and reuse variables (features) for model development. The other options serve\ndifferent purposes, such as data preprocessing or model documentation.","zh":"Amazon SageMaker Feature Store 是一个用于存储和管理特征的集中式存储库，使多个团队能够共享并复用用于模型开发的变量（特征）。其他选项用途不同，例如数据预处理或模型文档化。"},"tip":{"zh":"多团队共享和管理特征变量 → Feature Store；Data Wrangler 做预处理，Clarify 查偏见。","en":""},"keywords":["Feature Store","特征共享","SageMaker 功能"]},{"id":12,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"A company wants to use generative AI to increase developer productivity and software development. The\ncompany wants to use Amazon Q Developer.\nWhat can Amazon Q Developer do to help the company meet these requirements?","zh":"一家公司想使用生成式 AI 提升开发人员生产力和软件开发效率。该公司想使用 Amazon Q Developer。\nAmazon Q Developer 能做什么来帮助该公司满足这些要求？"},"options":[{"key":"A","en":"Create software snippets, reference tracking, and open source license tracking.","zh":"创建软件代码片段、进行引用追踪，以及开源许可证追踪。"},{"key":"B","en":"Run an application without provisioning or managing servers.","zh":"无需预置或管理服务器即可运行应用。"},{"key":"C","en":"Enable voice commands for coding and providing natural language search.","zh":"启用语音编码命令，并提供自然语言搜索。"},{"key":"D","en":"Convert audio files to text documents by using ML models.","zh":"使用 ML 模型把音频文件转换为文本文档。"}],"explanation":{"en":"Amazon Q Developer is designed to assist developers by generating software snippets, tracking\nreferences, and managing open source licenses, which aligns with the company's goal of increasing\nproductivity in software development. The other options do not match the intended use of Amazon Q\nDeveloper.","zh":"Amazon Q Developer 旨在通过生成软件代码片段、追踪引用和管理开源许可证来协助开发人员，这与该公司提升软件开发生产力的目标一致。其他选项与 Amazon Q Developer 的预期用途不符。"},"tip":{"zh":"Q Developer = 写代码片段 + 引用追踪 + 开源许可追踪；免服务器是 Lambda。","en":""},"keywords":["Amazon Q Developer","开发效率","生成式 AI 应用场景"]},{"id":13,"type":"single","answer":["A"],"topic":"security","stem":{"en":"A financial institution is using Amazon Bedrock to develop an AI application. The application is hosted in a\nVPC. To meet regulatory compliance standards, the VPC is not allowed access to any internet traffic.\nWhich AWS service or feature will meet these requirements?","zh":"一家金融机构正在使用 Amazon Bedrock 开发一个 AI 应用。该应用托管在一个 VPC 中。为满足监管合规标准，该 VPC 不允许访问任何互联网流量。\n哪种 AWS 服务或功能能满足这些要求？"},"options":[{"key":"A","en":"AWS PrivateLink","zh":"AWS PrivateLink"},{"key":"B","en":"Amazon Macie","zh":"Amazon Macie"},{"key":"C","en":"Amazon CloudFront","zh":"Amazon CloudFront"},{"key":"D","en":"Internet gateway","zh":"互联网网关"}],"explanation":{"en":"AWS PrivateLink allows secure, private connectivity between VPCs and AWS services without needing\ninternet access, making it suitable for meeting regulatory compliance standards. The other options either\ndo not provide private connectivity or require internet access.","zh":"AWS PrivateLink 允许 VPC 与 AWS 服务之间建立安全的私有连接，而无需互联网访问，因此适合满足监管合规标准。其他选项要么不提供私有连接，要么需要互联网访问。"},"tip":{"zh":"VPC 不能上公网又要用 Bedrock → PrivateLink 私有连接；互联网网关正好相反。","en":""},"keywords":["PrivateLink","VPC","私有连接","合规"]},{"id":14,"type":"single","answer":["C"],"topic":"general","stem":{"en":"A company wants to develop an educational game where users answer questions such as the following:\n\"A jar contains six red, four green, and three yellow marbles. What is the probability of choosing a green\nmarble from the jar?\"\nWhich solution meets these requirements with the LEAST operational overhead?","zh":"一家公司想开发一款教育游戏，用户需要回答如下问题：\n“一个罐子里有 6 个红球、4 个绿球和 3 个黄球。从罐中抽到绿球的概率是多少？”\n哪种解决方案能以最少的运营开销满足这些要求？"},"options":[{"key":"A","en":"Use supervised learning to create a regression model that will predict probability.","zh":"使用监督式学习创建一个预测概率的回归模型。"},{"key":"B","en":"Use reinforcement learning to train a model to return the probability.","zh":"使用强化学习训练一个返回概率的模型。"},{"key":"C","en":"Use code that will calculate probability by using simple rules and computations.","zh":"使用基于简单规则和计算的代码来计算概率。"},{"key":"D","en":"Use unsupervised learning to create a model that will estimate probability density.","zh":"使用无监督学习创建一个估计概率密度的模型。"}],"explanation":{"en":"Calculating probability in this scenario involves straightforward arithmetic, making it most efficient to use\nsimple rules and computations. This approach requires the least operational overhead compared to using\ncomplex ML models, which are unnecessary for such basic tasks.","zh":"在这个场景中计算概率只是简单的算术运算，因此使用简单规则和计算最为高效。与使用复杂的 ML 模型相比，这种方法所需的运营开销最少，而这类基础任务根本不需要 ML 模型。"},"tip":{"zh":"简单算术就能算概率 → 直接写代码；上 ML 模型只会徒增开销。","en":""},"keywords":["运营开销","规则计算","何时不该用 ML"]},{"id":15,"type":"single","answer":["C"],"topic":"eval","stem":{"en":"Which metric measures the runtime efficiency of operating AI models?","zh":"哪种指标衡量运行 AI 模型时的运行时效率？"},"options":[{"key":"A","en":"Customer satisfaction score (CSAT)","zh":"客户满意度分数（CSAT）"},{"key":"B","en":"Training time for each epoch","zh":"每个轮次（epoch）的训练时间"},{"key":"C","en":"Average response time","zh":"平均响应时间"},{"key":"D","en":"Number of training instances","zh":"训练实例数量"}],"explanation":{"en":"Average response time measures how quickly an AI model produces an output, which reflects the runtime\nefficiency of the model. The other options do not directly measure the efficiency of operating AI models.","zh":"平均响应时间衡量 AI 模型产生输出的快慢，反映了模型的运行时效率。其他选项都不能直接衡量运行 AI 模型的效率。"},"tip":{"zh":"运行时效率 = 出结果有多快 → 平均响应时间；训练时间和实例数属于训练阶段。","en":""},"keywords":["运行时效率","平均响应时间","性能指标"]},{"id":16,"type":"single","answer":["B"],"topic":"services","stem":{"en":"A company is building a contact center application and wants to gain insights from customer\nconversations. The company wants to analyze and extract key information from the audio of the customer\ncalls.\nWhich solution meets these requirements?","zh":"一家公司正在构建一个联络中心应用，希望从客户对话中获取洞察。该公司想分析客户通话音频并从中提取关键信息。\n哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Build a conversational chatbot by using Amazon Lex.","zh":"使用 Amazon Lex 构建一个对话式聊天机器人。"},{"key":"B","en":"Transcribe call recordings by using Amazon Transcribe.","zh":"使用 Amazon Transcribe 转写通话录音。"},{"key":"C","en":"Extract information from call recordings by using Amazon SageMaker Model Monitor.","zh":"使用 Amazon SageMaker Model Monitor 从通话录音中提取信息。"},{"key":"D","en":"Create classification labels by using Amazon Comprehend.","zh":"使用 Amazon Comprehend 创建分类标签。"}],"explanation":{"en":"Amazon Transcribe converts audio recordings into text, which allows for further analysis and extraction of\nkey information from customer conversations. The other options do not directly handle audio transcription\nor extraction of information from audio.","zh":"Amazon Transcribe 把音频录音转换为文本，从而可以对客户对话做进一步分析并提取关键信息。其他选项都不直接处理音频转写或从音频中提取信息。"},"tip":{"zh":"音频转文字再做分析 → Transcribe；Lex 是聊天机器人，Model Monitor 是监控漂移。","en":""},"keywords":["Transcribe","语音转文本","通话分析"]},{"id":17,"type":"single","answer":["B"],"topic":"data","stem":{"en":"A company has petabytes of unlabeled customer data to use for an advertisement campaign. The\ncompany wants to classify its customers into tiers to advertise and promote the company's products.\nWhich methodology should the company use to meet these requirements?","zh":"一家公司拥有数 PB 的未标注客户数据，可用于广告活动。该公司想把客户分为不同层级，以便投放和推广公司产品。\n该公司应使用哪种方法满足这些要求？"},"options":[{"key":"A","en":"Supervised learning","zh":"监督式学习"},{"key":"B","en":"Unsupervised learning","zh":"无监督学习"},{"key":"C","en":"Reinforcement learning","zh":"强化学习"},{"key":"D","en":"Reinforcement learning from human feedback (RLHF)","zh":"基于人类反馈的强化学习（RLHF）"}],"explanation":{"en":"Unsupervised learning is suitable for analyzing unlabeled data and grouping it into clusters or tiers, which\n\naligns with the company’s goal of classifying customers. The other methods require labeled data or are\nused for different types of problems.","zh":"无监督学习适合分析未标注数据并将其划分为簇或层级，这与该公司对客户进行分类的目标一致。其他方法要么需要标注数据，要么用于不同类型的问题。"},"tip":{"zh":"数据没标签又要分群分层 → 无监督学习；监督式学习需要标注，排除。","en":""},"keywords":["无监督学习","客户分群","未标注数据"]},{"id":18,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"An AI practitioner wants to use a foundation model (FM) to design a search application. The search\napplication must handle queries that have text and images.\nWhich type of FM should the AI practitioner use to power the search application?","zh":"一位 AI 从业者想使用基础模型（FM）设计一个搜索应用。该搜索应用必须能处理同时包含文本和图像的查询。\n该 AI 从业者应使用哪种类型的 FM 来支撑该搜索应用？"},"options":[{"key":"A","en":"Multi-modal embedding model","zh":"多模态嵌入模型"},{"key":"B","en":"Text embedding model","zh":"文本嵌入模型"},{"key":"C","en":"Multi-modal generation model","zh":"多模态生成模型"},{"key":"D","en":"Image generation model","zh":"图像生成模型"}],"explanation":{"en":"A multi-modal embedding model can handle both text and image queries by embedding them into a\nshared space, enabling the search application to process and relate different data types. The other options\nare not suitable for handling both text and image inputs effectively.","zh":"多模态嵌入模型可以把文本和图像查询都嵌入到同一个共享空间中，使搜索应用能够处理并关联不同类型的数据。其他选项无法有效处理文本和图像两种输入。"},"tip":{"zh":"文本+图像一起做检索 → 多模态嵌入模型；生成模型是造内容，不做相似度检索。","en":""},"keywords":["多模态嵌入","向量检索","FM 选型"]},{"id":19,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"A company uses a foundation model (FM) from Amazon Bedrock for an AI search tool. The company\nwants to fine-tune the model to be more accurate by using the company's data.\nWhich strategy will successfully fine-tune the model?","zh":"一家公司使用 Amazon Bedrock 上的基础模型（FM）构建了一个 AI 搜索工具。该公司想使用自己的数据微调该模型，使其更准确。\n哪种策略能成功微调该模型？"},"options":[{"key":"A","en":"Provide labeled data with the prompt field and the completion field.","zh":"提供同时包含 prompt 字段和 completion 字段的标注数据。"},{"key":"B","en":"Prepare the training dataset by creating a .txt file that contains multiple lines in .csv format.","zh":"通过创建一个包含多行 .csv 格式内容的 .txt 文件来准备训练数据集。"},{"key":"C","en":"Purchase Provisioned Throughput for Amazon Bedrock.","zh":"为 Amazon Bedrock 购买预置吞吐量。"},{"key":"D","en":"Train the model on journals and textbooks.","zh":"使用期刊和教科书来训练该模型。"}],"explanation":{"en":"Fine-tuning a foundation model involves training it with labeled data that contains both input prompts and\ncorresponding expected completions to adjust the model’s behavior to fit the company’s needs. The other\noptions are not directly related to the fine-tuning process using specific labeled data.","zh":"微调基础模型需要用标注数据对其进行训练，这些数据既包含输入的提示（prompt），也包含对应的期望补全（completion），从而把模型行为调整为符合公司需求。其他选项与使用特定标注数据进行微调的过程没有直接关系。"},"tip":{"zh":"Bedrock 微调数据集 = prompt 与 completion 成对的标注数据；预置吞吐量只管容量。","en":""},"keywords":["微调","prompt/completion","Bedrock 自定义模型"]},{"id":20,"type":"single","answer":["C"],"topic":"general","stem":{"en":"A company wants to use AI to protect its application from threats. The AI solution needs to check if an IP\naddress is from a suspicious source.\nWhich solution meets these requirements?","zh":"一家公司想用 AI 保护其应用免受威胁。该 AI 解决方案需要检查某个 IP 地址是否来自可疑来源。\n哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Build a speech recognition system.","zh":"构建一个语音识别系统。"},{"key":"B","en":"Create a natural language processing (NLP) named entity recognition system.","zh":"创建一个自然语言处理（NLP）命名实体识别系统。"},{"key":"C","en":"Develop an anomaly detection system.","zh":"开发一个异常检测系统。"},{"key":"D","en":"Create a fraud forecasting system.","zh":"创建一个欺诈预测系统。"}],"explanation":{"en":"An anomaly detection system can identify suspicious behavior, such as IP addresses that deviate from\n\nexpected patterns, which helps in protecting the application from threats. The other options are not\ndesigned for detecting suspicious IP addresses.","zh":"异常检测系统可以识别可疑行为，例如偏离预期模式的 IP 地址，从而有助于保护应用免受威胁。其他选项并非为检测可疑 IP 地址而设计。"},"tip":{"zh":"判断 IP 是否“不正常” → 异常检测；欺诈预测是针对交易，不是来源识别。","en":""},"keywords":["异常检测","威胁防护","安全场景"]},{"id":21,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"Which feature of Amazon OpenSearch Service gives companies the ability to build vector database\napplications?","zh":"Amazon OpenSearch Service 的哪项功能使公司能够构建向量数据库应用？"},"options":[{"key":"A","en":"Integration with Amazon S3 for object storage","zh":"与 Amazon S3 集成以进行对象存储"},{"key":"B","en":"Support for geospatial indexing and queries","zh":"支持地理空间索引和查询"},{"key":"C","en":"Scalable index management and nearest neighbor search capability","zh":"可扩展的索引管理能力和最近邻搜索能力"},{"key":"D","en":"Ability to perform real-time analysis on streaming data","zh":"能够对流式数据执行实时分析"}],"explanation":{"en":"The scalable index management and nearest neighbor search capability in Amazon OpenSearch Service\nenables companies to build vector database applications, which are crucial for tasks like similarity search\nin AI models. The other options do not specifically provide the vector search functionality.","zh":"Amazon OpenSearch Service 中可扩展的索引管理能力和最近邻搜索能力使公司能够构建向量数据库应用，这对 AI 模型中的相似度搜索等任务至关重要。其他选项并不专门提供向量搜索功能。"},"tip":{"zh":"向量数据库的关键是“最近邻搜索” → 选 kNN；地理空间和流式分析都不是向量检索。","en":""},"keywords":["向量数据库","最近邻搜索","OpenSearch"]},{"id":22,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"Which option is a use case for generative AI models?","zh":"哪个选项是生成式 AI 模型的使用场景？"},"options":[{"key":"A","en":"Improving network security by using intrusion detection systems","zh":"使用入侵检测系统提升网络安全"},{"key":"B","en":"Creating photorealistic images from text descriptions for digital marketing","zh":"根据文本描述为数字营销创建照片级逼真的图像"},{"key":"C","en":"Enhancing database performance by using optimized indexing","zh":"通过优化索引提升数据库性能"},{"key":"D","en":"Analyzing financial data to forecast stock market trends","zh":"分析财务数据以预测股市走势"}],"explanation":{"en":"Generative AI models are used to create new content, such as photorealistic images from text\ndescriptions, which is useful for digital marketing. The other options involve tasks better suited for\nanalytical or detection systems rather than generative models.","zh":"生成式 AI 模型用于创建新内容，例如根据文本描述生成照片级逼真的图像，这对数字营销很有用。其他选项涉及的任务更适合用分析型或检测型系统，而不是生成式模型。"},"tip":{"zh":"生成式 AI 的核心是“造新内容” → 文生图；检测和预测属于判别式/分析型模型。","en":""},"keywords":["生成式 AI","使用场景","文生图"]},{"id":23,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"A company wants to build a generative AI application by using Amazon Bedrock and needs to choose a\nfoundation model (FM). The company wants to know how much information can fit into one prompt.\nWhich consideration will inform the company's decision?","zh":"一家公司想使用 Amazon Bedrock 构建一个生成式 AI 应用，并需要选择一个基础模型（FM）。该公司想了解一个提示词中能容纳多少信息。\n哪项考量会影响该公司的决定？"},"options":[{"key":"A","en":"Temperature","zh":"温度（Temperature）"},{"key":"B","en":"Context window","zh":"上下文窗口（Context window）"},{"key":"C","en":"Batch size","zh":"批大小（Batch size）"},{"key":"D","en":"Model size","zh":"模型大小（Model size）"}],"explanation":{"en":"The context window determines how much information can fit into a single prompt. It specifies the number\nof tokens the foundation model can process at once, affecting the length of input that can be provided. The\nother options do not directly relate to prompt size.","zh":"上下文窗口决定了一个提示词中能容纳多少信息。它规定了基础模型一次能处理的词元（token）数量，从而影响可提供的输入长度。其他选项与提示词大小没有直接关系。"},"tip":{"zh":"问“一个提示词能塞多少内容” → 上下文窗口（token 上限）；温度只调随机性。","en":""},"keywords":["上下文窗口","token","FM 选型"]},{"id":24,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"A company wants to make a chatbot to help customers. The chatbot will help solve technical problems\nwithout human intervention.\nThe company chose a foundation model (FM) for the chatbot. The chatbot needs to produce responses\nthat adhere to company tone.\nWhich solution meets these requirements?","zh":"一家公司想制作一个聊天机器人来帮助客户。该聊天机器人将在无需人工介入的情况下帮助解决技术问题。\n该公司为该聊天机器人选择了一个基础模型（FM）。该聊天机器人需要生成符合公司语气（tone）的响应。\n哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Set a low limit on the number of tokens the FM can produce.","zh":"对 FM 可生成的词元（token）数量设置较低上限。"},{"key":"B","en":"Use batch inferencing to process detailed responses.","zh":"使用批量推理来处理详细的响应。"},{"key":"C","en":"Experiment and refine the prompt until the FM produces the desired responses.","zh":"反复试验并优化提示词，直到 FM 生成符合期望的响应。"},{"key":"D","en":"Define a higher number for the temperature parameter.","zh":"把温度（temperature）参数设为更高的数值。"}],"explanation":{"en":"Experimenting and refining the prompt allows you to guide the FM to produce responses that align with the\ncompany's desired tone. This approach helps to shape the behavior of the chatbot. The other options do\nnot directly ensure adherence to company tone.","zh":"反复试验并优化提示词，可以引导 FM 生成符合公司期望语气的响应。这种方法有助于塑造聊天机器人的行为。其他选项都不能直接确保响应符合公司语气。"},"tip":{"zh":"要让输出符合公司语气 → 调提示词；限 token 数、提温度只会改长度和随机性。","en":""},"keywords":["提示工程","输出语气","聊天机器人"]},{"id":25,"type":"single","answer":["A"],"topic":"eval","stem":{"en":"A company wants to use a large language model (LLM) on Amazon Bedrock for sentiment analysis. The\ncompany wants to classify the sentiment of text passages as positive or negative.\nWhich prompt engineering strategy meets these requirements?","zh":"一家公司想使用 Amazon Bedrock 上的大型语言模型（LLM）进行情感分析。该公司想把文本段落的情感分类为正面或负面。\n哪种提示工程策略能满足这些要求？"},"options":[{"key":"A","en":"Provide examples of text passages with corresponding positive or negative labels in the prompt followed by the new text passage to be classified.","zh":"在提示词中提供带有对应正面或负面标签的文本段落示例，后面再附上待分类的新文本段落。"},{"key":"B","en":"Provide a detailed explanation of sentiment analysis and how LLMs work in the prompt.","zh":"在提示词中详细解释情感分析以及 LLM 的工作原理。"},{"key":"C","en":"Provide the new text passage to be classified without any additional context or examples.","zh":"只提供待分类的新文本段落，不提供任何额外上下文或示例。"},{"key":"D","en":"Provide the new text passage with a few examples of unrelated tasks, such as text summarization or question answering.","zh":"提供新文本段落，并附上一些无关任务的示例，例如文本摘要或问答。"}],"explanation":{"en":"Providing examples with labels in the prompt helps the LLM understand the context of sentiment analysis,\nimproving its accuracy in classifying the new text passage as positive or negative. The other options do not\neffectively guide the LLM for sentiment analysis.","zh":"在提示词中提供带标签的示例有助于 LLM 理解情感分析的上下文，从而提高其把新文本段落分类为正面或负面的准确性。其他选项都不能有效引导 LLM 完成情感分析。"},"tip":{"zh":"要分类 → 给带标签的示例（少样本提示），这就是 few-shot 的典型用法。","en":""},"keywords":["少样本提示","情感分析","提示工程"]},{"id":26,"type":"single","answer":["B"],"topic":"security","stem":{"en":"A security company is using Amazon Bedrock to run foundation models (FMs). The company wants to\nensure that only authorized users invoke the models. The company needs to identify any unauthorized\naccess attempts to set appropriate AWS Identity and Access Management (IAM) policies and roles for\nfuture iterations of the FMs.\nWhich AWS service should the company use to identify unauthorized users that are trying to access\nAmazon Bedrock?","zh":"一家安全公司正在使用 Amazon Bedrock 运行基础模型（FM）。该公司希望确保只有已获授权的用户才能调用这些模型。该公司需要识别任何未经授权的访问尝试，以便为 FM 的后续迭代设置合适的 AWS Identity and Access Management（IAM）策略和角色。\n该公司应使用哪种 AWS 服务来识别试图访问 Amazon Bedrock 的未授权用户？"},"options":[{"key":"A","en":"AWS Audit Manager","zh":"AWS Audit Manager"},{"key":"B","en":"AWS CloudTrail","zh":"AWS CloudTrail"},{"key":"C","en":"Amazon Fraud Detector","zh":"Amazon Fraud Detector"},{"key":"D","en":"AWS Trusted Advisor","zh":"AWS Trusted Advisor"}],"explanation":{"en":"AWS CloudTrail records API activity and provides a log of access attempts, which helps identify\nunauthorized users trying to access Amazon Bedrock. The other services are not specifically used for\ntracking unauthorized access attempts in this context.","zh":"AWS CloudTrail 记录 API 活动并提供访问尝试的日志，有助于识别试图访问 Amazon Bedrock 的未授权用户。其他服务在此场景下并不专门用于跟踪未授权访问尝试。"},"tip":{"zh":"查“谁调用了 API、谁被拒绝” → CloudTrail 审计日志；Audit Manager 是合规评估。","en":""},"keywords":["CloudTrail","访问审计","IAM 策略"]},{"id":27,"type":"single","answer":["A"],"topic":"sagemaker","stem":{"en":"A company has developed an ML model for image classification. The company wants to deploy the model\nto production so that a web application can use the model.\nThe company needs to implement a solution to host the model and serve predictions without managing\nany of the underlying infrastructure.\nWhich solution will meet these requirements?","zh":"一家公司开发了一个用于图像分类的 ML 模型。该公司想把模型部署到生产环境，以便某个 Web 应用可以使用该模型。\n该公司需要实现一个解决方案来托管模型并提供预测服务，同时不管理任何底层基础设施。\n哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Use Amazon SageMaker Serverless Inference to deploy the model.","zh":"使用 Amazon SageMaker Serverless Inference 部署该模型。"},{"key":"B","en":"Use Amazon CloudFront to deploy the model.","zh":"使用 Amazon CloudFront 部署该模型。"},{"key":"C","en":"Use Amazon API Gateway to host the model and serve predictions.","zh":"使用 Amazon API Gateway 托管该模型并提供预测服务。"},{"key":"D","en":"Use AWS Batch to host the model and serve predictions.","zh":"使用 AWS Batch 托管该模型并提供预测服务。"}],"explanation":{"en":"Amazon SageMaker Serverless Inference allows the company to deploy the ML model without managing\nany underlying infrastructure, making it suitable for hosting the model and serving predictions. The other\noptions do not directly provide serverless model deployment capabilities.","zh":"Amazon SageMaker Serverless Inference 使公司无需管理任何底层基础设施即可部署 ML 模型，适合托管模型并提供预测服务。其他选项都不能直接提供无服务器的模型部署能力。"},"tip":{"zh":"不想管基础设施又要托管模型 → Serverless Inference；API Gateway 只是网关，不跑模型。","en":""},"keywords":["无服务器推理","模型托管","SageMaker"]},{"id":28,"type":"single","answer":["B"],"topic":"security","stem":{"en":"An AI company periodically evaluates its systems and processes with the help of independent software\nvendors (ISVs). The company needs to receive email message notifications when an ISV's compliance\nreports become available.\nWhich AWS service can the company use to meet this requirement?","zh":"一家 AI 公司在独立软件供应商（ISV）的帮助下定期评估其系统和流程。该公司需要在 ISV 的合规报告可用时收到电子邮件通知。\n该公司可以使用哪种 AWS 服务来满足这一要求？"},"options":[{"key":"A","en":"AWS Audit Manager","zh":"AWS Audit Manager"},{"key":"B","en":"AWS Artifact","zh":"AWS Artifact"},{"key":"C","en":"AWS Trusted Advisor","zh":"AWS Trusted Advisor"},{"key":"D","en":"AWS Data Exchange","zh":"AWS Data Exchange"}],"explanation":{"en":"AWS Artifact provides access to compliance reports, including those from independent software vendors\n(ISVs). The company can use AWS Artifact to receive notifications when new compliance reports are\navailable. The other services are not used for accessing and notifying about compliance reports.","zh":"AWS Artifact 提供对合规报告的访问，包括来自独立软件供应商（ISV）的报告。该公司可以使用 AWS Artifact 在新合规报告可用时接收通知。其他服务不用于访问合规报告或就此发送通知。"},"tip":{"zh":"要下载或订阅合规报告（含 ISV 报告） → AWS Artifact；Audit Manager 是自建审计。","en":""},"keywords":["AWS Artifact","合规报告","ISV"]},{"id":29,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"A company wants to use a large language model (LLM) to develop a conversational agent. The company\nneeds to prevent the LLM from being manipulated with common prompt engineering techniques to perform\nundesirable actions or expose sensitive information.\nWhich action will reduce these risks?","zh":"一家公司想使用大型语言模型（LLM）开发一个对话式智能体。该公司需要防止 LLM 被常见的提示工程技术操纵，从而执行不当操作或泄露敏感信息。\n哪种做法能降低这些风险？"},"options":[{"key":"A","en":"Create a prompt template that teaches the LLM to detect attack patterns.","zh":"创建一个提示词模板，教会 LLM 识别攻击模式。"},{"key":"B","en":"Increase the temperature parameter on invocation requests to the LLM.","zh":"提高向 LLM 发起调用请求时的温度（temperature）参数。"},{"key":"C","en":"Avoid using LLMs that are not listed in Amazon SageMaker.","zh":"避免使用未列在 Amazon SageMaker 中的 LLM。"},{"key":"D","en":"Decrease the number of input tokens on invocations of the LLM.","zh":"减少调用 LLM 时的输入词元（token）数量。"}],"explanation":{"en":"Creating a prompt template that helps the LLM detect common attack patterns can reduce the risk of\nprompt injection and other undesirable manipulations. The other options do not effectively address the risk\nof prompt manipulation or unauthorized use.","zh":"创建一个帮助 LLM 识别常见攻击模式的提示词模板，可以降低提示注入（prompt injection）及其他不当操纵的风险。其他选项都不能有效应对提示操纵或未授权使用的风险。"},"tip":{"zh":"防提示注入 → 用提示模板教模型识别攻击模式；调温度和 token 数都防不住。","en":""},"keywords":["提示注入","提示工程","LLM 安全"]},{"id":30,"type":"single","answer":["D"],"topic":"genai","stem":{"en":"A company is using the Generative AI Security Scoping Matrix to assess security responsibilities for its\nsolutions. The company has identified four different solution scopes based on the matrix.\nWhich solution scope gives the company the MOST ownership of security responsibilities?","zh":"一家公司正在使用生成式 AI 安全范围矩阵（Generative AI Security Scoping Matrix）评估其解决方案的安全责任。该公司根据该矩阵确定了四种不同的解决方案范围。\n哪种解决方案范围使该公司承担最多的安全责任？"},"options":[{"key":"A","en":"Using a third-party enterprise application that has embedded generative AI features.","zh":"使用一个内嵌生成式 AI 功能的第三方企业应用。"},{"key":"B","en":"Building an application by using an existing third-party generative AI foundation model (FM).","zh":"使用现有的第三方生成式 AI 基础模型（FM）构建一个应用。"},{"key":"C","en":"Refining an existing third-party generative AI foundation model (FM) by fine-tuning the model by using data specific to the business.","zh":"使用业务专属数据微调现有的第三方生成式 AI 基础模型（FM），对其进行改进。"},{"key":"D","en":"Building and training a generative AI model from scratch by using specific data that a customer owns.","zh":"使用客户自有的特定数据，从头构建并训练一个生成式 AI 模型。"}],"explanation":{"en":"Building and training a generative AI model from scratch gives the company the most ownership of\nsecurity responsibilities, as it involves full control over data, training, deployment, and security measures.\nThe other options involve varying levels of dependency on third-party tools and services, which reduces\nthe company's ownership of security.","zh":"从头构建并训练生成式 AI 模型使公司承担最多的安全责任，因为这涉及对数据、训练、部署和安全措施的完全控制。其他选项对第三方工具和服务的依赖程度各不相同，因而降低了公司的安全责任。"},"tip":{"zh":"越靠自己造，责任越大 → 从头训练模型 = 安全责任最大；用现成应用责任最小。","en":""},"keywords":["共享责任模型","安全范围矩阵","责任划分"]},{"id":31,"type":"single","answer":["A"],"topic":"general","stem":{"en":"An AI practitioner has a database of animal photos. The AI practitioner wants to automatically identify and\ncategorize the animals in the photos without manual human effort.\nWhich strategy meets these requirements?","zh":"一位 AI 从业者拥有一个动物照片数据库。该 AI 从业者希望在无需人工操作的情况下自动识别并分类照片中的动物。\n哪种策略能满足这些要求？"},"options":[{"key":"A","en":"Object detection","zh":"目标检测"},{"key":"B","en":"Anomaly detection","zh":"异常检测"},{"key":"C","en":"Named entity recognition","zh":"命名实体识别"},{"key":"D","en":"Inpainting","zh":"图像修复（Inpainting）"}],"explanation":{"en":"Object detection is used to automatically identify and categorize objects (in this case, animals) in photos. It\ncan detect the presence of animals and classify them accordingly. The other strategies are not suitable for\nidentifying and categorizing animals in images.","zh":"目标检测用于自动识别并分类照片中的对象（在本例中是动物）。它可以检测动物的存在并对其进行分类。其他策略不适合在图像中识别和分类动物。"},"tip":{"zh":"在图片里找动物并分类 → 目标检测；NER 处理文本，inpainting 是补图。","en":""},"keywords":["目标检测","图像识别","计算机视觉"]},{"id":32,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"A company wants to create an application by using Amazon Bedrock. The company has a limited budget\nand prefers flexibility without long-term commitment.\nWhich Amazon Bedrock pricing model meets these requirements?","zh":"一家公司想使用 Amazon Bedrock 创建一个应用。该公司的预算有限，并偏好灵活且无长期承诺的方式。\n哪种 Amazon Bedrock 定价模式能满足这些要求？"},"options":[{"key":"A","en":"On-Demand","zh":"按需（On-Demand）"},{"key":"B","en":"Model customization","zh":"模型自定义（Model customization）"},{"key":"C","en":"Provisioned Throughput","zh":"预置吞吐量（Provisioned Throughput）"},{"key":"D","en":"Spot Instance","zh":"竞价型实例（Spot Instance）"}],"explanation":{"en":"The On-Demand pricing model provides flexibility without requiring a long-term commitment, allowing the\ncompany to pay only for the resources used, which fits well with a limited budget. The other options are\neither not relevant to pricing flexibility or involve specific resource commitments.","zh":"按需定价模式提供灵活性且无需长期承诺，公司只需为使用的资源付费，这与有限的预算很契合。其他选项要么与定价灵活性无关，要么涉及特定的资源承诺。"},"tip":{"zh":"预算有限 + 要灵活不要承诺 → 按需（On-Demand）；预置吞吐量是长期承诺。","en":""},"keywords":["按需定价","预置吞吐量","成本优化"]},{"id":33,"type":"single","answer":["B"],"topic":"security","stem":{"en":"Which AWS service or feature can help an AI development team quickly deploy and consume a foundation\nmodel (FM) within the team's VPC?","zh":"哪种 AWS 服务或功能可以帮助 AI 开发团队在团队自己的 VPC 内快速部署并使用基础模型（FM）？"},"options":[{"key":"A","en":"Amazon Personalize","zh":"Amazon Personalize"},{"key":"B","en":"Amazon SageMaker JumpStart","zh":"Amazon SageMaker JumpStart"},{"key":"C","en":"PartyRock, an Amazon Bedrock Playground","zh":"PartyRock，一个 Amazon Bedrock Playground"},{"key":"D","en":"Amazon SageMaker endpoints","zh":"Amazon SageMaker 端点"}],"explanation":{"en":"Amazon SageMaker JumpStart provides pre-built models, including foundation models, that can be quickly\ndeployed and consumed within a VPC, helping teams get started faster. The other options are not\ndesigned for deploying foundation models in this context.","zh":"Amazon SageMaker JumpStart 提供预构建模型（包括基础模型），可在 VPC 内快速部署并使用，帮助团队更快上手。其他选项在此场景下并非为部署基础模型而设计。"},"tip":{"zh":"要在 VPC 内快速开箱用 FM → SageMaker JumpStart；PartyRock 是公开体验的 playground。","en":""},"keywords":["JumpStart","FM 部署","VPC"]},{"id":34,"type":"single","answer":["A"],"topic":"security","stem":{"en":"How can companies use large language models (LLMs) securely on Amazon Bedrock?","zh":"公司如何才能在 Amazon Bedrock 上安全地使用大型语言模型（LLM）？"},"options":[{"key":"A","en":"Configure AWS Identity and Access Management (IAM) roles and policies by using least privilege access.","zh":"按照最小权限原则配置 AWS Identity and Access Management（IAM）角色和策略。"},{"key":"B","en":"Enable AWS Audit Manager for automatic model evaluation jobs.","zh":"为自动模型评估作业启用 AWS Audit Manager。"},{"key":"C","en":"Enable Amazon Bedrock automatic model evaluation jobs.","zh":"启用 Amazon Bedrock 的自动模型评估作业。"},{"key":"D","en":"Use Amazon CloudWatch Logs to make models explainable and to monitor for bias.","zh":"使用 Amazon CloudWatch Logs 让模型可解释并监控偏见。"}],"explanation":{"en":"Designing clear prompts and using IAM roles with least privilege access ensures secure use of LLMs on\nAmazon Bedrock by minimizing access risks and preventing misuse. The other options do not directly\naddress securing the use of LLMs.","zh":"设计清晰的提示词并使用最小权限访问的 IAM 角色，可以最大限度地降低访问风险并防止滥用，从而确保在 Amazon Bedrock 上安全使用 LLM。其他选项都不能直接解决 LLM 使用过程中的安全问题。"},"tip":{"zh":"LLM 安全用起来 → IAM 最小权限；模型评估作业和日志都管不了谁能调用。","en":""},"keywords":["最小权限","IAM","Bedrock 安全"]},{"id":35,"type":"single","answer":["A"],"topic":"services","stem":{"en":"A company has terabytes of data in a database that the company can use for business analysis. The\ncompany wants to build an AI-based application that can build a SQL query from input text that employees\nprovide. The employees have minimal experience with technology.\nWhich solution meets these requirements?","zh":"一家公司的数据库中有数 TB 数据，可用于业务分析。该公司想构建一个基于 AI 的应用，能够根据员工输入的文本生成 SQL 查询。这些员工的技术经验很少。\n哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Generative pre-trained transformers (GPT)","zh":"生成式预训练变换器（GPT）"},{"key":"B","en":"Residual neural network","zh":"残差神经网络"},{"key":"C","en":"Support vector machine","zh":"支持向量机"},{"key":"D","en":"WaveNet","zh":"WaveNet"}],"explanation":{"en":"GPT models are well-suited for converting natural language input into structured queries like SQL, making\nthem ideal for building an AI-based application that translates employee-provided text into SQL queries.\nThe other options are not designed for natural language understanding and query generation tasks.","zh":"GPT 模型非常适合把自然语言输入转换为 SQL 这样的结构化查询，因此是构建“把员工提供的文本转换为 SQL 查询”这类 AI 应用的理想选择。其他选项并非为自然语言理解和查询生成任务而设计。"},"tip":{"zh":"自然语言转 SQL → GPT 这类语言模型；SVM、WaveNet 都不懂自然语言。","en":""},"keywords":["GPT","自然语言转 SQL","文本生成"]},{"id":36,"type":"single","answer":["B"],"topic":"sagemaker","stem":{"en":"A company built a deep learning model for object detection and deployed the model to production.\nWhich AI process occurs when the model analyzes a new image to identify objects?","zh":"一家公司构建了一个用于目标检测的深度学习模型，并将该模型部署到生产环境。\n当该模型分析一张新图像以识别对象时，发生的是哪种 AI 过程？"},"options":[{"key":"A","en":"Training","zh":"训练"},{"key":"B","en":"Inference","zh":"推理"},{"key":"C","en":"Model deployment","zh":"模型部署"},{"key":"D","en":"Bias correction","zh":"偏见纠正"}],"explanation":{"en":"Inference is the process where the model analyzes new data (in this case, a new image) to make\npredictions or identify objects. The other options are related to different stages of the AI lifecycle, such as\nbuilding or preparing the model.","zh":"推理是模型分析新数据（在本例中是一张新图像）以做出预测或识别对象的过程。其他选项与 AI 生命周期的不同阶段有关，例如构建或准备模型。"},"tip":{"zh":"模型“用”起来分析新数据 → 推理（inference）；训练是学参数，部署是上线。","en":""},"keywords":["推理","AI 生命周期","模型上线"]},{"id":37,"type":"single","answer":["A"],"topic":"responsible","stem":{"en":"An AI practitioner is building a model to generate images of humans in various professions. The AI\npractitioner discovered that the input data is biased and that specific attributes affect the image generation\nand create bias in the model.\nWhich technique will solve the problem?","zh":"一位 AI 从业者正在构建一个生成各种职业人物图像的模型。该 AI 从业者发现输入数据存在偏见，某些属性会影响图像生成并在模型中造成偏见。\n哪种技术能解决该问题？"},"options":[{"key":"A","en":"Data augmentation for imbalanced classes","zh":"对不平衡类别进行数据增强"},{"key":"B","en":"Model monitoring for class distribution","zh":"针对类别分布的模型监控"},{"key":"C","en":"Retrieval Augmented Generation (RAG)","zh":"检索增强生成（RAG）"},{"key":"D","en":"Watermark detection for images","zh":"图像水印检测"}],"explanation":{"en":"Data augmentation for imbalanced classes helps address bias by creating a more balanced dataset,\nensuring that different attributes are equally represented. This reduces bias in image generation. The other\noptions do not directly address data bias issues.","zh":"对不平衡类别进行数据增强可以通过创建更均衡的数据集来应对偏见，确保不同属性得到同等体现，从而减少图像生成中的偏见。其他选项都不能直接解决数据偏见问题。"},"tip":{"zh":"数据本身不平衡导致偏见 → 数据增强补平各类别；监控只能发现，不能修。","en":""},"keywords":["数据增强","类别不平衡","偏见"]},{"id":38,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"A company is using an Amazon Titan foundation model (FM) in Amazon Bedrock. The company needs to\nsupplement the model by using relevant data from the company's private data sources.\nWhich solution will meet this requirement?","zh":"一家公司在 Amazon Bedrock 中使用 Amazon Titan 基础模型（FM）。该公司需要使用来自公司私有数据源的相关数据来补充该模型。\n哪种解决方案能满足这一要求？"},"options":[{"key":"A","en":"Use a different FM.","zh":"改用另一个 FM。"},{"key":"B","en":"Choose a lower temperature value.","zh":"选择更低的温度（temperature）值。"},{"key":"C","en":"Create an Amazon Bedrock knowledge base.","zh":"创建一个 Amazon Bedrock 知识库。"},{"key":"D","en":"Enable model invocation logging.","zh":"启用模型调用日志记录。"}],"explanation":{"en":"Creating an Amazon Bedrock knowledge base allows the company to supplement the foundation model\nwith relevant data from their private data sources. This ensures that the model has access to the\nadditional, context-specific information needed. The other options do not directly address supplementing\nthe model with private data.","zh":"创建 Amazon Bedrock 知识库可以让公司用其私有数据源中的相关数据来补充基础模型，从而确保模型能够访问所需的额外、上下文相关的信息。其他选项都不能直接实现用私有数据补充模型。"},"tip":{"zh":"要接入私有数据补充模型 → Bedrock 知识库（RAG）；换模型、调温度都补不进私有数据。","en":""},"keywords":["知识库","RAG","私有数据"]},{"id":39,"type":"single","answer":["B"],"topic":"responsible","stem":{"en":"A medical company is customizing a foundation model (FM) for diagnostic purposes. The company needs\nthe model to be transparent and explainable to meet regulatory requirements.\nWhich solution will meet these requirements?","zh":"一家医疗公司正在为诊断目的定制一个基础模型（FM）。该公司需要该模型具有透明性和可解释性，以满足监管要求。\n哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Configure the security and compliance by using Amazon Inspector.","zh":"使用 Amazon Inspector 配置安全与合规。"},{"key":"B","en":"Generate simple metrics, reports, and examples by using Amazon SageMaker Clarify.","zh":"使用 Amazon SageMaker Clarify 生成简单的指标、报告和示例。"},{"key":"C","en":"Encrypt and secure training data by using Amazon Macie.","zh":"使用 Amazon Macie 加密和保护训练数据。"},{"key":"D","en":"Gather more data. Use Amazon Rekognition to add custom labels to the data.","zh":"收集更多数据。使用 Amazon Rekognition 为数据添加自定义标签。"}],"explanation":{"en":"Amazon SageMaker Clarify helps with transparency and explainability by generating metrics, reports, and\nexamples that show how the model makes decisions, which is essential for meeting regulatory\nrequirements. The other options are not directly related to improving the model's transparency or\nexplainability.","zh":"Amazon SageMaker Clarify 通过生成展示模型如何做决策的指标、报告和示例来帮助实现透明性和可解释性，这对于满足监管要求至关重要。其他选项与提升模型的透明性或可解释性没有直接关系。"},"tip":{"zh":"监管要“可解释 + 透明” → SageMaker Clarify 出指标和报告；Inspector、Macie 管安全。","en":""},"keywords":["SageMaker Clarify","可解释性","合规"]},{"id":40,"type":"multi","answer":["B","C"],"topic":"security","stem":{"en":"A company wants to deploy a conversational chatbot to answer customer questions. The chatbot is based\non a fine-tuned Amazon SageMaker JumpStart model. The application must comply with multiple\nregulatory frameworks.\nWhich capabilities can the company show compliance for? (Choose two.)","zh":"一家公司想部署一个对话式聊天机器人来回答客户问题。该聊天机器人基于一个经过微调的 Amazon SageMaker JumpStart 模型。该应用必须符合多个监管框架。\n该公司可以就哪些能力证明合规？（选择两项。）"},"options":[{"key":"A","en":"Auto scaling inference endpoints","zh":"推理端点自动扩缩容"},{"key":"B","en":"Threat detection","zh":"威胁检测"},{"key":"C","en":"Data protection","zh":"数据保护"},{"key":"D","en":"Cost optimization","zh":"成本优化"},{"key":"E","en":"Loosely coupled microservices","zh":"松耦合微服务"}],"explanation":{"en":"Threat detection: Ensuring security measures are in place to detect threats is important for compliance\nwith regulatory frameworks.\nData protection: Proper data handling and protection measures are key compliance aspects, especially in\napplications dealing with sensitive customer information.\nThe other options (auto scaling, cost optimization, and loosely coupled microservices) are more related to\nperformance and architecture rather than regulatory compliance.","zh":"威胁检测：确保有相应的安全措施来检测威胁，对于符合监管框架很重要。\n数据保护：恰当的数据处理和保护措施是关键合规要素，尤其是处理敏感客户信息的应用。\n其他选项（自动扩缩容、成本优化和松耦合微服务）更多与性能和架构相关，而不是与监管合规相关。"},"tip":{"zh":"合规关注“安全”和“数据” → 威胁检测 + 数据保护；扩缩容、成本、架构不算合规能力。","en":""},"keywords":["合规","威胁检测","数据保护"]},{"id":41,"type":"single","answer":["B"],"topic":"eval","stem":{"en":"A company is training a foundation model (FM). The company wants to increase the accuracy of the model\nup to a specific acceptance level.\nWhich solution will meet these requirements?","zh":"一家公司正在训练一个基础模型（FM）。该公司想把模型的准确率提升到某个可接受的特定水平。\n哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Decrease the batch size.","zh":"减小批大小（batch size）。"},{"key":"B","en":"Increase the epochs.","zh":"增加轮次（epochs）数量。"},{"key":"C","en":"Decrease the epochs.","zh":"减少轮次（epochs）数量。"},{"key":"D","en":"Increase the temperature parameter.","zh":"提高温度（temperature）参数。"}],"explanation":{"en":"Increasing the number of epochs allows the model to train for more iterations, improving its accuracy until\nthe model reaches an optimal level. The other options are either less effective or unrelated to improving\naccuracy.","zh":"增加轮次数量可以让模型训练更多迭代，从而提高准确率，直到模型达到最优水平。其他选项要么效果较差，要么与提升准确率无关。"},"tip":{"zh":"要提高准确率就多训几轮 → 增加 epochs；温度是推理参数，跟训练准确率无关。","en":""},"keywords":["epochs","准确率","超参数"]},{"id":42,"type":"single","answer":["B"],"topic":"eval","stem":{"en":"A company is building a large language model (LLM) question answering chatbot. The company wants to\ndecrease the number of actions call center employees need to take to respond to customer questions.\nWhich business objective should the company use to evaluate the effect of the LLM chatbot?","zh":"一家公司正在构建一个基于大型语言模型（LLM）的问答聊天机器人。该公司希望减少呼叫中心员工回应客户问题所需执行的操作数量。\n该公司应使用哪项业务目标来评估该 LLM 聊天机器人的效果？"},"options":[{"key":"A","en":"Website engagement rate","zh":"网站互动率"},{"key":"B","en":"Average call duration","zh":"平均通话时长"},{"key":"C","en":"Corporate social responsibility","zh":"企业社会责任"},{"key":"D","en":"Regulatory compliance","zh":"监管合规"}],"explanation":{"en":"Reducing the average call duration directly indicates how effectively the LLM chatbot is helping call center\nemployees answer customer questions, thus reducing the number of actions needed. The other options\nare not directly related to the performance of a call center chatbot.","zh":"平均通话时长缩短，直接说明 LLM 聊天机器人在帮助呼叫中心员工回答客户问题方面有多有效，从而减少了所需执行的操作数量。其他选项与呼叫中心聊天机器人的表现没有直接关系。"},"tip":{"zh":"衡量“员工少做了多少操作” → 平均通话时长；网站互动率跟呼叫中心无关。","en":""},"keywords":["业务指标","平均通话时长","LLM 效果评估"]},{"id":43,"type":"single","answer":["D"],"topic":"responsible","stem":{"en":"Which functionality does Amazon SageMaker Clarify provide?","zh":"Amazon SageMaker Clarify 提供哪项功能？"},"options":[{"key":"A","en":"Integrates a Retrieval Augmented Generation (RAG) workflow","zh":"集成检索增强生成（RAG）工作流"},{"key":"B","en":"Monitors the quality of ML models in production","zh":"监控生产环境中 ML 模型的质量"},{"key":"C","en":"Documents critical details about ML models","zh":"记录 ML 模型的关键细节"},{"key":"D","en":"Identifies potential bias during data preparation","zh":"在数据准备阶段识别潜在偏见"}],"explanation":{"en":"Amazon SageMaker Clarify helps detect potential bias in datasets and models during data preparation,\ntraining, and deployment. It also provides tools for explainability. The other options are functionalities that\ndo not directly match SageMaker Clarify's core features.","zh":"Amazon SageMaker Clarify 有助于在数据准备、训练和部署阶段检测数据集和模型中的潜在偏见，同时还提供可解释性工具。其他选项的功能与 SageMaker Clarify 的核心特性并不直接对应。"},"tip":{"zh":"Clarify = 查偏见 + 做可解释；模型质量监控是 Model Monitor，模型文档是 Model Cards。","en":""},"keywords":["SageMaker Clarify","偏见检测","可解释性"]},{"id":44,"type":"single","answer":["C"],"topic":"eval","stem":{"en":"A company is developing a new model to predict the prices of specific items. The model performed well on\nthe training dataset. When the company deployed the model to production, the model's performance\ndecreased significantly.\nWhat should the company do to mitigate this problem?","zh":"一家公司正在开发一个新模型来预测特定商品的价格。该模型在训练数据集上表现良好。当该公司把模型部署到生产环境后，模型性能显著下降。\n该公司应做什么来缓解这个问题？"},"options":[{"key":"A","en":"Reduce the volume of data that is used in training.","zh":"减少训练中使用的数据量。"},{"key":"B","en":"Add hyperparameters to the model.","zh":"为模型添加超参数。"},{"key":"C","en":"Increase the volume of data that is used in training.","zh":"增加训练中使用的数据量。"},{"key":"D","en":"Increase the model training time.","zh":"延长模型训练时间。"}],"explanation":{"en":"Increasing the volume of data used in training helps the model generalize better to new, unseen data,\nreducing overfitting and improving performance in production. The other options either do not address the\nissue of model generalization or are unlikely to effectively solve the problem.","zh":"增加训练中使用的数据量有助于模型更好地泛化到新的、未见过的数据，从而减少过拟合并改善生产环境中的性能。其他选项要么没有解决模型泛化问题，要么不太可能有效解决问题。"},"tip":{"zh":"训练好、上线差 = 过拟合 → 加数据；减数据、加超参数只会更糟。","en":""},"keywords":["过拟合","泛化","数据量"]},{"id":45,"type":"multi","answer":["B","D"],"topic":"genai","stem":{"en":"An ecommerce company wants to build a solution to determine customer sentiments based on written\ncustomer reviews of products.\nWhich AWS services meet these requirements? (Choose two.)","zh":"一家电商公司想构建一个解决方案，根据书面商品评价判断客户情感。\n哪些 AWS 服务能满足这些要求？（选择两项。）"},"options":[{"key":"A","en":"Amazon Lex","zh":"Amazon Lex"},{"key":"B","en":"Amazon Comprehend","zh":"Amazon Comprehend"},{"key":"C","en":"Amazon Polly","zh":"Amazon Polly"},{"key":"D","en":"Amazon Bedrock","zh":"Amazon Bedrock"},{"key":"E","en":"Amazon Rekognition","zh":"Amazon Rekognition"}],"explanation":{"en":"Amazon Comprehend: This service is specifically designed for natural language processing (NLP) tasks,\nincluding sentiment analysis, making it ideal for analyzing customer reviews.\nAmazon Bedrock: Bedrock can be used to leverage foundation models, which can also be employed for\nsentiment analysis tasks.\nThe other options are not suitable for sentiment analysis of written customer reviews.","zh":"Amazon Comprehend：该服务专为自然语言处理（NLP）任务（包括情感分析）而设计，因此非常适合分析客户评价。\nAmazon Bedrock：Bedrock 可以利用基础模型，而这些模型同样可用于情感分析任务。\n其他选项不适合对书面客户评价进行情感分析。"},"tip":{"zh":"文本情感分析 → Comprehend（专用）+ Bedrock（FM）；Lex 是对话，Polly 是语音合成。","en":""},"keywords":["情感分析","Comprehend","Bedrock"]},{"id":46,"type":"single","answer":["D"],"topic":"genai","stem":{"en":"A company wants to use large language models (LLMs) with Amazon Bedrock to develop a chat interface\nfor the company's product manuals. The manuals are stored as PDF files.\nWhich solution meets these requirements MOST cost-effectively?","zh":"一家公司想使用 Amazon Bedrock 上的大型语言模型（LLM）为公司产品手册开发一个聊天界面。这些手册以 PDF 文件形式存储。\n哪种解决方案能以最具成本效益的方式满足这些要求？"},"options":[{"key":"A","en":"Use prompt engineering to add one PDF file as context to the user prompt when the prompt is submitted to Amazon Bedrock.","zh":"使用提示工程，在向 Amazon Bedrock 提交提示词时把一个 PDF 文件作为上下文加入用户提示词。"},{"key":"B","en":"Use prompt engineering to add all the PDF files as context to the user prompt when the prompt is submitted to Amazon Bedrock.","zh":"使用提示工程，在向 Amazon Bedrock 提交提示词时把所有 PDF 文件作为上下文加入用户提示词。"},{"key":"C","en":"Use all the PDF documents to fine-tune a model with Amazon Bedrock. Use the fine-tuned model to process user prompts.","zh":"使用全部 PDF 文档通过 Amazon Bedrock 微调一个模型。使用该微调后的模型处理用户提示词。"},{"key":"D","en":"Upload PDF documents to an Amazon Bedrock knowledge base. Use the knowledge base to provide context when users submit prompts to Amazon Bedrock.","zh":"把 PDF 文档上传到 Amazon Bedrock 知识库。当用户向 Amazon Bedrock 提交提示词时，使用该知识库提供上下文。"}],"explanation":{"en":"Using an Amazon Bedrock knowledge base allows the model to efficiently access relevant information\nfrom the PDF manuals when needed, reducing the cost compared to continuously fine-tuning a model or\nproviding all PDFs as context in each prompt. This approach ensures that only necessary context is\nprovided, making it cost-effective.","zh":"使用 Amazon Bedrock 知识库可以让模型在需要时高效地访问 PDF 手册中的相关信息，与持续微调模型或在每次提示中都提供全部 PDF 相比，成本更低。这种方法确保只提供必要的上下文，因而具有成本效益。"},"tip":{"zh":"大量 PDF 要按需检索 → 知识库（RAG）最省钱；把所有 PDF 塞进提示词会爆 token。","en":""},"keywords":["知识库","RAG","成本优化","PDF"]},{"id":47,"type":"single","answer":["D"],"topic":"responsible","stem":{"en":"A social media company wants to use a large language model (LLM) for content moderation. The\ncompany wants to evaluate the LLM outputs for bias and potential discrimination against specific groups or\nindividuals.\nWhich data source should the company use to evaluate the LLM outputs with the LEAST administrative\neffort?","zh":"一家社交媒体公司想使用大型语言模型（LLM）进行内容审核。该公司想评估 LLM 的输出是否存在针对特定群体或个人的偏见和潜在歧视。\n该公司应使用哪种数据源来以最少的管理工作量评估 LLM 的输出？"},"options":[{"key":"A","en":"User-generated content","zh":"用户生成内容"},{"key":"B","en":"Moderation logs","zh":"审核日志"},{"key":"C","en":"Content moderation guidelines","zh":"内容审核指南"},{"key":"D","en":"Benchmark datasets","zh":"基准数据集（Benchmark datasets）"}],"explanation":{"en":"Benchmark datasets are standardized datasets specifically designed for evaluating models for bias and\nfairness, allowing for efficient assessment with minimal administrative effort. The other options would\nrequire more manual processing and might not provide a consistent basis for evaluating bias and\ndiscrimination.","zh":"基准数据集是专为评估模型的偏见和公平性而设计的标准化数据集，能以最少的管理工作量实现高效评估。其他选项需要更多人工处理，并且可能无法为评估偏见和歧视提供一致的基准。"},"tip":{"zh":"要省人力地评偏见 → 现成的基准数据集；用户内容和日志还得自己清洗标注。","en":""},"keywords":["基准数据集","偏见评估","公平性"]},{"id":48,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"A company wants to use a pre-trained generative AI model to generate content for its marketing\ncampaigns. The company needs to ensure that the generated content aligns with the company's brand\nvoice and messaging requirements.\nWhich solution meets these requirements?","zh":"一家公司想使用预训练的生成式 AI 模型为其营销活动生成内容。该公司需要确保生成的内容符合公司的品牌语气和传播要求。\n哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Optimize the model's architecture and hyperparameters to improve the model's overall performance.","zh":"优化模型的架构和超参数，以提升模型的整体性能。"},{"key":"B","en":"Increase the model's complexity by adding more layers to the model's architecture.","zh":"通过向模型架构中添加更多层来提高模型复杂度。"},{"key":"C","en":"Create effective prompts that provide clear instructions and context to guide the model's generation.","zh":"创建有效的提示词，提供清晰的指令和上下文来引导模型生成。"},{"key":"D","en":"Select a large, diverse dataset to pre-train a new generative model.","zh":"选择一个大型、多样的数据集来预训练一个新的生成式模型。"}],"explanation":{"en":"Creating effective prompts helps guide the pre-trained generative AI model to produce content that aligns\nwith the company's brand voice and messaging. The other options either involve model architecture\nchanges or require extensive training, which are not necessary for aligning content generation.","zh":"创建有效的提示词有助于引导预训练的生成式 AI 模型生成符合公司品牌语气和传播要求的内容。其他选项要么涉及修改模型架构，要么需要大量训练，而这些对于对齐内容生成并非必要。"},"tip":{"zh":"预训练模型要贴合品牌语气 → 靠提示词引导；改架构、重新预训练成本太高。","en":""},"keywords":["提示工程","品牌语气","内容生成"]},{"id":49,"type":"multi","answer":["A","C"],"topic":"responsible","stem":{"en":"A loan company is building a generative AI-based solution to offer new applicants discounts based on\nspecific business criteria. The company wants to build and use an AI model responsibly to minimize bias\nthat could negatively affect some customers.\nWhich actions should the company take to meet these requirements? (Choose two.)","zh":"一家贷款公司正在构建一个基于生成式 AI 的解决方案，根据特定业务标准为新申请人提供折扣。该公司希望负责任地构建和使用 AI 模型，以尽量减少可能对部分客户产生负面影响的偏见。\n该公司应采取哪些行动来满足这些要求？（选择两项。）"},"options":[{"key":"A","en":"Detect imbalances or disparities in the data.","zh":"检测数据中的不平衡或不均等现象。"},{"key":"B","en":"Ensure that the model runs frequently.","zh":"确保模型频繁运行。"},{"key":"C","en":"Evaluate the model's behavior so that the company can provide transparency to stakeholders.","zh":"评估模型的行为，以便公司能够向利益相关者提供透明度。"},{"key":"D","en":"Use the Recall-Oriented Understudy for Gisting Evaluation (ROUGE) technique to ensure that the model is 100% accurate.","zh":"使用面向召回率的要点评估替身（ROUGE）技术来确保模型 100% 准确。"},{"key":"E","en":"Ensure that the model's inference time is within the accepted limits.","zh":"确保模型的推理时间在可接受范围内。"}],"explanation":{"en":"Detect imbalances or disparities in the data: Identifying and addressing data imbalances helps\nminimize biases that could negatively affect customers.\nEvaluate the model's behavior so that the company can provide transparency to stakeholders:\nEvaluating the model and ensuring transparency is important for responsible AI usage, as it helps\nstakeholders understand how decisions are made.\nThe other options are either not directly related to minimizing bias or do not address responsible AI\ndevelopment.","zh":"检测数据中的不平衡或不均等现象：识别并处理数据不平衡有助于减少可能对客户产生负面影响的偏见。\n评估模型的行为，以便公司能够向利益相关者提供透明度：评估模型并确保透明度对于负责任地使用 AI 很重要，因为这有助于利益相关者理解决策是如何做出的。\n其他选项要么与减少偏见没有直接关系，要么没有涉及负责任的 AI 开发。"},"tip":{"zh":"负责任 AI 两件事 → 查数据不平衡 + 评估行为保透明；跑得勤、跑得快都不算公平性。","en":""},"keywords":["负责任 AI","偏见","透明度","数据不平衡"]},{"id":50,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"A company is using an Amazon Bedrock base model to summarize documents for an internal use case.\nThe company trained a custom model to improve the summarization quality.\nWhich action must the company take to use the custom model through Amazon Bedrock?","zh":"一家公司正在使用 Amazon Bedrock 上的基础模型来为内部用例做文档摘要。该公司训练了一个自定义模型以提升摘要质量。\n该公司必须采取哪项行动才能通过 Amazon Bedrock 使用该自定义模型？"},"options":[{"key":"A","en":"Purchase Provisioned Throughput for the custom model.","zh":"为该自定义模型购买预置吞吐量（Provisioned Throughput）。"},{"key":"B","en":"Deploy the custom model in an Amazon SageMaker endpoint for real-time inference.","zh":"将该自定义模型部署到 Amazon SageMaker 端点以进行实时推理。"},{"key":"C","en":"Register the model with the Amazon SageMaker Model Registry.","zh":"将该模型注册到 Amazon SageMaker Model Registry。"},{"key":"D","en":"Grant access to the custom model in Amazon Bedrock.","zh":"在 Amazon Bedrock 中授予对该自定义模型的访问权限。"}],"explanation":{"en":"","zh":""},"tip":{"zh":"Bedrock 里用自定义模型必须先买预置吞吐量；SageMaker 端点就绕开了 Bedrock。","en":""},"keywords":["预置吞吐量","自定义模型","Bedrock"]},{"id":51,"type":"single","answer":["B"],"topic":"eval","stem":{"en":"A company needs to choose a model from Amazon Bedrock to use internally. The company must identify a\nmodel that generates responses in a style that the company's employees prefer.\nWhat should the company do to meet these requirements?","zh":"一家公司需要从 Amazon Bedrock 中选择一个模型供内部使用。该公司必须找出一个能以公司员工偏好的风格生成响应的模型。\n该公司应做什么来满足这些要求？"},"options":[{"key":"A","en":"Evaluate the models by using built-in prompt datasets.","zh":"使用内置提示词数据集评估这些模型。"},{"key":"B","en":"Evaluate the models by using a human workforce and custom prompt datasets.","zh":"使用人工团队和自定义提示词数据集评估这些模型。"},{"key":"C","en":"Use public model leaderboards to identify the model.","zh":"使用公开的模型排行榜来确定模型。"},{"key":"D","en":"Use the model InvocationLatency runtime metrics in Amazon CloudWatch when trying models.","zh":"在试用模型时使用 Amazon CloudWatch 中的 InvocationLatency 运行时指标。"}],"explanation":{"en":"Evaluating models using a human workforce and custom prompt datasets ensures that the model\ngenerates responses in the style that aligns with the company’s preferences. The other options either do\nnot provide direct feedback on style preferences or are not specific enough for determining suitability\nbased on employee preferences.","zh":"使用人工团队和自定义提示词数据集评估模型，可以确保模型生成的响应风格符合公司的偏好。其他选项要么无法提供关于风格偏好的直接反馈，要么不够具体，无法根据员工偏好判断适用性。"},"tip":{"zh":"要贴合“员工喜好风格” → 人工评估 + 自定义提示词；公开榜单和延迟指标都不管风格。","en":""},"keywords":["人工评估","模型选择","自定义数据集"]},{"id":52,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"A student at a university is copying content from generative AI to write essays.\nWhich challenge of responsible generative AI does this scenario represent?\nD","zh":"一名大学生在撰写论文时抄袭生成式 AI 生成的内容。\n这一场景代表了负责任生成式 AI 的哪项挑战？"},"options":[{"key":"A","en":"Toxicity","zh":"毒性（Toxicity）"},{"key":"B","en":"Hallucinations","zh":"幻觉（Hallucinations）"},{"key":"C","en":"Plagiarism","zh":"抄袭（Plagiarism）"},{"key":"D","en":"Privacy","zh":"隐私（Privacy）"}],"explanation":{"en":"Copying content from generative AI to write essays without proper attribution constitutes plagiarism, which\nis a key challenge of responsible generative AI. The other options are unrelated to this specific issue.","zh":"未注明出处就抄袭生成式 AI 生成的内容来撰写论文，构成抄袭，这是负责任生成式 AI 的一项关键挑战。其他选项与这一具体问题无关。"},"tip":{"zh":"把 AI 内容当自己写的 → 抄袭；幻觉是内容假，隐私是泄露数据。","en":""},"keywords":["抄袭","负责任 AI","生成式 AI 挑战"]},{"id":53,"type":"single","answer":["D"],"topic":"genai","stem":{"en":"A company needs to build its own large language model (LLM) based on only the company's private data.\nThe company is concerned about the environmental effect of the training process.\nWhich Amazon EC2 instance type has the LEAST environmental effect when training LLMs?","zh":"一家公司需要仅基于公司的私有数据构建自己的大型语言模型（LLM）。该公司担心训练过程对环境的影响。\n哪种 Amazon EC2 实例类型在训练 LLM 时对环境的影响最小？"},"options":[{"key":"A","en":"Amazon EC2 C series","zh":"Amazon EC2 C 系列"},{"key":"B","en":"Amazon EC2 G series","zh":"Amazon EC2 G 系列"},{"key":"C","en":"Amazon EC2 P series","zh":"Amazon EC2 P 系列"},{"key":"D","en":"Amazon EC2 Trn series","zh":"Amazon EC2 Trn 系列"}],"explanation":{"en":"Amazon EC2 Trn series instances (powered by AWS Trainium chips) are designed to provide efficient and\nenvironmentally friendly training of large machine learning models. They are optimized for energy\nefficiency, which reduces the environmental impact of the training process. The other instance types are\nnot specifically optimized for minimizing environmental effects during training.","zh":"Amazon EC2 Trn 系列实例（由 AWS Trainium 芯片驱动）专为高效且环保地训练大型机器学习模型而设计。它们针对能效进行了优化，可降低训练过程对环境的影响。其他实例类型并未专门针对训练期间最小化环境影响进行优化。"},"tip":{"zh":"要环保又省电地训练 → Trainium 的 Trn 系列；P/G 系列是通用 GPU 训练。","en":""},"keywords":["Trainium","能效","可持续性"]},{"id":54,"type":"single","answer":["C"],"topic":"responsible","stem":{"en":"A company wants to build an interactive application for children that generates new stories based on\nclassic stories. The company wants to use Amazon Bedrock and needs to ensure that the results and\ntopics are appropriate for children.\nWhich AWS service or feature will meet these requirements?","zh":"一家公司想为儿童构建一个互动应用，根据经典故事生成新故事。该公司想使用 Amazon Bedrock，并需要确保生成的结果和主题适合儿童。\n哪种 AWS 服务或功能能满足这些要求？"},"options":[{"key":"A","en":"Amazon Rekognition","zh":"Amazon Rekognition"},{"key":"B","en":"Amazon Bedrock playgrounds","zh":"Amazon Bedrock playgrounds"},{"key":"C","en":"Guardrails for Amazon Bedrock","zh":"Guardrails for Amazon Bedrock"},{"key":"D","en":"Agents for Amazon Bedrock","zh":"Agents for Amazon Bedrock"}],"explanation":{"en":"Guardrails for Amazon Bedrock can help ensure that the output generated by Amazon Bedrock is\nappropriate for children. Guardrails are used to apply content moderation, guidelines, and ensure safety by\nfiltering potentially harmful or inappropriate content, which is essential when building an interactive\napplication for children.","zh":"Guardrails for Amazon Bedrock 有助于确保 Amazon Bedrock 生成的输出适合儿童。护栏用于实施内容审核、准则，并通过过滤潜在有害或不适当的内容来确保安全，这在为儿童构建互动应用时至关重要。"},"tip":{"zh":"要过滤不当内容 → 护栏（Guardrails）；playgrounds 只是试用界面，不做过滤。","en":""},"keywords":["护栏","内容审核","儿童安全"]},{"id":55,"type":"single","answer":["A"],"topic":"general","stem":{"en":"A company is building an application that needs to generate synthetic data that is based on existing data.\nWhich type of model can the company use to meet this requirement?","zh":"一家公司正在构建一个应用，需要基于现有数据生成合成数据。\n该公司可以使用哪种类型的模型来满足这一要求？"},"options":[{"key":"A","en":"Generative adversarial network (GAN)","zh":"生成对抗网络（GAN）"},{"key":"B","en":"XGBoost","zh":"XGBoost"},{"key":"C","en":"Residual neural network","zh":"残差神经网络"},{"key":"D","en":"WaveNet","zh":"WaveNet"}],"explanation":{"en":"","zh":""},"tip":{"zh":"生成合成数据 → GAN（生成器造假、判别器打假）；XGBoost 是表格分类回归。","en":""},"keywords":["GAN","合成数据","生成模型"]},{"id":56,"type":"single","answer":["D"],"topic":"sagemaker","stem":{"en":"A digital devices company wants to predict customer demand for memory hardware. The company does\nnot have coding experience or knowledge of ML algorithms and needs to develop a data-driven predictive\nmodel. The company needs to perform analysis on internal data and external data.\nWhich solution will meet these requirements?","zh":"一家数字设备公司想预测客户对内存硬件的需求。该公司没有编程经验，也不了解 ML 算法，需要开发一个数据驱动的预测模型。该公司需要对内部数据和外部数据进行分析。\n哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Store the data in Amazon S3. Create ML models and demand forecast predictions by using Amazon SageMaker built-in algorithms that use the data from Amazon S3.","zh":"把数据存储在 Amazon S3 中。使用 Amazon SageMaker 内置算法并利用 Amazon S3 中的数据来创建 ML 模型和需求预测。"},{"key":"B","en":"Import the data into Amazon SageMaker Data Wrangler. Create ML models and demand forecast predictions by using SageMaker built-in algorithms.","zh":"把数据导入 Amazon SageMaker Data Wrangler。使用 SageMaker 内置算法创建 ML 模型和需求预测。"},{"key":"C","en":"Import the data into Amazon SageMaker Data Wrangler. Build ML models and demand forecast predictions by using an Amazon Personalize Trending-Now recipe.","zh":"把数据导入 Amazon SageMaker Data Wrangler。使用 Amazon Personalize 的 Trending-Now 配方构建 ML 模型和需求预测。"},{"key":"D","en":"Import the data into Amazon SageMaker Canvas. Build ML models and demand forecast predictions by selecting the values in the data from SageMaker Canvas.","zh":"把数据导入 Amazon SageMaker Canvas。通过选择 SageMaker Canvas 中数据的值来构建 ML 模型和需求预测。"}],"explanation":{"en":"Amazon SageMaker Canvas is a no-code tool that allows users to build ML models and make predictions\nwithout requiring programming knowledge. It is ideal for users with no coding experience, providing an\neasy interface for importing data and generating predictive models. The other options require more\ntechnical expertise or are not designed for no-code model building.","zh":"Amazon SageMaker Canvas 是一款无代码工具，让用户无需编程知识即可构建 ML 模型并做出预测。它非常适合没有编码经验的用户，提供易于使用的界面来导入数据和生成预测模型。其他选项需要更多技术专长，或者并非为无代码建模而设计。"},"tip":{"zh":"无代码 + 不会算法 → SageMaker Canvas；内置算法和 Data Wrangler 都还要写代码。","en":""},"keywords":["SageMaker Canvas","无代码","需求预测"]},{"id":57,"type":"single","answer":["B"],"topic":"responsible","stem":{"en":"A company has installed a security camera. The company uses an ML model to evaluate the security\ncamera footage for potential thefts. The company has discovered that the model disproportionately flags\npeople who are members of a specific ethnic group.\nWhich type of bias is affecting the model output?","zh":"一家公司安装了一台安防摄像头。该公司使用 ML 模型评估安防摄像头录像中可能存在的盗窃行为。该公司发现该模型会不成比例地标记某一特定族裔群体的成员。\n哪种类型的偏见正在影响模型输出？"},"options":[{"key":"A","en":"Measurement bias","zh":"测量偏见（Measurement bias）"},{"key":"B","en":"Sampling bias","zh":"抽样偏见（Sampling bias）"},{"key":"C","en":"Observer bias","zh":"观察者偏见（Observer bias）"},{"key":"D","en":"Confirmation bias","zh":"确认偏见（Confirmation bias）"}],"explanation":{"en":"Sampling bias occurs when the training data is not representative of the overall population, leading to\ndisproportionate flagging of specific groups. In this case, the model may have been trained on biased data\nthat did not adequately represent all ethnic groups, resulting in skewed predictions. The other types of bias\ndo not directly apply to the selection of training data or its representativeness.","zh":"当训练数据不能代表整体人群时，就会产生抽样偏见，导致对特定群体不成比例地标记。在本例中，模型可能是用有偏见的、未能充分代表所有族裔群体的数据训练的，因而产生了偏斜的预测。其他类型的偏见并不直接适用于训练数据的选择或其代表性。"},"tip":{"zh":"训练数据没覆盖全人群 → 抽样偏见；这是数据代表性问题的标准答案。","en":""},"keywords":["抽样偏见","训练数据代表性","公平性"]},{"id":58,"type":"single","answer":["B"],"topic":"general","stem":{"en":"A company is building a customer service chatbot. The company wants the chatbot to improve its\nresponses by learning from past interactions and online resources.\nWhich AI learning strategy provides this self-improvement capability?","zh":"一家公司正在构建一个客户服务聊天机器人。该公司希望该聊天机器人通过从过去的交互和在线资源中学习来改进其响应。\n哪种 AI 学习策略提供这种自我改进能力？"},"options":[{"key":"A","en":"Supervised learning with a manually curated dataset of good responses and bad responses","zh":"使用由优质响应和劣质响应人工整理的数据集进行监督式学习"},{"key":"B","en":"Reinforcement learning with rewards for positive customer feedback","zh":"使用针对正面客户反馈给予奖励的强化学习"},{"key":"C","en":"Unsupervised learning to find clusters of similar customer inquiries","zh":"使用无监督学习来发现相似客户咨询的聚类"},{"key":"D","en":"Supervised learning with a continuously updated FAQ database","zh":"使用持续更新的 FAQ 数据库进行监督式学习"}],"explanation":{"en":"Reinforcement learning allows the chatbot to learn from interactions by receiving rewards for positive\ncustomer feedback, which helps the model self-improve over time. The other options do not directly\nprovide a mechanism for continuous self-improvement based on interactions.","zh":"强化学习让聊天机器人通过获得正面客户反馈的奖励来从交互中学习，这有助于模型随着时间推移自我改进。其他选项都不能直接提供基于交互持续自我改进的机制。"},"tip":{"zh":"靠反馈奖励越用越好 → 强化学习；监督式学习要人先标注，不会自己进化。","en":""},"keywords":["强化学习","自我改进","奖励机制"]},{"id":59,"type":"single","answer":["A"],"topic":"eval","stem":{"en":"An AI practitioner has built a deep learning model to classify the types of materials in images. The AI\npractitioner now wants to measure the model performance.\nWhich metric will help the AI practitioner evaluate the performance of the model?","zh":"一位 AI 从业者构建了一个深度学习模型来对图像中的材料类型进行分类。该 AI 从业者现在想衡量模型性能。\n哪种指标能帮助该 AI 从业者评估模型性能？"},"options":[{"key":"A","en":"Confusion matrix","zh":"混淆矩阵"},{"key":"B","en":"Correlation matrix","zh":"相关性矩阵"},{"key":"C","en":"R2 score","zh":"R2 分数"},{"key":"D","en":"Mean squared error (MSE)","zh":"均方误差（MSE）"}],"explanation":{"en":"A confusion matrix provides detailed insights into the performance of a classification model by showing the\ntrue positives, false positives, true negatives, and false negatives. This metric helps evaluate how well the\nmodel classifies the different types of materials in images. The other metrics are not as suitable for\nevaluating a classification model.","zh":"混淆矩阵通过展示真正例、假正例、真负例和假负例，提供关于分类模型性能的详细洞察。该指标有助于评估模型对图像中不同材料类型的分类效果。其他指标不太适合评估分类模型。"},"tip":{"zh":"分类模型看表现 → 混淆矩阵；R2 和 MSE 是回归指标。","en":""},"keywords":["混淆矩阵","分类评估","指标选择"]},{"id":60,"type":"single","answer":["A"],"topic":"general","stem":{"en":"A company has built a chatbot that can respond to natural language questions with images. The company\nwants to ensure that the chatbot does not return inappropriate or unwanted images.\nWhich solution will meet these requirements?","zh":"一家公司构建了一个聊天机器人，能够用图像回答自然语言问题。该公司希望确保该聊天机器人不会返回不适当或不想要的图像。\n哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Implement moderation APIs.","zh":"实施审核（moderation）API。"},{"key":"B","en":"Retrain the model with a general public dataset.","zh":"使用通用的公开数据集重新训练模型。"},{"key":"C","en":"Perform model validation.","zh":"执行模型验证。"},{"key":"D","en":"Automate user feedback integration.","zh":"自动化用户反馈集成。"}],"explanation":{"en":"Implementing moderation APIs can help filter and block inappropriate or unwanted images before they are\nreturned by the chatbot. The other options do not directly address ensuring that the chatbot avoids\nreturning inappropriate images.","zh":"实施审核 API 有助于在聊天机器人返回图像之前过滤并拦截不适当或不想要的图像。其他选项都不能直接确保聊天机器人避免返回不适当的图像。"},"tip":{"zh":"要拦住不雅图像 → 审核 API 过滤；重训和验证都管不住实时输出。","en":""},"keywords":["内容审核","图像过滤","安全护栏"]},{"id":61,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"An AI practitioner is using an Amazon Bedrock base model to summarize session chats from the customer\nservice department. The AI practitioner wants to store invocation logs to monitor model input and output\ndata.\nWhich strategy should the AI practitioner use?","zh":"一位 AI 从业者正在使用 Amazon Bedrock 的基础模型对客服部门的会话聊天记录进行摘要。该从业者希望存储调用日志，以监控模型的输入和输出数据。该从业者应使用哪种策略？"},"options":[{"key":"A","en":"Configure AWS CloudTrail as the logs destination for the model.","zh":"将 AWS CloudTrail 配置为该模型的日志目标。"},{"key":"B","en":"Enable model invocation logging in Amazon Bedrock.","zh":"在 Amazon Bedrock 中启用模型调用日志记录。"},{"key":"C","en":"Configure AWS Audit Manager as the logs destination for the model.","zh":"将 AWS Audit Manager 配置为该模型的日志目标。"},{"key":"D","en":"Configure model invocation logging in Amazon EventBridge.","zh":"在 Amazon EventBridge 中配置模型调用日志记录。"}],"explanation":{"en":"Enabling invocation logging in Amazon Bedrock allows the AI practitioner to monitor and store the input\nand output data for model invocations. The other options are not directly used for logging model\ninvocations in Amazon Bedrock.","zh":"在 Amazon Bedrock 中启用调用日志记录，可以让从业者监控并存储模型调用的输入和输出数据。其他选项并不直接用于在 Amazon Bedrock 中记录模型调用日志。"},"tip":{"zh":"要看模型的输入和输出内容 → 开 Bedrock 模型调用日志；CloudTrail 只记 API 调用行为。","en":""},"keywords":["模型调用日志","Amazon Bedrock","输入输出监控"]},{"id":62,"type":"single","answer":["A"],"topic":"sagemaker","stem":{"en":"A company is building an ML model to analyze archived data. The company must perform inference on\nlarge datasets that are multiple GBs in size. The company does not need to access the model predictions\nimmediately.\nWhich Amazon SageMaker inference option will meet these requirements?","zh":"某公司正在构建一个 ML 模型来分析归档数据。公司必须对多个 GB 规模的大型数据集执行推理。公司不需要立即获取模型的预测结果。哪种 Amazon SageMaker 推理选项能满足这些要求？"},"options":[{"key":"A","en":"Batch transform","zh":"批量转换"},{"key":"B","en":"Real-time inference","zh":"实时推理"},{"key":"C","en":"Serverless inference","zh":"无服务器推理"},{"key":"D","en":"Asynchronous inference","zh":"异步推理"}],"explanation":{"en":"Batch transform is ideal for processing large datasets that do not require real-time predictions. It allows the\ncompany to perform inference on multiple GBs of data efficiently without needing immediate results. The\nother options are more suitable for scenarios requiring real-time or near real-time access.","zh":"批量转换非常适合处理不需要实时预测的大型数据集。它让公司能够高效地对多个 GB 的数据执行推理，而无需立即获得结果。其他选项更适合需要实时或近实时访问的场景。"},"tip":{"zh":"GB 级大数据集又不急着要结果 → 批量转换；要即时返回才选实时推理。","en":""},"keywords":["批量转换","大数据集","离线推理"]},{"id":63,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"Which term describes the numerical representations of real-world objects and concepts that AI and natural\nlanguage processing (NLP) models use to improve understanding of textual information?","zh":"哪个术语描述的是 AI 和自然语言处理（NLP）模型用来提升对文本信息理解能力的、真实世界对象和概念的数值表示？"},"options":[{"key":"A","en":"Embeddings","zh":"嵌入向量"},{"key":"B","en":"Tokens","zh":"词元（token）"},{"key":"C","en":"Models","zh":"模型"},{"key":"D","en":"Binaries","zh":"二进制文件"}],"explanation":{"en":"Embeddings are numerical representations of real-world objects and concepts that help AI and NLP\nmodels understand and work with textual information more effectively by capturing relationships and\nsimilarities between words or phrases. The other options do not describe this concept.","zh":"嵌入向量是真实世界对象和概念的数值表示，通过捕捉词或短语之间的关系和相似性，帮助 AI 和 NLP 模型更有效地理解和处理文本信息。其他选项不描述这一概念。"},"tip":{"zh":"数值表示 + 语义相似度 → 嵌入向量；词元只是文本切分后的片段。","en":""},"keywords":["嵌入向量","数值表示","NLP"]},{"id":64,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"A research company implemented a chatbot by using a foundation model (FM) from Amazon Bedrock. The\nchatbot searches for answers to questions from a large database of research papers.\nAfter multiple prompt engineering attempts, the company notices that the FM is performing poorly because\nof the complex scientific terms in the research papers.\nHow can the company improve the performance of the chatbot?","zh":"某研究公司使用 Amazon Bedrock 的基础模型（FM）实现了一个聊天机器人。该聊天机器人从庞大的研究论文数据库中检索问题的答案。经过多次提示工程尝试后，公司发现该 FM 因为研究论文中的复杂科学术语而表现不佳。公司应如何提升该聊天机器人的性能？"},"options":[{"key":"A","en":"Use few-shot prompting to define how the FM can answer the questions.","zh":"使用少样本提示来定义该 FM 如何回答问题。"},{"key":"B","en":"Use domain adaptation fine-tuning to adapt the FM to complex scientific terms.","zh":"使用领域自适应微调，让该 FM 适应复杂的科学术语。"},{"key":"C","en":"Change the FM inference parameters.","zh":"更改该 FM 的推理参数。"},{"key":"D","en":"Clean the research paper data to remove complex scientific terms.","zh":"清洗研究论文数据，删除复杂的科学术语。"}],"explanation":{"en":"Domain adaptation fine-tuning allows the FM to better understand the complex scientific terms by training it\nwith domain-specific data, improving its performance on such specialized content. The other options are\neither insufficient or not directly related to handling complex terminology effectively.","zh":"领域自适应微调通过使用领域特定数据训练 FM，使其更好地理解复杂的科学术语，从而提升模型在此类专业内容上的表现。其他选项要么效果不足，要么与有效处理复杂术语没有直接关系。"},"tip":{"zh":"专业术语听不懂 → 领域自适应微调；提示工程已试过无效，就别再调参数了。","en":""},"keywords":["领域自适应","微调","专业术语"]},{"id":65,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"A company wants to use a large language model (LLM) on Amazon Bedrock for sentiment analysis. The\ncompany needs the LLM to produce more consistent responses to the same input prompt.\nWhich adjustment to an inference parameter should the company make to meet these requirements?","zh":"某公司希望使用 Amazon Bedrock 上的大型语言模型（LLM）进行情感分析。公司需要让该 LLM 对相同的输入提示产生更一致的回复。公司应调整哪个推理参数来满足这些要求？"},"options":[{"key":"A","en":"Decrease the temperature value.","zh":"降低 temperature 值。"},{"key":"B","en":"Increase the temperature value.","zh":"提高 temperature 值。"},{"key":"C","en":"Decrease the length of output tokens.","zh":"减少输出词元的长度。"},{"key":"D","en":"Increase the maximum generation length.","zh":"提高最大生成长度。"}],"explanation":{"en":"Decreasing the temperature value makes the model's output more deterministic and consistent by\nreducing randomness in response generation. The other adjustments do not directly ensure consistent\nresponses.","zh":"降低 temperature 值会减少回复生成过程中的随机性，使模型输出更具确定性、更一致。其他调整不能直接保证回复的一致性。"},"tip":{"zh":"要稳定可复现 → 调低 temperature；调高只会让输出更发散。","en":""},"keywords":["temperature","确定性","一致性"]},{"id":66,"type":"single","answer":["A"],"topic":"security","stem":{"en":"A company wants to develop a large language model (LLM) application by using Amazon Bedrock and\ncustomer data that is uploaded to Amazon S3. The company's security policy states that each team can\naccess data for only the team's own customers.\nWhich solution will meet these requirements?","zh":"某公司希望使用 Amazon Bedrock 和上传到 Amazon S3 的客户数据来开发大型语言模型（LLM）应用。公司的安全策略规定，每个团队只能访问本团队自己客户的数据。哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Create an Amazon Bedrock custom service role for each team that has access to only the team's customer data.","zh":"为每个团队创建一个 Amazon Bedrock 自定义服务角色，该角色只能访问本团队的客户数据。"},{"key":"B","en":"Create a custom service role that has Amazon S3 access. Ask teams to specify the customer name on each Amazon Bedrock request.","zh":"创建一个具有 Amazon S3 访问权限的自定义服务角色。要求各团队在每次 Amazon Bedrock 请求中指定客户名称。"},{"key":"C","en":"Redact personal data in Amazon S3. Update the S3 bucket policy to allow team access to customer data.","zh":"在 Amazon S3 中对个人数据进行脱敏。更新 S3 存储桶策略，允许团队访问客户数据。"},{"key":"D","en":"Create one Amazon Bedrock role that has full Amazon S3 access. Create IAM roles for each team that have access to only each team's customer folders.","zh":"创建一个拥有完整 Amazon S3 访问权限的 Amazon Bedrock 角色。为每个团队创建 IAM 角色，使其只能访问各自团队的客户文件夹。"}],"explanation":{"en":"Creating a custom Amazon Bedrock service role for each team with restricted access to only the team's\ncustomer data ensures compliance with the security policy, providing the necessary data segregation and\naccess control. The other options do not effectively enforce team-specific access or may pose risks of\nbroader access than allowed by the policy.","zh":"为每个团队创建只能访问本团队客户数据的 Amazon Bedrock 自定义服务角色，可确保符合安全策略，实现必要的数据隔离和访问控制。其他选项无法有效强制团队级访问隔离，或可能带来超出策略允许范围的访问风险。"},"tip":{"zh":"按团队隔离数据 → 每个团队一个 Bedrock 服务角色，权限最小化。","en":""},"keywords":["服务角色","数据隔离","最小权限"]},{"id":67,"type":"single","answer":["C"],"topic":"responsible","stem":{"en":"A medical company deployed a disease detection model on Amazon Bedrock. To comply with privacy\npolicies, the company wants to prevent the model from including personal patient information in its\nresponses. The company also wants to receive notification when policy violations occur.\nWhich solution meets these requirements?","zh":"某医疗公司在 Amazon Bedrock 上部署了一个疾病检测模型。为遵守隐私政策，公司希望防止模型在回复中包含患者个人信息。公司还希望在发生策略违规时收到通知。哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Use Amazon Macie to scan the model's output for sensitive data and set up alerts for potential violations.","zh":"使用 Amazon Macie 扫描模型输出中的敏感数据，并为潜在违规设置告警。"},{"key":"B","en":"Configure AWS CloudTrail to monitor the model's responses and create alerts for any detected personal information.","zh":"配置 AWS CloudTrail 监控模型回复，并对检测到的任何个人信息创建告警。"},{"key":"C","en":"Use Guardrails for Amazon Bedrock to filter content. Set up Amazon CloudWatch alarms for notification of policy violations.","zh":"使用 Guardrails for Amazon Bedrock 过滤内容。设置 Amazon CloudWatch 告警以通知策略违规。"},{"key":"D","en":"Implement Amazon SageMaker Model Monitor to detect data drift and receive alerts when model quality degrades.","zh":"实施 Amazon SageMaker Model Monitor 以检测数据漂移，并在模型质量下降时收到告警。"}],"explanation":{"en":"Guardrails for Amazon Bedrock can be used to filter content and ensure that personal patient information\nis not included in model responses. Setting up Amazon CloudWatch alarms allows the company to receive\nnotifications when policy violations occur. The other options are not specifically designed for filtering model\noutput and monitoring policy compliance.","zh":"Guardrails for Amazon Bedrock 可用于过滤内容，确保患者个人信息不出现在模型回复中。设置 Amazon CloudWatch 告警可让公司在发生策略违规时收到通知。其他选项并非专门用于过滤模型输出和监控策略合规性。"},"tip":{"zh":"过滤模型输入输出 → Guardrails；要发告警就再配 CloudWatch。","en":""},"keywords":["Guardrails","内容过滤","CloudWatch 告警"]},{"id":68,"type":"single","answer":["A"],"topic":"services","stem":{"en":"A company manually reviews all submitted resumes in PDF format. As the company grows, the company\nexpects the volume of resumes to exceed the company's review capacity. The company needs an\nautomated system to convert the PDF resumes into plain text format for additional processing.\nWhich AWS service meets this requirement?","zh":"某公司目前人工审核所有以 PDF 格式提交的简历。随着公司发展，预计简历数量将超出公司的审核能力。公司需要一个自动化系统，把 PDF 简历转换成纯文本格式以便后续处理。哪种 AWS 服务能满足这一要求？"},"options":[{"key":"A","en":"Amazon Textract","zh":"Amazon Textract"},{"key":"B","en":"Amazon Personalize","zh":"Amazon Personalize"},{"key":"C","en":"Amazon Lex","zh":"Amazon Lex"},{"key":"D","en":"Amazon Transcribe","zh":"Amazon Transcribe"}],"explanation":{"en":"Amazon Textract can extract text from PDF documents, making it suitable for converting resumes into\nplain text for further processing. The other services do not provide functionality to extract text from PDFs.","zh":"Amazon Textract 可以从 PDF 文档中提取文本，适合把简历转换为纯文本以供后续处理。其他服务不提供从 PDF 中提取文本的功能。"},"tip":{"zh":"PDF 或扫描件提取文字 → Textract；音频转文字才是 Transcribe。","en":""},"keywords":["Textract","文档文本提取","PDF"]},{"id":69,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"An education provider is building a question and answer application that uses a generative AI model to\nexplain complex concepts. The education provider wants to automatically change the style of the model\nresponse depending on who is asking the question. The education provider will give the model the age\nrange of the user who has asked the question.\nWhich solution meets these requirements with the LEAST implementation effort?","zh":"某教育机构正在构建一个问答应用，使用生成式 AI 模型解释复杂概念。该机构希望根据提问者的身份自动改变模型回复的风格。该机构会把提问用户的年龄段提供给模型。哪种解决方案能以最少的实施工作量满足这些要求？"},"options":[{"key":"A","en":"Fine-tune the model by using additional training data that is representative of the various age ranges that the application will support.","zh":"使用代表应用将支持的各年龄段的额外训练数据对该模型进行微调。"},{"key":"B","en":"Add a role description to the prompt context that instructs the model of the age range that the response should target.","zh":"在提示上下文中添加角色描述，指示模型回复应面向的年龄段。"},{"key":"C","en":"Use chain-of-thought reasoning to deduce the correct style and complexity for a response suitable for that user.","zh":"使用思维链推理来推断适合该用户的正确风格和复杂度。"},{"key":"D","en":"Summarize the response text depending on the age of the user so that younger users receive shorter responses.","zh":"根据用户年龄对回复文本进行摘要，使较年轻的用户得到更短的回复。"}],"explanation":{"en":"Adding a role description to the prompt is the simplest and most effective way to adjust the model's\nresponse style based on the user's age range. It requires minimal implementation effort and effectively\ntailors the output. The other options involve more complex processes, such as fine-tuning or additional\nreasoning steps.","zh":"在提示中添加角色描述，是根据用户年龄段调整模型回复风格最简单、最有效的方法。它所需的实施工作量最小，并能有效定制输出。其他选项涉及更复杂的流程，例如微调或额外的推理步骤。"},"tip":{"zh":"要最省事地改风格 → 提示里写角色描述；微调是重活，不划算。","en":""},"keywords":["角色描述","提示工程","最少工作量"]},{"id":70,"type":"single","answer":["B"],"topic":"eval","stem":{"en":"Which strategy evaluates the accuracy of a foundation model (FM) that is used in image classification\ntasks?","zh":"哪种策略可以评估用于图像分类任务的基础模型（FM）的准确率？"},"options":[{"key":"A","en":"Calculate the total cost of resources used by the model.","zh":"计算模型所用资源的总成本。"},{"key":"B","en":"Measure the model's accuracy against a predefined benchmark dataset.","zh":"用预定义的基准数据集衡量模型的准确率。"},{"key":"C","en":"Count the number of layers in the neural network.","zh":"统计神经网络中的层数。"},{"key":"D","en":"Assess the color accuracy of images processed by the model.","zh":"评估模型处理图像的色彩准确度。"}],"explanation":{"en":"Evaluating a foundation model's accuracy by measuring its performance against a predefined benchmark\ndataset is the standard approach for assessing accuracy in image classification tasks. The other options\ndo not provide an appropriate measure of classification accuracy.","zh":"通过预定义的基准数据集衡量模型表现，是评估图像分类任务准确率的标准做法。其他选项不能提供合适的分类准确率度量。"},"tip":{"zh":"评准确率 → 拿基准数据集去测；层数、成本、色彩都跟准确率无关。","en":""},"keywords":["基准数据集","准确率评估","图像分类"]},{"id":71,"type":"multi","answer":["A","C"],"topic":"responsible","stem":{"en":"An accounting firm wants to implement a large language model (LLM) to automate document processing.\nThe firm must proceed responsibly to avoid potential harms.\nWhat should the firm do when developing and deploying the LLM? (Choose two.)","zh":"某会计师事务所希望实施大型语言模型（LLM）来自动化文档处理。该事务所必须以负责任的方式推进，以避免潜在危害。在开发和部署该 LLM 时，该事务所应做什么？（选择两项）"},"options":[{"key":"A","en":"Include fairness metrics for model evaluation.","zh":"在模型评估中包含公平性指标。"},{"key":"B","en":"Adjust the temperature parameter of the model.","zh":"调整模型的 temperature 参数。"},{"key":"C","en":"Modify the training data to mitigate bias.","zh":"修改训练数据以减轻偏见。"},{"key":"D","en":"Avoid overfitting on the training data.","zh":"避免对训练数据过拟合。"},{"key":"E","en":"Apply prompt engineering techniques.","zh":"应用提示工程技术。"}],"explanation":{"en":"Include fairness metrics for model evaluation: Fairness metrics help ensure that the LLM is unbiased\nand treats all cases equitably, which is essential for responsible AI use.\nModify the training data to mitigate bias: Adjusting the training data helps reduce any inherent bias that\n\nmight exist, contributing to a more fair and responsible LLM.\nThe other options are related to general model optimization but do not directly address responsible AI\npractices regarding potential harms like bias and fairness.","zh":"在模型评估中包含公平性指标：公平性指标有助于确保 LLM 不带偏见、公平对待所有情况，这对负责任地使用 AI 至关重要。\n修改训练数据以减轻偏见：调整训练数据有助于减少可能存在的固有偏见，从而构建更公平、更负责任的 LLM。\n其他选项与一般模型优化有关，但并不直接涉及针对偏见和公平性等潜在危害的负责任 AI 实践。"},"tip":{"zh":"负责任 AI 抓两头：训练数据去偏见 + 评估加公平性指标。","en":""},"keywords":["公平性指标","偏见缓解","负责任 AI"]},{"id":72,"type":"single","answer":["C"],"topic":"sagemaker","stem":{"en":"A company is building an ML model. The company collected new data and analyzed the data by creating a\ncorrelation matrix, calculating statistics, and visualizing the data.\nWhich stage of the ML pipeline is the company currently in?","zh":"某公司正在构建 ML 模型。公司收集了新数据，并通过创建相关性矩阵、计算统计量和可视化数据来分析这些数据。该公司目前处于 ML 流水线的哪个阶段？"},"options":[{"key":"A","en":"Data pre-processing","zh":"数据预处理"},{"key":"B","en":"Feature engineering","zh":"特征工程"},{"key":"C","en":"Exploratory data analysis","zh":"探索性数据分析"},{"key":"D","en":"Hyperparameter tuning","zh":"超参数调优"}],"explanation":{"en":"The company is currently in the exploratory data analysis (EDA) stage, which involves summarizing data\nthrough statistics, visualizations, and correlation matrices to understand the dataset before moving on to\nmodeling. The other options are subsequent steps in the ML pipeline.","zh":"公司目前处于探索性数据分析（EDA）阶段，该阶段通过统计量、可视化和相关性矩阵来汇总数据，以便在进入建模之前理解数据集。其他选项是 ML 流水线中更靠后的步骤。"},"tip":{"zh":"相关性矩阵 + 统计量 + 可视化 = 探索性数据分析，还没开始建模。","en":""},"keywords":["探索性数据分析","相关性矩阵","数据可视化"]},{"id":73,"type":"single","answer":["D"],"topic":"genai","stem":{"en":"A company has documents that are missing some words because of a database error. The company\nwants to build an ML model that can suggest potential words to fill in the missing text.\nWhich type of model meets this requirement?","zh":"某公司的文档因数据库错误而缺失了一些单词。公司希望构建一个 ML 模型，能够推荐候选词来填补缺失的文本。哪种类型的模型能满足这一要求？"},"options":[{"key":"A","en":"Topic modeling","zh":"主题建模"},{"key":"B","en":"Clustering models","zh":"聚类模型"},{"key":"C","en":"Prescriptive ML models","zh":"规范性 ML 模型"},{"key":"D","en":"BERT-based models","zh":"基于 BERT 的模型"}],"explanation":{"en":"BERT-based models are well-suited for natural language understanding tasks, including filling in missing\nwords, because they use contextual information to predict missing tokens in a text. The other types of\nmodels are not designed for this type of text completion task.","zh":"基于 BERT 的模型非常适合自然语言理解任务，包括填补缺失单词，因为它们利用上下文信息来预测文本中缺失的词元。其他类型的模型并非为此类文本补全任务而设计。"},"tip":{"zh":"填词补全靠双向上下文 → 选 BERT；聚类和主题建模做不到。","en":""},"keywords":["BERT","文本补全","上下文"]},{"id":74,"type":"single","answer":["C"],"topic":"services","stem":{"en":"A company wants to display the total sales for its top-selling products across various retail locations in the\npast 12 months.\nWhich AWS solution should the company use to automate the generation of graphs?","zh":"某公司希望展示过去 12 个月中各零售网点最畅销产品的总销售额。公司应使用哪种 AWS 解决方案来自动生成图表？"},"options":[{"key":"A","en":"Amazon Q in Amazon EC2","zh":"Amazon Q in Amazon EC2"},{"key":"B","en":"Amazon Q Developer","zh":"Amazon Q Developer"},{"key":"C","en":"Amazon Q in Amazon QuickSight","zh":"Amazon Q in Amazon QuickSight"},{"key":"D","en":"Amazon Q in AWS Chatbot","zh":"Amazon Q in AWS Chatbot"}],"explanation":{"en":"Amazon Q in Amazon QuickSight allows users to ask questions in natural language and automatically\ngenerate graphs and visualizations to display insights, such as total sales for top-selling products. The\nother options do not provide the same functionality for generating visual analytics.","zh":"Amazon Q in Amazon QuickSight 允许用户用自然语言提问，并自动生成图表和可视化来展示洞察，例如最畅销产品的总销售额。其他选项不提供相同的可视化分析生成功能。"},"tip":{"zh":"用自然语言自动生成 BI 图表 → QuickSight 里的 Amazon Q。","en":""},"keywords":["Amazon Q","QuickSight","可视化"]},{"id":75,"type":"single","answer":["C"],"topic":"eval","stem":{"en":"A company is building a chatbot to improve user experience. The company is using a large language\nmodel (LLM) from Amazon Bedrock for intent detection. The company wants to use few-shot learning to\nimprove intent detection accuracy.\nWhich additional data does the company need to meet these requirements?","zh":"某公司正在构建聊天机器人以改善用户体验。公司使用 Amazon Bedrock 的大型语言模型（LLM）进行意图检测，并希望使用少样本学习来提高意图检测的准确率。公司需要哪些额外数据来满足这些要求？"},"options":[{"key":"A","en":"Pairs of chatbot responses and correct user intents","zh":"聊天机器人回复与正确用户意图的配对"},{"key":"B","en":"Pairs of user messages and correct chatbot responses","zh":"用户消息与正确聊天机器人回复的配对"},{"key":"C","en":"Pairs of user messages and correct user intents","zh":"用户消息与正确用户意图的配对"},{"key":"D","en":"Pairs of user intents and correct chatbot responses","zh":"用户意图与正确聊天机器人回复的配对"}],"explanation":{"en":"Few-shot learning involves providing the model with a few examples to help it understand how to perform\nthe task. For intent detection, the company needs pairs of user messages and the correct user intents,\nwhich will help the LLM improve its accuracy in detecting user intents. The other options do not provide the\nnecessary pairing for improving intent detection.","zh":"少样本学习需要向模型提供少量示例，帮助它理解如何执行任务。对于意图检测，公司需要用户消息与正确用户意图的配对，这能帮助 LLM 提高意图检测的准确率。其他选项没有提供提升意图检测所需的配对。"},"tip":{"zh":"意图检测就是「消息 → 意图」，示例必须是用户消息配正确意图。","en":""},"keywords":["少样本学习","意图检测","示例数据"]},{"id":76,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"A company is using few-shot prompting on a base model that is hosted on Amazon Bedrock. The model\ncurrently uses 10 examples in the prompt. The model is invoked once daily and is performing well. The\ncompany wants to lower the monthly cost.\nWhich solution will meet these requirements?","zh":"某公司在 Amazon Bedrock 托管的某基础模型上使用少样本提示。该模型的提示中目前使用了 10 个示例。该模型每天被调用一次，且运行良好。公司希望降低月度成本。哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Customize the model by using fine-tuning.","zh":"通过微调来自定义该模型。"},{"key":"B","en":"Decrease the number of tokens in the prompt.","zh":"减少提示中的词元数量。"},{"key":"C","en":"Increase the number of tokens in the prompt.","zh":"增加提示中的词元数量。"},{"key":"D","en":"Use Provisioned Throughput.","zh":"使用预置吞吐量。"}],"explanation":{"en":"Decreasing the number of tokens in the prompt reduces the amount of data being processed, thereby\nlowering the cost of using the model. Since the model is performing well, reducing the prompt size is a\ncost-effective way to maintain performance while lowering expenses. The other options either increase\ncosts or are unrelated to prompt size.","zh":"减少提示中的词元数量会减少需要处理的数据量，从而降低使用模型的成本。由于模型运行良好，缩小提示规模是在保持性能的同时降低费用的经济做法。其他选项要么会增加成本，要么与提示规模无关。"},"tip":{"zh":"按词元计费 → 每天才调一次，砍提示词元最省钱；预置吞吐量反而更贵。","en":""},"keywords":["词元计费","成本优化","少样本提示"]},{"id":77,"type":"single","answer":["B"],"topic":"responsible","stem":{"en":"An AI practitioner is using a large language model (LLM) to create content for marketing campaigns. The\ngenerated content sounds plausible and factual but is incorrect.\nWhich problem is the LLM having?","zh":"某 AI 从业者正在使用大型语言模型（LLM）为营销活动创建内容。生成的内容听起来合理且像事实，但实际上是错误的。该 LLM 出现了什么问题？"},"options":[{"key":"A","en":"Data leakage","zh":"数据泄露"},{"key":"B","en":"Hallucination","zh":"幻觉"},{"key":"C","en":"Overfitting","zh":"过拟合"},{"key":"D","en":"Underfitting","zh":"欠拟合"}],"explanation":{"en":"Hallucination occurs when a large language model generates content that appears plausible and factual\nbut is incorrect or fabricated. This is a common issue with LLMs. The other options do not describe this\nparticular behavior.","zh":"幻觉是指大型语言模型生成看似合理、像事实但实际错误或凭空捏造的内容。这是 LLM 的常见问题。其他选项不描述这一特定行为。"},"tip":{"zh":"一本正经地胡说八道 → 幻觉；既不是过拟合，也不是数据泄露。","en":""},"keywords":["幻觉","大型语言模型","内容可靠性"]},{"id":78,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"An AI practitioner trained a custom model on Amazon Bedrock by using a training dataset that contains\nconfidential data. The AI practitioner wants to ensure that the custom model does not generate inference\nresponses based on confidential data.\nHow should the AI practitioner prevent responses based on confidential data?","zh":"某 AI 从业者使用包含机密数据的训练数据集在 Amazon Bedrock 上训练了一个自定义模型。该从业者希望确保该自定义模型不会基于机密数据生成推理回复。该从业者应如何防止基于机密数据的回复？"},"options":[{"key":"A","en":"Delete the custom model. Remove the confidential data from the training dataset. Retrain the custom model.","zh":"删除该自定义模型。从训练数据集中移除机密数据。重新训练该自定义模型。"},{"key":"B","en":"Mask the confidential data in the inference responses by using dynamic data masking.","zh":"使用动态数据脱敏对推理回复中的机密数据进行掩码。"},{"key":"C","en":"Encrypt the confidential data in the inference responses by using Amazon SageMaker.","zh":"使用 Amazon SageMaker 对推理回复中的机密数据进行加密。"},{"key":"D","en":"Encrypt the confidential data in the custom model by using AWS Key Management Service (AWS KMS).","zh":"使用 AWS Key Management Service（AWS KMS）对自定义模型中的机密数据进行加密。"}],"explanation":{"en":"To ensure that the custom model does not generate responses based on confidential data, the best\napproach is to retrain the model without including the confidential data. This prevents the model from\nlearning patterns associated with that sensitive information, thereby avoiding its use in inference. The\nother options do not address the root cause of the issue—removing confidential data from the training\nprocess.","zh":"要确保自定义模型不会基于机密数据生成回复，最好的方法是重新训练模型且不包含机密数据。这样可以防止模型学习与该敏感信息相关的模式，从而避免在推理中使用它。其他选项都没有解决根本原因——从训练过程中移除机密数据。"},"tip":{"zh":"模型学进去就忘不掉 → 删模型、剔数据、重训；加密和脱敏治不了根。","en":""},"keywords":["机密数据","重新训练","数据泄露"]},{"id":79,"type":"single","answer":["A"],"topic":"eval","stem":{"en":"A company has built a solution by using generative AI. The solution uses large language models (LLMs) to\ntranslate training manuals from English into other languages. The company wants to evaluate the\naccuracy of the solution by examining the text generated for the manuals.\nWhich model evaluation strategy meets these requirements?","zh":"某公司使用生成式 AI 构建了一个解决方案。该方案使用大型语言模型（LLM）把培训手册从英文翻译成其他语言。公司希望通过检查为手册生成的文本，来评估该解决方案的准确率。哪种模型评估策略能满足这些要求？"},"options":[{"key":"A","en":"Bilingual Evaluation Understudy (BLEU)","zh":"双语评估替补（BLEU）"},{"key":"B","en":"Root mean squared error (RMSE)","zh":"均方根误差（RMSE）"},{"key":"C","en":"Recall-Oriented Understudy for Gisting Evaluation (ROUGE)","zh":"面向召回率的要点评估替补（ROUGE）"},{"key":"D","en":"F1 score","zh":"F1 分数"}],"explanation":{"en":"The BLEU (Bilingual Evaluation Understudy) score is a common metric used to evaluate the accuracy of\nmachine translation by comparing the generated translation with reference translations. It is specifically\ndesigned for translation tasks, whereas the other metrics are not suitable for evaluating translation quality.","zh":"BLEU（Bilingual Evaluation Understudy）分数是评估机器翻译准确率的常用指标，它通过把生成的译文与参考译文进行比较来衡量质量。它专为翻译任务设计，而其他指标不适合评估翻译质量。"},"tip":{"zh":"机器翻译看 BLEU，文本摘要看 ROUGE；RMSE 和 F1 都不对口。","en":""},"keywords":["BLEU","机器翻译","评估指标"]},{"id":80,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"A large retailer receives thousands of customer support inquiries about products every day. The customer\nsupport inquiries need to be processed quickly. The company wants to implement Agents for Amazon\nBedrock.\nWhat are the key benefits of using Amazon Bedrock agents that could help this retailer?","zh":"某大型零售商每天收到数千条关于产品的客户支持咨询。这些客户支持咨询需要被快速处理。该公司希望实施 Agents for Amazon Bedrock。使用 Amazon Bedrock 代理的关键优势中，哪一项能帮助该零售商？"},"options":[{"key":"A","en":"Generation of custom foundation models (FMs) to predict customer needs","zh":"生成自定义基础模型（FM）以预测客户需求"},{"key":"B","en":"Automation of repetitive tasks and orchestration of complex workflows","zh":"自动化重复性任务并编排复杂工作流"},{"key":"C","en":"Automatically calling multiple foundation models (FMs) and consolidating the results","zh":"自动调用多个基础模型（FM）并合并结果"},{"key":"D","en":"Selecting the foundation model (FM) based on predefined criteria and metrics","zh":"根据预定义的标准和指标选择基础模型（FM）"}],"explanation":{"en":"Amazon Bedrock agents help automate repetitive tasks and orchestrate complex workflows, which is ideal\nfor handling thousands of customer support inquiries efficiently. This helps reduce response times and\nimproves productivity. The other options do not directly address automation and orchestration of tasks for\ncustomer support.","zh":"Amazon Bedrock 代理有助于自动化重复性任务并编排复杂工作流，非常适合高效处理数千条客户支持咨询。这有助于缩短响应时间并提升工作效率。其他选项并未直接涉及客户支持任务的自动化和编排。"},"tip":{"zh":"Agent 的价值是自动跑流程、编排调工具，不是帮你挑模型。","en":""},"keywords":["Agents for Amazon Bedrock","任务编排","自动化"]},{"id":81,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"Which option is a benefit of ongoing pre-training when fine-tuning a foundation model (FM)?","zh":"在对基础模型（FM）进行微调时，持续预训练有什么好处？"},"options":[{"key":"A","en":"Helps decrease the model's complexity","zh":"有助于降低模型的复杂度"},{"key":"B","en":"Improves model performance over time","zh":"随时间推移提升模型性能"},{"key":"C","en":"Decreases the training time requirement","zh":"缩短所需的训练时间"},{"key":"D","en":"Optimizes model inference time","zh":"优化模型推理时间"}],"explanation":{"en":"Ongoing pre-training helps enhance a foundation model's performance by continuously updating it with\nnew data, thereby improving its ability to generalize and perform well on different tasks. The other options\ndo not directly relate to the benefits of ongoing pre-training.","zh":"持续预训练通过用新数据不断更新基础模型来增强其性能，从而提升其泛化能力以及在不同任务上的表现。其他选项与持续预训练的好处没有直接关系。"},"tip":{"zh":"持续预训练就是「持续喂新数据」，换来的是越用越好，不是更省时。","en":""},"keywords":["持续预训练","模型性能","泛化能力"]},{"id":82,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"What are tokens in the context of generative AI models?","zh":"在生成式 AI 模型的语境下，词元（token）是什么？"},"options":[{"key":"A","en":"Tokens are the basic units of input and output that a generative AI model operates on, representing words, subwords, or other linguistic units.","zh":"词元是生成式 AI 模型处理的基本输入输出单元，代表单词、子词或其他语言单元。"},{"key":"B","en":"Tokens are the mathematical representations of words or concepts used in generative AI models.","zh":"词元是生成式 AI 模型中使用的单词或概念的数学表示。"},{"key":"C","en":"Tokens are the pre-trained weights of a generative AI model that are fine-tuned for specific tasks.","zh":"词元是生成式 AI 模型为特定任务微调过的预训练权重。"},{"key":"D","en":"Tokens are the specific prompts or instructions given to a generative AI model to generate output.","zh":"词元是提供给生成式 AI 模型以生成输出的特定提示或指令。"}],"explanation":{"en":"Tokens are the smallest units (e.g., words, subwords, or characters) that generative AI models use to\nprocess text. They form the basis of both the input given to and the output generated by the model. The\nother options do not accurately describe tokens in this context.","zh":"词元是生成式 AI 模型处理文本时使用的最小单元（例如单词、子词或字符）。它们构成模型输入和输出的基础。其他选项没有准确描述此语境下的词元。"},"tip":{"zh":"词元 = 文本切分的最小单元；数值表示是嵌入向量，别混。","en":""},"keywords":["词元","输入输出单元","生成式 AI"]},{"id":83,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"A company wants to assess the costs that are associated with using a large language model (LLM) to\ngenerate inferences. The company wants to use Amazon Bedrock to build generative AI applications.\nWhich factor will drive the inference costs?","zh":"某公司希望评估使用大型语言模型（LLM）生成推理所涉及的成本。公司打算使用 Amazon Bedrock 构建生成式 AI 应用。哪个因素会驱动推理成本？"},"options":[{"key":"A","en":"Number of tokens consumed","zh":"消耗的词元数量"},{"key":"B","en":"Temperature value","zh":"temperature 值"},{"key":"C","en":"Amount of data used to train the LLM","zh":"用于训练该 LLM 的数据量"},{"key":"D","en":"Total training time","zh":"总训练时间"}],"explanation":{"en":"Inference costs for large language models are typically driven by the number of tokens processed during\ninput and output, as each token incurs computational resources. The other factors (temperature value,\ntraining data, and training time) do not directly impact inference costs.","zh":"大型语言模型的推理成本通常由输入和输出过程中处理的词元数量决定，因为每个词元都会消耗计算资源。其他因素（temperature 值、训练数据和训练时间）不会直接影响推理成本。"},"tip":{"zh":"Bedrock 推理按词元计费，输入输出词元越多越贵。","en":""},"keywords":["推理成本","词元计费","Amazon Bedrock"]},{"id":84,"type":"single","answer":["C"],"topic":"security","stem":{"en":"A company is using Amazon SageMaker Studio notebooks to build and train ML models. The company\nstores the data in an Amazon S3 bucket. The company needs to manage the flow of data from Amazon S3\nto SageMaker Studio notebooks.\nWhich solution will meet this requirement?","zh":"某公司使用 Amazon SageMaker Studio 笔记本构建和训练 ML 模型。公司将数据存储在 Amazon S3 存储桶中。公司需要管理从 Amazon S3 到 SageMaker Studio 笔记本的数据流。哪种解决方案能满足这一要求？"},"options":[{"key":"A","en":"Use Amazon Inspector to monitor SageMaker Studio.","zh":"使用 Amazon Inspector 监控 SageMaker Studio。"},{"key":"B","en":"Use Amazon Macie to monitor SageMaker Studio.","zh":"使用 Amazon Macie 监控 SageMaker Studio。"},{"key":"C","en":"Configure SageMaker to use a VPC with an S3 endpoint.","zh":"配置 SageMaker 使用带 S3 端点的 VPC。"},{"key":"D","en":"Configure SageMaker to use S3 Glacier Deep Archive.","zh":"配置 SageMaker 使用 S3 Glacier Deep Archive。"}],"explanation":{"en":"Configuring Amazon SageMaker to use a VPC with an S3 endpoint ensures secure, direct, and managed\ndata flow between Amazon S3 and SageMaker Studio notebooks. This setup avoids public internet\nexposure and maintains data integrity during transfers. The other options do not provide a solution for\nmanaging the data flow in this context.","zh":"配置 Amazon SageMaker 使用带 S3 端点的 VPC，可以确保 Amazon S3 与 SageMaker Studio 笔记本之间安全、直接且受管的数据流。此设置可避免暴露在公共互联网上，并在传输过程中保持数据完整性。其他选项在此场景下无法提供管理数据流的方案。"},"tip":{"zh":"私有网络里访问 S3 → VPC + S3 网关端点；Inspector 和 Macie 都不管数据流。","en":""},"keywords":["VPC","S3 端点","数据流管理"]},{"id":85,"type":"single","answer":["A"],"topic":"eval","stem":{"en":"A company has a foundation model (FM) that was customized by using Amazon Bedrock to answer\ncustomer queries about products. The company wants to validate the model's responses to new types of\nqueries. The company needs to upload a new dataset that Amazon Bedrock can use for validation.\nWhich AWS service meets these requirements?","zh":"某公司有一个使用 Amazon Bedrock 定制的基础模型（FM），用于回答客户关于产品的问题。公司希望验证该模型对新型查询的回复。公司需要上传一个可供 Amazon Bedrock 用于验证的新数据集。哪种 AWS 服务能满足这些要求？"},"options":[{"key":"A","en":"Amazon S3","zh":"Amazon S3"},{"key":"B","en":"Amazon Elastic Block Store (Amazon EBS)","zh":"Amazon Elastic Block Store（Amazon EBS）"},{"key":"C","en":"Amazon Elastic File System (Amazon EFS)","zh":"Amazon Elastic File System（Amazon EFS）"},{"key":"D","en":"AWS Snowcone","zh":"AWS Snowcone"}],"explanation":{"en":"Amazon S3 is the most suitable AWS service for uploading and storing datasets used for validation\npurposes. It is highly scalable and integrated with Amazon Bedrock, allowing easy access to data for\nmodel validation. The other options do not provide the same level of integration or suitability for managing\ndatasets in this context.","zh":"Amazon S3 是上传和存储用于验证的数据集最合适的 AWS 服务。它高度可扩展并与 Amazon Bedrock 集成，便于访问数据用于模型验证。其他选项在此场景下不具备同等程度的集成能力或数据集管理适用性。"},"tip":{"zh":"Bedrock 的数据入口只有 S3，训练和验证数据集都放这儿。","en":""},"keywords":["Amazon S3","验证数据集","Amazon Bedrock"]},{"id":86,"type":"single","answer":["D"],"topic":"genai","stem":{"en":"Which prompting attack directly exposes the configured behavior of a large language model (LLM)?","zh":"哪种提示攻击会直接暴露大型语言模型（LLM）已配置的行为？"},"options":[{"key":"A","en":"Prompted persona switches","zh":"提示人设切换"},{"key":"B","en":"Exploiting friendliness and trust","zh":"利用友好与信任"},{"key":"C","en":"Ignoring the prompt template","zh":"忽略提示模板"},{"key":"D","en":"Extracting the prompt template","zh":"提取提示模板"}],"explanation":{"en":"\"Extracting the prompt template\" is a type of prompting attack that involves directly exposing the\nconfigured behavior or the underlying system prompt of a large language model (LLM). This attack can\nreveal sensitive details about how the model operates, including its internal instructions or restrictions,\nwhich are typically not intended to be disclosed to the user. Such an exposure can compromise the\nsecurity and reliability of the LLM by making it vulnerable to further exploitation or misuse.","zh":"「提取提示模板」是一种提示攻击，会直接暴露大型语言模型（LLM）已配置的行为或底层系统提示。此类攻击可能泄露模型运作方式的敏感细节，包括其内部指令或限制，而这些通常是不打算向用户披露的。这种暴露会通过使 LLM 更易被进一步利用或滥用来危及它的安全性和可靠性。"},"tip":{"zh":"问「把系统提示词原样复述」→ 提取提示模板，属直接泄露配置。","en":""},"keywords":["提示攻击","系统提示泄露","提示模板"]},{"id":87,"type":"single","answer":["C"],"topic":"security","stem":{"en":"A company wants to use Amazon Bedrock. The company needs to review which security aspects the\ncompany is responsible for when using Amazon Bedrock.\nWhich security aspect will the company be responsible for?","zh":"某公司希望使用 Amazon Bedrock。公司需要审查在使用 Amazon Bedrock 时自己负责哪些安全方面。公司将对哪个安全方面负责？"},"options":[{"key":"A","en":"Patching and updating the versions of Amazon Bedrock","zh":"为 Amazon Bedrock 的各版本打补丁并更新"},{"key":"B","en":"Protecting the infrastructure that hosts Amazon Bedrock","zh":"保护承载 Amazon Bedrock 的基础设施"},{"key":"C","en":"Securing the company's data in transit and at rest","zh":"保护公司数据在传输中和静态存储时的安全"},{"key":"D","en":"Provisioning Amazon Bedrock within the company network","zh":"在公司网络内部署 Amazon Bedrock"}],"explanation":{"en":"According to the AWS Shared Responsibility Model, AWS manages the security of the cloud, including the\ninfrastructure and services like Amazon Bedrock. Customers are responsible for security in the cloud,\nwhich encompasses protecting their data, managing access controls, and configuring security settings for\ntheir applications.\nReference: https://aws.amazon.com/compliance/shared-responsibility-model/?nc1=h_ls","zh":"根据 AWS 责任共担模型，AWS 负责「云的安全」，包括基础设施和 Amazon Bedrock 这类服务。客户负责「云中的安全」，包括保护自己的数据、管理访问控制以及为应用配置安全设置。\n参考：https://aws.amazon.com/compliance/shared-responsibility-model/?nc1=h_ls"},"tip":{"zh":"责任共担：AWS 管云本身，客户管云里的数据和权限。","en":""},"keywords":["责任共担模型","数据安全","合规"]},{"id":88,"type":"single","answer":["B"],"topic":"responsible","stem":{"en":"A social media company wants to use a large language model (LLM) to summarize messages. The\ncompany has chosen a few LLMs that are available on Amazon SageMaker JumpStart. The company\nwants to compare the generated output toxicity of these models.\nWhich strategy gives the company the ability to evaluate the LLMs with the LEAST operational overhead?","zh":"某社交媒体公司希望使用大型语言模型（LLM）对消息进行摘要。公司已经选定了几个在 Amazon SageMaker JumpStart 上可用的 LLM，并希望比较这些模型生成内容的毒性。哪种策略能让公司以最少的运维开销评估这些 LLM？"},"options":[{"key":"A","en":"Crowd-sourced evaluation","zh":"众包评估"},{"key":"B","en":"Automatic model evaluation","zh":"自动模型评估"},{"key":"C","en":"Model evaluation with human workers","zh":"人工评估"},{"key":"D","en":"Reinforcement learning from human feedback (RLHF)","zh":"基于人类反馈的强化学习（RLHF）"}],"explanation":{"en":"Automatic model evaluation is the strategy that allows the company to evaluate the LLMs with the least\noperational overhead. This method leverages automated tools and processes to assess the toxicity or\nquality of the generated output without the need for manual intervention or crowd-sourced input. By using\npre-built evaluation metrics or toxicity detection models, the company can quickly and efficiently evaluate\nmultiple models without the complexity and time required for human evaluations.","zh":"自动模型评估是能让公司以最少运维开销评估 LLM 的策略。该方法利用自动化工具和流程来评估生成输出的毒性或质量，无需人工干预或众包输入。通过使用预置的评估指标或毒性检测模型，公司可以快速高效地评估多个模型，而不必承担人工评估的复杂性和时间成本。"},"tip":{"zh":"要最少人力 → 自动模型评估；众包和人工都费人，RLHF 更重。","en":""},"keywords":["自动模型评估","毒性检测","运维开销"]},{"id":89,"type":"single","answer":["D"],"topic":"responsible","stem":{"en":"A company is testing the security of a foundation model (FM). During testing, the company wants to get\naround the safety features and make harmful content.\nWhich security technique is this an example of?","zh":"某公司正在测试基础模型（FM）的安全性。在测试期间，公司希望绕过安全功能并生成有害内容。这是哪种安全技术的示例？"},"options":[{"key":"A","en":"Fuzzing training data to find vulnerabilities","zh":"对训练数据进行模糊测试以发现漏洞"},{"key":"B","en":"Denial of service (DoS)","zh":"拒绝服务（DoS）"},{"key":"C","en":"Penetration testing with authorization","zh":"经授权的渗透测试"},{"key":"D","en":"Jailbreak","zh":"越狱"}],"explanation":{"en":"\"Jailbreaking\" refers to attempts to bypass or disable the built-in safety features and restrictions of a\nsystem, in this case, a foundation model (FM). This technique involves trying to circumvent the safeguards\nthat prevent the model from generating harmful or unsafe content. Jailbreaking is often performed to\nexploit vulnerabilities in a model’s filtering or safety protocols, making it a direct attempt to undermine its\nprotections.","zh":"「越狱」是指试图绕过或禁用系统（此处指基础模型）内置的安全功能和限制。该技术试图规避那些阻止模型生成有害或不安全内容的防护措施。越狱通常用于利用模型过滤或安全协议中的漏洞，因此是对其防护机制的直接攻击。"},"tip":{"zh":"绕过安全护栏、诱导输出有害内容 → 越狱；渗透测试是有授权的。","en":""},"keywords":["越狱","安全防护绕过","有害内容"]},{"id":90,"type":"single","answer":["B"],"topic":"security","stem":{"en":"A company needs to use Amazon SageMaker for model training and inference. The company must comply\nwith regulatory requirements to run SageMaker jobs in an isolated environment without internet access.\nWhich solution will meet these requirements?","zh":"某公司需要使用 Amazon SageMaker 进行模型训练和推理。公司必须遵守监管要求，在没有互联网访问的隔离环境中运行 SageMaker 作业。哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Run SageMaker training and inference by using SageMaker Experiments.","zh":"使用 SageMaker Experiments 运行 SageMaker 训练和推理。"},{"key":"B","en":"Run SageMaker training and inference by using network isolation.","zh":"使用网络隔离运行 SageMaker 训练和推理。"},{"key":"C","en":"Encrypt the data at rest by using encryption for SageMaker geospatial capabilities.","zh":"使用 SageMaker 地理空间功能的加密来加密静态数据。"},{"key":"D","en":"Associate appropriate AWS Identity and Access Management (IAM) roles with the SageMaker jobs.","zh":"为 SageMaker 作业关联适当的 AWS Identity and Access Management（IAM）角色。"}],"explanation":{"en":"Network isolation in Amazon SageMaker allows you to run training and inference jobs in an environment\nthat does not have access to the internet. This helps ensure that the data and the model do not\ninadvertently access external resources, meeting regulatory compliance requirements for isolated\nenvironments.","zh":"Amazon SageMaker 中的网络隔离允许你在无法访问互联网的环境中运行训练和推理作业。这有助于确保数据和模型不会意外访问外部资源，从而满足隔离环境的监管合规要求。"},"tip":{"zh":"断网跑作业 → SageMaker 网络隔离（network isolation）。","en":""},"keywords":["网络隔离","合规","SageMaker"]},{"id":91,"type":"single","answer":["C"],"topic":"responsible","stem":{"en":"An ML research team develops custom ML models. The model artifacts are shared with other teams for\nintegration into products and services. The ML team retains the model training code and data. The ML\nteam wants to build a mechanism that the ML team can use to audit models.\nWhich solution should the ML team use when publishing the custom ML models?","zh":"某 ML 研究团队开发自定义 ML 模型。模型构件会共享给其他团队，以便集成到产品和服务中。该 ML 团队保留模型训练代码和数据。该团队希望建立一种可用于审计模型的机制。在发布自定义 ML 模型时，该团队应使用哪种解决方案？"},"options":[{"key":"A","en":"Create documents with the relevant information. Store the documents in Amazon S3.","zh":"创建包含相关信息的文档。把文档存储在 Amazon S3 中。"},{"key":"B","en":"Use AWS AI Service Cards for transparency and understanding models.","zh":"使用 AWS AI Service Cards 实现透明度并帮助理解模型。"},{"key":"C","en":"Create Amazon SageMaker Model Cards with intended uses and training and inference details.","zh":"创建 Amazon SageMaker Model Cards，记录预期用途以及训练和推理详情。"},{"key":"D","en":"Create model training scripts. Commit the model training scripts to a Git repository.","zh":"创建模型训练脚本。把模型训练脚本提交到 Git 仓库。"}],"explanation":{"en":"Amazon SageMaker Model Cards are designed to document the essential details about machine learning\nmodels, including their intended uses, training datasets, training parameters, evaluation metrics, and\ninference environment. This provides a centralized mechanism to store and audit the metadata of the\nmodels, which is ideal for the ML team's need to share and audit models effectively.\nKey benefits of Amazon SageMaker Model Cards:\nStandardized documentation of models' characteristics and intended use cases.\nTransparency and traceability for auditing purposes.\nIntegration with other AWS services for lifecycle management.","zh":"Amazon SageMaker Model Cards 旨在记录机器学习模型的关键信息，包括预期用途、训练数据集、训练参数、评估指标和推理环境。这提供了一个集中存储和审计模型元数据的机制，非常适合该团队有效共享和审计模型的需求。\nAmazon SageMaker Model Cards 的主要优势：\n以标准化方式记录模型特征和预期用例。\n为审计目的提供透明度和可追溯性。\n与其他 AWS 服务集成以实现生命周期管理。"},"tip":{"zh":"自家模型要可审计 → SageMaker Model Cards；AI Service Cards 是 AWS 对自己服务的说明。","en":""},"keywords":["SageMaker Model Cards","模型审计","文档化"]},{"id":92,"type":"single","answer":["D"],"topic":"general","stem":{"en":"A software company builds tools for customers. The company wants to use AI to increase software\ndevelopment productivity.\nWhich solution will meet these requirements?","zh":"某软件公司为客户构建工具。公司希望利用 AI 提高软件开发效率。哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Use a binary classification model to generate code reviews.","zh":"使用二分类模型生成代码评审。"},{"key":"B","en":"Install code recommendation software in the company's developer tools.","zh":"在公司的开发者工具中安装代码推荐软件。"},{"key":"C","en":"Install a code forecasting tool to predict potential code issues.","zh":"安装代码预测工具来预测潜在的代码问题。"},{"key":"D","en":"Use a natural language processing (NLP) tool to generate code.","zh":"使用自然语言处理（NLP）工具生成代码。"}],"explanation":{"en":"Natural language processing (NLP) tools can be used to generate code from high-level descriptions or\nsuggestions, which can greatly enhance software development productivity. By leveraging NLP models,\ndevelopers can automate repetitive coding tasks, generate code snippets, or even complete blocks of\ncode based on natural language inputs. This can speed up development and reduce errors.","zh":"自然语言处理（NLP）工具可以根据高层描述或建议生成代码，从而大幅提升软件开发效率。借助 NLP 模型，开发者可以自动化重复性编码任务、生成代码片段，甚至根据自然语言输入补全整段代码。这能加快开发速度并减少错误。"},"tip":{"zh":"用自然语言描述直接生成代码 → NLP 生成式工具，如 Amazon Q Developer。","en":""},"keywords":["代码生成","NLP","开发效率"]},{"id":93,"type":"single","answer":["C"],"topic":"sagemaker","stem":{"en":"A retail store wants to predict the demand for a specific product for the next few weeks by using the\nAmazon SageMaker DeepAR forecasting algorithm.\nWhich type of data will meet this requirement?","zh":"某零售商店希望使用 Amazon SageMaker DeepAR 预测算法预测某特定产品未来几周的需求。哪种类型的数据能满足这一要求？"},"options":[{"key":"A","en":"Text data","zh":"文本数据"},{"key":"B","en":"Image data","zh":"图像数据"},{"key":"C","en":"Time series data","zh":"时间序列数据"},{"key":"D","en":"Binary data","zh":"二进制数据"}],"explanation":{"en":"The Amazon SageMaker DeepAR forecasting algorithm is specifically designed for forecasting scalar\n(one-dimensional) time series data using recurrent neural networks (RNNs). It excels when trained on\ndatasets containing hundreds of related time series, enabling it to learn patterns across multiple series and\nprovide accurate forecasts.\nReference:","zh":"Amazon SageMaker DeepAR 预测算法专门用于使用循环神经网络（RNN）对一维时间序列数据进行预测。当在包含数百条相关时间序列的数据集上训练时，它表现出色，能够跨多条序列学习模式并提供准确预测。\n参考："},"tip":{"zh":"DeepAR 就是时间序列预测算法，喂时间序列数据，不是文本或图像。","en":""},"keywords":["DeepAR","时间序列","需求预测"]},{"id":94,"type":"single","answer":["D"],"topic":"responsible","stem":{"en":"A large retail bank wants to develop an ML system to help the risk management team decide on loan\nallocations for different demographics.\nWhat must the bank do to develop an unbiased ML model?","zh":"某大型零售银行希望开发一个 ML 系统，帮助风险管理团队为不同人群决定贷款额度分配。该银行必须做什么才能开发出无偏见的 ML 模型？"},"options":[{"key":"A","en":"Reduce the size of the training dataset.","zh":"减小训练数据集的规模。"},{"key":"B","en":"Ensure that the ML model predictions are consistent with historical results.","zh":"确保 ML 模型的预测与历史结果一致。"},{"key":"C","en":"Create a different ML model for each demographic group.","zh":"为每个人群分别创建不同的 ML 模型。"},{"key":"D","en":"Measure class imbalance on the training dataset. Adapt the training process accordingly.","zh":"衡量训练数据集中的类别不平衡，并相应地调整训练过程。"}],"explanation":{"en":"In machine learning, class imbalance occurs when certain classes are underrepresented in the training\ndataset, leading to biased model predictions. To develop an unbiased model, it's crucial to assess the\nclass distribution and adjust the training process to address any imbalances. This can be achieved through\ntechniques such as oversampling the minority class, undersampling the majority class, or applying class\nweights to ensure the model treats all classes equitably.","zh":"在机器学习中，当某些类别在训练数据集中代表性不足时，就会出现类别不平衡，从而导致模型预测带有偏见。要开发无偏见的模型，关键在于评估类别分布并调整训练过程以解决不平衡。可以通过对少数类过采样、对多数类欠采样或应用类别权重等技术来实现，以确保模型公平对待所有类别。"},"tip":{"zh":"偏见常来自类别不平衡 → 先测量再调整采样或类别权重。","en":""},"keywords":["类别不平衡","公平性","偏见"]},{"id":95,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"Which prompting technique can protect against prompt injection attacks?","zh":"哪种提示技术可以防御提示注入攻击？"},"options":[{"key":"A","en":"Adversarial prompting","zh":"对抗性提示"},{"key":"B","en":"Zero-shot prompting","zh":"零样本提示"},{"key":"C","en":"Least-to-most prompting","zh":"由少到多提示"},{"key":"D","en":"Chain-of-thought prompting","zh":"思维链提示"}],"explanation":{"en":"Adversarial prompting is a technique used to defend against prompt injection attacks by crafting inputs that\nare specifically designed to identify and neutralize malicious prompts. This approach involves generating\nprompts that can detect and mitigate adversarial inputs, thereby enhancing the robustness of language\nmodels against such attacks.","zh":"对抗性提示是一种用于防御提示注入攻击的技术，它通过精心构造输入来识别并化解恶意提示。该方法生成能够检测和缓解对抗性输入的提示，从而增强语言模型抵御此类攻击的鲁棒性。"},"tip":{"zh":"防提示注入 → 对抗性提示；零样本、思维链都不是安全手段。","en":""},"keywords":["提示注入","对抗性提示","安全防护"]},{"id":96,"type":"single","answer":["C"],"topic":"eval","stem":{"en":"A company has fine-tuned a large language model (LLM) to answer questions for a help desk. The\ncompany wants to determine if the fine-tuning has enhanced the model's accuracy.\nWhich metric should the company use for the evaluation?","zh":"某公司微调了一个大型语言模型（LLM）来为服务台回答问题。公司希望确定微调是否提升了该模型的准确率。公司应使用哪个指标进行评估？"},"options":[{"key":"A","en":"Precision","zh":"精确率"},{"key":"B","en":"Time to first token","zh":"首词元延迟"},{"key":"C","en":"F1 score","zh":"F1 分数"},{"key":"D","en":"Word error rate","zh":"词错误率"}],"explanation":{"en":"The F1 score is a metric that combines precision and recall into a single value, providing a balance\nbetween the two. It is particularly useful in evaluating models where there is an uneven class distribution,\nas it considers both false positives and false negatives. The F1 score is calculated as the harmonic mean\nof precision and recall:\n\nThis metric ranges from 0 to 1, with 1 indicating perfect precision and recall. In the context of evaluating a\nfine-tuned large language model (LLM) for a help desk application, the F1 score is appropriate because it\nassesses the model's ability to provide accurate and relevant responses, balancing the trade-off between\nprecision (correctness of responses) and recall (completeness of relevant responses).\nReference:","zh":"F1 分数是把精确率和召回率合并为一个值的指标，在两者之间取得平衡。在评估类别分布不均衡的模型时尤其有用，因为它同时考虑假阳性和假阴性。F1 分数计算为精确率和召回率的调和平均数：\n\n该指标范围为 0 到 1，1 表示精确率和召回率都完美。在评估服务台应用的微调大型语言模型（LLM）时，F1 分数是合适的，因为它评估模型提供准确且相关回复的能力，在精确率（回复的正确性）和召回率（相关回复的完整性）之间取得平衡。\n参考："},"tip":{"zh":"既要准又要全 → 用 F1；精确率和召回率单独看都会偏。","en":""},"keywords":["F1 分数","精确率","召回率"]},{"id":97,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"A company is using Retrieval Augmented Generation (RAG) with Amazon Bedrock and Stable Diffusion to\ngenerate product images based on text descriptions. The results are often random and lack specific\ndetails. The company wants to increase the specificity of the generated images.\nWhich solution meets these requirements?","zh":"某公司使用 Amazon Bedrock 的检索增强生成（RAG）配合 Stable Diffusion，根据文本描述生成产品图像。结果往往很随机且缺乏具体细节。公司希望提高生成图像的具体性。哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Increase the number of generation steps.","zh":"增加生成步数。"},{"key":"B","en":"Use the MASK_IMAGE_BLACK mask source option.","zh":"使用 MASK_IMAGE_BLACK 掩码来源选项。"},{"key":"C","en":"Increase the classifier-free guidance (CFG) scale.","zh":"提高无分类器引导（CFG）比例。"},{"key":"D","en":"Increase the prompt strength.","zh":"提高提示强度。"}],"explanation":{"en":"In Stable Diffusion, the classifier-free guidance (CFG) scale parameter controls how closely the\ngenerated image adheres to the provided text prompt. By increasing the CFG scale, the model places\nmore emphasis on the prompt, leading to images that more accurately reflect the specified details.\nHowever, it's important to balance this setting, as excessively high values can result in less diverse and\npotentially lower-quality images.","zh":"在 Stable Diffusion 中，无分类器引导（CFG）比例参数控制生成图像贴合所提供文本提示的程度。提高 CFG 比例会让模型更重视提示，从而生成更准确反映指定细节的图像。但需要平衡该设置，因为过高的值会导致多样性下降，并可能降低图像质量。"},"tip":{"zh":"图不贴合提示 → 提高 CFG 比例；太高又会糊、会单调。","en":""},"keywords":["CFG 比例","Stable Diffusion","提示贴合度"]},{"id":98,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"A company wants to implement a large language model (LLM) based chatbot to provide customer service\nagents with real-time contextual responses to customers' inquiries. The company will use the company's\npolicies as the knowledge base.\nWhich solution will meet these requirements MOST cost-effectively?","zh":"某公司希望实施基于大型语言模型（LLM）的聊天机器人，为客户服务坐席提供针对客户咨询的实时上下文回复。公司将使用公司政策作为知识库。哪种解决方案能以最具成本效益的方式满足这些要求？"},"options":[{"key":"A","en":"Retrain the LLM on the company policy data.","zh":"用公司政策数据重新训练该 LLM。"},{"key":"B","en":"Fine-tune the LLM on the company policy data.","zh":"用公司政策数据微调该 LLM。"},{"key":"C","en":"Implement Retrieval Augmented Generation (RAG) for in-context responses.","zh":"实施检索增强生成（RAG）以提供上下文回复。"},{"key":"D","en":"Use pre-training and data augmentation on the company policy data.","zh":"对公司政策数据使用预训练和数据增强。"}],"explanation":{"en":"Retrieval Augmented Generation (RAG) integrates external data sources with LLMs to produce accurate\nand contextually relevant outputs without the need for extensive retraining. By connecting the chatbot to\nthe company's policy documents, RAG enables the model to retrieve pertinent information in real-time,\nensuring responses are both accurate and up-to-date. This approach is cost-effective as it leverages\nexisting data without the computational expenses associated with retraining or fine-tuning large models.\nReference:","zh":"检索增强生成（RAG）将外部数据源与 LLM 集成，无需大量重新训练即可生成准确且上下文相关的输出。通过把聊天机器人连接到公司政策文档，RAG 使模型能够实时检索相关信息，确保回复既准确又是最新的。这种方法具有成本效益，因为它利用现有数据，而不必承担重新训练或微调大型模型的计算开销。\n参考："},"tip":{"zh":"私有知识库要实时更新又不想重训 → RAG 最省钱。","en":""},"keywords":["RAG","知识库","成本效益"]},{"id":99,"type":"single","answer":["A"],"topic":"services","stem":{"en":"A company wants to create a new solution by using AWS Glue. The company has minimal programming\nexperience with AWS Glue.\nWhich AWS service can help the company use AWS Glue?","zh":"某公司希望使用 AWS Glue 创建新解决方案。该公司对 AWS Glue 的编程经验很少。哪种 AWS 服务可以帮助该公司使用 AWS Glue？"},"options":[{"key":"A","en":"Amazon Q Developer","zh":"Amazon Q Developer"},{"key":"B","en":"AWS Config","zh":"AWS Config"},{"key":"C","en":"Amazon Personalize","zh":"Amazon Personalize"},{"key":"D","en":"Amazon Comprehend","zh":"Amazon Comprehend"}],"explanation":{"en":"Amazon Q Developer is a tool designed to help users with minimal programming experience to work with\nAWS Glue. It provides a graphical user interface and simplifies the creation of data transformation and\nextraction workflows, allowing users to perform tasks like querying and working with data without needing\ndeep coding skills.","zh":"Amazon Q Developer 是一款帮助编程经验很少的用户使用 AWS Glue 的工具。它提供图形界面并简化数据转换和提取工作流的创建，使用户无需深厚的编码技能即可执行查询和处理数据等任务。"},"tip":{"zh":"不会写代码又想用 Glue → Amazon Q Developer 帮你生成。","en":""},"keywords":["Amazon Q Developer","AWS Glue","低代码"]},{"id":100,"type":"single","answer":["A"],"topic":"responsible","stem":{"en":"A company is developing a mobile ML app that uses a phone's camera to diagnose and treat insect bites.\nThe company wants to train an image classification model by using a diverse dataset of insect bite photos\nfrom different genders, ethnicities, and geographic locations around the world.\nWhich principle of responsible AI does the company demonstrate in this scenario?","zh":"某公司正在开发一款移动 ML 应用，使用手机摄像头诊断和治疗昆虫叮咬。公司希望使用来自世界各地不同性别、族裔和地理位置的多样化昆虫叮咬照片数据集来训练图像分类模型。在此场景中，公司体现了哪项负责任 AI 原则？"},"options":[{"key":"A","en":"Fairness","zh":"公平性"},{"key":"B","en":"Explainability","zh":"可解释性"},{"key":"C","en":"Governance","zh":"治理"},{"key":"D","en":"Transparency","zh":"透明度"}],"explanation":{"en":"The company is actively seeking to ensure that the image classification model is trained on a diverse\ndataset that includes insect bite photos from various genders, ethnicities, and geographic locations. This\nreflects the fairness principle of responsible AI, which emphasizes creating models that make unbiased\ndecisions across all demographic groups. By including a diverse range of data, the company is aiming to\nprevent biases that could lead to inaccurate diagnoses or treatments for certain groups of people.\nFairness ensures that AI systems do not discriminate based on race, gender, geography, or other\ncharacteristics.","zh":"公司积极确保图像分类模型在包含不同性别、族裔和地理位置的昆虫叮咬照片的多样化数据集上训练。这体现了负责任 AI 的公平性原则，该原则强调创建能在所有人群上做出无偏见决策的模型。通过纳入多样化的数据，公司旨在防止可能导致某些人群诊断或治疗不准确的偏见。公平性确保 AI 系统不会基于种族、性别、地理或其他特征进行歧视。"},"tip":{"zh":"数据集覆盖各类人群 → 公平性；可解释性和透明度是另外两个维度。","en":""},"keywords":["公平性","多样化数据集","负责任 AI"]},{"id":101,"type":"single","answer":["A"],"topic":"responsible","stem":{"en":"A company is developing an ML model to make loan approvals. The company must implement a solution\nto detect bias in the model. The company must also be able to explain the model's predictions.\nWhich solution will meet these requirements?","zh":"某公司正在开发一个用于贷款审批的 ML 模型。公司必须实施一个能检测模型中偏见的解决方案，并且必须能够解释模型的预测。哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Amazon SageMaker Clarify","zh":"Amazon SageMaker Clarify"},{"key":"B","en":"Amazon SageMaker Data Wrangler","zh":"Amazon SageMaker Data Wrangler"},{"key":"C","en":"Amazon SageMaker Model Cards","zh":"Amazon SageMaker Model Cards"},{"key":"D","en":"AWS AI Service Cards","zh":"AWS AI Service Cards"}],"explanation":{"en":"Amazon SageMaker Clarify is a tool that helps detect bias in machine learning models and provides\nexplainability for model predictions. It allows users to understand the factors influencing a model's\npredictions and assess whether the model is fair across different demographic groups. This is exactly what\nthe company needs for detecting bias and explaining model decisions, especially for high-stakes\napplications like loan approvals.\nBias detection: SageMaker Clarify can analyze the training data and the model's predictions to identify\nand mitigate bias.\nExplainability: It provides features for explaining the predictions made by the model, which helps\nusers understand the reasons behind the model's decisions.","zh":"Amazon SageMaker Clarify 是一款帮助检测机器学习模型偏见并提供预测可解释性的工具。它让用户能够理解影响模型预测的因素，并评估模型在不同人群之间是否公平。这正是公司在贷款审批这类高风险应用中检测偏见和解释模型决策所需要的。\n偏见检测：SageMaker Clarify 可以分析训练数据和模型预测，以识别并缓解偏见。\n可解释性：它提供解释模型预测的功能，帮助用户理解模型决策背后的原因。"},"tip":{"zh":"既要查偏见又要解释预测 → SageMaker Clarify 一个工具全包。","en":""},"keywords":["SageMaker Clarify","偏见检测","可解释性"]},{"id":102,"type":"single","answer":["C"],"topic":"eval","stem":{"en":"A company has developed a generative text summarization model by using Amazon Bedrock. The\ncompany will use Amazon Bedrock automatic model evaluation capabilities.\nWhich metric should the company use to evaluate the accuracy of the model?","zh":"某公司使用 Amazon Bedrock 开发了一个生成式文本摘要模型。公司将使用 Amazon Bedrock 的自动模型评估功能。公司应使用哪个指标来评估该模型的准确率？"},"options":[{"key":"A","en":"Area Under the ROC Curve (AUC) score","zh":"受试者工作特征曲线下面积（AUC）分数"},{"key":"B","en":"F1 score","zh":"F1 分数"},{"key":"C","en":"BERTScore","zh":"BERTScore"},{"key":"D","en":"Real world knowledge (RWK) score","zh":"真实世界知识（RWK）分数"}],"explanation":{"en":"BERTScore is a metric specifically designed for evaluating the quality of text generated by models,\nparticularly in tasks like text summarization and machine translation. It uses contextual embeddings from a\npre-trained BERT model to compare generated text with reference text at the word level, making it well-\nsuited for evaluating the accuracy of generative text summarization models.\nBERTScore assesses the semantic similarity between the generated text and the reference text, providing\na more nuanced evaluation compared to traditional methods that focus on exact matches.","zh":"BERTScore 是专为评估模型生成文本质量而设计的指标，尤其适用于文本摘要和机器翻译等任务。它使用预训练 BERT 模型的上下文嵌入，在词级别把生成文本与参考文本进行比较，因此非常适合评估生成式文本摘要模型的准确率。\nBERTScore 评估生成文本与参考文本之间的语义相似度，相比只关注精确匹配的传统方法能提供更细致的评估。"},"tip":{"zh":"生成式摘要比语义相似 → 用 BERTScore；AUC 和 F1 是分类指标。","en":""},"keywords":["BERTScore","文本摘要","语义相似度"]},{"id":103,"type":"single","answer":["A"],"topic":"general","stem":{"en":"An AI practitioner wants to predict the classification of flowers based on petal length, petal width, sepal\nlength, and sepal width.\nWhich algorithm meets these requirements?","zh":"某 AI 从业者希望根据花瓣长度、花瓣宽度、萼片长度和萼片宽度来预测花的分类。哪种算法能满足这些要求？"},"options":[{"key":"A","en":"K-nearest neighbors (k-NN)","zh":"K 近邻（k-NN）"},{"key":"B","en":"K-mean","zh":"K 均值"},{"key":"C","en":"Autoregressive Integrated Moving Average (ARIMA)","zh":"自回归积分滑动平均（ARIMA）"},{"key":"D","en":"Linear regression","zh":"线性回归"}],"explanation":{"en":"K-nearest neighbors (k-NN) is a supervised learning algorithm used for classification tasks. It works by\nclassifying a data point based on how its features (such as petal length, petal width, sepal length, and\nsepal width in this case) are similar to the data points in the training set. For this problem, where the task is\nto classify flowers based on their features, k-NN is an appropriate choice.\nk-NN is simple and effective for classification problems where the decision boundary is not necessarily\nlinear, as it looks at the closest neighbors to make predictions.","zh":"K 近邻（k-NN）是一种用于分类任务的监督式学习算法。它通过判断某数据点的特征（此处为花瓣长度、花瓣宽度、萼片长度和萼片宽度）与训练集中数据点的相似程度来对该数据点进行分类。对于此问题，任务是根据特征对花进行分类，k-NN 是合适的选择。\nk-NN 简单有效，适用于决策边界不一定是线性的分类问题，因为它通过查看最近的邻居来做出预测。"},"tip":{"zh":"有标签 + 分类任务 → k-NN；K 均值是无监督聚类，别选错。","en":""},"keywords":["k-NN","分类","监督式学习"]},{"id":104,"type":"single","answer":["A"],"topic":"security","stem":{"en":"A company is using custom models in Amazon Bedrock for a generative AI application. The company\nwants to use a company managed encryption key to encrypt the model artifacts that the model\ncustomization jobs create.\nWhich AWS service meets these requirements?","zh":"某公司在 Amazon Bedrock 中使用自定义模型构建生成式 AI 应用。公司希望使用公司托管的加密密钥来加密模型定制作业创建的模型构件。哪种 AWS 服务能满足这些要求？"},"options":[{"key":"A","en":"AWS Key Management Service (AWS KMS)","zh":"AWS Key Management Service（AWS KMS）"},{"key":"B","en":"Amazon Inspector","zh":"Amazon Inspector"},{"key":"C","en":"Amazon Macie","zh":"Amazon Macie"},{"key":"D","en":"AWS Secrets Manager","zh":"AWS Secrets Manager"}],"explanation":{"en":"AWS Key Management Service (AWS KMS) is a fully managed service that allows you to create and\ncontrol encryption keys used to encrypt your data. It is ideal for scenarios like this, where a company\nwants to use a custom, company-managed encryption key to protect model artifacts. AWS KMS allows you\nto securely manage keys for encrypting and decrypting data, and it integrates with various AWS services,\nincluding Amazon Bedrock.\nAWS KMS provides centralized key management, and it is designed for use cases that involve encrypting\nboth data and artifacts, such as model customization jobs.","zh":"AWS Key Management Service（AWS KMS）是一项完全托管的服务，允许你创建并控制用于加密数据的加密密钥。它非常适合此类场景：公司希望使用自定义的、由公司管理的加密密钥来保护模型构件。AWS KMS 允许你安全管理用于加密和解密数据的密钥，并与包括 Amazon Bedrock 在内的多种 AWS 服务集成。\nAWS KMS 提供集中式密钥管理，专为需要同时加密数据和构件（例如模型定制作业）的用例而设计。"},"tip":{"zh":"自己管加密密钥 → AWS KMS；Secrets Manager 是存密码的。","en":""},"keywords":["AWS KMS","加密密钥","模型构件"]},{"id":105,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"A company wants to use large language models (LLMs) to produce code from natural language code\ncomments.\nWhich LLM feature meets these requirements?","zh":"某公司希望使用大型语言模型（LLM）根据自然语言代码注释生成代码。哪项 LLM 功能能满足这些要求？"},"options":[{"key":"A","en":"Text summarization","zh":"文本摘要"},{"key":"B","en":"Text generation","zh":"文本生成"},{"key":"C","en":"Text completion","zh":"文本补全"},{"key":"D","en":"Text classification","zh":"文本分类"}],"explanation":{"en":"Text generation is the feature of large language models (LLMs) that enables them to produce text based\non a given prompt or input. In this scenario, the input would be natural language code comments, and the\nLLM would generate code based on those comments. This process involves understanding the context of\nthe comment and generating corresponding code, which is the core functionality of text generation.","zh":"文本生成是大型语言模型（LLM）的一项功能，使其能够根据给定的提示或输入生成文本。在此场景中，输入是自然语言代码注释，LLM 会根据这些注释生成代码。该过程涉及理解注释的上下文并生成相应的代码，这正是文本生成的核心功能。"},"tip":{"zh":"从注释写出整段新代码 → 文本生成；补全只是接着写已有的。","en":""},"keywords":["文本生成","代码生成","LLM 功能"]},{"id":106,"type":"single","answer":["C"],"topic":"eval","stem":{"en":"A company is introducing a mobile app that helps users learn foreign languages. The app makes text more\ncoherent by calling a large language model (LLM). The company collected a diverse dataset of text and\nsupplemented the dataset with examples of more readable versions. The company wants the LLM output\nto resemble the provided examples.\nWhich metric should the company use to assess whether the LLM meets these requirements?","zh":"某公司推出一款帮助用户学习外语的移动应用。该应用通过调用大型语言模型（LLM）使文本更连贯。公司收集了多样化的文本数据集，并用更易读版本的示例对该数据集进行了补充。公司希望 LLM 的输出与所提供的示例相似。公司应使用哪个指标来评估该 LLM 是否满足这些要求？"},"options":[{"key":"A","en":"Value of the loss function","zh":"损失函数的值"},{"key":"B","en":"Semantic robustness","zh":"语义鲁棒性"},{"key":"C","en":"Recall-Oriented Understudy for Gisting Evaluation (ROUGE) score","zh":"面向召回率的要点评估替补（ROUGE）分数"},{"key":"D","en":"Latency of the text generation","zh":"文本生成的延迟"}],"explanation":{"en":"ROUGE is a set of metrics that evaluates the quality of summaries by comparing the overlap of n-grams,\nword sequences, and word pairs between the model output and reference examples. Since the company\nis working on a language model that improves the coherence of text and wants the output to resemble the\nprovided examples (which are more readable versions of the original text), ROUGE is the most appropriate\nmetric. It assesses how closely the generated text matches the reference text in terms of content and\nreadability.\nROUGE score is commonly used to evaluate the performance of models in tasks like summarization,\nwhere the goal is to ensure the generated text aligns closely with human-provided examples.","zh":"ROUGE 是一组指标，通过比较模型输出与参考示例之间 n-gram、词序列和词对的重叠程度来评估摘要质量。由于公司正在处理一个提升文本连贯性的语言模型，并希望输出与所提供的示例（即原始文本更易读的版本）相似，因此 ROUGE 是最合适的指标。它评估生成文本在内容和可读性上与参考文本的接近程度。\nROUGE 分数常用于评估模型在摘要等任务中的表现，这类任务的目标是确保生成文本与人工提供的示例高度一致。"},"tip":{"zh":"输出要和参考示例对齐（摘要类）→ ROUGE；BLEU 才是翻译。","en":""},"keywords":["ROUGE","摘要评估","参考示例"]},{"id":107,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"A company notices that its foundation model (FM) generates images that are unrelated to the prompts.\nThe company wants to modify the prompt techniques to decrease unrelated images.\nWhich solution meets these requirements?","zh":"某公司发现其基础模型（FM）生成的图像与提示无关。公司希望修改提示技术以减少无关图像。哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Use zero-shot prompts.","zh":"使用零样本提示。"},{"key":"B","en":"Use negative prompts.","zh":"使用负向提示。"},{"key":"C","en":"Use positive prompts.","zh":"使用正向提示。"},{"key":"D","en":"Use ambiguous prompts.","zh":"使用模糊提示。"}],"explanation":{"en":"Negative prompts are used to explicitly instruct the model about what to avoid or not generate. By\nproviding the model with specific guidance on what is not desired (e.g., by including terms or concepts that\nshould not appear in the image), the model can better focus on generating relevant and related content.\nThis technique can help reduce unrelated or irrelevant images by constraining the model's creative\ngeneration process.","zh":"负向提示用于明确告诉模型应避免或不生成什么。通过向模型提供关于不希望出现内容的具体指导（例如包含不应出现在图像中的术语或概念），模型能更好地聚焦于生成相关且贴合的内容。该技术通过约束模型的创造性生成过程，有助于减少无关或不相关的图像。"},"tip":{"zh":"不想让图里出现什么 → 写负向提示，明确排除。","en":""},"keywords":["负向提示","图像生成","提示技术"]},{"id":108,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"A company wants to use a large language model (LLM) to generate concise, feature-specific descriptions\nfor the company’s products.\nWhich prompt engineering technique meets these requirements?","zh":"某公司希望使用大型语言模型（LLM）为其产品生成简洁、突出特性的描述。哪种提示工程技术能满足这些要求？"},"options":[{"key":"A","en":"Create one prompt that covers all products. Edit the responses to make the responses more specific, concise, and tailored to each product.","zh":"创建一个覆盖所有产品的提示。编辑回复，使其更具体、简洁并贴合每个产品。"},{"key":"B","en":"Create prompts for each product category that highlight the key features. Include the desired output format and length for each prompt response.","zh":"为每个产品类别创建突出关键特性的提示。在每个提示的回复中说明期望的输出格式和长度。"},{"key":"C","en":"Include a diverse range of product features in each prompt to generate creative and unique descriptions.","zh":"在每个提示中包含多样化的产品特性，以生成有创意且独特的描述。"},{"key":"D","en":"Provide detailed, product-specific prompts to ensure precise and customized descriptions.","zh":"提供详细、针对具体产品的提示，以确保描述精确且定制化。"}],"explanation":{"en":"To generate concise, feature-specific descriptions for each product, the company should create prompts\ntailored to specific product categories. By highlighting the key features of each product category in the\nprompt, the model can focus on generating descriptions that are relevant and aligned with the unique\nattributes of each product. Additionally, specifying the desired output format and length ensures that the\n\nresponses meet the company's requirements for conciseness and clarity.\nTailored prompts help ensure the model generates relevant and accurate descriptions by focusing on the\nmost important features of each product category.\nDesired output format and length ensure the responses are consistent and concise, as required.","zh":"要为每个产品生成简洁、突出特性的描述，公司应创建针对具体产品类别定制的提示。通过在提示中突出每个产品类别的关键特性，模型可以专注于生成与每个产品独特属性相关且一致的描述。此外，明确期望的输出格式和长度可确保回复满足公司对简洁性和清晰度的要求。\n定制提示通过聚焦每个产品类别最重要的特性，帮助确保模型生成相关且准确的描述。\n明确的输出格式和长度可确保回复符合要求，保持一致且简洁。"},"tip":{"zh":"按品类分组 + 写清格式长度 → 比一个提示包打天下更可控。","en":""},"keywords":["提示工程","输出格式","产品类别"]},{"id":109,"type":"single","answer":["B"],"topic":"eval","stem":{"en":"A company is developing an ML model to predict customer churn. The model performs well on the training\ndataset but does not accurately predict churn for new data.\nWhich solution will resolve this issue?","zh":"某公司正在开发一个预测客户流失的 ML 模型。该模型在训练数据集上表现良好，但对新数据的流失预测不准确。哪种解决方案能解决此问题？"},"options":[{"key":"A","en":"Decrease the regularization parameter to increase model complexity.","zh":"降低正则化参数以增加模型复杂度。"},{"key":"B","en":"Increase the regularization parameter to decrease model complexity.","zh":"提高正则化参数以降低模型复杂度。"},{"key":"C","en":"Add more features to the input data.","zh":"向输入数据添加更多特征。"},{"key":"D","en":"Train the model for more epochs.","zh":"训练模型更多轮次。"}],"explanation":{"en":"The issue described is a common case of overfitting, where the model performs well on the training data\nbut fails to generalize to new, unseen data. This suggests that the model is too complex and has learned\nto memorize the training data rather than identifying generalizable patterns.\nIncreasing the regularization parameter helps to reduce model complexity by penalizing large weights,\nthereby encouraging simpler models that are less likely to overfit. This will improve the model's ability to\ngeneralize to new data, potentially improving performance on unseen customer data.","zh":"所描述的问题是典型的过拟合：模型在训练数据上表现良好，却无法泛化到新的、未见过的数据。这说明模型过于复杂，学到了记忆训练数据，而不是识别可泛化的模式。\n提高正则化参数通过对大权重施加惩罚来降低模型复杂度，从而促使模型更简单、更不易过拟合。这将提升模型对新数据的泛化能力，有可能改善其在未见过的客户数据上的表现。"},"tip":{"zh":"训练好、新数据差 = 过拟合 → 加大正则化降复杂度。","en":""},"keywords":["过拟合","正则化","泛化能力"]},{"id":110,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"A company is implementing intelligent agents to provide conversational search experiences for its\ncustomers. The company needs a database service that will support storage and queries of embeddings\nfrom a generative AI model as vectors in the database.\nWhich AWS service will meet these requirements?","zh":"某公司正在实施智能代理，为客户提供对话式搜索体验。公司需要一个数据库服务，支持以向量形式存储和查询生成式 AI 模型的嵌入向量。哪种 AWS 服务能满足这些要求？"},"options":[{"key":"A","en":"Amazon Athena","zh":"Amazon Athena"},{"key":"B","en":"Amazon Aurora PostgreSQL","zh":"Amazon Aurora PostgreSQL"},{"key":"C","en":"Amazon Redshift","zh":"Amazon Redshift"},{"key":"D","en":"Amazon EMR","zh":"Amazon EMR"}],"explanation":{"en":"Amazon Aurora PostgreSQL is a relational database service that supports a wide range of applications,\nincluding those that require vector-based operations. Specifically, Aurora PostgreSQL can be extended\nwith vector search capabilities using extensions like pgvector. This extension allows you to store, index,\nand query vector embeddings from generative AI models, making it well-suited for the company's needs to\nstore and query embeddings as vectors.\npgvector is an extension for PostgreSQL that provides efficient similarity search for vector data, which is\nideal for storing and querying embeddings.","zh":"Amazon Aurora PostgreSQL 是一种关系数据库服务，支持广泛的应用，包括需要向量运算的应用。具体而言，Aurora PostgreSQL 可以通过 pgvector 等扩展来增加向量搜索能力。该扩展允许你存储、索引和查询来自生成式 AI 模型的向量嵌入，非常适合公司以向量形式存储和查询嵌入的需求。\npgvector 是 PostgreSQL 的一个扩展，为向量数据提供高效的相似性搜索，非常适合存储和查询嵌入向量。"},"tip":{"zh":"向量库要 pgvector → Aurora PostgreSQL；Athena 和 Redshift 不是首选。","en":""},"keywords":["pgvector","Aurora PostgreSQL","向量搜索"]},{"id":111,"type":"single","answer":["A"],"topic":"responsible","stem":{"en":"A financial institution is building an AI solution to make loan approval decisions by using a foundation\nmodel (FM). For security and audit purposes, the company needs the AI solution's decisions to be\nexplainable.\nWhich factor relates to the explainability of the AI solution's decisions?","zh":"某金融机构正在使用基础模型（FM）构建一个做出贷款审批决策的 AI 解决方案。出于安全和审计目的，公司需要该 AI 解决方案的决策是可解释的。哪个因素与 AI 解决方案决策的可解释性有关？"},"options":[{"key":"A","en":"Model complexity","zh":"模型复杂度"},{"key":"B","en":"Training time","zh":"训练时间"},{"key":"C","en":"Number of hyperparameters","zh":"超参数数量"},{"key":"D","en":"Deployment time","zh":"部署时间"}],"explanation":{"en":"Model complexity plays a significant role in the explainability of an AI solution. Simpler models tend to be\nmore explainable because it is easier to understand how they make decisions. For example, linear\nregression or decision trees are generally easier to interpret compared to more complex models like deep\nneural networks.\nIn contrast, highly complex models, such as deep learning models, may provide very accurate results but\nare often considered \"black boxes,\" meaning their decision-making process is not easily interpretable. This\nlack of transparency makes it difficult to explain their decisions in a way that satisfies regulatory\nrequirements or customer understanding.","zh":"模型复杂度对 AI 解决方案的可解释性有显著影响。更简单的模型往往更易解释，因为更容易理解它们如何做出决策。例如，线性回归或决策树通常比深度神经网络等更复杂的模型更易解释。\n相比之下，深度学习模型等高度复杂的模型可能给出非常准确的结果，但常被视为「黑盒」，即其决策过程不易解释。这种透明度的缺失使得难以用满足监管要求或客户理解的方式解释其决策。"},"tip":{"zh":"越复杂越黑盒 → 可解释性看模型复杂度，跟训练部署时间无关。","en":""},"keywords":["可解释性","模型复杂度","黑盒"]},{"id":112,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"A pharmaceutical company wants to analyze user reviews of new medications and provide a concise\noverview for each medication.\nWhich solution meets these requirements?","zh":"某制药公司希望分析用户对新型药物的评论，并为每种药物提供简洁的概述。哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Create a time-series forecasting model to analyze the medication reviews by using Amazon Personalize.","zh":"使用 Amazon Personalize 创建时间序列预测模型来分析药物评论。"},{"key":"B","en":"Create medication review summaries by using Amazon Bedrock large language models (LLMs).","zh":"使用 Amazon Bedrock 大型语言模型（LLM）创建药物评论摘要。"},{"key":"C","en":"Create a classification model that categorizes medications into different groups by using Amazon SageMaker.","zh":"使用 Amazon SageMaker 创建把药物归入不同分组的分类模型。"},{"key":"D","en":"Create medication review summaries by using Amazon Rekognition.","zh":"使用 Amazon Rekognition 创建药物评论摘要。"}],"explanation":{"en":"Amazon Bedrock provides access to a variety of large language models (LLMs), which are well-suited for\ntasks such as text summarization. By using LLMs, the pharmaceutical company can automatically\ngenerate concise and coherent summaries of user reviews for each medication. These models are\ndesigned to understand and process large amounts of text, making them ideal for summarizing user\nreviews in a clear and efficient manner.\nAmazon Bedrock allows the company to utilize LLMs that can generate summaries, which is exactly what\nis needed in this case.","zh":"Amazon Bedrock 提供对各种大型语言模型（LLM）的访问，这些模型非常适合文本摘要等任务。通过使用 LLM，该制药公司可以自动为每种药物的用户评论生成简洁且连贯的摘要。这些模型旨在理解和处理大量文本，因此非常适合以清晰高效的方式总结用户评论。\nAmazon Bedrock 让公司能够利用可生成摘要的 LLM，而这正是本案例所需要的。"},"tip":{"zh":"文本摘要 → Bedrock 的 LLM；Rekognition 只处理图像和视频。","en":""},"keywords":["文本摘要","Amazon Bedrock","LLM"]},{"id":113,"type":"single","answer":["A"],"topic":"responsible","stem":{"en":"A company wants to build a lead prioritization application for its employees to contact potential customers.\nThe application must give employees the ability to view and adjust the weights assigned to different\nvariables in the model based on domain knowledge and expertise.\nWhich ML model type meets these requirements?","zh":"某公司希望为员工构建一个潜在客户优先级排序应用，以便联系潜在客户。该应用必须让员工能够基于领域知识和专业经验，查看并调整模型中分配给不同变量的权重。哪种 ML 模型类型能满足这些要求？"},"options":[{"key":"A","en":"Logistic regression model","zh":"逻辑回归模型"},{"key":"B","en":"Deep learning model built on principal components","zh":"基于主成分构建的深度学习模型"},{"key":"C","en":"K-nearest neighbors (k-NN) model","zh":"K 近邻（k-NN）模型"},{"key":"D","en":"Neural network","zh":"神经网络"}],"explanation":{"en":"A logistic regression model is a simple, interpretable machine learning model that allows users to adjust\nthe weights of different variables based on domain knowledge and expertise. Since logistic regression is\nbased on a linear relationship between the input features and the predicted outcome, each feature has a\ncorresponding weight (coefficient) that can be easily viewed and adjusted. This makes it a suitable choice\nfor a lead prioritization application where domain experts need the ability to modify the model based on\ntheir knowledge.","zh":"逻辑回归模型是一种简单、可解释的机器学习模型，允许用户基于领域知识和专业经验调整不同变量的权重。由于逻辑回归基于输入特征与预测结果之间的线性关系，每个特征都有对应的权重（系数），可以方便地查看和调整。这使其成为潜在客户优先级排序应用的合适选择，因为领域专家需要能够根据自己的知识修改模型。"},"tip":{"zh":"要能手动看权重、调权重 → 逻辑回归；神经网络权重看不懂。","en":""},"keywords":["逻辑回归","权重可调","可解释性"]},{"id":114,"type":"hotspot","answer":[],"topic":"eval","stem":{"en":"A company wants to build an ML application.\nSelect and order the correct steps from the following list to develop a well-architected ML workload. Each\nstep should be selected one time.","zh":"某公司希望构建一个 ML 应用。请从以下列表中选出并排序正确的步骤，以开发架构良好的 ML 工作负载。每个步骤只能选择一次。"},"options":[],"explanation":{"en":"The typical sequence of steps in building an ML application involves:\n1. Defining the business goal and framing the ML problem - This step involves understanding the\nbusiness need and determining how ML can address it.\n2. Developing the model - This involves selecting the appropriate algorithm, training the model, and\nevaluating it.\n3. Deploying the model - Once the model is trained, it is deployed to production to serve predictions.\n4. Monitoring the model - After deployment, the model is monitored to ensure it performs well over time\nand to detect any issues like model drift.","zh":"构建 ML 应用的典型步骤顺序如下：\n1. 定义业务目标并为 ML 问题建模——该步骤涉及理解业务需求并确定 ML 如何满足该需求。\n2. 开发模型——这涉及选择合适的算法、训练模型并对其进行评估。\n3. 部署模型——模型训练完成后，将其部署到生产环境以提供预测。\n4. 监控模型——部署后，对模型进行监控，以确保其随时间推移表现良好，并检测模型漂移等问题。"},"tip":{"zh":"排序题记顺序：定业务目标 → 开发模型 → 部署 → 监控。","en":""},"keywords":["ML 生命周期","步骤排序","良好架构"]},{"id":115,"type":"single","answer":["C"],"topic":"eval","stem":{"en":"Which strategy will determine if a foundation model (FM) effectively meets business objectives?","zh":"哪种策略能确定基础模型（FM）是否有效满足业务目标？"},"options":[{"key":"A","en":"Evaluate the model's performance on benchmark datasets.","zh":"在基准数据集上评估模型的表现。"},{"key":"B","en":"Analyze the model's architecture and hyperparameters.","zh":"分析模型的架构和超参数。"},{"key":"C","en":"Assess the model's alignment with specific use cases.","zh":"评估模型与具体用例的契合度。"},{"key":"D","en":"Measure the computational resources required for model deployment.","zh":"衡量模型部署所需的计算资源。"}],"explanation":{"en":"To determine if a foundation model (FM) effectively meets business objectives, the key is to assess how\nwell the model aligns with the specific use cases or business goals it is intended to address. This involves\nevaluating whether the model can provide meaningful and accurate outputs relevant to the business’s\nneeds, ensuring that it solves the real-world problems the company aims to tackle.\nAligning with specific use cases ensures that the model’s capabilities are tailored to the tasks at hand,\nsuch as improving customer support, enhancing decision-making, or automating certain processes.","zh":"要确定基础模型（FM）是否有效满足业务目标，关键是评估模型与其预期解决的具体用例或业务目标的契合程度。这涉及评估模型能否提供与业务需求相关的有意义且准确的输出，确保它解决公司希望应对的现实问题。\n与具体用例契合，可确保模型能力针对手头任务进行调整，例如改进客户支持、增强决策或自动化某些流程。"},"tip":{"zh":"问「是否满足业务目标」→ 看与具体用例的契合度，不是刷榜分数。","en":""},"keywords":["业务目标","用例契合度","模型评估"]},{"id":116,"type":"single","answer":["A"],"topic":"data","stem":{"en":"A company needs to train an ML model to classify images of different types of animals. The company has\na large dataset of labeled images and will not label more data.\nWhich type of learning should the company use to train the model?","zh":"某公司需要训练一个 ML 模型来对不同种类动物的图像进行分类。公司拥有大型的已标注图像数据集，并且不会再标注更多数据。公司应使用哪种类型的学习来训练该模型？"},"options":[{"key":"A","en":"Supervised learning","zh":"监督式学习"},{"key":"B","en":"Unsupervised learning","zh":"无监督学习"},{"key":"C","en":"Reinforcement learning","zh":"强化学习"},{"key":"D","en":"Active learning","zh":"主动学习"}],"explanation":{"en":"In supervised learning, the model is trained using a labeled dataset, where each image (input) has a\ncorresponding label (the type of animal, in this case). Since the company already has a large dataset of\nlabeled images, supervised learning is the most appropriate approach. The model learns to classify the\nimages based on the features and labels in the training data.","zh":"在监督式学习中，模型使用已标注数据集进行训练，其中每张图像（输入）都有对应的标签（此例中为动物种类）。由于公司已经拥有大型的已标注图像数据集，监督式学习是最合适的方法。模型会根据训练数据中的特征和标签学习对图像进行分类。"},"tip":{"zh":"有标注数据 + 分类 → 监督式学习；无监督只能聚类。","en":""},"keywords":["监督式学习","标注数据","图像分类"]},{"id":117,"type":"single","answer":["C"],"topic":"responsible","stem":{"en":"Which phase of the ML lifecycle determines compliance and regulatory requirements?","zh":"ML 生命周期的哪个阶段决定合规与监管要求？"},"options":[{"key":"A","en":"Feature engineering","zh":"特征工程"},{"key":"B","en":"Model training","zh":"模型训练"},{"key":"C","en":"Data collection","zh":"数据收集"},{"key":"D","en":"Business goal identification","zh":"业务目标识别"}],"explanation":{"en":"The data collection phase of the ML lifecycle is the most relevant for determining compliance and\nregulatory requirements. During this phase, organizations must ensure that the data being collected and\nused for training the model complies with legal and regulatory standards, such as data privacy laws (e.g.,\nGDPR, HIPAA), industry-specific regulations, and ethical considerations. The organization must also verify\nthat they have the proper consent to use the data and that the data does not contain any biases or violate\nany regulations.","zh":"ML 生命周期中的数据收集阶段与确定合规和监管要求最为相关。在此阶段，组织必须确保为训练模型而收集和使用的数据符合法律和监管标准，例如数据隐私法（如 GDPR、HIPAA）、行业特定法规以及伦理考量。组织还必须核实自己拥有使用数据的适当授权，且数据不含任何偏见或不违反任何法规。"},"tip":{"zh":"合规要在收数据时就管住 → 数据收集阶段，采集合规。","en":""},"keywords":["数据收集","合规","ML 生命周期"]},{"id":118,"type":"single","answer":["A"],"topic":"eval","stem":{"en":"A food service company wants to develop an ML model to help decrease daily food waste and increase\nsales revenue. The company needs to continuously improve the model's accuracy.\nWhich solution meets these requirements?","zh":"某餐饮服务公司希望开发一个 ML 模型，帮助减少每日食物浪费并提升销售收入。公司需要持续提升模型的准确率。哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Use Amazon SageMaker and iterate with newer data.","zh":"使用 Amazon SageMaker 并用更新的数据迭代。"},{"key":"B","en":"Use Amazon Personalize and iterate with historical data.","zh":"使用 Amazon Personalize 并用历史数据迭代。"},{"key":"C","en":"Use Amazon CloudWatch to analyze customer orders.","zh":"使用 Amazon CloudWatch 分析客户订单。"},{"key":"D","en":"Use Amazon Rekognition to optimize the model.","zh":"使用 Amazon Rekognition 优化模型。"}],"explanation":{"en":"To continuously improve the accuracy of the machine learning model, Amazon SageMaker is the\nappropriate solution. SageMaker allows for efficient model training, deployment, and iteration. The\ncompany can use SageMaker to retrain the model regularly with newer data to account for changes in\ncustomer behavior, market trends, and other dynamic factors that may affect food waste and sales\nrevenue. Iterating with newer data helps improve the model's performance over time, ensuring it remains\naccurate and relevant.","zh":"要持续提升机器学习模型的准确率，Amazon SageMaker 是合适的解决方案。SageMaker 支持高效的模型训练、部署和迭代。公司可以使用 SageMaker 定期用更新的数据重新训练模型，以适应客户行为变化、市场趋势以及其他可能影响食物浪费和销售收入的动态因素。用更新的数据迭代有助于随时间提升模型表现，确保其保持准确和相关。"},"tip":{"zh":"要持续变准 → 用新数据反复迭代重训，选 SageMaker。","en":""},"keywords":["SageMaker","持续迭代","重新训练"]},{"id":119,"type":"single","answer":["D"],"topic":"security","stem":{"en":"A company has developed an ML model to predict real estate sale prices. The company wants to deploy\nthe model to make predictions without managing servers or infrastructure.\nWhich solution meets these requirements?","zh":"某公司开发了一个预测房地产销售价格的 ML 模型。公司希望部署该模型来进行预测，同时不管理服务器或基础设施。哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Deploy the model on an Amazon EC2 instance.","zh":"在 Amazon EC2 实例上部署该模型。"},{"key":"B","en":"Deploy the model on an Amazon Elastic Kubernetes Service (Amazon EKS) cluster.","zh":"在 Amazon Elastic Kubernetes Service（Amazon EKS）集群上部署该模型。"},{"key":"C","en":"Deploy the model by using Amazon CloudFront with an Amazon S3 integration.","zh":"使用 Amazon CloudFront 与 Amazon S3 集成来部署该模型。"},{"key":"D","en":"Deploy the model by using an Amazon SageMaker endpoint.","zh":"使用 Amazon SageMaker 端点部署该模型。"}],"explanation":{"en":"Amazon SageMaker provides a fully managed service for deploying machine learning models at scale\nwithout needing to manage servers or infrastructure. When you deploy a model using Amazon\nSageMaker endpoints, it handles all the infrastructure, scaling, and maintenance aspects. This allows the\ncompany to focus solely on making predictions and integrating the model into their application, without\nworrying about managing servers or clusters.\nAmazon SageMaker simplifies the deployment of ML models by providing scalable, secure, and\nserverless endpoints, which are ideal for serving predictions in real-time.","zh":"Amazon SageMaker 提供完全托管的服务，可大规模部署机器学习模型，而无需管理服务器或基础设施。当你使用 Amazon SageMaker 端点部署模型时，它会处理所有基础设施、扩缩容和维护方面的工作。这让公司可以只专注于做出预测并将模型集成到应用中，无需担心管理服务器或集群。\nAmazon SageMaker 通过提供可扩展、安全且无服务器的端点，简化了 ML 模型的部署，非常适合实时提供预测。"},"tip":{"zh":"不想管服务器 → SageMaker 端点（全托管）；EC2 和 EKS 都要自己运维。","en":""},"keywords":["SageMaker 端点","无服务器","模型部署"]},{"id":120,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"A company wants to develop an AI application to help its employees check open customer claims, identify\ndetails for a specific claim, and access documents for a claim.\nWhich solution meets these requirements?","zh":"某公司希望开发一个 AI 应用，帮助员工查看未结的客户索赔、识别特定索赔的详情，并访问某项索赔的文档。哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Use Agents for Amazon Bedrock with Amazon Fraud Detector to build the application.","zh":"使用 Agents for Amazon Bedrock 配合 Amazon Fraud Detector 构建该应用。"},{"key":"B","en":"Use Agents for Amazon Bedrock with Amazon Bedrock knowledge bases to build the application.","zh":"使用 Agents for Amazon Bedrock 配合 Amazon Bedrock 知识库构建该应用。"},{"key":"C","en":"Use Amazon Personalize with Amazon Bedrock knowledge bases to build the application.","zh":"使用 Amazon Personalize 配合 Amazon Bedrock 知识库构建该应用。"},{"key":"D","en":"Use Amazon SageMaker to build the application by training a new ML model.","zh":"使用 Amazon SageMaker 训练新的 ML 模型来构建该应用。"}],"explanation":{"en":"Amazon Bedrock is a service that allows you to build AI-powered applications using foundation models\n(FMs) without managing infrastructure. Agents for Amazon Bedrock allows you to create intelligent\nagents that can help users interact with data and perform tasks such as checking open customer claims,\nidentifying claim details, and accessing relevant documents.\nBy using Amazon Bedrock knowledge bases, the AI agent can access relevant information (e.g., details\n\nabout claims, documents, or customer data) in real time, and provide precise, context-driven answers\nbased on the claim-related data stored in the knowledge base.\nAgents for Amazon Bedrock can help automate interactions by understanding and responding to\nnatural language queries, making it a good fit for this use case.\nAmazon Bedrock knowledge bases enable the system to access stored information, documents, and\ndetails for specific claims efficiently.","zh":"Amazon Bedrock 是一项允许你使用基础模型（FM）构建 AI 驱动应用而无需管理基础设施的服务。Agents for Amazon Bedrock 允许你创建智能代理，帮助用户与数据交互并执行任务，例如查看未结客户索赔、识别索赔详情以及访问相关文档。\n通过使用 Amazon Bedrock 知识库，AI 代理可以实时访问相关信息（例如索赔详情、文档或客户数据），并基于知识库中存储的索赔相关数据提供精确、上下文驱动的答案。\nAgents for Amazon Bedrock 可以通过理解和响应自然语言查询来帮助自动化交互，因此非常适合此用例。\nAmazon Bedrock 知识库使系统能够高效访问特定索赔的已存储信息、文档和详情。"},"tip":{"zh":"查业务数据 + 检索文档 → Agent 配 Bedrock 知识库，不用自己训模型。","en":""},"keywords":["Agents for Amazon Bedrock","知识库","RAG"]},{"id":121,"type":"single","answer":["C"],"topic":"general","stem":{"en":"A manufacturing company uses AI to inspect products and find any damages or defects.\nWhich type of AI application is the company using?","zh":"一家制造公司使用 AI 检查产品并找出任何损坏或缺陷。\n该公司使用的是哪一类 AI 应用？"},"options":[{"key":"A","en":"Recommendation system","zh":"推荐系统"},{"key":"B","en":"Natural language processing (NLP)","zh":"自然语言处理（NLP）"},{"key":"C","en":"Computer vision","zh":"计算机视觉"},{"key":"D","en":"Image processing","zh":"图像处理"}],"explanation":{"en":"Computer vision is a field of AI that enables machines to interpret and understand visual information from\nthe world, such as images and videos. In the case of the manufacturing company, the AI is used to inspect\nproducts for damages or defects, which involves analyzing visual data (e.g., product images or videos).\nThis is a classic application of computer vision, where the AI system identifies and classifies objects or\ndefects within images.","zh":"计算机视觉是 AI 的一个领域，它使机器能够解读和理解来自现实世界的视觉信息，例如图像和视频。在这家制造公司的场景中，AI 用于检查产品是否存在损坏或缺陷，这涉及分析视觉数据（例如产品图像或视频）。这是计算机视觉的典型应用，AI 系统在图像中识别并分类物体或缺陷。"},"tip":{"zh":"看图找缺陷=计算机视觉；图像处理只是像素加工，不做识别判断。","en":""},"keywords":["计算机视觉","缺陷检测","图像识别"]},{"id":122,"type":"single","answer":["B"],"topic":"eval","stem":{"en":"A company wants to create an ML model to predict customer satisfaction. The company needs fully\nautomated model tuning.\nWhich AWS service meets these requirements?","zh":"一家公司希望创建 ML 模型来预测客户满意度。该公司需要全自动的模型调优。\n哪项 AWS 服务能满足这些要求？"},"options":[{"key":"A","en":"Amazon Personalize","zh":"Amazon Personalize"},{"key":"B","en":"Amazon SageMaker","zh":"Amazon SageMaker"},{"key":"C","en":"Amazon Athena","zh":"Amazon Athena"},{"key":"D","en":"Amazon Comprehend","zh":"Amazon Comprehend"}],"explanation":{"en":"Amazon SageMaker provides a fully managed environment for building, training, and deploying machine\nlearning models, including automatic model tuning. Specifically, SageMaker includes a feature called\nAutomatic Model Tuning (or Hyperparameter Optimization), which automates the process of finding\nthe best hyperparameters for your machine learning model. This is essential when you want to optimize\nthe model’s performance without manual intervention.\nAmazon SageMaker allows you to automate the training process and hyperparameter tuning, which\naligns perfectly with the company's need for fully automated model tuning.","zh":"Amazon SageMaker 提供完全托管的环境，用于构建、训练和部署机器学习模型，其中包括自动模型调优。具体而言，SageMaker 包含一项称为自动模型调优（Automatic Model Tuning，即超参数优化）的功能，可自动完成寻找机器学习模型最佳超参数的过程。当你希望在不进行人工干预的情况下优化模型性能时，这一点至关重要。\nAmazon SageMaker 可让你自动化训练过程和超参数调优，完全契合该公司对全自动模型调优的需求。"},"tip":{"zh":"要全自动调参 → SageMaker 的自动模型调优（超参数优化），Personalize 只做推荐。","en":""},"keywords":["自动模型调优","超参数优化","SageMaker"]},{"id":123,"type":"single","answer":["A"],"topic":"responsible","stem":{"en":"Which technique can a company use to lower bias and toxicity in generative AI applications during the\npost-processing ML lifecycle?","zh":"在 ML 生命周期的后处理阶段，公司可以使用哪种技术来降低生成式 AI 应用中的偏见和有害内容？"},"options":[{"key":"A","en":"Human-in-the-loop","zh":"人在回路"},{"key":"B","en":"Data augmentation","zh":"数据增强"},{"key":"C","en":"Feature engineering","zh":"特征工程"},{"key":"D","en":"Adversarial training","zh":"对抗训练"}],"explanation":{"en":"Human-in-the-loop (HITL) is a technique where human oversight is involved in the decision-making\nprocess of AI systems. In the context of generative AI applications, HITL can be used during the post-\nprocessing phase to identify and mitigate biases or toxic outputs. Humans can review and intervene when\nthe model generates inappropriate or biased content, providing corrections or adjustments that help\nreduce the likelihood of toxicity and bias. This feedback loop helps refine and improve the model’s outputs\nover time.","zh":"人在回路（HITL）是一种在 AI 系统的决策过程中引入人工监督的技术。在生成式 AI 应用的场景中，HITL 可在后处理阶段用于识别和缓解偏见或有毒输出。当模型生成不当或有偏见的内容时，人工可以审查并介入，提供纠正或调整，从而降低出现有害内容和偏见的可能性。这种反馈回路有助于随时间推移不断改进和提升模型的输出。"},"tip":{"zh":"问的是“后处理阶段”→ 只能靠人审，选人在回路；数据增强、对抗训练都在训练期。","en":""},"keywords":["人在回路","后处理","偏见与有害内容"]},{"id":124,"type":"single","answer":["A"],"topic":"responsible","stem":{"en":"A bank has fine-tuned a large language model (LLM) to expedite the loan approval process. During an\nexternal audit of the model, the company discovered that the model was approving loans at a faster pace\nfor a specific demographic than for other demographics.\nHow should the bank fix this issue MOST cost-effectively?","zh":"一家银行微调了大型语言模型（LLM）以加快贷款审批流程。在对该模型进行外部审计时，公司发现该模型对某一特定人群的贷款审批速度快于其他人群。\n该银行应以最具成本效益的方式如何解决此问题？"},"options":[{"key":"A","en":"Include more diverse training data. Fine-tune the model again by using the new data.","zh":"纳入更多样化的训练数据。使用新数据再次微调模型。"},{"key":"B","en":"Use Retrieval Augmented Generation (RAG) with the fine-tuned model.","zh":"在微调后的模型上使用检索增强生成（RAG）。"},{"key":"C","en":"Use AWS Trusted Advisor checks to eliminate bias.","zh":"使用 AWS Trusted Advisor 检查来消除偏见。"},{"key":"D","en":"Pre-train a new LLM with more diverse training data.","zh":"使用更多样化的训练数据预训练一个新的 LLM。"}],"explanation":{"en":"The issue described is a case of bias in the model’s decision-making process, where the model is showing\na preference for a specific demographic. The most cost-effective way to address this is to include more\ndiverse training data that better represents all demographics. By fine-tuning the model with this more\ndiverse data, you can help ensure that the model treats all demographic groups fairly and does not exhibit\nbiased behavior.\nFine-tuning the model with updated data ensures that the model learns from a more representative\nsample, improving fairness in its predictions without needing to completely retrain the model from scratch.","zh":"所描述的问题是模型决策过程中的偏见，即模型对某一特定人群表现出偏好。解决该问题最具成本效益的方法是纳入能更好代表所有人群的更多样化训练数据。通过用这些更多样化的数据微调模型，可以帮助确保模型公平对待所有人群，不表现出偏见行为。\n用更新后的数据微调模型可确保模型从更具代表性的样本中学习，提升其预测的公平性，而无需完全从头重新训练模型。"},"tip":{"zh":"偏见来自数据不均衡 → 补数据再微调最省钱；重训新模型（D）成本最高。","en":""},"keywords":["偏见","微调","训练数据多样性"]},{"id":125,"type":"hotspot","answer":[],"topic":"genai","stem":{"en":"A company has developed a large language model (LLM) and wants to make the LLM available to multiple\ninternal teams. The company needs to select the appropriate inference mode for each team.\nSelect the correct inference mode from the following list for each use case. Each inference mode should\nbe selected one or more times.","zh":"一家公司开发了一个大型语言模型（LLM），希望让多个内部团队都能使用该 LLM。公司需要为每个团队选择合适的推理模式。\n请从下面的列表中为每个使用场景选择正确的推理模式。每种推理模式可被选择一次或多次。"},"options":[],"explanation":{"en":"The company’s chatbot needs predictions from the LLM to understand users’ intent with minimal\nlatency - Real-time inference\nThis scenario requires Real-time inference, as chatbots typically need immediate responses with low\nlatency to provide an interactive user experience.\nA data processing job needs to query the LLM to process gigabytes of text files on weekends -\nBatch transform\nThis use case is best suited for Batch transform. Since the data processing job involves handling large\namounts of data, and it is scheduled for weekends, batch processing can handle these large volumes\nefficiently.\nThe company’s engineering team needs to create an API that can process small pieces of text\ncontent and provide low-latency predictions - Real-time inference\nReal-time inference is the correct choice here, as the API needs to process text quickly and provide\nimmediate responses, making real-time inference appropriate.","zh":"公司聊天机器人需要 LLM 提供预测以理解用户意图，且延迟要最小 — 实时推理\n该场景需要实时推理，因为聊天机器人通常需要低延迟的即时响应，以提供交互式用户体验。\n某数据处理作业需要在周末查询 LLM 来处理数 GB 的文本文件 — 批量转换\n该使用场景最适合批量转换。由于该数据处理作业涉及处理大量数据，且安排在周末执行，批处理可以高效处理这些大容量数据。\n公司工程团队需要创建一个 API，用于处理小段文本内容并提供低延迟预测 — 实时推理\n此处实时推理是正确选择，因为该 API 需要快速处理文本并立即返回响应，因此实时推理是合适的。"},"tip":{"zh":"聊天/API 要低延迟→实时推理；周末跑大批量文件→批量转换，抓这两个关键词。","en":""},"keywords":["推理模式","实时推理","批量转换"]},{"id":126,"type":"multi","answer":["A","D"],"topic":"security","stem":{"en":"A company needs to log all requests made to its Amazon Bedrock API. The company must retain the logs\nsecurely for 5 years at the lowest possible cost.\nWhich combination of AWS service and storage class meets these requirements? (Choose two.)","zh":"一家公司需要记录对其 Amazon Bedrock API 的所有请求。该公司必须以尽可能低的成本安全地保留这些日志 5 年。\n哪一项 AWS 服务与存储类的组合能满足这些要求？（选择两项。）"},"options":[{"key":"A","en":"AWS CloudTrail","zh":"AWS CloudTrail"},{"key":"B","en":"Amazon CloudWatch","zh":"Amazon CloudWatch"},{"key":"C","en":"AWS Audit Manager","zh":"AWS Audit Manager"},{"key":"D","en":"Amazon S3 Intelligent-Tiering","zh":"Amazon S3 Intelligent-Tiering"},{"key":"E","en":"Amazon S3 Standard","zh":"Amazon S3 Standard"}],"explanation":{"en":"AWS CloudTrail is the AWS service designed for logging and monitoring API calls made to AWS services,\nincluding Amazon Bedrock. CloudTrail records detailed information about the API requests, including the\nidentity of the requester, the time of the request, and the source IP address. This service is ideal for\nlogging all requests made to the Amazon Bedrock API and meets the logging requirement.\nAmazon S3 Intelligent-Tiering is a storage class designed for storing data that has unpredictable access\npatterns. It automatically moves data between two access tiers (frequent and infrequent) based on usage,\nwhich helps reduce costs while ensuring data is still available when needed. For retaining logs securely\nover 5 years at the lowest possible cost, this storage class provides an efficient way to handle long-term\nstorage requirements without incurring unnecessary costs.","zh":"AWS CloudTrail 是专为记录和监控对 AWS 服务（包括 Amazon Bedrock）的 API 调用而设计的 AWS 服务。CloudTrail 会记录有关 API 请求的详细信息，包括请求者的身份、请求时间和源 IP 地址。该服务非常适合记录对 Amazon Bedrock API 的所有请求，满足日志记录要求。\nAmazon S3 Intelligent-Tiering 是一种为访问模式不可预测的数据而设计的存储类。它会根据使用情况在两个访问层（频繁访问和不频繁访问）之间自动移动数据，有助于降低成本，同时确保数据在需要时仍然可用。要以尽可能低的成本安全地保留日志 5 年，该存储类提供了一种高效处理长期存储需求的方式，且不会产生不必要的成本。"},"tip":{"zh":"记录 API 调用 → CloudTrail；访问不可预测还要省 5 年 → S3 Intelligent-Tiering。","en":""},"keywords":["CloudTrail","API 日志","S3 智能分层"]},{"id":127,"type":"single","answer":["A"],"topic":"services","stem":{"en":"An ecommerce company wants to improve search engine recommendations by customizing the results for\neach user of the company’s ecommerce platform.\nWhich AWS service meets these requirements?","zh":"一家电子商务公司希望通过为该公司电商平台的每位用户定制结果来改进搜索引擎推荐。\n哪项 AWS 服务能满足这些要求？"},"options":[{"key":"A","en":"Amazon Personalize","zh":"Amazon Personalize"},{"key":"B","en":"Amazon Kendra","zh":"Amazon Kendra"},{"key":"C","en":"Amazon Rekognition","zh":"Amazon Rekognition"},{"key":"D","en":"Amazon Transcribe","zh":"Amazon Transcribe"}],"explanation":{"en":"Amazon Personalize is an AWS service specifically designed to build and deploy personalized\nrecommendations for users. It allows you to create custom machine learning models for personalized user\nexperiences, such as product recommendations, search results, or content suggestions. For an\necommerce company aiming to improve search engine recommendations tailored to each user, Amazon\nPersonalize is the ideal choice as it leverages user behavior data and machine learning to deliver highly\nrelevant recommendations.","zh":"Amazon Personalize 是一项专为构建和部署面向用户的个性化推荐而设计的 AWS 服务。它允许你创建自定义机器学习模型，以实现个性化用户体验，例如产品推荐、搜索结果或内容建议。对于希望改进针对每位用户的搜索引擎推荐的电商公司来说，Amazon Personalize 是理想选择，因为它利用用户行为数据和机器学习来提供高度相关的推荐。"},"tip":{"zh":"按用户个性化推荐 → Personalize；Kendra 是文档智能搜索，不做个性化。","en":""},"keywords":["个性化推荐","Personalize","用户行为"]},{"id":128,"type":"single","answer":["A"],"topic":"security","stem":{"en":"A hospital is developing an AI system to assist doctors in diagnosing diseases based on patient records\nand medical images. To comply with regulations, the sensitive patient data must not leave the country the\ndata is located in.\nWhich data governance strategy will ensure compliance and protect patient privacy?","zh":"一家医院正在开发 AI 系统，根据患者病历和医学影像协助医生诊断疾病。为符合法规要求，敏感的患者数据不得离开数据所在的国家/地区。\n哪种数据治理策略能确保合规并保护患者隐私？"},"options":[{"key":"A","en":"Data residency","zh":"数据驻留"},{"key":"B","en":"Data quality","zh":"数据质量"},{"key":"C","en":"Data discoverability","zh":"数据可发现性"},{"key":"D","en":"Data enrichment","zh":"数据丰富化"}],"explanation":{"en":"Data residency refers to the practice of ensuring that data is stored and processed within a specific\ngeographical location to comply with regulations or policies. In this scenario, where sensitive patient data\nmust not leave the country it originates from, implementing a data residency strategy ensures compliance\nwith legal and regulatory requirements while protecting patient privacy. This approach is crucial for\norganizations like hospitals operating under strict data governance frameworks such as HIPAA or GDPR.","zh":"数据驻留是指确保数据在特定地理位置内存储和处理，以符合法规或政策的做法。在本场景中，敏感的患者数据不得离开其来源国，实施数据驻留策略可确保符合法律和监管要求，同时保护患者隐私。对于在医院这类受 HIPAA 或 GDPR 等严格数据治理框架约束的组织中运营的机构，这种做法至关重要。"},"tip":{"zh":"数据不许出境 → 数据驻留（data residency），看到“留在本国”就选它。","en":""},"keywords":["数据驻留","合规","数据治理"]},{"id":129,"type":"single","answer":["A"],"topic":"eval","stem":{"en":"A company needs to monitor the performance of its ML systems by using a highly scalable AWS service.\nWhich AWS service meets these requirements?","zh":"一家公司需要使用高度可扩展的 AWS 服务来监控其 ML 系统的性能。\n哪项 AWS 服务能满足这些要求？"},"options":[{"key":"A","en":"Amazon CloudWatch","zh":"Amazon CloudWatch"},{"key":"B","en":"AWS CloudTrail","zh":"AWS CloudTrail"},{"key":"C","en":"AWS Trusted Advisor","zh":"AWS Trusted Advisor"},{"key":"D","en":"AWS Config","zh":"AWS Config"}],"explanation":{"en":"Amazon CloudWatch is a highly scalable AWS service designed for monitoring and observability. It\nprovides real-time monitoring of system metrics, including performance data for ML systems, such as\nresource utilization (CPU, memory, etc.), model inference latency, request counts, and errors. CloudWatch\nenables users to set up alarms, visualize metrics, and automate actions based on performance thresholds,\nmaking it ideal for monitoring the performance of ML systems.","zh":"Amazon CloudWatch 是一项高度可扩展的 AWS 服务，专为监控和可观测性而设计。它提供系统指标的实时监控，包括 ML 系统的性能数据，例如资源利用率（CPU、内存等）、模型推理延迟、请求数和错误。CloudWatch 使用户能够设置告警、可视化指标，并基于性能阈值自动执行操作，因此非常适合监控 ML 系统的性能。"},"tip":{"zh":"监控指标和性能 → CloudWatch；CloudTrail 记 API 审计，Config 查配置合规。","en":""},"keywords":["CloudWatch","性能监控","指标告警"]},{"id":130,"type":"single","answer":["A"],"topic":"responsible","stem":{"en":"An AI practitioner is developing a prompt for an Amazon Titan model. The model is hosted on Amazon\nBedrock. The AI practitioner is using the model to solve numerical reasoning challenges. The AI\npractitioner adds the following phrase to the end of the prompt: “Ask the model to show its work by\nexplaining its reasoning step by step.”\nWhich prompt engineering technique is the AI practitioner using?","zh":"一位 AI 从业者正在为 Amazon Titan 模型开发提示。该模型托管在 Amazon Bedrock 上。该 AI 从业者使用该模型来解决数值推理难题。该 AI 从业者在提示末尾添加了以下语句：“要求模型通过逐步解释其推理过程来展示解题过程。”\n该 AI 从业者使用的是哪种提示工程技术？"},"options":[{"key":"A","en":"Chain-of-thought prompting","zh":"思维链提示"},{"key":"B","en":"Prompt injection","zh":"提示注入"},{"key":"C","en":"Few-shot prompting","zh":"少样本提示"},{"key":"D","en":"Prompt templating","zh":"提示模板化"}],"explanation":{"en":"Chain-of-thought prompting is a technique in prompt engineering where the AI model is encouraged to\nbreak down its reasoning process step by step to solve a problem, such as numerical reasoning\nchallenges. By explicitly instructing the model to \"show its work by explaining its reasoning step by step,\"\nthe practitioner ensures the model provides a logical sequence of intermediate steps leading to the\nsolution. This improves the accuracy and transparency of the model's outputs, particularly for complex\nreasoning tasks.","zh":"思维链提示是提示工程中的一种技术，鼓励 AI 模型逐步拆解其推理过程来解决诸如数值推理难题之类的问题。通过明确指示模型“逐步解释其推理过程来展示解题过程”，从业者确保模型提供通向解决方案的一系列逻辑中间步骤。这提高了模型输出的准确性和透明度，尤其是在复杂推理任务中。"},"tip":{"zh":"看到“step by step / 展示推理过程”→ 思维链（CoT），经典送分题。","en":""},"keywords":["思维链","提示工程","逐步推理"]},{"id":131,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"Which AWS service makes foundation models (FMs) available to help users build and scale generative AI\napplications?","zh":"哪项 AWS 服务提供基础模型（FM），帮助用户构建和扩展生成式 AI 应用？"},"options":[{"key":"A","en":"Amazon Q Developer","zh":"Amazon Q Developer"},{"key":"B","en":"Amazon Bedrock","zh":"Amazon Bedrock"},{"key":"C","en":"Amazon Kendra","zh":"Amazon Kendra"},{"key":"D","en":"Amazon Comprehend","zh":"Amazon Comprehend"}],"explanation":{"en":"Amazon Bedrock is an AWS service that allows users to build and scale generative AI applications using\nfoundation models (FMs) without the need to manage infrastructure. It provides access to pre-trained\nmodels from AWS and third-party providers, enabling developers to integrate generative AI capabilities like\ntext generation, summarization, and question-answering into their applications. This makes Amazon\nBedrock the ideal choice for building and scaling generative AI solutions.","zh":"Amazon Bedrock 是一项 AWS 服务，让用户无需管理基础设施即可使用基础模型（FM）构建和扩展生成式 AI 应用。它提供对来自 AWS 和第三方提供商的预训练模型的访问，使开发者能够将文本生成、摘要和问答等生成式 AI 能力集成到其应用中。这使 Amazon Bedrock 成为构建和扩展生成式 AI 解决方案的理想选择。"},"tip":{"zh":"生成式 AI + 基础模型托管 → Bedrock；Q Developer 是写代码助手，不是模型平台。","en":""},"keywords":["Bedrock","基础模型","生成式 AI"]},{"id":132,"type":"single","answer":["A"],"topic":"general","stem":{"en":"A company is building a mobile app for users who have a visual impairment. The app must be able to hear\nwhat users say and provide voice responses.\nWhich solution will meet these requirements?","zh":"一家公司正在为有视力障碍的用户构建一款移动应用。该应用必须能够听取用户所说的话并提供语音回复。\n哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Use a deep learning neural network to perform speech recognition.","zh":"使用深度学习神经网络执行语音识别。"},{"key":"B","en":"Build ML models to search for patterns in numeric data.","zh":"构建 ML 模型来搜索数值数据中的模式。"},{"key":"C","en":"Use generative AI summarization to generate human-like text.","zh":"使用生成式 AI 摘要生成类人文本。"},{"key":"D","en":"Build custom models for image classification and recognition.","zh":"构建用于图像分类和识别的自定义模型。"}],"explanation":{"en":"To meet the requirements of enabling the app to \"hear what users say and provide voice responses,\" the\nsolution must include speech recognition and text-to-speech capabilities. Using a deep learning neural\nnetwork for speech recognition allows the app to convert spoken words into text. Once the input is\nunderstood, text-to-speech systems can provide voice responses back to users. This approach is\nfundamental in applications that assist users with visual impairments by enabling interaction through\nspoken language.","zh":"为满足让应用“听取用户所说的话并提供语音回复”的要求，解决方案必须包含语音识别和文本转语音能力。使用深度学习神经网络进行语音识别，可使应用将口语转换为文本。一旦理解了输入内容，文本转语音系统就能向用户提供语音回复。这种方法是通过口语进行交互来帮助视力障碍用户的应用的基础。"},"tip":{"zh":"听人说话+语音回答 → 语音识别（ASR）加文本转语音（TTS），靠深度学习。","en":""},"keywords":["语音识别","文本转语音","无障碍"]},{"id":133,"type":"single","answer":["D"],"topic":"genai","stem":{"en":"A company wants to enhance response quality for a large language model (LLM) for complex problem-\nsolving tasks. The tasks require detailed reasoning and a step-by-step explanation process.\nWhich prompt engineering technique meets these requirements?","zh":"一家公司希望提升大型语言模型（LLM）在复杂问题解决任务中的响应质量。这些任务需要详细的推理和逐步解释过程。\n哪种提示工程技术能满足这些要求？"},"options":[{"key":"A","en":"Few-shot prompting","zh":"少样本提示"},{"key":"B","en":"Zero-shot prompting","zh":"零样本提示"},{"key":"C","en":"Directional stimulus prompting","zh":"定向刺激提示"},{"key":"D","en":"Chain-of-thought prompting","zh":"思维链提示"}],"explanation":{"en":"Chain-of-thought prompting is specifically designed to enhance the reasoning capabilities of a large\nlanguage model (LLM) by encouraging it to provide step-by-step explanations for complex problem-solving\ntasks. This approach helps the model break down a problem into smaller, logical steps, ensuring that the\nresponse is detailed, accurate, and easy to follow.","zh":"思维链提示专门用于增强大型语言模型（LLM）的推理能力，它鼓励模型为复杂问题解决任务提供逐步解释。这种方法帮助模型将问题拆解为更小的逻辑步骤，确保响应详细、准确且易于理解。"},"tip":{"zh":"“详细推理 + 逐步解释”= 思维链；少样本/零样本只讲给不给例子。","en":""},"keywords":["思维链","复杂推理","提示工程"]},{"id":134,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"A company wants to keep its foundation model (FM) relevant by using the most recent data. The company\nwants to implement a model training strategy that includes regular updates to the FM.\nWhich solution meets these requirements?","zh":"一家公司希望通过使用最新数据来保持其基础模型（FM）的相关性。该公司希望实施一种包含定期更新 FM 的模型训练策略。\n哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Batch learning","zh":"批量学习"},{"key":"B","en":"Continuous pre-training","zh":"持续预训练"},{"key":"C","en":"Static training","zh":"静态训练"},{"key":"D","en":"Latent training","zh":"潜在训练"}],"explanation":{"en":"Continuous pre-training keeps a foundation model “always learning” by periodically (or even continuously)\ningesting the latest data and updating its weights. This approach ensures the model stays current without\nhaving to start training from scratch every time new data arrives, unlike static or strictly batch-oriented\nmethods.","zh":"持续预训练通过定期（甚至持续地）摄取最新数据并更新模型权重，使基础模型保持“持续学习”状态。这种方法确保模型保持最新，而无需在每次新数据到来时都从头开始训练，这与静态方法或严格面向批处理的方法不同。"},"tip":{"zh":"要用最新数据不断更新权重 → 持续预训练（continuous pre-training）。","en":""},"keywords":["持续预训练","模型更新","基础模型"]},{"id":135,"type":"hotspot","answer":[],"topic":"data","stem":{"en":"A company wants to develop ML applications to improve business operations and efficiency.\nSelect the correct ML paradigm from the following list for each use case. Each ML paradigm should be\nselected one or more times.","zh":"一家公司希望开发 ML 应用以改善业务运营和效率。\n请从下面的列表中为每个使用场景选择正确的 ML 范式。每种 ML 范式可被选择一次或多次。"},"options":[],"explanation":{"en":"Binary classification: Supervised learning\nBinary classification involves predicting one of two possible outcomes, requiring labeled training data.\nMulti-class classification: Supervised learning\nMulti-class classification extends binary classification to predict one of several classes, also requiring\nlabeled data.\nK-means clustering: Unsupervised learning\nK-means clustering is used to group data points into clusters without requiring labeled data.\nDimensionality reduction: Unsupervised learning\nDimensionality reduction techniques, like PCA, reduce the number of features in the dataset without\nneeding labeled data.","zh":"二分类：监督式学习\n二分类涉及预测两种可能结果之一，需要有标注的训练数据。\n多分类：监督式学习\n多分类将二分类扩展为预测多个类别之一，同样需要有标注的数据。\nK-means 聚类：无监督学习\nK-means 聚类用于将数据点分组成簇，不需要有标注的数据。\n降维：无监督学习\n降维技术（如 PCA）可在不需要有标注数据的情况下减少数据集中的特征数量。"},"tip":{"zh":"有标签（分类）→ 监督式；无标签（聚类、降维、PCA）→ 无监督。","en":""},"keywords":["监督式学习","无监督学习","聚类与降维"]},{"id":136,"type":"single","answer":["D"],"topic":"responsible","stem":{"en":"Which option is a characteristic of AI governance frameworks for building trust and deploying human-\ncentered AI technologies?","zh":"哪一项是 AI 治理框架的特征——用于建立信任并部署以人为本的 AI 技术？"},"options":[{"key":"A","en":"Expanding initiatives across business units to create long-term business value","zh":"在各业务部门扩展相关举措以创造长期业务价值"},{"key":"B","en":"Ensuring alignment with business standards, revenue goals, and stakeholder expectations","zh":"确保与业务标准、收入目标和利益相关者期望保持一致"},{"key":"C","en":"Overcoming challenges to drive business transformation and growth","zh":"克服挑战以推动业务转型和增长"},{"key":"D","en":"Developing policies and guidelines for data, transparency, responsible AI, and compliance","zh":"制定针对数据、透明度、负责任 AI 和合规性的政策与指南"}],"explanation":{"en":"AI governance frameworks focus on building trust and ensuring the responsible deployment of AI\ntechnologies. They establish clear policies and guidelines to address critical aspects such as data\nmanagement, transparency, ethical considerations, responsible AI practices, and regulatory compliance.\nThese frameworks help organizations mitigate risks, promote fairness, and foster public trust in AI\nsystems, making them essential for creating human-centered AI technologies.","zh":"AI 治理框架侧重于建立信任并确保以负责任的方式部署 AI 技术。它们制定明确的政策和指南，以应对数据管理、透明度、伦理考量、负责任 AI 实践和法规合规等关键方面。这些框架帮助组织降低风险、促进公平性并培养公众对 AI 系统的信任，因此对于打造以人为本的 AI 技术至关重要。"},"tip":{"zh":"治理框架=定政策定指南（数据、透明度、负责任 AI、合规）；A/B/C 都是业务价值。","en":""},"keywords":["AI 治理","政策与指南","负责任 AI"]},{"id":137,"type":"single","answer":["C"],"topic":"eval","stem":{"en":"An ecommerce company is using a generative AI chatbot to respond to customer inquiries. The company\nwants to measure the financial effect of the chatbot on the company’s operations.\nWhich metric should the company use?","zh":"一家电子商务公司正在使用生成式 AI 聊天机器人回应客户咨询。该公司希望衡量该聊天机器人对公司运营的财务影响。\n该公司应使用哪项指标？"},"options":[{"key":"A","en":"Number of customer inquiries handled","zh":"处理的客户咨询数量"},{"key":"B","en":"Cost of training AI models","zh":"训练 AI 模型的成本"},{"key":"C","en":"Cost for each customer conversation","zh":"每次客户会话的成本"},{"key":"D","en":"Average handled time (AHT)","zh":"平均处理时长（AHT）"}],"explanation":{"en":"To measure the financial effect of a generative AI chatbot on the company's operations, the cost for each\ncustomer conversation is the most relevant metric. It directly quantifies the operational expense\nassociated with using the chatbot to handle customer inquiries. By analyzing this metric, the company can\nevaluate how much it spends per conversation and compare it to the cost of alternative methods (e.g.,\nhuman agents), providing insight into the chatbot's financial efficiency and ROI.","zh":"要衡量生成式 AI 聊天机器人对公司运营的财务影响，每次客户会话的成本是最相关的指标。它直接量化了使用聊天机器人处理客户咨询所产生的运营费用。通过分析该指标，公司可以评估每次会话的花费，并将其与替代方式（例如人工坐席）的成本进行比较，从而了解聊天机器人的财务效率和投资回报率。"},"tip":{"zh":"问“财务影响”→ 每次会话成本；咨询量和 AHT 是效率指标，不是钱。","en":""},"keywords":["单位成本","财务影响","ROI"]},{"id":138,"type":"single","answer":["B"],"topic":"services","stem":{"en":"A company wants to find groups for its customers based on the customers’ demographics and buying\npatterns.\nWhich algorithm should the company use to meet this requirement?","zh":"一家公司希望根据客户的人口统计特征和购买模式为其客户找到分组。\n该公司应使用哪种算法来满足此要求？"},"options":[{"key":"A","en":"K-nearest neighbors (k-NN)","zh":"K 近邻（k-NN）"},{"key":"B","en":"K-means","zh":"K-means"},{"key":"C","en":"Decision tree","zh":"决策树"},{"key":"D","en":"Support vector machine","zh":"支持向量机"}],"explanation":{"en":"K-means is a clustering algorithm used in unsupervised learning to group data points into clusters based\non their similarities. It is well-suited for finding patterns in customer demographics and buying behavior.\nThe algorithm identifies groups (clusters) of customers with similar characteristics, which can then be used\nfor targeted marketing, personalized recommendations, or segmentation.","zh":"K-means 是一种用于无监督学习的聚类算法，可根据相似性将数据点分组成簇。它非常适合在客户人口统计特征和购买行为中发现模式。该算法识别具有相似特征的客户群体（簇），随后可用于定向营销、个性化推荐或客户细分。"},"tip":{"zh":"要“分组/分群”且没有标签 → K-means 聚类；k-NN、决策树、SVM 都是监督式。","en":""},"keywords":["K-means","聚类","客户细分"]},{"id":139,"type":"single","answer":["C"],"topic":"responsible","stem":{"en":"A company’s large language model (LLM) is experiencing hallucinations.\nHow can the company decrease hallucinations?","zh":"一家公司的大型语言模型（LLM）正在出现幻觉。\n该公司如何减少幻觉？"},"options":[{"key":"A","en":"Set up Agents for Amazon Bedrock to supervise the model training.","zh":"设置适用于 Amazon Bedrock 的 Agents 来监督模型训练。"},{"key":"B","en":"Use data pre-processing and remove any data that causes hallucinations.","zh":"使用数据预处理并移除任何导致幻觉的数据。"},{"key":"C","en":"Decrease the temperature inference parameter for the model.","zh":"降低模型的 temperature 推理参数。"},{"key":"D","en":"Use a foundation model (FM) that is trained to not hallucinate.","zh":"使用一个经过训练不会产生幻觉的基础模型（FM）。"}],"explanation":{"en":"In the context of large language models (LLMs), the temperature inference parameter controls the\nrandomness of the model's output. Lowering the temperature reduces randomness and makes the model's\n\nresponses more deterministic and focused on the most likely predictions. By decreasing the temperature,\nthe likelihood of hallucinations (when the model generates incorrect or nonsensical information) is\nreduced, as the model relies more on high-probability outputs rather than exploring less likely possibilities.","zh":"在大型语言模型（LLM）的语境中，temperature 推理参数控制模型输出的随机性。降低 temperature 会减少随机性，使模型的响应更加确定，并聚焦于最可能的预测。通过降低 temperature，幻觉（模型生成不正确或无意义信息）的可能性会降低，因为模型更多地依赖高概率输出，而不是探索可能性较低的选项。"},"tip":{"zh":"幻觉多=输出太随机 → 调低 temperature；不存在“不幻觉的模型”这个选项。","en":""},"keywords":["幻觉","temperature","推理参数"]},{"id":140,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"A company is using a large language model (LLM) on Amazon Bedrock to build a chatbot. The chatbot\nprocesses customer support requests. To resolve a request, the customer and the chatbot must interact a\nfew times.\nWhich solution gives the LLM the ability to use content from previous customer messages?","zh":"一家公司在 Amazon Bedrock 上使用大型语言模型（LLM）构建聊天机器人。该聊天机器人处理客户支持请求。为解决一个请求，客户与聊天机器人必须交互几次。\n哪种解决方案能让 LLM 使用之前客户消息中的内容？"},"options":[{"key":"A","en":"Turn on model invocation logging to collect messages.","zh":"开启模型调用日志记录以收集消息。"},{"key":"B","en":"Add messages to the model prompt.","zh":"将消息添加到模型提示中。"},{"key":"C","en":"Use Amazon Personalize to save conversation history.","zh":"使用 Amazon Personalize 保存对话历史。"},{"key":"D","en":"Use Provisioned Throughput for the LLM.","zh":"为 LLM 使用预置吞吐量。"}],"explanation":{"en":"To give a large language model (LLM) the ability to use content from previous customer messages in a\nconversation, the previous messages must be included in the model prompt. This technique is known as\nprompt engineering and allows the LLM to retain context by incorporating a history of the interaction\nwithin the prompt. By appending prior exchanges to the prompt, the model can generate contextually\nrelevant and coherent responses throughout the multi-turn conversation.","zh":"要让大型语言模型（LLM）能够在对话中使用之前客户消息的内容，必须将之前的消息包含在模型提示中。这种技术称为提示工程，通过将交互历史并入提示，使 LLM 能够保留上下文。通过将先前的往来内容追加到提示中，模型可以在整个多轮对话中生成上下文相关且连贯的响应。"},"tip":{"zh":"多轮记忆=把历史消息塞进 prompt；调用日志只做审计，不会自动进上下文。","en":""},"keywords":["多轮对话","提示工程","上下文"]},{"id":141,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"A company’s employees provide product descriptions and recommendations to customers when\ncustomers call the customer service center. These recommendations are based on where the customers\nare located. The company wants to use foundation models (FMs) to automate this process.\nWhich AWS service meets these requirements?","zh":"当客户致电客服中心时，公司的员工会向客户提供产品描述和推荐。这些推荐基于客户所在的位置。该公司希望使用基础模型（FM）来自动化此过程。\n哪项 AWS 服务能满足这些要求？"},"options":[{"key":"A","en":"Amazon Macie","zh":"Amazon Macie"},{"key":"B","en":"Amazon Transcribe","zh":"Amazon Transcribe"},{"key":"C","en":"Amazon Bedrock","zh":"Amazon Bedrock"},{"key":"D","en":"Amazon Textract","zh":"Amazon Textract"}],"explanation":{"en":"Amazon Bedrock enables companies to use foundation models (FMs) to build and automate tasks like\ngenerating product descriptions and recommendations. It allows the integration of pre-trained FMs into\napplications without managing infrastructure, making it an ideal choice for automating customer service\ntasks. With Amazon Bedrock, the company can leverage FMs to generate tailored recommendations\nbased on customer locations, enabling dynamic and efficient customer interactions.","zh":"Amazon Bedrock 使公司能够使用基础模型（FM）来构建和自动化生成产品描述和推荐等任务。它允许将预训练的 FM 集成到应用中而无需管理基础设施，因此是自动化客户服务任务的理想选择。借助 Amazon Bedrock，公司可以利用 FM 生成基于客户位置的定制推荐，实现动态且高效的客户互动。"},"tip":{"zh":"用基础模型做生成式任务 → Bedrock；Macie 查敏感数据，Transcribe 转写语音。","en":""},"keywords":["Bedrock","基础模型","客服自动化"]},{"id":142,"type":"single","answer":["A"],"topic":"security","stem":{"en":"A company wants to upload customer service email messages to Amazon S3 to develop a business\nanalysis application. The messages sometimes contain sensitive data. The company wants to receive an\nalert every time sensitive information is found.\nWhich solution fully automates the sensitive information detection process with the LEAST development\neffort?","zh":"一家公司希望将客户服务电子邮件上传到 Amazon S3，以开发一个业务分析应用。这些邮件有时包含敏感数据。该公司希望每次发现敏感信息时都能收到提醒。\n哪种解决方案能以最少的开发工作量完全自动化敏感信息检测过程？"},"options":[{"key":"A","en":"Configure Amazon Macie to detect sensitive information in the documents that are uploaded to Amazon S3.","zh":"配置 Amazon Macie 以检测上传到 Amazon S3 的文档中的敏感信息。"},{"key":"B","en":"Use Amazon SageMaker endpoints to deploy a large language model (LLM) to redact sensitive data.","zh":"使用 Amazon SageMaker 端点部署大型语言模型（LLM）来编辑敏感数据。"},{"key":"C","en":"Develop multiple regex patterns to detect sensitive data. Expose the regex patterns on an Amazon SageMaker notebook.","zh":"开发多个正则表达式模式来检测敏感数据。在 Amazon SageMaker 笔记本上公开这些正则表达式模式。"},{"key":"D","en":"Ask the customers to avoid sharing sensitive information in their email messages.","zh":"要求客户避免在电子邮件中共享敏感信息。"}],"explanation":{"en":"Amazon Macie is a fully managed data security and privacy service that uses machine learning to discover\nand protect sensitive data in Amazon S3. It can automatically detect sensitive information, such as\npersonally identifiable information (PII) or financial data, and send alerts when such data is found. This\napproach minimizes development effort, as it does not require custom regex patterns or model\ndevelopment, and it is specifically designed to handle the scenario described.","zh":"Amazon Macie 是一项完全托管的数据安全和隐私服务，使用机器学习来发现和保护 Amazon S3 中的敏感数据。它可以自动检测敏感信息（例如个人身份信息（PII）或财务数据），并在发现此类数据时发送提醒。这种方法将开发工作量降到最低，因为它不需要自定义正则表达式或模型开发，而且它正是为处理所述场景而设计的。"},"tip":{"zh":"S3 里的敏感数据自动发现+告警 → Macie，零开发量，别自己写正则。","en":""},"keywords":["Macie","敏感数据检测","PII"]},{"id":143,"type":"hotspot","answer":[],"topic":"genai","stem":{"en":"A company is training its employees on how to structure prompts for foundation models.\nSelect the correct prompt engineering technique from the following list for each prompt template. Each\nprompt engineering technique should be selected one time.","zh":"一家公司正在培训员工如何为基础模型构建提示。\n请从下面的列表中为每个提示模板选择正确的提示工程技术。每种提示工程技术应被选择一次。"},"options":[],"explanation":{"en":"\"Classify the following text as either sports, politics, or entertainment: [input text].\"\nCorrect Answer: Zero-shot learning\nZero-shot learning involves providing the model with a task and no prior examples, relying entirely on the\nmodel's pre-trained knowledge to perform the classification.\n\n\"A [image 1], [image 2], and [image 3] are examples of [target class]. Classify the following image\nas [target class].\"\nCorrect Answer: Few-shot learning\nFew-shot learning provides the model with a few examples (image 1, image 2, and image 3) before asking\nit to classify a new instance, helping it generalize to the task with minimal examples.\n\"[Question.] [Instructions to follow.] Think step by step and walk me through your thinking.\"\nCorrect Answer: Chain-of-thought reasoning\nChain-of-thought reasoning encourages the model to break down its reasoning process step by step,\nenhancing its ability to solve complex tasks logically.","zh":"“将以下文本分类为体育、政治或娱乐：[输入文本]。”\n正确答案：零样本学习\n零样本学习是向模型提供任务而不提供任何先前示例，完全依靠模型的预训练知识来执行分类。\n\n“[图像 1]、[图像 2] 和 [图像 3] 是 [目标类别] 的示例。将以下图像分类为 [目标类别]。”\n正确答案：少样本学习\n少样本学习在要求模型分类新实例之前先向模型提供少量示例（图像 1、图像 2 和图像 3），帮助模型以最少的示例泛化到该任务。\n“[问题。] [要遵循的指示。] 逐步思考并向我展示你的思考过程。”\n正确答案：思维链推理\n思维链推理鼓励模型逐步拆解其推理过程，增强其以逻辑方式解决复杂任务的能力。"},"tip":{"zh":"没例子=零样本；给几个例子=少样本；让他 step by step=思维链。","en":""},"keywords":["零样本","少样本","思维链"]},{"id":144,"type":"hotspot","answer":[],"topic":"genai","stem":{"en":"A company is using a generative AI model to develop a digital assistant. The model’s responses\noccasionally include undesirable and potentially harmful content.\nSelect the correct Amazon Bedrock filter policy from the following list for each mitigation action. Each filter\npolicy should be selected one time.","zh":"一家公司正在使用生成式 AI 模型开发数字助理。该模型的响应偶尔会包含不良且可能有害的内容。\n请从下面的列表中为每项缓解措施选择正确的 Amazon Bedrock 过滤器策略。每种过滤器策略应被选择一次。"},"options":[],"explanation":{"en":"Block input prompts or model responses that contain harmful content such as hate, insults,\nviolence, or misconduct - Content filters\nAvoid subjects related to illegal investment advice or legal advice - Denied topics\nDetect and block specific offensive terms - Word filters\nDetect and filter out information in the model's responses that is not grounded in the provided\nsource information - Contextual grounding check","zh":"阻止包含仇恨、侮辱、暴力或不当行为等有害内容的输入提示或模型响应 — 内容过滤器\n避免与非法投资建议或法律建议相关的主题 — 拒绝主题\n检测并阻止特定的冒犯性词语 — 词语过滤器\n检测并过滤掉模型响应中未以所提供的源信息为依据的信息 — 上下文事实接地检查"},"tip":{"zh":"仇恨暴力→内容过滤器；整类话题→拒绝主题；违禁词→词语过滤器；查无出处→上下文接地检查。","en":""},"keywords":["Bedrock 护栏","内容过滤器","拒绝主题"]},{"id":145,"type":"single","answer":["B"],"topic":"responsible","stem":{"en":"Which option is a benefit of using Amazon SageMaker Model Cards to document AI models?","zh":"使用 Amazon SageMaker Model Cards 记录 AI 模型的哪一项优势？"},"options":[{"key":"A","en":"Providing a visually appealing summary of a model’s capabilities.","zh":"提供模型能力的视觉上吸引人的摘要。"},{"key":"B","en":"Standardizing information about a model’s purpose, performance, and limitations.","zh":"标准化关于模型用途、性能和局限性的信息。"},{"key":"C","en":"Reducing the overall computational requirements of a model.","zh":"降低模型的整体计算需求。"},{"key":"D","en":"Physically storing models for archival purposes.","zh":"为归档目的以物理方式存储模型。"}],"explanation":{"en":"Amazon SageMaker Model Cards provide a structured way to document key details about AI models,\nincluding their intended use, performance metrics, and limitations. This helps organizations maintain\ntransparency, compliance, and governance in AI model development, making it easier to track and\nmanage models over time.","zh":"Amazon SageMaker Model Cards 提供了一种结构化的方式来记录 AI 模型的关键细节，包括其预期用途、性能指标和局限性。这有助于组织在 AI 模型开发中保持透明度、合规性和治理，使模型随时间推移更易于跟踪和管理。"},"tip":{"zh":"Model Cards=标准化文档（用途、性能、局限），跟性能和存储无关。","en":""},"keywords":["Model Cards","模型文档","透明度"]},{"id":146,"type":"single","answer":["A"],"topic":"eval","stem":{"en":"What does an F1 score measure in the context of foundation model (FM) performance?","zh":"在基础模型（FM）性能的语境中，F1 分数衡量什么？"},"options":[{"key":"A","en":"Model precision and recall","zh":"模型的精确率和召回率"},{"key":"B","en":"Model speed in generating responses","zh":"模型生成响应的速度"},{"key":"C","en":"Financial cost of operating the model","zh":"运行模型的财务成本"},{"key":"D","en":"Energy efficiency of the model’s computations","zh":"模型计算的能效"}],"explanation":{"en":"The F1 score is a metric used to evaluate the performance of a classification model by considering both\nprecision (the proportion of correctly predicted positive cases out of all predicted positives) and recall (the\nproportion of correctly predicted positive cases out of all actual positives). It is the harmonic mean of\nprecision and recall, ensuring a balance between them, especially when dealing with imbalanced datasets.","zh":"F1 分数是一种用于评估分类模型性能的指标，它同时考虑精确率（在所有预测为正的样本中正确预测为正的比例）和召回率（在所有实际为正的样本中正确预测为正的比例）。它是精确率和召回率的调和平均数，确保两者之间的平衡，在处理不平衡数据集时尤为重要。"},"tip":{"zh":"F1 = 精确率与召回率的调和平均，背这一个公式就够了。","en":""},"keywords":["F1 分数","精确率","召回率"]},{"id":147,"type":"single","answer":["D"],"topic":"eval","stem":{"en":"A company deployed an AI/ML solution to help customer service agents respond to frequently asked\nquestions. The questions can change over time. The company wants to give customer service agents the\nability to ask questions and receive automatically generated answers to common customer questions.\nWhich strategy will meet these requirements MOST cost-effectively?","zh":"一家公司部署了一个 AI/ML 解决方案，帮助客服人员回答常见问题。这些问题会随时间变化。该公司希望让客服人员能够提出问题，并自动获得针对常见客户问题的答案。\n哪种策略能以最具成本效益的方式满足这些要求？"},"options":[{"key":"A","en":"Fine-tune the model regularly.","zh":"定期微调模型。"},{"key":"B","en":"Train the model by using context data.","zh":"使用上下文数据训练模型。"},{"key":"C","en":"Pre-train and benchmark the model by using context data.","zh":"使用上下文数据预训练并基准测试模型。"},{"key":"D","en":"Use Retrieval Augmented Generation (RAG) with prompt engineering techniques.","zh":"结合提示工程技术使用检索增强生成（RAG）。"}],"explanation":{"en":"Retrieval Augmented Generation (RAG) is a cost-effective approach that enhances AI-generated\nresponses by retrieving relevant information from external knowledge sources. Instead of fine-tuning or re-\ntraining a model, RAG dynamically pulls the most recent and relevant data at query time. This is\nparticularly useful in scenarios where questions change over time, ensuring that the AI/ML solution\nprovides accurate and up-to-date responses without requiring expensive and time-consuming model\nretraining. Prompt engineering techniques further optimize how the model processes and generates\nresponses, improving accuracy and relevance.","zh":"检索增强生成（RAG）是一种经济高效的方法，它通过从外部知识源检索相关信息来增强 AI 生成的响应。RAG 无需微调或重新训练模型，而是在查询时动态拉取最新且相关的数据。这在问题随时间变化的场景中特别有用，可确保 AI/ML 解决方案提供准确且最新的答案，而无需昂贵且耗时的模型重新训练。提示工程技术进一步优化模型处理和生成响应的方式，提高准确性和相关性。"},"tip":{"zh":"知识天天变就别微调，用 RAG 查最新资料，最省钱。","en":""},"keywords":["RAG","知识更新","成本效益"]},{"id":148,"type":"single","answer":["A"],"topic":"responsible","stem":{"en":"A company built an AI-powered resume screening system. The company used a large dataset to train the\nmodel. The dataset contained resumes that were not representative of all demographics.\nWhich core dimension of responsible AI does this scenario present?","zh":"一家公司构建了一个 AI 驱动的简历筛选系统。该公司使用大型数据集训练模型。该数据集包含的简历不能代表所有人群。\n该场景呈现了负责任 AI 的哪个核心维度？"},"options":[{"key":"A","en":"Fairness","zh":"公平性"},{"key":"B","en":"Explainability","zh":"可解释性"},{"key":"C","en":"Privacy and security","zh":"隐私与安全"},{"key":"D","en":"Transparency","zh":"透明度"}],"explanation":{"en":"The scenario describes a dataset that is not representative of all demographics, which can lead to\nbiased model predictions. This directly relates to fairness, a core dimension of responsible AI that ensures\nAI systems make unbiased and equitable decisions across different demographic groups. Addressing\nfairness involves techniques such as balanced dataset curation, bias detection, and mitigation strategies to\nensure that the AI system does not discriminate against any group.","zh":"该场景描述的数据集不能代表所有人群，这可能导致有偏见的模型预测。这直接关系到公平性，公平性是负责任 AI 的一个核心维度，确保 AI 系统在不同人群之间做出无偏见且公平的决策。解决公平性问题涉及平衡数据集整理、偏见检测和缓解策略等技术，以确保 AI 系统不歧视任何群体。"},"tip":{"zh":"数据不代表全部人群 → 公平性；可解释性讲“能不能说清原因”。","en":""},"keywords":["公平性","代表性数据","负责任 AI"]},{"id":149,"type":"multi","answer":["A","B"],"topic":"security","stem":{"en":"A global financial company has developed an ML application to analyze stock market data and provide\nstock market trends. The company wants to continuously monitor the application development phases and\nto ensure that company policies and industry regulations are followed.\nWhich AWS services will help the company assess compliance requirements? (Choose two.)","zh":"一家全球金融公司开发了一个 ML 应用来分析股票市场数据并提供股市趋势。该公司希望持续监控应用开发阶段，并确保遵循公司政策和行业法规。\n哪些 AWS 服务将帮助该公司评估合规要求？（选择两项。）"},"options":[{"key":"A","en":"AWS Audit Manager","zh":"AWS Audit Manager"},{"key":"B","en":"AWS Config","zh":"AWS Config"},{"key":"C","en":"Amazon Inspector","zh":"Amazon Inspector"},{"key":"D","en":"Amazon CloudWatch","zh":"Amazon CloudWatch"},{"key":"E","en":"AWS CloudTrail","zh":"AWS CloudTrail"}],"explanation":{"en":"AWS Audit Manager helps organizations continuously assess and audit compliance with industry\nregulations and internal policies by automating evidence collection and generating audit reports. This is\nessential for ensuring that the ML application meets regulatory requirements.\nAWS Config enables continuous monitoring and compliance checks by tracking configuration\nchanges in AWS resources. It helps the company ensure that infrastructure settings align with security\npolicies and industry standards.","zh":"AWS Audit Manager 通过自动收集证据并生成审计报告，帮助组织持续评估和审计对行业法规和内部政策的合规情况。这对于确保 ML 应用满足监管要求至关重要。\nAWS Config 通过跟踪 AWS 资源中的配置变更，实现持续监控和合规检查。它帮助公司确保基础设施设置符合安全策略和行业标准。"},"tip":{"zh":"评估合规 → Audit Manager（自动取证出审计报告）+ Config（配置变更持续检查）。","en":""},"keywords":["Audit Manager","Config","合规审计"]},{"id":150,"type":"single","answer":["D"],"topic":"eval","stem":{"en":"A company wants to improve the accuracy of the responses from a generative AI application. The\napplication uses a foundation model (FM) on Amazon Bedrock.\nWhich solution meets these requirements MOST cost-effectively?","zh":"一家公司希望提高生成式 AI 应用响应的准确性。该应用使用 Amazon Bedrock 上的基础模型（FM）。\n哪种解决方案能以最具成本效益的方式满足这些要求？"},"options":[{"key":"A","en":"Fine-tune the FM.","zh":"微调该 FM。"},{"key":"B","en":"Retrain the FM.","zh":"重新训练该 FM。"},{"key":"C","en":"Train a new FM.","zh":"训练一个新的 FM。"},{"key":"D","en":"Use prompt engineering.","zh":"使用提示工程。"}],"explanation":{"en":"Using prompt engineering is the most cost-effective way to improve the accuracy of responses from a\ngenerative AI application without retraining or fine-tuning the foundation model (FM). Prompt engineering\ninvolves carefully designing the input prompts to guide the model toward producing better responses,\n\nimproving relevance and accuracy.","zh":"使用提示工程是提高生成式 AI 应用响应准确性最具成本效益的方式，无需重新训练或微调基础模型（FM）。提示工程涉及精心设计输入提示，引导模型生成更好的响应，提高相关性和准确性。"},"tip":{"zh":"只想提准确率、又最省钱 → 先改提示（prompt engineering），别急着微调。","en":""},"keywords":["提示工程","成本效益","准确性"]},{"id":151,"type":"single","answer":["B"],"topic":"responsible","stem":{"en":"A company wants to identify harmful language in the comments section of social media posts by using an\nML model. The company will not use labeled data to train the model.\nWhich strategy should the company use to identify harmful language?","zh":"一家公司希望使用 ML 模型识别社交媒体帖子评论区中的有害语言。该公司不会使用有标注的数据来训练模型。\n该公司应使用哪种策略来识别有害语言？"},"options":[{"key":"A","en":"Use Amazon Rekognition moderation.","zh":"使用 Amazon Rekognition 审核。"},{"key":"B","en":"Use Amazon Comprehend toxicity detection.","zh":"使用 Amazon Comprehend 有害内容检测。"},{"key":"C","en":"Use Amazon SageMaker built-in algorithms to train the model.","zh":"使用 Amazon SageMaker 内置算法训练模型。"},{"key":"D","en":"Use Amazon Polly to monitor comments.","zh":"使用 Amazon Polly 监控评论。"}],"explanation":{"en":"Amazon Comprehend provides pre-trained NLP models, including toxicity detection, to analyze text for\nharmful language. Since the company does not plan to use labeled data for training, Amazon Comprehend\nis a suitable choice because it does not require custom training and can automatically detect toxic or\nharmful content in comments.","zh":"Amazon Comprehend 提供预训练的 NLP 模型，包括有害内容检测，用于分析文本中的有害语言。由于该公司不打算使用有标注的数据进行训练，Amazon Comprehend 是合适的选择，因为它不需要自定义训练，并且可以自动检测评论中的有害内容。"},"tip":{"zh":"文本有害内容+没有标注数据 → Comprehend 毒性检测，开箱即用。","en":""},"keywords":["Comprehend","有害内容检测","预训练模型"]},{"id":152,"type":"single","answer":["D"],"topic":"sagemaker","stem":{"en":"A media company wants to analyze viewer behavior and demographics to recommend personalized\ncontent. The company wants to deploy a customized ML model in its production environment. The\ncompany also wants to observe if the model quality drifts over time.\nWhich AWS service or feature meets these requirements?","zh":"一家媒体公司希望分析观众行为和人口统计特征，以推荐个性化内容。该公司希望在其生产环境中部署自定义 ML 模型。该公司还希望观察模型质量是否随时间发生漂移。\n哪项 AWS 服务或功能能满足这些要求？"},"options":[{"key":"A","en":"Amazon Rekognition","zh":"Amazon Rekognition"},{"key":"B","en":"Amazon SageMaker Clarify","zh":"Amazon SageMaker Clarify"},{"key":"C","en":"Amazon Comprehend","zh":"Amazon Comprehend"},{"key":"D","en":"Amazon SageMaker Model Monitor","zh":"Amazon SageMaker Model Monitor"}],"explanation":{"en":"Amazon SageMaker Model Monitor continuously tracks deployed ML models in production to detect\ndata drift, model drift, and quality degradation over time. This is essential for ensuring that the\nrecommendation model remains accurate as viewer behavior and demographics change. Model Monitor\nhelps detect anomalies and provides alerts when model performance deviates from expected trends,\nallowing the company to take corrective action.","zh":"Amazon SageMaker Model Monitor 持续跟踪生产环境中已部署的 ML 模型，以检测随时间推移出现的数据漂移、模型漂移和质量下降。这对于确保推荐模型在观众行为和人口统计特征变化时仍保持准确至关重要。Model Monitor 有助于检测异常，并在模型性能偏离预期趋势时提供告警，使公司能够采取纠正措施。"},"tip":{"zh":"上线后盯“质量漂移”→ Model Monitor；Clarify 查偏见和可解释性。","en":""},"keywords":["Model Monitor","模型漂移","生产监控"]},{"id":153,"type":"single","answer":["A"],"topic":"responsible","stem":{"en":"A company is deploying AI/ML models by using AWS services. The company wants to offer transparency\ninto the models’ decision-making processes and provide explanations for the model outputs.\nWhich AWS service or feature meets these requirements?","zh":"一家公司正在使用 AWS 服务部署 AI/ML 模型。该公司希望让模型的决策过程具有透明度，并为模型输出提供解释。\n哪项 AWS 服务或功能能满足这些要求？"},"options":[{"key":"A","en":"Amazon SageMaker Model Cards","zh":"Amazon SageMaker Model Cards"},{"key":"B","en":"Amazon Rekognition","zh":"Amazon Rekognition"},{"key":"C","en":"Amazon Comprehend","zh":"Amazon Comprehend"},{"key":"D","en":"Amazon Lex","zh":"Amazon Lex"}],"explanation":{"en":"Amazon SageMaker Model Cards help provide transparency into AI/ML models by documenting key\ndetails such as model purpose, training data, performance metrics, and limitations. This documentation\nenables organizations to explain model outputs and decision-making processes, ensuring\naccountability and compliance with responsible AI principles.","zh":"Amazon SageMaker Model Cards 通过记录模型用途、训练数据、性能指标和局限性等关键细节，帮助为 AI/ML 模型提供透明度。这种文档使组织能够解释模型输出和决策过程，确保问责制并符合负责任 AI 原则。"},"tip":{"zh":"要“透明度+解释输出” → Model Cards 文档化，题目里透明度基本都指它。","en":""},"keywords":["Model Cards","透明度","可解释性"]},{"id":154,"type":"single","answer":["A"],"topic":"services","stem":{"en":"A manufacturing company wants to create product descriptions in multiple languages.\nWhich AWS service will automate this task?","zh":"一家制造公司希望创建多种语言的产品描述。\n哪项 AWS 服务将自动化此任务？"},"options":[{"key":"A","en":"Amazon Translate","zh":"Amazon Translate"},{"key":"B","en":"Amazon Transcribe","zh":"Amazon Transcribe"},{"key":"C","en":"Amazon Kendra","zh":"Amazon Kendra"},{"key":"D","en":"Amazon Polly","zh":"Amazon Polly"}],"explanation":{"en":"Amazon Translate is an AWS service that automates language translation using neural machine\ntranslation (NMT). It enables businesses to generate product descriptions in multiple languages\nquickly and accurately, making it the best choice for this task.","zh":"Amazon Translate 是一项使用神经机器翻译（NMT）自动完成语言翻译的 AWS 服务。它使企业能够快速、准确地生成多种语言的产品描述，因此是此任务的最佳选择。"},"tip":{"zh":"多语言翻译 → Translate；Transcribe 是语音转文字，Polly 是文字转语音。","en":""},"keywords":["Translate","机器翻译","多语言"]},{"id":155,"type":"hotspot","answer":[],"topic":"genai","stem":{"en":"A company wants more customized responses to its generative AI models’ prompts.\nSelect the correct customization methodology from the following list for each use case. Each use case\nshould be selected one time.","zh":"一家公司希望对其生成式 AI 模型的提示获得更加定制化的响应。\n请从下面的列表中为每个使用场景选择正确的定制方法。每个使用场景应被选择一次。"},"options":[],"explanation":{"en":"The models must be taught a new domain-specific task - Model fine-tuning\nFine-tuning is the best approach when a model needs to learn a specific domain-related task. It involves\nadjusting a pre-trained model with a smaller, task-specific dataset to improve performance in that domain.\nA limited amount of labeled data is available and more data is needed - Data augmentation\nData augmentation helps in scenarios where labeled data is scarce by artificially increasing the size and\nvariability of the dataset, improving model generalization.\nOnly unlabeled data is available - Continued pre-training\nContinued pre-training allows an existing foundation model to be further trained on domain-specific,\nunlabeled data to adapt to new contexts without requiring labeled data.","zh":"必须教会模型一项新的领域特定任务 — 模型微调\n当模型需要学习特定的领域相关任务时，微调是最佳方法。它涉及用较小的任务特定数据集调整预训练模型，以提升其在该领域的性能。\n可用的标注数据有限，还需要更多数据 — 数据增强\n数据增强通过人为扩大数据集的规模和多样性，帮助解决标注数据稀缺的场景，提升模型泛化能力。\n只有无标注数据可用 — 持续预训练\n持续预训练允许现有基础模型在领域特定、无标注的数据上进一步训练，从而无需标注数据即可适应新的上下文。"},"tip":{"zh":"学新领域任务=微调；标注太少=数据增强；只有无标注=持续预训练。","en":""},"keywords":["微调","数据增强","持续预训练"]},{"id":156,"type":"single","answer":["A"],"topic":"responsible","stem":{"en":"Which AWS feature records details about ML instance data for governance and reporting?","zh":"哪项 AWS 功能会为治理和报告目的记录 ML 实例数据的详细信息？"},"options":[{"key":"A","en":"Amazon SageMaker Model Cards","zh":"Amazon SageMaker Model Cards"},{"key":"B","en":"Amazon SageMaker Debugger","zh":"Amazon SageMaker Debugger"},{"key":"C","en":"Amazon SageMaker Model Monitor","zh":"Amazon SageMaker Model Monitor"},{"key":"D","en":"Amazon SageMaker JumpStart","zh":"Amazon SageMaker JumpStart"}],"explanation":{"en":"Amazon SageMaker Model Cards record key details about machine learning models, including intended\nuse, training data, evaluation metrics, and compliance information. They support governance and reporting\nby providing a standardized way to document model information throughout its lifecycle.","zh":"Amazon SageMaker Model Cards 记录机器学习模型的关键细节，包括预期用途、训练数据、评估指标和合规信息。它们通过提供一种在模型整个生命周期内记录模型信息的标准化方式，支持治理和报告。"},"tip":{"zh":"治理和报告要的“模型档案” → Model Cards；Debugger 调训练，Monitor 看漂移。","en":""},"keywords":["Model Cards","治理","模型文档"]},{"id":157,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"A financial company is using ML to help with some of the company’s tasks.\nWhich option is a use of generative AI models?","zh":"一家金融公司正在使用 ML 来协助公司的一些任务。\n哪一项是生成式 AI 模型的用途？"},"options":[{"key":"A","en":"Summarizing customer complaints","zh":"汇总客户投诉"},{"key":"B","en":"Classifying customers based on product usage","zh":"根据产品使用情况对客户进行分类"},{"key":"C","en":"Segmenting customers based on type of investments","zh":"根据投资类型对客户进行细分"},{"key":"D","en":"Forecasting revenue for certain products","zh":"预测某些产品的收入"}],"explanation":{"en":"Generative AI models are designed to generate new content such as text, images, or audio. Summarizing\ncustomer complaints involves generating concise versions of longer texts, which is a task well-suited for\ngenerative AI models like large language models.","zh":"生成式 AI 模型旨在生成新内容，例如文本、图像或音频。汇总客户投诉涉及生成长文本的简明版本，这是一项非常适合大型语言模型等生成式 AI 模型的任务。"},"tip":{"zh":"生成式=产出新内容（摘要、写文案）；分类、细分、预测都是传统 ML。","en":""},"keywords":["生成式 AI","摘要","内容生成"]},{"id":158,"type":"single","answer":["A"],"topic":"services","stem":{"en":"A medical company wants to develop an AI application that can access structured patient records, extract\nrelevant information, and generate concise summaries.\nWhich solution will meet these requirements?","zh":"一家医疗公司希望开发一个 AI 应用，能够访问结构化患者病历、提取相关信息并生成简明摘要。\n哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Use Amazon Comprehend Medical to extract relevant medical entities and relationships. Apply rule- based logic to structure and format summaries.","zh":"使用 Amazon Comprehend Medical 提取相关医疗实体和关系。应用基于规则的逻辑来组织和格式化摘要。"},{"key":"B","en":"Use Amazon Personalize to analyze patient engagement patterns. Integrate the output with a general purpose text summarization tool.","zh":"使用 Amazon Personalize 分析患者参与模式。将输出与通用文本摘要工具集成。"},{"key":"C","en":"Use Amazon Textract to convert scanned documents into digital text. Design a keyword extraction system to generate summaries.","zh":"使用 Amazon Textract 将扫描文档转换为数字文本。设计一个关键词提取系统来生成摘要。"},{"key":"D","en":"Implement Amazon Kendra to provide a searchable index for medical records. Use a template-based system to format summaries.","zh":"实施 Amazon Kendra 为病历提供可搜索索引。使用基于模板的系统来格式化摘要。"}],"explanation":{"en":"Amazon Comprehend Medical is specifically designed to extract structured medical information (such as\nmedication, condition, test results) from unstructured text. By applying rule-based logic afterward, relevant\ndata can be formatted into concise summaries, meeting both the extraction and summarization needs.","zh":"Amazon Comprehend Medical 专门用于从非结构化文本中提取结构化医疗信息（例如药物、病症、检验结果）。之后应用基于规则的逻辑，可将相关数据格式化为简明摘要，同时满足提取和摘要两项需求。"},"tip":{"zh":"病历实体抽取 → Comprehend Medical；Textract 只做 OCR，不懂医疗语义。","en":""},"keywords":["Comprehend Medical","医疗实体抽取","摘要"]},{"id":159,"type":"single","answer":["D"],"topic":"genai","stem":{"en":"Which option describes embeddings in the context of AI?","zh":"哪一项描述了 AI 语境中的嵌入向量？"},"options":[{"key":"A","en":"A method for compressing large datasets","zh":"一种压缩大型数据集的方法"},{"key":"B","en":"An encryption method for securing sensitive data","zh":"一种保护敏感数据的加密方法"},{"key":"C","en":"A method for visualizing high-dimensional data","zh":"一种可视化高维数据的方法"},{"key":"D","en":"A numerical method for data representation in a reduced dimensionality space","zh":"一种在降维空间中进行数据表示的数值方法"}],"explanation":{"en":"Embeddings are numerical representations of data, such as words, images, or items, in a lower-\ndimensional vector space. They capture semantic relationships and patterns in the data, enabling models\nto process and compare inputs efficiently.","zh":"嵌入向量是数据（例如词语、图像或物品）在低维向量空间中的数值表示。它们捕捉数据中的语义关系和模式，使模型能够高效地处理和比较输入。"},"tip":{"zh":"嵌入=把文本图片变成低维向量，比的是语义距离，不是压缩也不是加密。","en":""},"keywords":["嵌入向量","降维表示","语义相似度"]},{"id":160,"type":"single","answer":["D"],"topic":"genai","stem":{"en":"A company is building an AI application to summarize books of varying lengths. During testing, the\napplication fails to summarize some books.\nWhy does the application fail to summarize some books?","zh":"一家公司正在构建一个 AI 应用来汇总长度各异的书籍。在测试期间，该应用无法汇总某些书籍。\n为什么该应用无法汇总某些书籍？"},"options":[{"key":"A","en":"The temperature is set too high.","zh":"temperature 设置过高。"},{"key":"B","en":"The selected model does not support fine-tuning.","zh":"所选模型不支持微调。"},{"key":"C","en":"The Top P value is too high.","zh":"Top P 值过高。"},{"key":"D","en":"The input tokens exceed the model’s context size.","zh":"输入词元（token）超过了模型的上下文大小。"}],"explanation":{"en":"Language models have a maximum context size, which limits the number of input tokens they can process\nat once. If a book's length exceeds this limit, the model cannot handle the full input, leading to failure in\nsummarization.","zh":"语言模型有最大上下文大小，这限制了它们一次可处理的输入词元数量。如果一本书的长度超过此限制，模型就无法处理完整输入，从而导致汇总失败。"},"tip":{"zh":"长文档处理不了 → 输入 token 超上下文窗口，跟温度和微调无关。","en":""},"keywords":["上下文窗口","词元限制","长文本"]},{"id":161,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"An airline company wants to build a conversational AI assistant to answer customer questions about flight\nschedules, booking, and payments. The company wants to use large language models (LLMs) and a\nknowledge base to create a text-based chatbot interface.\nWhich solution will meet these requirements with the LEAST development effort?","zh":"一家航空公司希望构建一个对话式 AI 助手，用于回答客户关于航班时刻、预订和支付的问题。该公司希望使用大型语言模型（LLM）和知识库来创建一个基于文本的聊天机器人界面。\n哪种解决方案能以最少的开发工作量满足这些要求？"},"options":[{"key":"A","en":"Train models on Amazon SageMaker Autopilot.","zh":"在 Amazon SageMaker Autopilot 上训练模型。"},{"key":"B","en":"Develop a Retrieval Augmented Generation (RAG) agent by using Amazon Bedrock.","zh":"使用 Amazon Bedrock 开发检索增强生成（RAG）代理。"},{"key":"C","en":"Create a Python application by using Amazon Q Developer.","zh":"使用 Amazon Q Developer 创建 Python 应用。"},{"key":"D","en":"Fine-tune models on Amazon SageMaker Jumpstart.","zh":"在 Amazon SageMaker JumpStart 上微调模型。"}],"explanation":{"en":"Amazon Bedrock allows quick integration of large language models with a knowledge base using RAG\narchitecture, enabling accurate and dynamic responses based on up-to-date information. This approach\nrequires minimal development effort while leveraging powerful generative capabilities.","zh":"Amazon Bedrock 允许使用 RAG 架构快速将大型语言模型与知识库集成，从而基于最新信息提供准确且动态的响应。这种方法所需的开发工作量极少，同时利用了强大的生成能力。"},"tip":{"zh":"LLM+知识库做问答、还要开发量最小 → Bedrock 的 RAG 代理，别自己训模型。","en":""},"keywords":["RAG","Bedrock","知识库问答"]},{"id":162,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"What is tokenization used for in natural language processing (NLP)?","zh":"在自然语言处理（NLP）中，分词（tokenization）用于什么目的？"},"options":[{"key":"A","en":"To encrypt text data","zh":"加密文本数据"},{"key":"B","en":"To compress text files","zh":"压缩文本文件"},{"key":"C","en":"To break text into smaller units for processing","zh":"将文本拆分为更小的单元以便处理"},{"key":"D","en":"To translate text between languages","zh":"在不同语言之间翻译文本"}],"explanation":{"en":"Tokenization is the process of dividing text into smaller units, such as words, subwords, or characters,\nwhich can then be analyzed or processed by NLP models. It is a foundational step in preparing text data\nfor machine learning.","zh":"分词是将文本划分为更小单元（例如词语、子词或字符）的过程，这些单元随后可由 NLP 模型分析或处理。它是为机器学习准备文本数据的基础步骤。"},"tip":{"zh":"分词=把文本切成词元（token）喂给模型，是预处理第一步。","en":""},"keywords":["分词","词元","文本预处理"]},{"id":163,"type":"single","answer":["C"],"topic":"general","stem":{"en":"Which option is a characteristic of transformer-based language models?","zh":"哪一项是基于 Transformer 的语言模型的特征？"},"options":[{"key":"A","en":"Transformer-based language models use convolutional layers to apply filters across an input to capture local patterns through filtered views.","zh":"基于 Transformer 的语言模型使用卷积层对输入应用滤波器，通过滤波视图捕捉局部模式。"},{"key":"B","en":"Transformer-based language models can process only text data.","zh":"基于 Transformer 的语言模型只能处理文本数据。"},{"key":"C","en":"Transformer-based language models use self-attention mechanisms to capture contextual relationships.","zh":"基于 Transformer 的语言模型使用自注意力机制来捕捉上下文关系。"},{"key":"D","en":"Transformer-based language models process data sequences one element at a time in cyclic iterations.","zh":"基于 Transformer 的语言模型以循环迭代的方式逐个处理数据序列元素。"}],"explanation":{"en":"A key characteristic of transformer models is their use of self-attention mechanisms, which allow the model\nto weigh the importance of different words in a sequence relative to each other, enabling a deep\nunderstanding of context and meaning across the entire input.","zh":"Transformer 模型的一个关键特征是使用自注意力机制，它允许模型衡量序列中不同词语相对于彼此的重要性，从而能够深入理解整个输入的上下文和含义。"},"tip":{"zh":"Transformer 的招牌是自注意力（self-attention）；逐元素循环是 RNN 的做法。","en":""},"keywords":["Transformer","自注意力","上下文"]},{"id":164,"type":"single","answer":["D"],"topic":"responsible","stem":{"en":"A financial company is using AI systems to obtain customer credit scores as part of the loan application\nprocess. The company wants to expand to a new market in a different geographic area. The company\nmust ensure that it can operate in that geographic area.\nWhich compliance laws should the company review?","zh":"一家金融公司在贷款申请流程中使用 AI 系统获取客户信用评分。该公司希望扩展到不同地理区域的新市场。该公司必须确保能够在该地理区域运营。\n该公司应审查哪些合规法律？"},"options":[{"key":"A","en":"Local health data protection laws","zh":"当地健康数据保护法"},{"key":"B","en":"Local payment card data protection laws","zh":"当地支付卡数据保护法"},{"key":"C","en":"Local education privacy laws","zh":"当地教育隐私法"},{"key":"D","en":"Local algorithm accountability laws","zh":"当地算法问责法"}],"explanation":{"en":"When deploying AI systems that affect individuals, such as credit scoring, companies must comply with\nlocal algorithm accountability laws. These laws regulate the fairness, transparency, and impact of\nautomated decision-making, ensuring ethical use of AI in new geographic regions.","zh":"在部署影响个人的 AI 系统（例如信用评分）时，公司必须遵守当地的算法问责法。这些法律规范自动化决策的公平性、透明度和影响，确保在新的地理区域以合乎伦理的方式使用 AI。"},"tip":{"zh":"信用评分这类自动决策 → 看算法问责法；健康、支付卡、教育都不对题。","en":""},"keywords":["算法问责","合规","信用评分"]},{"id":165,"type":"multi","answer":["A","C"],"topic":"responsible","stem":{"en":"A company uses Amazon Bedrock for its generative AI application. The company wants to use Amazon\nBedrock Guardrails to detect and filter harmful user inputs and model-generated outputs.\nWhich content categories can the guardrails filter? (Choose two.)","zh":"一家公司为其生成式 AI 应用使用 Amazon Bedrock。该公司希望使用 Amazon Bedrock Guardrails 来检测和过滤有害的用户输入和模型生成的输出。\n这些护栏可以过滤哪些内容类别？（选择两项。）"},"options":[{"key":"A","en":"Hate","zh":"仇恨"},{"key":"B","en":"Politics","zh":"政治"},{"key":"C","en":"Violence","zh":"暴力"},{"key":"D","en":"Gambling","zh":"赌博"},{"key":"E","en":"Religion","zh":"宗教"}],"explanation":{"en":"Amazon Bedrock Guardrails provide configurable content filters to detect and block harmful content in\ngenerative AI applications. Specifically, they include filters for categories such as Hate and Violence,\namong others. These filters can be applied to both user inputs and model-generated outputs to ensure that\nthe AI application adheres to responsible AI practices and organizational policies.","zh":"Amazon Bedrock Guardrails 提供可配置的内容过滤器，用于检测和阻止生成式 AI 应用中的有害内容。具体而言，它们包含针对仇恨和暴力等类别的过滤器。这些过滤器可应用于用户输入和模型生成的输出，以确保 AI 应用遵循负责任 AI 实践和组织政策。"},"tip":{"zh":"Bedrock 内容过滤器管的是仇恨、暴力这类有害类别，政治宗教要另设拒绝主题。","en":""},"keywords":["Bedrock Guardrails","内容过滤器","仇恨与暴力"]},{"id":166,"type":"single","answer":["B"],"topic":"security","stem":{"en":"Which scenario describes a potential risk and limitation of prompt engineering in the context of a\ngenerative AI model?","zh":"在生成式 AI 模型的语境中，哪个场景描述了提示工程潜在的风险和局限性？"},"options":[{"key":"A","en":"Prompt engineering does not ensure that the model always produces consistent and deterministic outputs, eliminating the need for validation.","zh":"提示工程不能确保模型始终产生一致且确定的输出，从而无需进行验证。"},{"key":"B","en":"Prompt engineering could expose the model to vulnerabilities such as prompt injection attacks.","zh":"提示工程可能使模型面临提示注入攻击等漏洞。"},{"key":"C","en":"Properly designed prompts reduce but do not eliminate the risk of data poisoning or model hijacking.","zh":"设计良好的提示可以降低但无法消除数据投毒或模型劫持的风险。"},{"key":"D","en":"Prompt engineering does not ensure that the model will consistently generate highly reliable outputs when working with real-world data.","zh":"在处理真实世界数据时，提示工程不能确保模型始终生成高度可靠的输出。"}],"explanation":{"en":"A key risk in prompt engineering is prompt injection, where attackers manipulate input prompts to alter a\nmodel's behavior or produce unintended outputs. This vulnerability arises from the model's sensitivity to\ninput structure and content, making it a critical limitation in secure prompt design.","zh":"提示工程的一个关键风险是提示注入，即攻击者操纵输入提示以改变模型行为或产生非预期输出。该漏洞源于模型对输入结构和内容的敏感性，使其成为安全提示设计中的一个关键局限。"},"tip":{"zh":"提示工程最大的安全风险=提示注入（prompt injection），攻的是输入提示。","en":""},"keywords":["提示注入","安全风险","提示工程"]},{"id":167,"type":"multi","answer":["A","C"],"topic":"genai","stem":{"en":"A publishing company built a Retrieval Augmented Generation (RAG) based solution to give its users the\nability to interact with published content. New content is published daily. The company wants to provide a\nnear real-time experience to users.\nWhich steps in the RAG pipeline should the company implement by using offline batch processing to meet\nthese requirements? (Choose two.)","zh":"一家出版公司构建了一个基于检索增强生成（RAG）的解决方案，使用户能够与已发布的内容进行交互。每天都会发布新内容。该公司希望为用户提供接近实时的体验。\n为满足这些要求，RAG 管道中的哪些步骤应使用离线批处理来实现？（选择两项。）"},"options":[{"key":"A","en":"Generation of content embeddings","zh":"生成内容嵌入向量"},{"key":"B","en":"Generation of embeddings for user queries","zh":"为用户查询生成嵌入向量"},{"key":"C","en":"Creation of the search index","zh":"创建搜索索引"},{"key":"D","en":"Retrieval of relevant content","zh":"检索相关内容"},{"key":"E","en":"Response generation for the user","zh":"为用户生成响应"}],"explanation":{"en":"Generation of content embeddings\nNew or updated documents can be converted to vector representations in periodic batches (e.g., hourly,\nnightly). Because a document’s embedding remains fixed until the document itself changes, this step does\nnot have to run for every user query, making it ideal for offline processing.\nCreation of the search index\nAfter new embeddings are produced, the vector (or hybrid) index can be rebuilt or incrementally updated in\nbatch mode. Index construction is computationally intensive but happens infrequently relative to user\nrequests, so running it offline avoids adding latency to real-time interactions.","zh":"生成内容嵌入向量\n新增或更新的文档可以按周期（例如每小时、每晚）批量转换为向量表示。由于文档的嵌入向量在文档本身变更之前保持不变，该步骤不必针对每个用户查询运行，因此非常适合离线处理。\n创建搜索索引\n生成新的嵌入向量后，可以在批处理模式下重建或增量更新向量（或混合）索引。索引构建计算密集，但相对于用户请求而言发生频率较低，因此离线运行可避免给实时交互增加延迟。"},"tip":{"zh":"离线批处理只做“提前算好”的部分：文档嵌入和建索引；查询侧必须实时。","en":""},"keywords":["RAG 管道","离线批处理","索引构建"]},{"id":168,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"Which technique breaks a complex task into smaller subtasks that are sent sequentially to a large\nlanguage model (LLM)?","zh":"哪种技术将复杂任务拆分为更小的子任务，并按顺序发送给大型语言模型（LLM）？"},"options":[{"key":"A","en":"One-shot prompting","zh":"单样本提示"},{"key":"B","en":"Prompt chaining","zh":"提示链"},{"key":"C","en":"Tree of thoughts","zh":"思维树"},{"key":"D","en":"Retrieval Augmented Generation (RAG)","zh":"检索增强生成（RAG）"}],"explanation":{"en":"Prompt chaining involves breaking a complex task into smaller, manageable subtasks and passing them\nsequentially to a large language model. Each step builds upon the previous one, enabling more structured\nreasoning and improved task execution.","zh":"提示链涉及将复杂任务拆分为更小、更易管理的子任务，并按顺序传递给大型语言模型。每一步都建立在前一步的基础上，从而实现更结构化的推理和更好的任务执行。"},"tip":{"zh":"拆成子任务、按顺序一步步喂给 LLM → 提示链（prompt chaining）。","en":""},"keywords":["提示链","任务拆解","多步推理"]},{"id":169,"type":"single","answer":["C"],"topic":"eval","stem":{"en":"An AI practitioner needs to improve the accuracy of a natural language generation model. The model uses\nrapidly changing inventory data.\nWhich technique will improve the model's accuracy?","zh":"一位 AI 从业者需要提高自然语言生成模型的准确性。该模型使用的库存数据变化很快。\n哪种技术将提高模型的准确性？"},"options":[{"key":"A","en":"Transfer learning","zh":"迁移学习"},{"key":"B","en":"Federated learning","zh":"联邦学习"},{"key":"C","en":"Retrieval Augmented Generation (RAG)","zh":"检索增强生成（RAG）"},{"key":"D","en":"One-shot prompting","zh":"单样本提示"}],"explanation":{"en":"RAG enhances a language model by fetching up-to-date, domain-specific data (e.g., current inventory) at\ninference time and conditioning the generation on those facts, ensuring the output reflects the latest\ninformation and improving accuracy without retraining the core model.","zh":"RAG 通过在推理时获取最新、特定领域的数据（例如当前库存）并以这些事实为条件进行生成，来增强语言模型，确保输出反映最新信息，并在无需重新训练核心模型的情况下提高准确性。"},"tip":{"zh":"数据变化快 → 用 RAG 实时取数，模型不用重训也准。","en":""},"keywords":["RAG","实时数据","准确性"]},{"id":170,"type":"single","answer":["C"],"topic":"responsible","stem":{"en":"A company wants to collaborate with several research institutes to develop an AI model. The company\nneeds standardized documentation of model version tracking and a record of model development.\nWhich solution meets these requirements?","zh":"一家公司希望与多家研究机构合作开发一个 AI 模型。该公司需要标准化的模型版本跟踪文档以及模型开发记录。\n哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Track the model changes by using Git.","zh":"使用 Git 跟踪模型变更。"},{"key":"B","en":"Track the model changes by using Amazon Fraud Detector.","zh":"使用 Amazon Fraud Detector 跟踪模型变更。"},{"key":"C","en":"Track the model changes by using Amazon SageMaker Model Cards.","zh":"使用 Amazon SageMaker Model Cards 跟踪模型变更。"},{"key":"D","en":"Track the model changes by using Amazon Comprehend.","zh":"使用 Amazon Comprehend 跟踪模型变更。"}],"explanation":{"en":"SageMaker Model Cards provide a built-in framework for capturing and versioning key metadata, such as\ntraining data details, performance metrics, lineage, and intended use, for each model iteration. This\nstandardized documentation and history of development fulfills requirements for model version tracking\nand auditable records.","zh":"SageMaker Model Cards 提供了一个内置框架，用于为每个模型迭代版本捕获关键元数据并管理其版本，例如训练数据详情、性能指标、数据血缘和预期用途。这种标准化文档和开发历史满足了模型版本跟踪和可审计记录的要求。"},"tip":{"zh":"要标准化模型文档+版本跟踪+可审计 → Model Cards，Git 只是代码管理。","en":""},"keywords":["Model Cards","版本跟踪","可审计"]},{"id":171,"type":"single","answer":["D"],"topic":"eval","stem":{"en":"A company that uses multiple ML models wants to identify changes in original model quality so that the\ncompany can resolve any issues.\nWhich AWS service or feature meets these requirements?","zh":"一家使用多个 ML 模型的公司希望识别原始模型质量的变化，以便解决任何问题。\n哪项 AWS 服务或功能能满足这些要求？"},"options":[{"key":"A","en":"Amazon SageMaker JumpStart","zh":"Amazon SageMaker JumpStart"},{"key":"B","en":"Amazon SageMaker HyperPod","zh":"Amazon SageMaker HyperPod"},{"key":"C","en":"Amazon SageMaker Data Wrangler","zh":"Amazon SageMaker Data Wrangler"},{"key":"D","en":"Amazon SageMaker Model Monitor","zh":"Amazon SageMaker Model Monitor"}],"explanation":{"en":"SageMaker Model Monitor continuously measures data and prediction quality in production, detects\ndeviations from your model’s baseline (such as data drift or accuracy degradation), and alerts you so you\ncan investigate and resolve issues promptly.","zh":"SageMaker Model Monitor 持续衡量生产环境中的数据质量和预测质量，检测与模型基线之间的偏差（例如数据漂移或准确率下降），并向你发出告警，以便及时调查和解决问题。"},"tip":{"zh":"盯“模型质量变化/漂移”并告警 → Model Monitor，其余三个都是训练期工具。","en":""},"keywords":["Model Monitor","质量漂移","告警"]},{"id":172,"type":"single","answer":["C"],"topic":"eval","stem":{"en":"What is the purpose of chunking in Retrieval Augmented Generation (RAG)?","zh":"在检索增强生成（RAG）中，分块（chunking）的目的是什么？"},"options":[{"key":"A","en":"To avoid database storage limitations for large text documents by storing parts or chunks of the text","zh":"通过存储文本的部分内容或分块，避免大型文本文档的数据库存储限制"},{"key":"B","en":"To improve efficiency by avoiding the need to convert large text into vector embeddings","zh":"通过避免将大型文本转换为向量嵌入来提高效率"},{"key":"C","en":"To improve the contextual relevancy of results retrieved from the vector index","zh":"提高从向量索引中检索到的结果的上下文相关性"},{"key":"D","en":"To decrease the cost of storage by storing parts or chunks of the text","zh":"通过存储文本的部分内容或分块来降低存储成本"}],"explanation":{"en":"By splitting large documents into smaller, semantically coherent chunks, the retrieval system can match\nand return only the most context-relevant segments for a given query, enhancing the precision and\naccuracy of the generated responses.","zh":"通过将大型文档拆分为更小、语义连贯的块，检索系统可以针对给定查询仅匹配并返回与上下文最相关的片段，从而提高生成响应的精确率和准确性。"},"tip":{"zh":"分块不是为了省存储，是为了检索更准 → 提高上下文相关性。","en":""},"keywords":["分块","RAG","检索相关性"]},{"id":173,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"A company is developing an editorial assistant application that uses generative AI. During the pilot phase,\nusage is low and application performance is not a concern. The company cannot predict application usage\nafter the application is fully deployed and wants to minimize application costs.\nWhich solution will meet these requirements?","zh":"一家公司正在开发一个使用生成式 AI 的编辑助手应用。在试点阶段，使用量很低，应用性能不是问题。该公司无法预测应用完全部署后的使用量，并希望将应用成本降到最低。\n哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Use GPU-powered Amazon EC2 instances.","zh":"使用由 GPU 驱动的 Amazon EC2 实例。"},{"key":"B","en":"Use Amazon Bedrock with Provisioned Throughput.","zh":"使用带预置吞吐量的 Amazon Bedrock。"},{"key":"C","en":"Use Amazon Bedrock with On-Demand Throughput.","zh":"使用带按需吞吐量的 Amazon Bedrock。"},{"key":"D","en":"Use Amazon SageMaker JumpStart.","zh":"使用 Amazon SageMaker JumpStart。"}],"explanation":{"en":"On-Demand Throughput in Bedrock charges only for the inference calls you actually make, with no upfront\ncapacity commitment. This lets you start with minimal pilot usage and elastically handle unpredictable\nfuture load while keeping costs as low as possible.","zh":"Bedrock 中的按需吞吐量仅对你实际发起的推理调用收费，没有前期容量承诺。这使你能够以最小的试点使用量起步，并弹性应对不可预测的未来负载，同时将成本保持在尽可能低的水平。"},"tip":{"zh":"用量不可预测 → 按需吞吐量（按调用付费）；预置吞吐量要先承诺容量。","en":""},"keywords":["按需吞吐量","弹性","成本"]},{"id":174,"type":"single","answer":["B"],"topic":"responsible","stem":{"en":"A company deployed a Retrieval Augmented Generation (RAG) application on Amazon Bedrock that\ngathers financial news to distribute in daily newsletters. Users have recently reported politically influenced\nideas in the newsletters.\nWhich Amazon Bedrock guardrail can identify and filter this content?","zh":"一家公司在 Amazon Bedrock 上部署了一个检索增强生成（RAG）应用，该应用收集财经新闻用于每日简报的分发。用户最近报告称简报中出现了受政治影响的观点。\n哪项 Amazon Bedrock 护栏可以识别并过滤此类内容？"},"options":[{"key":"A","en":"Word filters","zh":"词语过滤器"},{"key":"B","en":"Denied topics","zh":"拒绝主题"},{"key":"C","en":"Sensitive information filters","zh":"敏感信息过滤器"},{"key":"D","en":"Content filters","zh":"内容过滤器"}],"explanation":{"en":"The Denied topics guardrail lets you define high-level categories (such as politics) that the model must\navoid. Bedrock enforces these rules during generation, filtering out any content related to politically\ninfluenced ideas.","zh":"拒绝主题护栏允许你定义模型必须避开的高层级类别（例如政治）。Bedrock 在生成过程中执行这些规则，过滤掉任何与受政治影响观点相关的内容。"},"tip":{"zh":"整类话题（政治、法律建议）要屏蔽 → 拒绝主题；内容过滤器只管仇恨暴力等。","en":""},"keywords":["拒绝主题","Bedrock 护栏","内容过滤"]},{"id":175,"type":"single","answer":["C"],"topic":"eval","stem":{"en":"A financial company is developing a fraud detection system that flags potential fraud cases in credit card\ntransactions. Employees will evaluate the flagged fraud cases. The company wants to minimize the\namount of time the employees spend reviewing flagged fraud cases that are not actually fraudulent.\nWhich evaluation metric meets these requirements?","zh":"一家金融公司正在开发一个欺诈检测系统，用于标记信用卡交易中的潜在欺诈案例。员工将对被标记的欺诈案例进行评估。该公司希望尽量减少员工审查实际上并非欺诈的被标记案例所花费的时间。\n哪项评估指标能满足这些要求？"},"options":[{"key":"A","en":"Recall","zh":"召回率"},{"key":"B","en":"Accuracy","zh":"准确率"},{"key":"C","en":"Precision","zh":"精确率"},{"key":"D","en":"Lift chart","zh":"提升图"}],"explanation":{"en":"Precision measures the proportion of flagged cases that are truly fraudulent (TP / [TP + FP]). Maximizing\nprecision reduces the number of false positives employees must review, cutting down wasted effort on\nnon-fraudulent cases.","zh":"精确率衡量被标记案例中真正为欺诈的比例（TP / [TP + FP]）。最大化精确率可减少员工必须审查的误报数量，从而减少在非欺诈案例上浪费的精力。"},"tip":{"zh":"不想被误报打扰 → 精确率；怕漏掉真欺诈才看召回率。","en":""},"keywords":["精确率","误报","欺诈检测"]},{"id":176,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"A company designed an AI-powered agent to answer customer inquiries based on product manuals.\nWhich strategy can improve customer confidence levels in the AI-powered agent's responses?","zh":"一家公司设计了一个 AI 驱动的代理，用于根据产品手册回答客户咨询。\n哪种策略可以提高客户对 AI 代理响应的信心水平？"},"options":[{"key":"A","en":"Writing the confidence level in the response","zh":"在响应中写出置信度水平"},{"key":"B","en":"Including referenced product manual links in the response","zh":"在响应中包含引用的产品手册链接"},{"key":"C","en":"Designing an agent avatar that looks like a computer","zh":"设计一个看起来像计算机的代理头像"},{"key":"D","en":"Training the agent to respond in the company's language style","zh":"训练代理用公司的语言风格进行响应"}],"explanation":{"en":"Providing direct links to the exact sections of the product manual that support each answer lets customers\nverify and trust the information, boosting confidence in the AI agent’s responses.","zh":"提供指向支撑每个答案的产品手册确切章节的直接链接，可让客户核实并信任这些信息，从而提升对 AI 代理响应的信心。"},"tip":{"zh":"让客户能自己核对出处 → 附上手册原文链接，信心自然上来。","en":""},"keywords":["可溯源性","引用来源","用户信任"]},{"id":177,"type":"single","answer":["A"],"topic":"responsible","stem":{"en":"A hospital developed an AI system to provide personalized treatment recommendations for patients. The\nAI system must provide the rationale behind the recommendations and make the insights accessible to\ndoctors and patients.\nWhich human-centered design principle does this scenario present?","zh":"一家医院开发了一个 AI 系统，为患者提供个性化治疗建议。该 AI 系统必须提供建议背后的理由，并让医生和患者都能理解这些洞察。\n该场景呈现了哪种以人为本的设计原则？"},"options":[{"key":"A","en":"Explainability","zh":"可解释性"},{"key":"B","en":"Privacy and security","zh":"隐私与安全"},{"key":"C","en":"Fairness","zh":"公平性"},{"key":"D","en":"Data governance","zh":"数据治理"}],"explanation":{"en":"Explainability ensures that the AI system reveals the reasoning behind its recommendations in an\nunderstandable way, making insights transparent and accessible to both doctors and patients.","zh":"可解释性确保 AI 系统以可理解的方式揭示其建议背后的推理，使洞察对医生和患者都透明且易于获取。"},"tip":{"zh":"要给出“为什么这么建议”且人能看懂 → 可解释性。","en":""},"keywords":["可解释性","以人为本","医疗 AI"]},{"id":178,"type":"single","answer":["A"],"topic":"eval","stem":{"en":"Which statement presents an advantage of using Retrieval Augmented Generation (RAG) for natural\nlanguage processing (NLP) tasks?","zh":"哪项陈述说明了将检索增强生成（RAG）用于自然语言处理（NLP）任务的优点？"},"options":[{"key":"A","en":"RAG can use external knowledge sources to generate more accurate and informative responses.","zh":"RAG 可以使用外部知识源来生成更准确、信息更丰富的响应。"},{"key":"B","en":"RAG is designed to improve the speed of language model training.","zh":"RAG 旨在提高语言模型训练的速度。"},{"key":"C","en":"RAG is primarily used for speech recognition tasks.","zh":"RAG 主要用于语音识别任务。"},{"key":"D","en":"RAG is a technique for data augmentation in computer vision tasks.","zh":"RAG 是计算机视觉任务中用于数据增强的技术。"}],"explanation":{"en":"By retrieving relevant documents or data at inference time and conditioning the generation on that external\nknowledge, RAG enriches model outputs with up-to-date, domain-specific information, boosting accuracy\nand informativeness without retraining the core model.","zh":"通过在推理时检索相关文档或数据，并以此外部知识为条件进行生成，RAG 用最新、特定领域的信息丰富模型输出，在无需重新训练核心模型的情况下提升准确性和信息丰富度。"},"tip":{"zh":"RAG 的优点是接外部知识库，答案更新更准，跟训练速度和语音无关。","en":""},"keywords":["RAG","外部知识","准确性"]},{"id":179,"type":"single","answer":["D"],"topic":"security","stem":{"en":"A company has created a custom model by fine-tuning an existing large language model (LLM) from\nAmazon Bedrock. The company wants to deploy the model to production and use the model to handle a\nsteady rate of requests each minute.\nWhich solution meets these requirements MOST cost-effectively?","zh":"一家公司通过微调 Amazon Bedrock 中现有的一个大型语言模型（LLM）创建了自定义模型。该公司希望将该模型部署到生产环境，并使用该模型处理每分钟稳定的请求量。\n哪种解决方案能以最具成本效益的方式满足这些要求？"},"options":[{"key":"A","en":"Deploy the model by using an Amazon EC2 compute optimized instance.","zh":"使用 Amazon EC2 计算优化型实例部署模型。"},{"key":"B","en":"Use the model with on-demand throughput on Amazon Bedrock.","zh":"在 Amazon Bedrock 上以按需吞吐量使用该模型。"},{"key":"C","en":"Store the model in Amazon S3 and host the model by using AWS Lambda.","zh":"将模型存储在 Amazon S3 中，并使用 AWS Lambda 托管模型。"},{"key":"D","en":"Purchase Provisioned Throughput for the model on Amazon Bedrock.","zh":"为 Amazon Bedrock 上的该模型购买预置吞吐量。"}],"explanation":{"en":"Provisioned Throughput is priced lower per request when you have a predictable, steady volume of calls.\nBy committing to a fixed throughput level, you secure the necessary capacity at a reduced unit cost\ncompared to on-demand, making it the most cost-effective choice for steady-minute usage.","zh":"当你拥有可预测且稳定的调用量时，预置吞吐量的单次请求价格更低。通过承诺固定的吞吐量水平，你可以以比按需更低的单位成本获得所需容量，因此对于每分钟稳定用量来说，它是最具成本效益的选择。"},"tip":{"zh":"稳定可预测的流量 → 预置吞吐量更便宜；按需适合波动或试点。","en":""},"keywords":["预置吞吐量","稳定流量","成本优化"]},{"id":180,"type":"single","answer":["B"],"topic":"data","stem":{"en":"Which technique involves training AI models on labeled datasets to adapt the models to specific industry\nterminology and requirements?","zh":"哪种技术涉及在有标注的数据集上训练 AI 模型，使模型适应特定的行业术语和需求？"},"options":[{"key":"A","en":"Data augmentation","zh":"数据增强"},{"key":"B","en":"Fine-tuning","zh":"微调"},{"key":"C","en":"Model quantization","zh":"模型量化"},{"key":"D","en":"Continuous pre-training","zh":"持续预训练"}],"explanation":{"en":"Fine-tuning takes a pre-trained model and continues training it on a labeled, domain-specific dataset so\nthe model learns industry terminology and task nuances directly from that specialized data.","zh":"微调采用预训练模型，并在有标注的领域特定数据集上继续训练它，使模型直接从这些专门数据中学习行业术语和任务细节。"},"tip":{"zh":"有标注数据+适应行业术语 → 微调；持续预训练用的是无标注数据。","en":""},"keywords":["微调","领域适应","标注数据"]},{"id":181,"type":"single","answer":["A"],"topic":"eval","stem":{"en":"A company is creating an agent for its application by using Amazon Bedrock Agents. The agent is\nperforming well, but the company wants to improve the agent’s accuracy by providing some specific\nexamples.\nWhich solution meets these requirements?","zh":"某公司正在使用 Amazon Bedrock Agents 为其应用程序创建一个智能体（agent）。该智能体运行良好，但公司希望通过提供一些具体的示例来提升智能体的准确性。\n哪种解决方案满足这些要求？"},"options":[{"key":"A","en":"Modify the advanced prompts for the agent to include the examples.","zh":"修改智能体的高级提示词（advanced prompts），把这些示例加进去。"},{"key":"B","en":"Create a guardrail for the agent that includes the examples.","zh":"为智能体创建护栏（guardrail），并在其中包含这些示例。"},{"key":"C","en":"Use Amazon SageMaker Ground Truth to label the examples.","zh":"使用 Amazon SageMaker Ground Truth 对这些示例进行标注。"},{"key":"D","en":"Run a script in AWS Lambda that adds the examples to the training dataset.","zh":"在 AWS Lambda 中运行脚本，把这些示例添加到训练数据集中。"}],"explanation":{"en":"Embedding specific input–output examples directly into the agent’s advanced prompt (few-shot prompting)\nguides the model toward more accurate behavior without retraining or additional tooling.","zh":"把具体的输入—输出示例直接嵌入智能体的高级提示词中（少样本提示，few-shot prompting），可以引导模型表现得更准确，而无需重新训练，也不需要额外的工具。"},"tip":{"zh":"只想给示例、不想重训模型 → 把示例塞进高级提示词做少样本提示，选 A。","en":""},"keywords":["Bedrock Agents","少样本提示","高级提示词"]},{"id":182,"type":"single","answer":["C"],"topic":"sagemaker","stem":{"en":"Which option is a benefit of using infrastructure as code (IaC) in machine learning operations (MLOps)?","zh":"在机器学习运维（MLOps）中使用基础设施即代码（IaC）有什么好处？"},"options":[{"key":"A","en":"IaC eliminates the need for hyperparameter tuning.","zh":"IaC 消除了超参数调优的需要。"},{"key":"B","en":"IaC always provisions powerful compute instances, contributing to the training of more accurate models.","zh":"IaC 总是预置性能强大的计算实例，有助于训练出更准确的模型。"},{"key":"C","en":"IaC streamlines the deployment of scalable and consistent ML workloads in cloud environments.","zh":"IaC 简化了在云环境中部署可扩展且一致的机器学习工作负载的过程。"},{"key":"D","en":"IaC minimizes overall expenses by deploying only low-cost instances.","zh":"IaC 通过只部署低成本实例来降低总体费用。"}],"explanation":{"en":"By describing infrastructure in code, teams can version, automate, and repeatably provision resources,\nensuring that ML training and inference environments are consistent, scalable, and easy to reproduce\nacross development, testing, and production.","zh":"用代码描述基础设施后，团队可以对资源进行版本控制、自动化配置并重复部署，从而确保机器学习训练和推理环境在开发、测试和生产之间保持一致、可扩展且易于复现。"},"tip":{"zh":"IaC 的价值是「环境一致、可复现、可扩展」，不是省钱也不是调参，选 C。","en":""},"keywords":["基础设施即代码","MLOps","可复现部署"]},{"id":183,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"A company wants to fine-tune a foundation model (FM) to answer questions for a specific domain. The\ncompany wants to use instruction-based fine-tuning.\nHow should the company prepare the training data?","zh":"某公司希望微调一个基础模型（FM）来回答特定领域的问题。该公司希望使用基于指令的微调（instruction-based fine-tuning）。\n公司应如何准备训练数据？"},"options":[{"key":"A","en":"Gather company internal documents and industry-specific materials. Merge the documents and materials into a single file.","zh":"收集公司内部文档和行业专属资料，并把文档和资料合并成单个文件。"},{"key":"B","en":"Collect external company reviews from various online sources. Manually label each review as either positive or negative.","zh":"从各种在线来源收集外部对公司评价，人工把每条评价标注为正面或负面。"},{"key":"C","en":"Create pairs of questions and answers that specifically address topics related to the company's industry domain.","zh":"创建专门针对公司所在行业领域主题的问答对（问题与答案的配对）。"},{"key":"D","en":"Create few-shot prompts to instruct the model to answer only domain knowledge.","zh":"创建少样本提示，指示模型只回答领域知识。"}],"explanation":{"en":"Instruction-based fine-tuning requires a dataset of instruction–response examples. By curating question–\nanswer pairs focused on the company’s domain, you teach the model exactly how to interpret domain-\nspecific queries and generate the correct responses during inference.","zh":"基于指令的微调需要「指令—回答」形式的示例数据集。通过整理聚焦公司所在领域的问答对，你教会模型如何理解领域特定的查询，并在推理时生成正确的回答。"},"tip":{"zh":"指令微调要「指令—回答」配对数据，所以准备行业问答对，选 C。","en":""},"keywords":["指令微调","问答对","训练数据准备"]},{"id":184,"type":"single","answer":["C"],"topic":"security","stem":{"en":"Which ML technique ensures data compliance and privacy when training AI models on AWS?","zh":"在 AWS 上训练 AI 模型时，哪种机器学习技术能确保数据合规与隐私？"},"options":[{"key":"A","en":"Reinforcement learning","zh":"强化学习"},{"key":"B","en":"Transfer learning","zh":"迁移学习"},{"key":"C","en":"Federated learning","zh":"联邦学习"},{"key":"D","en":"Unsupervised learning","zh":"无监督学习"}],"explanation":{"en":"Federated learning lets you train a global model across multiple data holders (for example, different AWS\naccounts or edge devices) without moving raw data to a central location. Each participant trains locally on\nits own private dataset and only shares model updates, preserving data privacy and ensuring compliance.","zh":"联邦学习让你可以在多个数据持有方（例如不同的 AWS 账户或边缘设备）之间训练一个全局模型，而无需把原始数据移动到中心位置。每个参与方在自己的私有数据集上本地训练，只共享模型更新，从而保护数据隐私并确保合规。"},"tip":{"zh":"数据不出本地、只上传模型更新 → 联邦学习，选 C。","en":""},"keywords":["联邦学习","数据隐私","合规"]},{"id":185,"type":"hotspot","answer":[],"topic":"genai","stem":{"en":"A company needs to customize a base model that is hosted on Amazon Bedrock.\nSelect the correct model customization method from the following list of company requirements. Each\nmodel customization method should be selected one or more times.","zh":"某公司需要自定义一个托管在 Amazon Bedrock 上的基础模型。\n请针对下列各项公司需求，从列表中选择正确的模型自定义方法。每种模型自定义方法应被选择一次或多次。"},"options":[],"explanation":{"en":"","zh":""},"tip":{"zh":"考的是 Bedrock 模型自定义方式（微调、持续预训练、蒸馏等）与各项需求的对应关系。","en":""},"keywords":["Bedrock","模型自定义","微调"]},{"id":186,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"A manufacturing company has an application that ingests consumer complaints from publicly available\nsources. The application uses complex hard-coded logic to process the complaints. The company wants to\nscale this logic across markets and product lines.\nWhich advantage do generative AI models offer for this scenario?","zh":"某制造企业有一个应用程序，用于从公开来源获取消费者投诉。该应用程序使用复杂的硬编码逻辑来处理这些投诉。公司希望把这一逻辑扩展到多个市场和产品线。\n针对此场景，生成式 AI 模型能带来什么优势？"},"options":[{"key":"A","en":"Predictability of outputs","zh":"输出的可预测性"},{"key":"B","en":"Adaptability","zh":"适应性"},{"key":"C","en":"Less sensitivity to changes in inputs","zh":"对输入变化的敏感度更低"},{"key":"D","en":"Explainability","zh":"可解释性"}],"explanation":{"en":"Generative AI models can generalize learned patterns to new domains and formats with minimal manual\nreconfiguration. This adaptability lets you extend complaint-processing logic across different markets and\nproduct lines without rewriting complex hard-coded rules.","zh":"生成式 AI 模型能够以极少的人工重新配置，把学到的模式泛化到新的领域和格式。这种适应性让你无需重写复杂的硬编码规则，就能把投诉处理逻辑扩展到不同的市场和产品线。"},"tip":{"zh":"硬编码规则难以跨市场扩展 → 生成式 AI 的优势是适应性，选 B。","en":""},"keywords":["生成式 AI 优势","适应性","泛化"]},{"id":187,"type":"single","answer":["C"],"topic":"general","stem":{"en":"A financial company wants to flag all credit card activity as possibly fraudulent or non-fraudulent based on\ntransaction data.\nWhich type of ML model meets these requirements?","zh":"某金融公司希望根据交易数据，把所有信用卡活动标记为可能欺诈或非欺诈。\n哪种类型的机器学习模型满足这些要求？"},"options":[{"key":"A","en":"Regression","zh":"回归"},{"key":"B","en":"Diffusion","zh":"扩散"},{"key":"C","en":"Binary classification","zh":"二分类"},{"key":"D","en":"Multi-class classification","zh":"多分类"}],"explanation":{"en":"Binary classification models are designed to distinguish between two classes - fraudulent versus non-\nfraudulent transactions - making them the appropriate choice for this use case.","zh":"二分类模型用于区分两个类别——欺诈交易与非欺诈交易——因此是此用例的合适选择。"},"tip":{"zh":"结果只有「欺诈 / 非欺诈」两类 → 二分类模型，选 C。","en":""},"keywords":["二分类","欺诈检测","分类模型"]},{"id":188,"type":"hotspot","answer":[],"topic":"responsible","stem":{"en":"A company is designing a customer service chatbot by using a fine-tuned large language model (LLM).\nThe company wants to ensure that the chatbot uses responsible AI characteristics.\nSelect the correct responsible AI characteristic from the following list for each application design action.\nEach responsible AI characteristic should be selected one time or not at all.","zh":"某公司正在使用经过微调的大型语言模型（LLM）设计一个客服聊天机器人。公司希望确保该聊天机器人具备负责任的 AI 特性。\n请针对每一项应用设计动作，从列表中选择正确的负责任的 AI 特性。每种负责任的 AI 特性应被选择一次或不被选择。"},"options":[],"explanation":{"en":"","zh":""},"tip":{"zh":"考的是公平性、透明度、可解释性等负责任 AI 特性与各项设计动作的对应关系。","en":""},"keywords":["负责任的 AI","公平性","透明度"]},{"id":189,"type":"single","answer":["D"],"topic":"genai","stem":{"en":"A hospital wants to use a generative AI solution with speech-to-text functionality to help improve employee\nskills in dictating clinical notes.\nWhich AWS service meets these requirements?","zh":"某医院希望使用具备语音转文本（speech-to-text）功能的生成式 AI 解决方案，帮助员工提升口述临床记录的技能。\n哪项 AWS 服务满足这些要求？"},"options":[{"key":"A","en":"Amazon Q Developer","zh":"Amazon Q Developer"},{"key":"B","en":"Amazon Polly","zh":"Amazon Polly"},{"key":"C","en":"Amazon Rekognition","zh":"Amazon Rekognition"},{"key":"D","en":"AWS HealthScribe","zh":"AWS HealthScribe"}],"explanation":{"en":"AWS HealthScribe is specifically designed for healthcare workflows, providing accurate speech-to-text\ntranscription of clinical conversations and generating structured clinical notes, meeting the hospital’s need\nto improve employee dictation of clinical documentation.","zh":"AWS HealthScribe 专为医疗保健工作流设计，可对临床对话进行准确的语音转文本转录，并生成结构化的临床记录，满足医院提升员工口述临床文档能力的需求。"},"tip":{"zh":"医疗场景的语音转文本并生成临床记录 → AWS HealthScribe，选 D。","en":""},"keywords":["HealthScribe","语音转文本","临床记录"]},{"id":190,"type":"single","answer":["B"],"topic":"services","stem":{"en":"Which type of AI model makes numeric predictions?","zh":"哪种类型的 AI 模型用于进行数值预测？"},"options":[{"key":"A","en":"Diffusion","zh":"扩散"},{"key":"B","en":"Regression","zh":"回归"},{"key":"C","en":"Transformer","zh":"Transformer"},{"key":"D","en":"Multi-modal","zh":"多模态"}],"explanation":{"en":"Regression models are designed to predict continuous numerical values (for example, forecasting sales\nfigures or estimating house prices), making them the appropriate choice for numeric predictions.","zh":"回归模型用于预测连续的数值（例如预测销售额或估算房价），因此是进行数值预测的合适选择。"},"tip":{"zh":"预测连续数值（销售额、房价）→ 回归模型，选 B。","en":""},"keywords":["回归","数值预测","连续值"]},{"id":191,"type":"hotspot","answer":[],"topic":"sagemaker","stem":{"en":"A company wants to use Amazon SageMaker features for various use cases.\nSelect the correct SageMaker feature from the following list for each use case. Each SageMaker feature\nshould be selected one time or not at all.","zh":"某公司希望针对多种用例使用 Amazon SageMaker 的各项功能。\n请针对每个用例，从列表中选择正确的 SageMaker 功能。每种 SageMaker 功能应被选择一次或不被选择。"},"options":[],"explanation":{"en":"","zh":""},"tip":{"zh":"考的是 SageMaker 各功能（Ground Truth、Clarify、Model Monitor、Feature Store 等）与用例的对应关系。","en":""},"keywords":["SageMaker","功能选型","用例匹配"]},{"id":192,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"What is the purpose of vector embeddings in a large language model (LLM)?","zh":"在大型语言模型（LLM）中，向量嵌入（vector embeddings）的作用是什么？"},"options":[{"key":"A","en":"Splitting text into manageable pieces of data","zh":"把文本切分成便于处理的数据片段"},{"key":"B","en":"Grouping a set of characters to be treated as a single unit","zh":"把一组字符当作单个单元来处理"},{"key":"C","en":"Providing the ability to mathematically compare texts","zh":"提供用数学方式比较文本的能力"},{"key":"D","en":"Providing the count of every word in the input","zh":"统计输入中每个单词的出现次数"}],"explanation":{"en":"Embeddings convert text into high-dimensional vectors that capture semantic relationships, allowing you to\ncompute distances or similarities between pieces of text for tasks like retrieval or clustering.","zh":"嵌入把文本转换成高维向量，从而捕捉语义关系，让你可以计算文本之间的欧氏距离或相似度，用于检索或聚类等任务。"},"tip":{"zh":"嵌入把文本变成向量，才能用数学方式比较语义相似度，选 C。","en":""},"keywords":["嵌入向量","语义相似度","向量化"]},{"id":193,"type":"multi","answer":["B","C"],"topic":"security","stem":{"en":"A company wants to fine-tune a foundation model (FM) by using AWS services. The company needs to\nensure that its data stays private, safe, and secure in the source AWS Region where the data is stored.\nWhich combination of steps will meet these requirements MOST cost-effectively? (Choose two.)","zh":"某公司希望使用 AWS 服务微调一个基础模型（FM）。公司需要确保其数据在存储数据所在的源 AWS 区域内保持私有、安全且受保护。\n哪种步骤组合能以最具成本效益的方式满足这些要求？（选择两项。）"},"options":[{"key":"A","en":"Host the model on premises by using AWS Outposts.","zh":"使用 AWS Outposts 在本地托管该模型。"},{"key":"B","en":"Use the Amazon Bedrock API.","zh":"使用 Amazon Bedrock API。"},{"key":"C","en":"Use AWS PrivateLink and a VPC.","zh":"使用 AWS PrivateLink 和 VPC。"},{"key":"D","en":"Host the Amazon Bedrock API on premises.","zh":"在本地托管 Amazon Bedrock API。"},{"key":"E","en":"Use Amazon CloudWatch logs and metrics.","zh":"使用 Amazon CloudWatch 日志和指标。"}],"explanation":{"en":"Use the Amazon Bedrock API: You’ll call Bedrock’s managed fine-tuning endpoints directly in your AWS\nRegion, so your data never leaves that region.\nUse AWS PrivateLink and a VPC: Front Bedrock API traffic through a VPC endpoint via PrivateLink to\nkeep all network traffic on the AWS backbone and within your account’s private network.","zh":"使用 Amazon Bedrock API：你将直接在自己所在的 AWS 区域调用 Bedrock 托管的微调端点，因此数据永远不会离开该区域。\n使用 AWS PrivateLink 和 VPC：通过 PrivateLink 的 VPC 端点转发 Bedrock API 流量，使所有网络流量都留在 AWS 骨干网上，并处于你账户的私有网络之内。"},"tip":{"zh":"数据不出区域又省钱 → 区域内的 Bedrock API + PrivateLink/VPC 端点，选 B、C。","en":""},"keywords":["PrivateLink","数据驻留","成本效益"]},{"id":194,"type":"single","answer":["B"],"topic":"security","stem":{"en":"A financial company uses AWS to host its generative AI models. The company must generate reports to\nshow adherence to international regulations for handling sensitive customer data.\nWhich AWS service meets these requirements?","zh":"某金融公司使用 AWS 托管其生成式 AI 模型。公司必须生成报告，以证明其符合处理敏感客户数据的国际法规。\n哪项 AWS 服务满足这些要求？"},"options":[{"key":"A","en":"Amazon Macie","zh":"Amazon Macie"},{"key":"B","en":"AWS Artifact","zh":"AWS Artifact"},{"key":"C","en":"AWS Secrets Manager","zh":"AWS Secrets Manager"},{"key":"D","en":"AWS Config","zh":"AWS Config"}],"explanation":{"en":"AWS Artifact provides on-demand access to AWS’s compliance reports and certifications (for example,\nISO, SOC, GDPR), enabling the company to demonstrate its generative AI workloads and data handling\npractices adhere to international regulatory requirements.","zh":"AWS Artifact 可按需提供 AWS 的合规报告和认证（例如 ISO、SOC、GDPR），使该公司能够证明其生成式 AI 工作负载和数据处理实践符合国际监管要求。"},"tip":{"zh":"要下载合规报告与认证文档 → AWS Artifact，选 B。","en":""},"keywords":["AWS Artifact","合规报告","认证"]},{"id":195,"type":"single","answer":["A"],"topic":"responsible","stem":{"en":"A medical company wants to modernize its onsite information processing application. The company wants\nto use generative AI to respond to medical questions from patients.\nWhich AWS service should the company use to ensure responsible AI for the application?","zh":"某医疗公司希望对其本地部署的信息处理应用程序进行现代化改造。公司希望使用生成式 AI 来回答患者的医疗问题。\n公司应使用哪项 AWS 服务来确保该应用程序符合负责任的 AI 要求？"},"options":[{"key":"A","en":"Guardrails for Amazon Bedrock","zh":"Guardrails for Amazon Bedrock"},{"key":"B","en":"Amazon Inspector","zh":"Amazon Inspector"},{"key":"C","en":"Amazon Rekognition","zh":"Amazon Rekognition"},{"key":"D","en":"AWS Trusted Advisor","zh":"AWS Trusted Advisor"}],"explanation":{"en":"Guardrails for Amazon Bedrock let you define and enforce safety, compliance, and bias controls on\ngenerative AI workloads. By embedding these guardrails into your application, you can ensure that patient-\nfacing responses meet medical accuracy, privacy, and regulatory requirements without having to build\ncustom monitoring or filtering pipelines yourself.","zh":"Guardrails for Amazon Bedrock 让你可以为生成式 AI 工作负载定义并强制执行安全、合规和偏见控制。把这些护栏嵌入应用程序后，你就能确保面向患者的回复满足医疗准确性、隐私和监管要求，而无需自行构建定制的监控或过滤管道。"},"tip":{"zh":"要给生成式 AI 加安全、合规、偏见护栏 → Bedrock Guardrails，选 A。","en":""},"keywords":["Guardrails","负责任的 AI","内容安全"]},{"id":196,"type":"single","answer":["A"],"topic":"eval","stem":{"en":"Which metric is used to evaluate the performance of foundation models (FMs) for text summarization\ntasks?","zh":"在文本摘要任务中，使用哪个指标来评估基础模型（FM）的性能？"},"options":[{"key":"A","en":"F1 score","zh":"F1 分数"},{"key":"B","en":"Bilingual Evaluation Understudy (BLEU) score","zh":"双语评估替补（BLEU）分数"},{"key":"C","en":"Accuracy","zh":"准确率"},{"key":"D","en":"Mean squared error (MSE)","zh":"均方误差（MSE）"}],"explanation":{"en":"Text summarization quality is most commonly assessed using ROUGE metrics, which report recall,\nprecision, and an F1-score that balances the two. The ROUGE-F1 (often simply called the F1 score in this\ncontext) measures how well the model’s summary overlaps with reference summaries, making it the\nstandard choice for evaluating foundation models on summarization tasks.","zh":"文本摘要的质量最常用 ROUGE 指标来评估，它报告召回率、精确率以及平衡两者的 F1 分数。ROUGE-F1（在此语境下常简称为 F1 分数）衡量模型生成的摘要与参考摘要的重合程度，因此是评估基础模型摘要任务的标准选择。"},"tip":{"zh":"摘要看 ROUGE，而 ROUGE 的综合指标就是 F1 分数，选 A。","en":""},"keywords":["F1 分数","ROUGE","文本摘要评估"]},{"id":197,"type":"single","answer":["D"],"topic":"eval","stem":{"en":"What is the benefit of fine-tuning a foundation model (FM)?","zh":"微调基础模型（FM）有什么好处？"},"options":[{"key":"A","en":"Fine-tuning reduces the FM's size and complexity and enables slower inference.","zh":"微调会减小基础模型的规模和复杂度，并使推理变慢。"},{"key":"B","en":"Fine-tuning uses specific training data to retrain the FM from scratch to adapt to a specific use case.","zh":"微调使用特定的训练数据从头重新训练基础模型，以适配特定用例。"},{"key":"C","en":"Fine-tuning keeps the FM's knowledge up to date by pre-training the FM on more recent data.","zh":"微调通过在更新的数据上预训练基础模型，使其知识保持最新。"},{"key":"D","en":"Fine-tuning improves the performance of the FM on a specific task by further training the FM on new labeled data.","zh":"微调通过用新的标注数据继续训练基础模型，提升其在特定任务上的表现。"}],"explanation":{"en":"By updating the model’s weights with task-relevant examples, fine-tuning sharpens its understanding of\ndomain-specific language and objectives, yielding higher accuracy and relevance on that particular task.","zh":"通过用与任务相关的示例更新模型权重，微调会强化模型对领域特定语言和目标的理解，从而在该特定任务上获得更高的准确性和相关性。"},"tip":{"zh":"微调 = 用新标注数据继续训练，提升特定任务表现，不是从头训练，选 D。","en":""},"keywords":["微调","标注数据","特定任务"]},{"id":198,"type":"single","answer":["D"],"topic":"genai","stem":{"en":"A company wants to improve its chatbot's responses to match the company's desired tone. The company\nhas 100 examples of high-quality conversations between customer service agents and customers. The\ncompany wants to use this data to incorporate company tone into the chatbot's responses.\nWhich solution meets these requirements?","zh":"某公司希望改善其聊天机器人的回复，使其符合公司期望的语气。公司拥有 100 个客服人员与客户之间的高质量对话示例。公司希望利用这些数据把公司语气融入聊天机器人的回复中。\n哪种解决方案满足这些要求？"},"options":[{"key":"A","en":"Use Amazon Personalize to generate responses.","zh":"使用 Amazon Personalize 生成回复。"},{"key":"B","en":"Create an Amazon SageMaker HyperPod pre-training job.","zh":"创建一个 Amazon SageMaker HyperPod 预训练作业。"},{"key":"C","en":"Host the model by using Amazon SageMaker. Use TensorRT for large language model (LLM) deployment.","zh":"使用 Amazon SageMaker 托管模型，并使用 TensorRT 进行大型语言模型（LLM）部署。"},{"key":"D","en":"Create an Amazon Bedrock fine-tuning job.","zh":"创建一个 Amazon Bedrock 微调作业。"}],"explanation":{"en":"Bedrock’s fine-tuning lets you adapt a foundation model on your own conversation examples—in this case,\nthe 100 high-quality transcripts to instill your company’s tone directly into the model’s response generation.","zh":"Bedrock 的微调功能让你可以用自己的对话示例来适配基础模型——在本例中，就是用这 100 份高质量对话记录，把公司语气直接注入模型的回复生成过程。"},"tip":{"zh":"有 100 条高质量对话、要学公司语气 → Bedrock 微调作业，选 D。","en":""},"keywords":["Bedrock 微调","语气对齐","对话数据"]},{"id":199,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"An ecommerce company is using a chatbot to automate the customer order submission process. The\nchatbot is powered by AI and is available to customers directly from the company's website 24 hours a\nday, 7 days a week.\nWhich option is an AI system input vulnerability that the company needs to resolve before the chatbot is\nmade available?","zh":"某电商公司正在使用聊天机器人自动完成客户下单流程。该聊天机器人由 AI 驱动，客户可以直接从公司网站访问它，全年 7×24 小时可用。\n在聊天机器人上线之前，公司需要解决哪种 AI 系统输入漏洞？"},"options":[{"key":"A","en":"Data leakage","zh":"数据泄露"},{"key":"B","en":"Prompt injection","zh":"提示注入"},{"key":"C","en":"Large language model (LLM) hallucinations","zh":"大型语言模型（LLM）幻觉"},{"key":"D","en":"Concept drift","zh":"概念漂移"}],"explanation":{"en":"Prompt injection is an input-level attack where a user crafts malicious input to override or manipulate the\nchatbot’s instructions or behavior. Addressing this vulnerability by sanitizing and constraining user prompts\nensures the chatbot won’t execute unintended or harmful instructions when it goes live.","zh":"提示注入是一种输入层面的攻击，用户通过构造恶意输入来覆盖或操纵聊天机器人的指令或行为。通过清理和约束用户提示来处理这一漏洞，可以确保聊天机器人在上线后不会执行非预期或有害的指令。"},"tip":{"zh":"用户输入被构造来覆盖指令 → 提示注入，属输入层漏洞，选 B。","en":""},"keywords":["提示注入","输入漏洞","安全防护"]},{"id":200,"type":"single","answer":["B"],"topic":"responsible","stem":{"en":"A social media company wants to prevent users from posting discriminatory content on the company's\napplication. The company wants to use Amazon Bedrock as part of the solution.\nHow can the company use Amazon Bedrock to meet these requirements?","zh":"某社交媒体公司希望阻止用户在其应用程序上发布歧视性内容。公司希望把 Amazon Bedrock 作为解决方案的一部分。\n公司如何利用 Amazon Bedrock 满足这些要求？"},"options":[{"key":"A","en":"Give users the ability to interact based on user preferences.","zh":"让用户能够根据个人偏好进行交互。"},{"key":"B","en":"Block interactions related to predefined topics.","zh":"阻止与预定义话题相关的交互。"},{"key":"C","en":"Restrict user conversations to predefined topics.","zh":"把用户对话限制在预定义话题范围内。"},{"key":"D","en":"Provide a variety of responses to select from for user engagement.","zh":"提供多种可供选择的回复以提升用户互动。"}],"explanation":{"en":"Amazon Bedrock’s built-in content moderation lets you define categories or keywords (e.g., hate speech,\ndiscriminatory language) and automatically block or filter any user inputs or outputs that fall under those\ntopics. By configuring Bedrock’s safety filters with your predefined “disallowed” categories, the application\nwill prevent discriminatory content from ever being posted.","zh":"Amazon Bedrock 内置的内容审核功能让你可以定义类别或关键词（例如仇恨言论、歧视性语言），并自动阻止或过滤落入这些话题的任何用户输入或输出。通过把预定义的“禁止”类别配置到 Bedrock 的安全过滤器中，应用程序就能防止歧视性内容被发布出去。"},"tip":{"zh":"用 Bedrock 护栏屏蔽预定义话题（如歧视言论），直接阻止交互，选 B。","en":""},"keywords":["内容审核","Bedrock 安全过滤","歧视性内容"]},{"id":201,"type":"single","answer":["B"],"topic":"general","stem":{"en":"An education company developed an application named Waftion. The application will give users the ability to enter text or provide a picture\nof a question. The application will respond with a written answer and an explanation of the written answer.\nWhich model type meets these requirements?","zh":"某教育公司正在开发一个应用程序，为学习者提供问答与讲解功能。该应用程序将允许用户输入文字，或提供一张题目图片。应用程序将以书面答案以及对书面答案的讲解作为回复。\n哪种模型类型满足这些要求？"},"options":[{"key":"A","en":"Computer vision model","zh":"计算机视觉模型"},{"key":"B","en":"Large multi-modal language model","zh":"大型多模态语言模型"},{"key":"C","en":"Diffusion model","zh":"扩散模型"},{"key":"D","en":"Text-to-speech model","zh":"文本转语音模型"}],"explanation":{"en":"A large multi-modal language model can natively ingest both text and images as inputs and generate text\noutputs, making it ideal for a system that accepts typed questions or photos of questions and returns\nwritten answers with explanations.","zh":"大型多模态语言模型能够原生地接收文本和图像作为输入，并生成文本输出，因此非常适合这样一个系统：它接受输入的文字问题或题目照片，并返回带有讲解的书面答案。"},"tip":{"zh":"既能读文字又能读图片、还要输出文字 → 大型多模态语言模型，选 B。","en":""},"keywords":["多模态","图文输入","模型选型"]},{"id":202,"type":"single","answer":["D"],"topic":"eval","stem":{"en":"In which stage of the generative AI model lifecycle are tests performed to examine the model's accuracy?","zh":"在生成式 AI 模型生命周期的哪个阶段，会执行测试来考察模型的准确性？"},"options":[{"key":"A","en":"Deployment","zh":"部署"},{"key":"B","en":"Data selection","zh":"数据选择"},{"key":"C","en":"Fine-tuning","zh":"微调"},{"key":"D","en":"Evaluation","zh":"评估"}],"explanation":{"en":"The evaluation stage is when you run tests and benchmarks, such as accuracy, precision, and other\nperformance metrics, to measure how well the generative AI model performs on hold-out or validation data\nbefore moving on to deployment.","zh":"评估阶段就是你运行测试和基准（例如准确率、精确率等性能指标）的阶段，用来衡量生成式 AI 模型在留出集或验证集上的表现，然后再进入部署环节。"},"tip":{"zh":"测准确率、跑基准都在「评估」阶段，在部署之前，选 D。","en":""},"keywords":["模型生命周期","评估阶段","准确率"]},{"id":203,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"Which statement correctly describes embeddings in generative AI?","zh":"关于生成式 AI 中的嵌入（embeddings），哪种说法是正确的？"},"options":[{"key":"A","en":"Embeddings represent data as high-dimensional vectors that capture semantic relationships.","zh":"嵌入把数据表示为能够捕捉语义关系的高维向量。"},{"key":"B","en":"Embeddings is a technique that searches data to find the most helpful information to answer natural language questions.","zh":"嵌入是一种搜索数据、找出最有帮助的信息来回答自然语言问题的技术。"},{"key":"C","en":"Embeddings reduce the hardware requirements of a model by using a less precise data type for the weights and activations.","zh":"嵌入通过对权重和激活值使用精度较低的数据类型，降低模型的硬件需求。"},{"key":"D","en":"Embeddings provide the ability to store and retrieve data for generative AI applications.","zh":"嵌入提供为生成式 AI 应用程序存储和检索数据的能力。"}],"explanation":{"en":"Embeddings map inputs like words, sentences, or documents into continuous vector spaces where\nsemantic similarity corresponds to geometric proximity, enabling models to reason about meaning and\nrelationships mathematically.","zh":"嵌入把单词、句子或文档等输入映射到连续的向量空间中，使语义相似性对应几何上的接近程度，从而让模型能够以数学方式对含义和关系进行推理。"},"tip":{"zh":"嵌入的本质是「高维向量 + 语义距离」，不是搜索也不是存储，选 A。","en":""},"keywords":["嵌入","高维向量","语义关系"]},{"id":204,"type":"single","answer":["A"],"topic":"eval","stem":{"en":"A company wants to add generative AI functionality to its application by integrating a large language model\n(LLM). The responses from the LLM must be as deterministic and as stable as possible.\nWhich solution meets these requirements?","zh":"某公司希望通过集成大型语言模型（LLM）为其应用程序增加生成式 AI 功能。LLM 的回复必须尽可能确定且稳定。\n哪种解决方案满足这些要求？"},"options":[{"key":"A","en":"Configure the application to automatically set the temperature parameter to 0 when submitting the prompt to the LLM.","zh":"配置应用程序，在向 LLM 提交提示词时自动把 temperature 参数设置为 0。"},{"key":"B","en":"Configure the application to automatically add \"make your response deterministic\" at the end of the prompt before submitting the prompt to the LLM.","zh":"配置应用程序，在向 LLM 提交提示词之前自动在提示词末尾加上“让你的回复具有确定性”。"},{"key":"C","en":"Configure the application to automatically add \"make your response deterministic\" at the beginning of the prompt before submitting the prompt to the LLM.","zh":"配置应用程序，在向 LLM 提交提示词之前自动在提示词开头加上“让你的回复具有确定性”。"},{"key":"D","en":"Configure the application to automatically set the temperature parameter to 1 when submitting the prompt to the LLM.","zh":"配置应用程序，在向 LLM 提交提示词时自动把 temperature 参数设置为 1。"}],"explanation":{"en":"The temperature hyperparameter directly controls the randomness of the LLM’s token sampling: setting it\nto 0 forces greedy decoding, yielding the most likely next token every time and thus fully deterministic,\nstable outputs.","zh":"temperature 超参数直接控制 LLM 词元采样（token sampling）的随机性：把它设为 0 会强制采用贪婪解码，每次都选择最可能的下一个词元，从而产生完全确定、稳定的输出。"},"tip":{"zh":"要确定性输出 → temperature 设为 0（贪婪解码），选 A。","en":""},"keywords":["temperature","确定性输出","推理参数"]},{"id":205,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"A company needs to select a generative AI model to build an application. The application must provide\nresponses to users in real time.\nWhich model characteristic should the company consider to meet these requirements?","zh":"某公司需要选择一个生成式 AI 模型来构建应用程序。该应用程序必须实时向用户提供回复。\n公司应考虑哪种模型特性来满足这些要求？"},"options":[{"key":"A","en":"Model complexity","zh":"模型复杂度"},{"key":"B","en":"Innovation speed","zh":"创新速度"},{"key":"C","en":"Inference speed","zh":"推理速度"},{"key":"D","en":"Training time","zh":"训练时间"}],"explanation":{"en":"For real-time applications, the model’s inference speed - ability to generate responses with low latency - is\nthe critical characteristic to ensure users receive answers promptly.","zh":"对于实时应用来说，模型的推理速度——以低延迟生成回复的能力——是确保用户及时获得答案的关键特性。"},"tip":{"zh":"实时响应看的是「推理速度」，训练时间再长也不影响上线体验，选 C。","en":""},"keywords":["推理速度","实时应用","低延迟"]},{"id":206,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"Which term refers to the instructions given to foundation models (FMs) so that the FMs provide a more\naccurate response to a question?","zh":"哪个术语指的是提供给基础模型（FM）的指令，使基础模型能对问题给出更准确的回答？"},"options":[{"key":"A","en":"Prompt","zh":"提示词（prompt）"},{"key":"B","en":"Direction","zh":"方向（direction）"},{"key":"C","en":"Dialog","zh":"对话（dialog）"},{"key":"D","en":"Translation","zh":"翻译（translation）"}],"explanation":{"en":"A prompt is the input instruction or query you provide to a foundation model to guide its response, ensuring\nthe model understands the task and delivers a more accurate answer.","zh":"提示词是你提供给基础模型的输入指令或查询，用于引导模型的回复，确保模型理解任务并给出更准确的答案。"},"tip":{"zh":"给基础模型的输入指令就叫「提示词（prompt）」，选 A。","en":""},"keywords":["提示词","指令","基础模型输入"]},{"id":207,"type":"single","answer":["C"],"topic":"responsible","stem":{"en":"A retail company wants to build an ML model to recommend products to customers. The company wants\nto build the model based on responsible practices.\nWhich practice should the company apply when collecting data to decrease model bias?","zh":"某零售公司希望构建一个机器学习模型，向客户推荐产品。公司希望基于负责任的实践来构建该模型。\n在收集数据以减少模型偏见时，公司应采用哪种做法？"},"options":[{"key":"A","en":"Use data from only customers who match the demographics of the company's overall customer base.","zh":"只使用与公司整体客户群人口统计特征相符的客户数据。"},{"key":"B","en":"Collect data from customers who have a past purchase history.","zh":"从有历史购买记录的客户处收集数据。"},{"key":"C","en":"Ensure that the data is balanced and collected from a diverse group.","zh":"确保数据是平衡的，并且来自多元化的群体。"},{"key":"D","en":"Ensure that the data is from a publicly available dataset.","zh":"确保数据来自公开可用的数据集。"}],"explanation":{"en":"By gathering training data that reflects the full spectrum of your customer population - across\ndemographics, behaviors, and preferences - you reduce skew toward any one subgroup and help the\nrecommender treat all users equitably.","zh":"通过收集能够反映客户群体全貌的训练数据——覆盖不同人口统计特征、行为和偏好——你可以减少对任何单一子群体的偏斜，帮助推荐系统公平地对待所有用户。"},"tip":{"zh":"降偏见靠数据「平衡 + 多元化」，只取单一群体反而加重偏见，选 C。","en":""},"keywords":["模型偏见","数据多样性","负责任 AI"]},{"id":208,"type":"single","answer":["A"],"topic":"eval","stem":{"en":"A company is developing an ML model to predict customer churn.\nWhich evaluation metric will assess the model's performance on a binary classification task such as\npredicting churn?","zh":"某公司正在开发一个机器学习模型来预测客户流失。\n哪个评估指标能评估模型在二分类任务（例如预测流失）上的表现？"},"options":[{"key":"A","en":"F1 score","zh":"F1 分数"},{"key":"B","en":"Mean squared error (MSE)","zh":"均方误差（MSE）"},{"key":"C","en":"R-squared","zh":"R 平方（R-squared）"},{"key":"D","en":"Time used to train the model","zh":"训练模型所用的时间"}],"explanation":{"en":"For binary classification tasks like churn prediction, the F1 score balances precision and recall into a single\nmetric, making it ideal for evaluating how well the model identifies churners without over- or\nunder-predicting.","zh":"对于流失预测这类二分类任务，F1 分数把精确率和召回率平衡为单一指标，因此非常适合评估模型识别流失客户的准确程度，同时避免过度预测或预测不足。"},"tip":{"zh":"二分类看 F1（精确率与召回率的调和平均），MSE/R² 是回归指标，选 A。","en":""},"keywords":["F1 分数","二分类","流失预测"]},{"id":209,"type":"single","answer":["A"],"topic":"eval","stem":{"en":"An AI practitioner is evaluating the performance of an Amazon SageMaker model. The AI practitioner must\nchoose a performance metric. The metric must show the ratio of the number of correctly classified items to\nthe total number of correctly and incorrectly classified items.\nWhich metric meets these requirements?","zh":"某 AI 从业者正在评估 Amazon SageMaker 模型的性能。该从业者必须选择一个性能指标。该指标必须表示「正确分类的条目数」与「正确和错误分类的条目总数」之比。\n哪个指标满足这些要求？"},"options":[{"key":"A","en":"Accuracy","zh":"准确率"},{"key":"B","en":"Precision","zh":"精确率"},{"key":"C","en":"F1 score","zh":"F1 分数"},{"key":"D","en":"Recall","zh":"召回率"}],"explanation":{"en":"Accuracy is defined as the number of correctly classified items (both true positives and true negatives)\ndivided by the total number of items evaluated (the sum of true positives, true negatives, false positives,\nand false negatives), matching exactly the ratio described.","zh":"准确率定义为正确分类的条目数（真阳性和真阴性之和）除以被评估的条目总数（真阳性、真阴性、假阳性和假阴性之和），与题目描述的比值完全吻合。"},"tip":{"zh":"「答对的 / 总题数」= 准确率；精确率看预测为正里对多少，选 A。","en":""},"keywords":["准确率","评估指标","分类"]},{"id":210,"type":"single","answer":["A"],"topic":"sagemaker","stem":{"en":"An ecommerce company receives multiple gigabytes of customer data daily. The company uses the data\nto train an ML model to forecast future product demand. The company needs a solution to perform\ninferences once each day.\nWhich inference type meets these requirements?","zh":"某电商公司每天收到数 GB 的客户数据。公司使用这些数据训练机器学习模型，以预测未来的产品需求。公司需要一个每天执行一次推理的解决方案。\n哪种推理类型满足这些要求？"},"options":[{"key":"A","en":"Batch inference","zh":"批量推理"},{"key":"B","en":"Asynchronous inference","zh":"异步推理"},{"key":"C","en":"Real-time inference","zh":"实时推理"},{"key":"D","en":"Serverless inference","zh":"无服务器推理"}],"explanation":{"en":"Batch inference is designed for high-volume, scheduled predictions: you can point it at the day’s gigabytes\nof data, run a job once daily, and generate all forecasts in one go without needing a persistent endpoint.","zh":"批量推理专为大批量、按计划执行的预测而设计：你可以把它指向当天数 GB 的数据，每天运行一次作业，一次性生成所有预测，而无需常驻端点。"},"tip":{"zh":"每天一次、数据量大 → 批量推理（batch transform），不需要常驻端点，选 A。","en":""},"keywords":["批量推理","定时任务","大批量"]},{"id":211,"type":"single","answer":["A"],"topic":"responsible","stem":{"en":"A company has developed a generative AI model for customer segmentation. The model has been\ndeployed in the company's production environment for a long time. The company recently noticed some\ninconsistency in the model's responses. The company wants to evaluate model bias and drift.\nWhich AWS service or feature meets these requirements?","zh":"某公司为客户细分开发了一个生成式 AI 模型。该模型已在公司生产环境中部署很长时间。公司最近注意到模型的回复出现了一些不一致。公司希望评估模型偏见和漂移。\n哪项 AWS 服务或功能满足这些要求？"},"options":[{"key":"A","en":"Amazon SageMaker Model Monitor","zh":"Amazon SageMaker Model Monitor"},{"key":"B","en":"Amazon SageMaker Clarify","zh":"Amazon SageMaker Clarify"},{"key":"C","en":"Amazon SageMaker Model Cards","zh":"Amazon SageMaker Model Cards"},{"key":"D","en":"Amazon SageMaker Feature Store","zh":"Amazon SageMaker Feature Store"}],"explanation":{"en":"SageMaker Model Monitor continuously collects inference and ground-truth data to automatically detect\ndata drift, concept drift, and bias shifts in production models. By configuring baseline metrics and\nthresholds, the company can track inconsistencies in responses over time and receive alerts whenever\nbias or drift exceed acceptable limits.","zh":"SageMaker Model Monitor 会持续收集推理数据和真实标签数据，自动检测生产模型中的数据漂移、概念漂移和偏见偏移。通过配置基线指标和阈值，公司可以跟踪回复随时间出现的不一致，并在偏见或漂移超出可接受范围时收到告警。"},"tip":{"zh":"生产环境持续监控漂移和偏见 → Model Monitor；Clarify 是训练期检测偏见，选 A。","en":""},"keywords":["Model Monitor","模型漂移","偏见监控"]},{"id":212,"type":"single","answer":["A"],"topic":"security","stem":{"en":"A company has signed up for Amazon Bedrock access to build applications. The company wants to restrict\nemployee access to specific models available on Amazon Bedrock.\nWhich solution meets these requirements?","zh":"某公司已注册 Amazon Bedrock 访问权限以构建应用程序。公司希望限制员工访问 Amazon Bedrock 上可用的特定模型。\n哪种解决方案满足这些要求？"},"options":[{"key":"A","en":"Use AWS Identity and Access Management (IAM) policies to restrict model access.","zh":"使用 AWS Identity and Access Management (IAM) 策略来限制模型访问。"},{"key":"B","en":"Use AWS Security Token Service (AWS STS) to generate temporary credentials for model use.","zh":"使用 AWS Security Token Service (AWS STS) 生成用于模型的临时凭证。"},{"key":"C","en":"Use AWS Identity and Access Management (IAM) service roles to restrict model subscription.","zh":"使用 AWS Identity and Access Management (IAM) 服务角色来限制模型订阅。"},{"key":"D","en":"Use Amazon Inspector to monitor model access.","zh":"使用 Amazon Inspector 监控模型访问。"}],"explanation":{"en":"With IAM policies you can grant or deny Bedrock API actions scoped to specific model ARNs, ensuring\nemployees can only invoke the exact models you authorize.","zh":"借助 IAM 策略，你可以授予或拒绝针对特定模型 ARN 的 Bedrock API 操作，确保员工只能调用你授权的那些模型。"},"tip":{"zh":"限制谁能用哪个模型 → IAM 策略按模型 ARN 授权，选 A。","en":""},"keywords":["IAM 策略","模型访问控制","Bedrock"]},{"id":213,"type":"single","answer":["A"],"topic":"data","stem":{"en":"Which ML technique uses training data that is labeled with the correct output values?","zh":"哪种机器学习技术使用带有正确输出值标签的训练数据？"},"options":[{"key":"A","en":"Supervised learning","zh":"监督式学习"},{"key":"B","en":"Unsupervised learning","zh":"无监督学习"},{"key":"C","en":"Reinforcement learning","zh":"强化学习"},{"key":"D","en":"Transfer learning","zh":"迁移学习"}],"explanation":{"en":"Supervised learning trains models on datasets where each example includes both input features and the\ncorrect output label, allowing the algorithm to learn the mapping from inputs to known targets.","zh":"监督式学习在数据集上训练模型，其中每个样本既包含输入特征，也包含正确的输出标签，使算法能够学习从输入到已知目标的映射关系。"},"tip":{"zh":"训练数据带标签 → 监督式学习；无监督没有标签，选 A。","en":""},"keywords":["监督式学习","标注数据","标签"]},{"id":214,"type":"single","answer":["B"],"topic":"eval","stem":{"en":"Which large language model (LLM) parameter controls the number of possible next words or tokens\nconsidered at each step of the text generation process?","zh":"哪个大型语言模型（LLM）参数控制在文本生成过程的每一步中考虑的可能的下一个单词或词元的数量？"},"options":[{"key":"A","en":"Maximum tokens","zh":"最大词元数（Maximum tokens）"},{"key":"B","en":"Top K","zh":"Top K"},{"key":"C","en":"Temperature","zh":"Temperature"},{"key":"D","en":"Batch size","zh":"批大小（Batch size）"}],"explanation":{"en":"The Top K parameter limits token sampling at each generation step to the K most probable next tokens. By\nchoosing how many of the highest-probability candidates to consider, Top K directly controls the breadth of\noptions the model evaluates when generating each token.","zh":"Top K 参数把每个生成步骤的词元采样限制在 K 个最可能的下一个词元内。通过选择要考虑多少个概率最高的候选，Top K 直接控制模型在生成每个词元时评估的选项范围。"},"tip":{"zh":"控制「每步只从最可能的 K 个词里挑」→ Top K；temperature 调的是概率分布形状，选 B。","en":""},"keywords":["Top K","词元采样","生成参数"]},{"id":215,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"A company is making a chatbot. The chatbot uses Amazon Lex and Amazon OpenSearch Service. The\nchatbot uses the company's private data to answer questions. The company needs to convert the data into\na vector representation before storing the data in a database.\nWhich type of foundation model (FM) meets these requirements?","zh":"某公司正在开发一个聊天机器人。该聊天机器人使用 Amazon Lex 和 Amazon OpenSearch Service。聊天机器人使用公司的私有数据来回答问题。公司需要先把数据转换为向量表示，然后再存储到数据库中。\n哪种类型的基础模型（FM）满足这些要求？"},"options":[{"key":"A","en":"Text completion model","zh":"文本补全模型"},{"key":"B","en":"Instruction following model","zh":"指令遵循模型"},{"key":"C","en":"Text embeddings model","zh":"文本嵌入模型"},{"key":"D","en":"Image generation model","zh":"图像生成模型"}],"explanation":{"en":"Text embeddings models transform input text into high-dimensional vector representations, making them\nideal for storing and retrieving your private data in a vector database for the chatbot.","zh":"文本嵌入模型把输入文本转换成高维向量表示，因此非常适合把聊天机器人的私有数据存储到向量数据库并从中检索。"},"tip":{"zh":"要把文本转成向量再存向量库 → 文本嵌入模型，选 C。","en":""},"keywords":["文本嵌入模型","向量数据库","语义检索"]},{"id":216,"type":"single","answer":["D"],"topic":"genai","stem":{"en":"A company wants to use a large language model (LLM) to generate product descriptions. The company\nwants to give the model example descriptions that follow a format.\nWhich prompt engineering technique will generate descriptions that match the format?","zh":"某公司希望使用大型语言模型（LLM）生成产品描述。公司希望向模型提供一些遵循特定格式的示例描述。\n哪种提示工程技术能生成符合该格式的描述？"},"options":[{"key":"A","en":"Zero-shot prompting","zh":"零样本提示"},{"key":"B","en":"Chain-of-thought prompting","zh":"思维链提示"},{"key":"C","en":"One-shot prompting","zh":"单样本提示"},{"key":"D","en":"Few-shot prompting","zh":"少样本提示"}],"explanation":{"en":"Few-shot prompting provides the model with several example product descriptions that follow your desired\nformat, enabling it to learn the pattern and generate new descriptions in the same style without further\ntraining.","zh":"少样本提示向模型提供若干符合你期望格式的示例产品描述，使模型能够学习其中的模式，并在无需额外训练的情况下生成同样风格的新描述。"},"tip":{"zh":"给多个示例让它照着写 → 少样本提示（few-shot），选 D。","en":""},"keywords":["少样本提示","示例","格式对齐"]},{"id":217,"type":"single","answer":["B"],"topic":"security","stem":{"en":"A bank is fine-tuning a large language model (LLM) on Amazon Bedrock to assist customers with\nquestions about their loans. The bank wants to ensure that the model does not reveal any private\ncustomer data.\nWhich solution meets these requirements?","zh":"某银行正在 Amazon Bedrock 上微调大型语言模型（LLM），以帮助客户解答贷款相关问题。银行希望确保该模型不会泄露任何客户隐私数据。\n哪种解决方案满足这些要求？"},"options":[{"key":"A","en":"Use Amazon Bedrock Guardrails.","zh":"使用 Amazon Bedrock Guardrails。"},{"key":"B","en":"Remove personally identifiable information (PII) from the customer data before fine-tuning the LLM.","zh":"在微调 LLM 之前，从客户数据中移除个人身份信息（PII）。"},{"key":"C","en":"Increase the Top-K parameter of the LLM.","zh":"提高 LLM 的 Top-K 参数。"},{"key":"D","en":"Store customer data in Amazon S3. Encrypt the data before fine-tuning the LLM.","zh":"把客户数据存储在 Amazon S3 中，并在微调 LLM 之前对数据加密。"}],"explanation":{"en":"Preprocessing your fine-tuning dataset to strip out names, account numbers, and other PII prevents the\nmodel from ever ingesting - or later regurgitating - private customer information. This data sanitization step\nis the most reliable way to guarantee that sensitive details aren’t embedded into the model.","zh":"对微调数据集进行预处理，剔除姓名、账号等 PII，可以防止模型接触到——并在之后复述出——客户隐私信息。这一数据清理步骤是确保敏感细节不会被嵌入模型的最可靠方式。"},"tip":{"zh":"防模型泄露隐私 → 微调前就把 PII 删掉；加密防的是存储泄露，不是模型输出，选 B。","en":""},"keywords":["PII 脱敏","微调数据","数据隐私"]},{"id":218,"type":"single","answer":["D"],"topic":"genai","stem":{"en":"A grocery store wants to create a chatbot to help customers find products in the store. The chatbot must\ncheck the inventory in real time and provide the product location in the store.\nWhich prompt engineering technique should the store use to build the chatbot?","zh":"某杂货店希望创建一个聊天机器人，帮助顾客在店内找到商品。该聊天机器人必须实时查询库存，并提供商品在店内的位置。\n该店应使用哪种提示工程技术来构建该聊天机器人？"},"options":[{"key":"A","en":"Zero-shot prompting","zh":"零样本提示"},{"key":"B","en":"Few-shot prompting","zh":"少样本提示"},{"key":"C","en":"Least-to-most prompting","zh":"由少到多提示（Least-to-most prompting）"},{"key":"D","en":"Reasoning and acting (ReAct) prompting","zh":"推理与行动（ReAct）提示"}],"explanation":{"en":"ReAct prompting interleaves the model’s chain-of-thought reasoning with explicit “actions” (such as calling\nyour real-time inventory API), then uses the API response to inform its final answer. By structuring your\nprompts to have the LLM think, choose the “CheckInventory” action with the product name, receive the live\nlocation data, and then respond to the user, you seamlessly integrate real-time lookups and precise\nproduct locations into the chatbot’s replies.","zh":"ReAct 提示把模型的思维链推理与明确的“动作”（例如调用你的实时库存 API）交织在一起，然后利用 API 的响应来形成最终答案。通过设计提示，让 LLM 先思考，再用商品名称选择“CheckInventory”动作，接收实时的位置数据，然后回复用户，你就能把实时查询和精确的商品位置无缝集成到聊天机器人的回复中。"},"tip":{"zh":"需要先推理再调用外部工具（查库存 API）→ ReAct 提示，选 D。","en":""},"keywords":["ReAct","工具调用","实时查询"]},{"id":219,"type":"single","answer":["B"],"topic":"security","stem":{"en":"A company uses a third-party model on Amazon Bedrock to analyze confidential documents. The\ncompany is concerned about data privacy.\nWhich statement describes how Amazon Bedrock protects data privacy?","zh":"某公司在 Amazon Bedrock 上使用第三方模型来分析机密文档。公司担心数据隐私问题。\n哪种说法描述了 Amazon Bedrock 如何保护数据隐私？"},"options":[{"key":"A","en":"User inputs and model outputs are anonymized and shared with third-party model providers.","zh":"用户输入和模型输出会经过匿名化处理，并与第三方模型提供商共享。"},{"key":"B","en":"User inputs and model outputs are not shared with any third-party model providers.","zh":"用户输入和模型输出不会与任何第三方模型提供商共享。"},{"key":"C","en":"User inputs are kept confidential, but model outputs are shared with third-party model providers.","zh":"用户输入会保密，但模型输出会与第三方模型提供商共享。"},{"key":"D","en":"User inputs and model outputs are redacted before the inputs and outputs are shared with third-party model providers.","zh":"在与第三方模型提供商共享之前，用户输入和模型输出会先被脱敏处理。"}],"explanation":{"en":"Amazon Bedrock processes your data entirely within AWS’s secure environment and does not forward\nyour inputs or the generated outputs back to the model vendor, ensuring that your confidential documents\nremain private.","zh":"Amazon Bedrock 完全在 AWS 的安全环境中处理你的数据，不会把你的输入或生成的输出转发给模型供应商，从而确保你的机密文档保持私密。"},"tip":{"zh":"Bedrock 的输入输出都不回传给模型供应商，选 B。","en":""},"keywords":["Bedrock 数据隐私","第三方模型","机密数据"]},{"id":220,"type":"single","answer":["C"],"topic":"services","stem":{"en":"An animation company wants to provide subtitles for its content.\nWhich AWS service meets this requirement?","zh":"某动画公司希望为其内容提供字幕。\n哪项 AWS 服务满足这一要求？"},"options":[{"key":"A","en":"Amazon Comprehend","zh":"Amazon Comprehend"},{"key":"B","en":"Amazon Polly","zh":"Amazon Polly"},{"key":"C","en":"Amazon Transcribe","zh":"Amazon Transcribe"},{"key":"D","en":"Amazon Translate","zh":"Amazon Translate"}],"explanation":{"en":"Amazon Transcribe converts spoken audio into accurate, time-stamped text transcripts, making it the ideal\nservice for generating subtitles from your animation audio tracks.","zh":"Amazon Transcribe 把语音音频转换成准确、带时间戳的文本转录，因此是根据动画音轨生成字幕的理想服务。"},"tip":{"zh":"音频转文字做字幕 → Transcribe；Polly 是文字转语音，别选反，选 C。","en":""},"keywords":["Transcribe","语音转文本","字幕"]},{"id":221,"type":"single","answer":["B"],"topic":"services","stem":{"en":"An ecommerce company wants to group customers based on their purchase history and preferences to\npersonalize the user experience of the company's application.\nWhich ML technique should the company use?","zh":"某电商公司希望根据客户的购买历史和偏好对客户进行分组，以实现应用程序用户体验的个性化。\n该公司应使用哪种机器学习技术？"},"options":[{"key":"A","en":"Classification","zh":"分类"},{"key":"B","en":"Clustering","zh":"聚类"},{"key":"C","en":"Regression","zh":"回归"},{"key":"D","en":"Content generation","zh":"内容生成"}],"explanation":{"en":"Clustering is an unsupervised learning technique that automatically groups data points - in this case,\ncustomers with similar purchase histories and preferences - into segments without needing predefined\nlabels, enabling personalized experiences.","zh":"聚类是一种无监督学习技术，可以自动把数据点——在本例中是购买历史和偏好相似的客户——划分为若干细分群体，而无需预定义标签，从而实现个性化体验。"},"tip":{"zh":"没有预设标签、只想把相似客户自动分组 → 聚类，选 B。","en":""},"keywords":["聚类","无监督学习","客户细分"]},{"id":222,"type":"single","answer":["C"],"topic":"security","stem":{"en":"A company wants to control employee access to publicly available foundation models (FMs).\nWhich solution meets these requirements?","zh":"某公司希望控制员工对公开可用的基础模型（FM）的访问。\n哪种解决方案满足这些要求？"},"options":[{"key":"A","en":"Analyze cost and usage reports in AWS Cost Explorer.","zh":"在 AWS Cost Explorer 中分析成本和使用情况报告。"},{"key":"B","en":"Download AWS security and compliance documents from AWS Artifact.","zh":"从 AWS Artifact 下载 AWS 安全与合规文档。"},{"key":"C","en":"Configure Amazon SageMaker JumpStart to restrict discoverable FMs.","zh":"配置 Amazon SageMaker JumpStart 以限制可发现的基础模型。"},{"key":"D","en":"Build a hybrid search solution by using Amazon OpenSearch Service.","zh":"使用 Amazon OpenSearch Service 构建混合搜索解决方案。"}],"explanation":{"en":"SageMaker JumpStart lets you curate which publicly available foundation models appear in your account’s\nmodel catalog. By using JumpStart’s model catalog settings (in combination with IAM), you can prevent\nemployees from discovering or deploying any FMs you haven’t explicitly allowed.","zh":"SageMaker JumpStart 让你可以管理账户模型目录中显示哪些公开可用的基础模型。通过使用 JumpStart 的模型目录设置（结合 IAM），你可以阻止员工发现或部署任何你未明确允许的基础模型。"},"tip":{"zh":"要限制员工能用哪些公开基础模型 → JumpStart 模型目录 + IAM，选 C。","en":""},"keywords":["JumpStart","模型目录","访问控制"]},{"id":223,"type":"single","answer":["B"],"topic":"eval","stem":{"en":"A company has set up a translation tool to help its customer service team handle issues from customers\naround the world. The company wants to evaluate the performance of the translation tool. The company\nsets up a parallel data process that compares the responses from the tool to responses from actual\nhumans. Both sets of responses are generated on the same set of documents.\nWhich strategy should the company use to evaluate the translation tool?","zh":"某公司搭建了一个翻译工具，帮助客服团队处理来自世界各地客户的问题。公司希望评估该翻译工具的性能。公司建立了一个并行数据流程，把该工具的回复与真实人工的回复进行对比。两组回复都是基于同一批文档生成的。\n公司应使用哪种策略来评估该翻译工具？"},"options":[{"key":"A","en":"Use the Bilingual Evaluation Understudy (BLEU) score to estimate the absolute translation quality of the two methods.","zh":"使用双语评估替补（BLEU）分数来估计这两种方法的绝对翻译质量。"},{"key":"B","en":"Use the Bilingual Evaluation Understudy (BLEU) score to estimate the relative translation quality of the two methods.","zh":"使用双语评估替补（BLEU）分数来估计这两种方法的相对翻译质量。"},{"key":"C","en":"Use the BERTScore to estimate the absolute translation quality of the two methods.","zh":"使用 BERTScore 来估计这两种方法的绝对翻译质量。"},{"key":"D","en":"Use the BERTScore to estimate the relative translation quality of the two methods.","zh":"使用 BERTScore 来估计这两种方法的相对翻译质量。"}],"explanation":{"en":"BLEU measures n-gram overlap between a candidate translation and one or more reference translations.\nWhen you apply it to both the tool’s outputs and the human outputs on the same source documents, you\nget comparable scores that let you directly assess which approach yields better translations.","zh":"BLEU 衡量候选译文与一个或多个参考译文之间的 n-gram 重合度。当你把同一批源文档上的工具输出和人工输出都用它来评分时，就能得到可比较的分数，从而直接判断哪种方法给出的译文更好。"},"tip":{"zh":"两套译文在同一批文档上对比 → BLEU 做「相对」质量比较，选 B。","en":""},"keywords":["BLEU","翻译质量评估","相对比较"]},{"id":224,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"An AI practitioner wants to generate more diverse and more creative outputs from a large language model\n(LLM).\nHow should the AI practitioner adjust the inference parameter?","zh":"某 AI 从业者希望让大型语言模型（LLM）产生更多样、更有创意的输出。\n该从业者应如何调整推理参数？"},"options":[{"key":"A","en":"Increase the temperature value.","zh":"提高 temperature 值。"},{"key":"B","en":"Decrease the Top K value.","zh":"降低 Top K 值。"},{"key":"C","en":"Increase the response length.","zh":"增加回复长度。"},{"key":"D","en":"Decrease the prompt length.","zh":"缩短提示词长度。"}],"explanation":{"en":"Raising the temperature softens the model’s probability distribution, increasing the chance of sampling\nless-likely tokens and thus producing more varied and creative responses.","zh":"提高 temperature 会使模型的概率分布变得更平缓，增加采样到低概率词元的机会，从而产生更多样、更有创意的回复。"},"tip":{"zh":"要更发散更有创意 → 调高 temperature；调低 Top K 反而更保守，选 A。","en":""},"keywords":["temperature","多样性","创造性输出"]},{"id":225,"type":"single","answer":["A"],"topic":"sagemaker","stem":{"en":"A company has developed custom computer vision models. The company needs a user-friendly interface\nfor data labeling to minimize model mistakes on new real-world data.\nWhich AWS service, feature, or tool meets these requirements?","zh":"某公司开发了定制的计算机视觉模型。公司需要一个易于使用的数据标注界面，以尽量减少模型在新的真实世界数据上的错误。\n哪项 AWS 服务、功能或工具满足这些要求？"},"options":[{"key":"A","en":"Amazon SageMaker Ground Truth","zh":"Amazon SageMaker Ground Truth"},{"key":"B","en":"Amazon SageMaker Canvas","zh":"Amazon SageMaker Canvas"},{"key":"C","en":"Amazon Bedrock playground","zh":"Amazon Bedrock playground"},{"key":"D","en":"Amazon Bedrock Agents","zh":"Amazon Bedrock Agents"}],"explanation":{"en":"SageMaker Ground Truth provides a built-in, easy-to-use labeling console with workflows and quality\ncontrols specifically for computer vision tasks, enabling you to efficiently generate high-quality labeled data\nand reduce model errors on real-world images.","zh":"SageMaker Ground Truth 提供内置、易用的标注控制台，并针对计算机视觉任务提供专门的工作流和质量控制，让你能够高效地生成高质量的标注数据，减少模型在真实图像上的错误。"},"tip":{"zh":"要数据标注界面 → SageMaker Ground Truth，选 A。","en":""},"keywords":["Ground Truth","数据标注","计算机视觉"]},{"id":226,"type":"multi","answer":["A","E"],"topic":"responsible","stem":{"en":"A company is integrating AI into its employee recruitment and hiring solution. The company wants to\nmitigate bias risks and ensure responsible AI practices while prioritizing equitable hiring decisions.\nWhich core dimensions of responsible AI should the company consider? (Choose two.)","zh":"某公司正在把 AI 集成到其员工招聘与录用解决方案中。公司希望降低偏见风险、确保负责任的 AI 实践，同时优先保证公平的招聘决策。\n公司应考虑负责任的 AI 的哪些核心维度？（选择两项。）"},"options":[{"key":"A","en":"Fairness","zh":"公平性"},{"key":"B","en":"Tolerance","zh":"容忍度"},{"key":"C","en":"Flexibility","zh":"灵活性"},{"key":"D","en":"Open source","zh":"开源"},{"key":"E","en":"Transparency","zh":"透明度"}],"explanation":{"en":"Fairness - Ensuring equitable outcomes across all demographic groups helps mitigate bias risks in hiring\ndecisions.\nTransparency - Providing clear explanations of how the AI makes decisions builds trust and allows auditing\nfor bias.","zh":"公平性——确保所有人口统计群体都能获得公平的结果，有助于降低招聘决策中的偏见风险。\n透明度——清晰说明 AI 如何做出决策，可以建立信任，并允许对偏见进行审计。"},"tip":{"zh":"招聘防偏见的两大维度 = 公平性 + 透明度，其余是干扰项，选 A、E。","en":""},"keywords":["公平性","透明度","负责任的 AI"]},{"id":227,"type":"single","answer":["C"],"topic":"eval","stem":{"en":"A financial company has deployed an ML model to predict customer churn. The model has been running in\nproduction for 1 week. The company wants to evaluate how accurately the model predicts churn compared\nto actual customer behavior.\nWhich metric meets these requirements?","zh":"某金融公司已部署一个机器学习模型来预测客户流失。该模型已在生产环境运行 1 周。公司希望评估模型预测流失与客户实际行为相比的准确程度。\n哪个指标满足这些要求？"},"options":[{"key":"A","en":"Root mean squared error (RMSE)","zh":"均方根误差（RMSE）"},{"key":"B","en":"Return on investment (ROI)","zh":"投资回报率（ROI）"},{"key":"C","en":"F1 score","zh":"F1 分数"},{"key":"D","en":"Bilingual Evaluation Understudy (BLEU) score","zh":"双语评估替补（BLEU）分数"}],"explanation":{"en":"The F1 score combines precision (how many predicted churners actually churned) and recall (how many\nactual churners were correctly identified) into a single metric, making it ideal for measuring your model’s\naccuracy on the binary churn\nprediction task.\n‐","zh":"F1 分数把精确率（预测会流失的客户中有多少真的流失了）和召回率（实际流失的客户中有多少被正确识别出来）合并为单一指标，因此非常适合衡量模型在二分类流失预测任务上的准确程度。"},"tip":{"zh":"二分类（流失/不流失）评估用 F1；RMSE 属回归、BLEU 属翻译，选 C。","en":""},"keywords":["F1 分数","流失预测","二分类"]},{"id":228,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"A company has a generative AI application that uses a pre-trained foundation model (FM) on Amazon\nBedrock. The company wants the FM to include more context by using company information.\nWhich solution meets these requirements MOST cost-effectively?","zh":"某公司有一个生成式 AI 应用程序，使用 Amazon Bedrock 上的预训练基础模型（FM）。公司希望利用公司信息让基础模型包含更多上下文。\n哪种解决方案以最具成本效益的方式满足这些要求？"},"options":[{"key":"A","en":"Use Amazon Bedrock Knowledge Bases.","zh":"使用 Amazon Bedrock Knowledge Bases。"},{"key":"B","en":"Choose a different FM on Amazon Bedrock.","zh":"在 Amazon Bedrock 上选择另一个基础模型。"},{"key":"C","en":"Use Amazon Bedrock Agents.","zh":"使用 Amazon Bedrock Agents。"},{"key":"D","en":"Deploy a custom model on Amazon Bedrock.","zh":"在 Amazon Bedrock 上部署自定义模型。"}],"explanation":{"en":"Amazon Bedrock Knowledge Bases let you index and retrieve your company’s documents at inference\ntime, injecting relevant context into the pre-trained FM’s prompts without the cost or complexity of\nre-training or fine-tuning a custom model. This retrieval-augmented approach delivers up-to-date,\ndomain-specific information in responses while keeping costs low.","zh":"Amazon Bedrock Knowledge Bases 让你可以在推理时对公司的文档建立索引并检索，把相关上下文注入预训练基础模型的提示词中，而无需承担重新训练或微调自定义模型的成本和复杂性。这种检索增强的方法能在回复中提供最新的领域专属信息，同时保持较低成本。"},"tip":{"zh":"要补公司私有知识又不想微调 → Knowledge Bases 做 RAG，最省钱，选 A。","en":""},"keywords":["Knowledge Bases","RAG","成本效益"]},{"id":229,"type":"hotspot","answer":[],"topic":"sagemaker","stem":{"en":"A company is using Amazon SageMaker to develop AI models.\nSelect the correct SageMaker feature or resource from the following list for each step in the AI model\nlifecycle workflow. Each SageMaker feature or resource should be selected one time or not at all.","zh":"某公司正在使用 Amazon SageMaker 开发 AI 模型。\n请针对 AI 模型生命周期工作流中的每个步骤，从列表中选择正确的 SageMaker 功能或资源。每种 SageMaker 功能或资源应被选择一次或不被选择。"},"options":[],"explanation":{"en":"","zh":""},"tip":{"zh":"考的是 SageMaker 各功能与模型生命周期各步骤（数据处理、训练、部署、监控）的对应关系。","en":""},"keywords":["SageMaker","生命周期","功能匹配"]},{"id":230,"type":"single","answer":["B"],"topic":"data","stem":{"en":"A food service company wants to collect a dataset to predict customer food preferences. The company\nwants to ensure that the food preferences of all demographics are included in the data.\nWhich dataset characteristic does this scenario present?","zh":"某餐饮服务公司希望收集一个数据集来预测客户的饮食偏好。公司希望确保所有人口统计群体的饮食偏好都包含在数据中。\n此场景体现的是数据集的哪种特性？"},"options":[{"key":"A","en":"Accuracy","zh":"准确性"},{"key":"B","en":"Diversity","zh":"多样性"},{"key":"C","en":"Recency bias","zh":"近因偏差"},{"key":"D","en":"Reliability","zh":"可靠性"}],"explanation":{"en":"Ensuring representation of all demographic groups addresses the dataset’s diversity, so the model learns\nfrom a wide range of customer preferences.","zh":"确保所有人口统计群体都有代表性，解决的是数据集的多样性问题，这样模型才能从广泛的客户偏好中学习。"},"tip":{"zh":"覆盖所有人群、避免单一偏斜 → 数据集多样性（diversity），选 B。","en":""},"keywords":["数据多样性","数据集特性","代表性"]},{"id":231,"type":"single","answer":["A"],"topic":"eval","stem":{"en":"A company wants to create a chatbot that answers questions about human resources policies. The\ncompany is using a large language model (LLM) and has a large digital documentation base.\nWhich technique should the company use to optimize the generated responses?","zh":"某公司希望创建一个聊天机器人来回答有关人力资源政策的问题。公司正在使用大型语言模型（LLM），并且拥有大量数字文档库。\n公司应使用哪种技术来优化生成的回复？"},"options":[{"key":"A","en":"Use Retrieval Augmented Generation (RAG).","zh":"使用检索增强生成（RAG）。"},{"key":"B","en":"Use few-shot prompting.","zh":"使用少样本提示。"},{"key":"C","en":"Set the temperature to 1.","zh":"把 temperature 设置为 1。"},{"key":"D","en":"Decrease the token size.","zh":"减小词元（token）长度。"}],"explanation":{"en":"RAG lets the chatbot pull in precise, up-to-date passages from your HR documentation at inference time,\ngrounding its answers in the actual policy text and ensuring accuracy without overloading the LLM’s\ncontext window.","zh":"RAG 让聊天机器人在推理时从 HR 文档中提取精确、最新的段落，把答案建立在真实的政策原文之上，从而在不过度占用 LLM 上下文窗口的情况下确保准确性。"},"tip":{"zh":"有大文档库要答准 → RAG 检索原文再生成，避免幻觉，选 A。","en":""},"keywords":["RAG","知识库问答","事实接地"]},{"id":232,"type":"single","answer":["D"],"topic":"eval","stem":{"en":"An education company is building a chatbot whose target audience is teenagers. The company is training\na custom large language model (LLM). The company wants the chatbot to speak in the target audience's\nlanguage style by using creative spelling and shortened words.\nWhich metric will assess the LLM's performance?","zh":"某教育公司正在构建一个目标受众为青少年的聊天机器人。公司正在训练一个自定义的大型语言模型（LLM）。公司希望该聊天机器人使用目标受众的语言风格说话，即使用创意拼写和缩写词。\n哪个指标能评估该 LLM 的性能？"},"options":[{"key":"A","en":"F1 score","zh":"F1 分数"},{"key":"B","en":"BERTScore","zh":"BERTScore"},{"key":"C","en":"Recall-Oriented Understudy for Gisting Evaluation (ROUGE)","zh":"面向摘要的召回率评估替补（ROUGE）"},{"key":"D","en":"Bilingual Evaluation Understudy (BLEU) score","zh":"双语评估替补（BLEU）分数"}],"explanation":{"en":"BLEU evaluates surface-level n-gram overlap between the LLM’s outputs and reference examples—in this\ncase, targets written in creative spelling and shorthand, making it well suited to measure how closely the\nmodel’s style matches the teenager-oriented language.","zh":"BLEU 评估 LLM 输出与参考示例之间表层的 n-gram 重合度——在本例中，参考目标是用创意拼写和缩写写成的——因此非常适合衡量模型风格与青少年化语言风格的接近程度。"},"tip":{"zh":"考察用词表面风格是否一致 → BLEU（n-gram 重合），选 D。","en":""},"keywords":["BLEU","风格匹配","n-gram 重合"]},{"id":233,"type":"single","answer":["B"],"topic":"general","stem":{"en":"A customer service team is developing an application to analyze customer feedback and automatically\nclassify the feedback into different categories. The categories include product quality, customer service,\nand delivery experience.\nWhich AI concept does this scenario present?","zh":"某客服团队正在开发一个应用程序，用于分析客户反馈并自动把反馈归入不同类别。这些类别包括产品质量、客户服务和配送体验。\n此场景体现的是哪种 AI 概念？"},"options":[{"key":"A","en":"Computer vision","zh":"计算机视觉"},{"key":"B","en":"Natural language processing (NLP)","zh":"自然语言处理（NLP）"},{"key":"C","en":"Recommendation systems","zh":"推荐系统"},{"key":"D","en":"Fraud detection","zh":"欺诈检测"}],"explanation":{"en":"Automatically analyzing and classifying free-text feedback into thematic categories is a core NLP task (text\nclassification).","zh":"自动分析自由文本反馈并归入主题类别，是自然语言处理（NLP）的核心任务（文本分类）。"},"tip":{"zh":"处理自由文本并分类 → NLP；视觉、推荐、欺诈都跟文本无关，选 B。","en":""},"keywords":["NLP","文本分类","客户反馈"]},{"id":234,"type":"single","answer":["B"],"topic":"responsible","stem":{"en":"A financial services company must ensure that its generative AI-powered chatbot provides factual\nresponses for regulatory compliance.\nWhich solution prevents the underlying foundation model (FM) from hallucinating?","zh":"某金融服务公司必须确保其由生成式 AI 驱动的聊天机器人提供符合监管合规要求的事实性回复。\n哪种解决方案能防止底层基础模型（FM）产生幻觉？"},"options":[{"key":"A","en":"Use AWS Config to query compliance metadata by using natural language.","zh":"使用 AWS Config，通过自然语言查询合规元数据。"},{"key":"B","en":"Configure Amazon Bedrock Guardrails to evaluate user inputs and model responses.","zh":"配置 Amazon Bedrock Guardrails 来评估用户输入和模型回复。"},{"key":"C","en":"Use Amazon Fraud Detector to detect potentially fraudulent online activities.","zh":"使用 Amazon Fraud Detector 检测可能具有欺诈性的在线活动。"},{"key":"D","en":"Use AWS Audit Manager to prepare IT audit and compliance reports.","zh":"使用 AWS Audit Manager 准备 IT 审计和合规报告。"}],"explanation":{"en":"Amazon Bedrock Guardrails allows you to define rules and policies that evaluate and constrain both user\ninputs and model responses. By configuring guardrails, you can prevent the generative AI model from\nproducing hallucinated or non-factual outputs, ensuring the chatbot adheres to compliance requirements\nand provides factual responses. This directly addresses the need to control hallucinations in generative AI\nsystems for regulatory compliance.","zh":"Amazon Bedrock Guardrails 允许你定义规则和策略，对用户输入和模型回复进行评估和约束。通过配置护栏，你可以防止生成式 AI 模型产生幻觉或非事实性的输出，确保聊天机器人遵守合规要求并提供事实性回复。这直接满足了在监管合规场景中控制生成式 AI 系统幻觉的需求。"},"tip":{"zh":"防幻觉、约束输入输出 → Bedrock Guardrails，选 B。","en":""},"keywords":["Guardrails","幻觉","监管合规"]},{"id":235,"type":"hotspot","answer":[],"topic":"genai","stem":{"en":"A company wants to develop a solution that uses generative AI to create content for product\nadvertisements, including sample images and slogans.\nSelect the correct model type from the following list for each action. Each model type should be selected\none time.","zh":"某公司希望开发一个使用生成式 AI 为产品广告创作内容的解决方案，内容包括示例图像和广告语。\n请针对每个动作，从列表中选择正确的模型类型。每种模型类型应被选择一次。"},"options":[],"explanation":{"en":"Create high-quality images that are influenced by the generated slogans and product -> Diffusion model\nCreate contextually relevant slogans based on the advertisement product -> Transformer-based model\nEnsure that company brand elements are properly placed in the images -> Object detection model\nDiffusion models are state-of-the-art for high-quality image generation.\nTransformer-based models excel at natural language processing, making them suitable for generating\ncontextually relevant slogans.\nObject detection models are designed to identify and ensure correct placement of specific objects (e.g.,\nbrand elements) within images.","zh":"创建受所生成广告语和产品影响的高质量图像 -> 扩散模型\n基于广告产品创建上下文相关的广告语 -> 基于 Transformer 的模型\n确保公司品牌元素被正确放置在图像中 -> 目标检测模型\n扩散模型是高质量图像生成的最先进方案。\n基于 Transformer 的模型擅长自然语言处理，因此适合生成上下文相关的广告语。\n目标检测模型用于识别并确保特定对象（例如品牌元素）在图像中的正确放置。"},"tip":{"zh":"考模型类型与动作的对应：出图=扩散、写文案=Transformer、定位品牌=目标检测。","en":""},"keywords":["扩散模型","Transformer","目标检测"]},{"id":236,"type":"single","answer":["C"],"topic":"sagemaker","stem":{"en":"A company has created multiple ML models. The company needs a solution for storing, managing, and\nversioning the models.\nWhich AWS service or feature meets these requirements?","zh":"某公司已创建多个机器学习模型。公司需要一个用于存储、管理和版本化这些模型的解决方案。\n哪项 AWS 服务或功能满足这些要求？"},"options":[{"key":"A","en":"AWS Audit Manager","zh":"AWS Audit Manager"},{"key":"B","en":"Amazon SageMaker Model Monitor","zh":"Amazon SageMaker Model Monitor"},{"key":"C","en":"Amazon SageMaker Model Registry","zh":"Amazon SageMaker Model Registry"},{"key":"D","en":"Amazon SageMaker Canvas","zh":"Amazon SageMaker Canvas"}],"explanation":{"en":"Amazon SageMaker Model Registry is the AWS service designed to store, manage, and version machine\nlearning models. It provides a central repository for tracking model versions and managing their\ndeployment status throughout the ML lifecycle.","zh":"Amazon SageMaker Model Registry 是专为存储、管理和版本化机器学习模型而设计的 AWS 服务。它提供集中式存储库，用于在整个机器学习生命周期中跟踪模型版本并管理其部署状态。"},"tip":{"zh":"模型存储 + 版本管理 → Model Registry；Model Monitor 是监控漂移，选 C。","en":""},"keywords":["Model Registry","模型版本管理","模型存储"]},{"id":237,"type":"single","answer":["A"],"topic":"responsible","stem":{"en":"An AI practitioner is building an ML model. The AI practitioner wants to provide model transparency and\nexplainability to stakeholders.\nWhich solution will meet these requirements?","zh":"某 AI 从业者正在构建一个机器学习模型。该从业者希望向利益相关方提供模型的透明度和可解释性。\n哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Present the model Shapley values.","zh":"展示模型的 Shapley 值。"},{"key":"B","en":"Provide the model accuracy measure.","zh":"提供模型的准确率指标。"},{"key":"C","en":"Provide the model confusion matrix.","zh":"提供模型的混淆矩阵。"},{"key":"D","en":"Provide a secure model inference endpoint.","zh":"提供一个安全的模型推理端点。"}],"explanation":{"en":"Presenting the model Shapley values provides transparency and explainability by showing how each\nfeature contributes to individual predictions, helping stakeholders understand the reasoning behind the\nmodel’s outputs.","zh":"展示模型的 Shapley 值可以提供透明度和可解释性，因为它展示了每个特征对单条预测的贡献程度，帮助利益相关方理解模型输出背后的推理过程。"},"tip":{"zh":"要可解释「为什么这么预测」→ SHAP 值；准确率、混淆矩阵只讲结果，选 A。","en":""},"keywords":["SHAP 值","可解释性","特征贡献"]},{"id":238,"type":"single","answer":["A"],"topic":"data","stem":{"en":"A company is developing an ML application. The application must automatically group similar customers\nand products based on their characteristics. Which ML strategy should the company use to meet these\nrequirements?","zh":"某公司正在开发一个机器学习应用程序。该应用程序必须根据客户和产品的特征，自动把相似的客户和产品分组。公司应使用哪种机器学习策略来满足这些要求？"},"options":[{"key":"A","en":"Unsupervised learning","zh":"无监督学习"},{"key":"B","en":"Supervised learning","zh":"监督式学习"},{"key":"C","en":"Reinforcement learning","zh":"强化学习"},{"key":"D","en":"Semi-supervised learning","zh":"半监督式学习"}],"explanation":{"en":"Unsupervised learning is used to automatically group or cluster similar customers and products based on\ntheir characteristics without the need for labeled data. This strategy fits scenarios where the goal is to\ndiscover patterns or groupings in the data.","zh":"无监督学习用于在无需标注数据的情况下，根据特征自动把相似的客户和产品分组或聚类。该策略适用于目标是发现数据中模式或分组的场景。"},"tip":{"zh":"没有标签、自动把相似项归堆 → 无监督学习（聚类），选 A。","en":""},"keywords":["无监督学习","聚类","分组"]},{"id":239,"type":"single","answer":["B"],"topic":"services","stem":{"en":"A news agency publishes articles in English. The agency wants to make articles available in other\nlanguages.\nWhich solution meets these requirements?","zh":"某新闻机构以英语发布文章。该机构希望让文章能以其他语言提供。\n哪种解决方案满足这些要求？"},"options":[{"key":"A","en":"Add Amazon Transcribe to the company’s website.","zh":"在公司网站上添加 Amazon Transcribe。"},{"key":"B","en":"Use the Amazon Translate real-time translation feature.","zh":"使用 Amazon Translate 的实时翻译功能。"},{"key":"C","en":"Add Amazon Personalize to the company’s website.","zh":"在公司网站上添加 Amazon Personalize。"},{"key":"D","en":"Use the Amazon Textract real-time document processing feature.","zh":"使用 Amazon Textract 的实时文档处理功能。"}],"explanation":{"en":"Amazon Translate provides real-time translation of text, making it suitable for automatically translating\narticles from English into other languages for publication.","zh":"Amazon Translate 提供文本的实时翻译，因此适合把英语文章自动翻译成其他语言并发布。"},"tip":{"zh":"文本跨语言翻译 → Amazon Translate；Transcribe 是语音转文字，选 B。","en":""},"keywords":["Amazon Translate","机器翻译","多语言"]},{"id":240,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"A bank is building a chatbot to answer customer questions about opening a bank account. The chatbot will\nuse public bank documents to generate responses. The company will use Amazon Bedrock and prompt\nengineering to improve the chatbot’s responses.\nWhich prompt engineering technique meets these requirements?","zh":"某银行正在构建一个聊天机器人，用于回答客户关于开立银行账户的问题。该聊天机器人将使用公开的银行文档来生成回复。公司将使用 Amazon Bedrock 和提示工程来改进聊天机器人的回复。\n哪种提示工程技术满足这些要求？"},"options":[{"key":"A","en":"Complexity-based prompting","zh":"基于复杂度的提示（Complexity-based prompting）"},{"key":"B","en":"Zero-shot prompting","zh":"零样本提示"},{"key":"C","en":"Few-shot prompting","zh":"少样本提示"},{"key":"D","en":"Directional stimulus prompting","zh":"方向性刺激提示（Directional stimulus prompting）"}],"explanation":{"en":"Few-shot prompting involves providing the generative AI model with several examples (drawn from public\nbank documents) to guide it in generating more accurate and relevant responses. This technique helps the\nchatbot better align its answers with the desired content and format.","zh":"少样本提示是指向生成式 AI 模型提供若干示例（取自公开的银行文档），引导它生成更准确、更相关的回复。该技术有助于聊天机器人更好地使回答与期望的内容和格式保持一致。"},"tip":{"zh":"给模型若干文档示例来引导回答 → 少样本提示，选 C。","en":""},"keywords":["少样本提示","提示工程","Bedrock"]},{"id":241,"type":"single","answer":["C"],"topic":"security","stem":{"en":"A company wants to fine-tune an ML model that is hosted on Amazon Bedrock. The company wants to\nuse its own sensitive data that is stored in private databases in a VPC. The data needs to stay within the\ncompany’s private network.\nWhich solution will meet these requirements?","zh":"某公司想要微调托管在 Amazon Bedrock 上的机器学习模型。该公司希望使用存储在 VPC 内私有数据库中的自有敏感数据。数据必须保留在该公司的私有网络内。哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Restrict access to Amazon Bedrock by using an AWS Identity and Access Management (IAM) service role.","zh":"通过使用 AWS Identity and Access Management（IAM）服务角色来限制对 Amazon Bedrock 的访问。"},{"key":"B","en":"Restrict access to Amazon Bedrock by using an AWS Identity and Access Management (IAM) resource policy.","zh":"通过使用 AWS Identity and Access Management（IAM）资源策略来限制对 Amazon Bedrock 的访问。"},{"key":"C","en":"Use AWS PrivateLink to connect the VPC and Amazon Bedrock.","zh":"使用 AWS PrivateLink 连接 VPC 和 Amazon Bedrock。"},{"key":"D","en":"Use AWS Key Management Service (AWS KMS) keys to encrypt the data.","zh":"使用 AWS Key Management Service（AWS KMS）密钥加密数据。"}],"explanation":{"en":"AWS PrivateLink enables secure, private connectivity between your VPC and Amazon Bedrock without\nexposing data to the public internet, ensuring that sensitive data stays within your private network during\nfine-tuning.","zh":"AWS PrivateLink 可在您的 VPC 与 Amazon Bedrock 之间建立安全、私有的连接，不会将数据暴露到公共互联网，从而确保敏感数据在微调期间始终留在私有网络内。"},"tip":{"zh":"要求数据不出私网 → 用 PrivateLink 建私有连接；IAM 和 KMS 都管不住流量走向。","en":""},"keywords":["AWS PrivateLink","私有网络","Amazon Bedrock"]},{"id":242,"type":"multi","answer":["A","C"],"topic":"services","stem":{"en":"A documentary filmmaker wants to reach more viewers. The filmmaker wants to automatically add\nsubtitles and voice-overs in multiple languages to their films.\nWhich combination of steps will meet these requirements? (Choose two.)","zh":"某纪录片导演希望触达更多观众。该导演希望自动为其影片添加多种语言的字幕和配音。以下哪组步骤组合能满足这些要求？（选择两项。）"},"options":[{"key":"A","en":"Use Amazon Transcribe and Amazon Translate to generate subtitles in other languages.","zh":"使用 Amazon Transcribe 和 Amazon Translate 生成其他语言的字幕。"},{"key":"B","en":"Use Amazon Textract and Amazon Translate to generate subtitles in other languages.","zh":"使用 Amazon Textract 和 Amazon Translate 生成其他语言的字幕。"},{"key":"C","en":"Use Amazon Polly to generate voice-overs in other languages.","zh":"使用 Amazon Polly 生成其他语言的配音。"},{"key":"D","en":"Use Amazon Translate to generate voice-overs in other languages.","zh":"使用 Amazon Translate 生成其他语言的配音。"},{"key":"E","en":"Use Amazon Textract to generate voice-overs in other languages.","zh":"使用 Amazon Textract 生成其他语言的配音。"}],"explanation":{"en":"Use Amazon Transcribe and Amazon Translate to generate subtitles in other languages: Amazon\nTranscribe converts spoken dialogue to text (subtitles), and Amazon Translate can then translate these\nsubtitles into multiple languages.\nUse Amazon Polly to generate voice-overs in other languages: Amazon Polly converts translated text into\nlifelike speech, enabling the creation of multilingual voice-overs.","zh":"使用 Amazon Transcribe 和 Amazon Translate 生成其他语言的字幕：Amazon Transcribe 将对话语音转换为文本（字幕），随后 Amazon Translate 可将这些字幕翻译成多种语言。\n使用 Amazon Polly 生成其他语言的配音：Amazon Polly 将翻译后的文本转换为逼真的语音，从而能够制作多语言配音。"},"tip":{"zh":"字幕＝语音转文字（Transcribe）＋翻译（Translate）；配音＝文字转语音（Polly）。","en":""},"keywords":["Amazon Transcribe","Amazon Polly","字幕与配音"]},{"id":243,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"A company wants to create a chatbot to answer employee questions about company policies. Company\npolicies are updated frequently. The chatbot must reflect the changes in near real time. The company\nwants to choose a large language model (LLM).\nWhich solution meets these requirements?","zh":"某公司想要创建一个聊天机器人，回答员工关于公司政策的问题。公司政策经常更新。该聊天机器人必须近实时地反映这些变更。该公司希望选择一种大型语言模型（LLM）。哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Fine-tune an LLM on the company policy text by using Amazon SageMaker.","zh":"使用 Amazon SageMaker 在公司政策文本上微调 LLM。"},{"key":"B","en":"Select a foundation model (FM) from Amazon Bedrock to build an application.","zh":"从 Amazon Bedrock 中选择一个基础模型（FM）来构建应用程序。"},{"key":"C","en":"Create a Retrieval Augmented Generation (RAG) workflow by using Amazon Bedrock Knowledge Bases.","zh":"使用 Amazon Bedrock Knowledge Bases 创建检索增强生成（RAG）工作流。"},{"key":"D","en":"Use Amazon Q Business to build a custom Q App.","zh":"使用 Amazon Q Business 构建自定义 Q App。"}],"explanation":{"en":"A RAG workflow with Amazon Bedrock Knowledge Bases allows the chatbot to access the most recent\ncompany policy documents dynamically, ensuring responses reflect policy updates in near real time\nwithout the need to retrain or fine-tune the LLM each time content changes.","zh":"使用 Amazon Bedrock Knowledge Bases 的 RAG 工作流，可让聊天机器人动态访问最新的公司政策文档，确保回答能近实时反映政策更新，而无需在内容每次变更时重新训练或微调 LLM。"},"tip":{"zh":"内容频繁更新又要近实时 → 用 RAG 检索知识库，别靠微调硬记。","en":""},"keywords":["RAG","知识库","近实时更新"]},{"id":244,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"A company is using supervised learning to train an AI model on a small labeled dataset that is specific to a\ntarget task.\nWhich step of the foundation model (FM) lifecycle does this describe?","zh":"某公司正在使用监督式学习，在一个特定于目标任务的小型标注数据集上训练 AI 模型。这描述的是基础模型（FM）生命周期的哪个步骤？"},"options":[{"key":"A","en":"Fine-tuning","zh":"微调"},{"key":"B","en":"Data selection","zh":"数据选择"},{"key":"C","en":"Pre-training","zh":"预训练"},{"key":"D","en":"Evaluation","zh":"评估"}],"explanation":{"en":"Fine-tuning is the process of training a pre-existing foundation model on a smaller, labeled dataset that is\nspecific to a target task, allowing the model to adapt to the company's requirements.","zh":"微调是指在较小的、特定于目标任务的标注数据集上训练已有的基础模型，使模型能够适应公司的需求。"},"tip":{"zh":"小数据集＋有标注＋针对特定任务 → 就是微调，预训练才是海量无标注语料。","en":""},"keywords":["微调","标注数据集","FM 生命周期"]},{"id":245,"type":"hotspot","answer":[],"topic":"responsible","stem":{"en":"A company is developing an AI application to help the company approve or deny personal loans. The\napplication must follow the principles of responsible AI.\nSelect the correct responsible AI principle from the following list for each action. Select each responsible\nAI principle one time or not at all.","zh":"某公司正在开发一个 AI 应用程序，帮助公司批准或拒绝个人贷款。该应用程序必须遵循负责任 AI 的原则。请从以下列表中为每个操作选择正确的负责任 AI 原则。每个负责任 AI 原则可选择一次或不选。"},"options":[],"explanation":{"en":"Encrypt the application data, and isolate the application on a private network -> Privacy and security\nEvaluate how different population groups will be impacted -> Fairness\nTest the application with unexpected data to ensure the application will work in unique situations ->\nRobustness\nProtecting data and networks is part of privacy and security.\nAssessing impacts on different groups ensures fairness.\nTesting with unexpected data checks the application's robustness.","zh":"加密应用程序数据，并将应用程序隔离在私有网络中 -> 隐私与安全\n评估不同人群将受到的影响 -> 公平性\n用意外数据测试应用程序，确保应用程序在特殊情况下也能正常工作 -> 稳健性\n保护数据和网络属于隐私与安全。\n评估对不同群体的影响可确保公平性。\n用意外数据进行测试可检验应用程序的稳健性。"},"tip":{"zh":"隐私安全＝加密隔离；公平＝看各群体影响；稳健＝喂意外数据也不崩。","en":""},"keywords":["负责任 AI","隐私与安全","公平性","稳健性"]},{"id":246,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"A company is introducing a new feature for its application. The feature will refine the style of output\nmessages. The company will fine-tune a large language model (LLM) on Amazon Bedrock to implement\nthe feature.\nWhich type of data does the company need to meet these requirements?","zh":"某公司正在为其应用程序推出一项新功能。该功能将优化输出消息的风格。该公司将在 Amazon Bedrock 上微调大型语言模型（LLM）来实现该功能。该公司需要哪种类型的数据来满足这些要求？"},"options":[{"key":"A","en":"Samples of only input messages","zh":"仅输入消息的样本"},{"key":"B","en":"Samples of only output messages","zh":"仅输出消息的样本"},{"key":"C","en":"Samples of pairs of input and output messages","zh":"输入与输出消息成对的样本"},{"key":"D","en":"Separate samples of input and output messages","zh":"输入消息和输出消息各自独立的样本"}],"explanation":{"en":"Fine-tuning a large language model to refine the style of output messages requires training data consisting\nof paired input and output messages. These pairs allow the model to learn the relationship between the\ninput provided and the desired styled output, ensuring the fine-tuned model produces responses with the\nintended style.","zh":"微调大型语言模型以优化输出消息的风格，需要由成对的输入和输出消息组成的训练数据。这些配对使模型能够学习所提供输入与期望风格化输出之间的关系，从而确保微调后的模型生成具有预期风格的响应。"},"tip":{"zh":"要学“输入→输出”的风格映射，必须用成对样本，各给一堆没用。","en":""},"keywords":["微调数据","输入输出配对","输出风格"]},{"id":247,"type":"single","answer":["D"],"topic":"sagemaker","stem":{"en":"A healthcare company is building an AI solution to predict patient readmission within 30 days of patient\ndischarge. The company has trained a model on historical patient data including medical history,\ndemographics, and treatment specifications, to provide readmission predictions in real time.\nWhich task describes AI model inference in this scenario?","zh":"某医疗公司正在构建一个 AI 解决方案，用于预测患者在出院后 30 天内是否再入院。该公司已使用历史患者数据（包括病史、人口统计信息和治疗方案）训练了一个模型，以实时提供再入院预测。在此场景中，哪项任务描述的是 AI 模型推理？"},"options":[{"key":"A","en":"Gather historical patient readmission data.","zh":"收集历史患者再入院数据。"},{"key":"B","en":"Use appropriate metrics and assess model performance.","zh":"使用适当的指标并评估模型性能。"},{"key":"C","en":"Use data to identify patient patterns and correlations.","zh":"使用数据识别患者模式和相关性。"},{"key":"D","en":"Use a trained model to predict patient readmission.","zh":"使用训练好的模型预测患者再入院。"}],"explanation":{"en":"Model inference refers to the process of applying a trained model to new data—in this case, using the\ntrained model to make real-time predictions about whether a patient will be readmitted within 30 days of\ndischarge.","zh":"模型推理是指将训练好的模型应用于新数据的过程——在本例中，即使用训练好的模型实时预测患者在出院后 30 天内是否会再入院。"},"tip":{"zh":"推理＝拿训练好的模型对新数据出预测；收集数据、评估、分析都不算。","en":""},"keywords":["模型推理","实时预测","训练与推理区别"]},{"id":248,"type":"single","answer":["B"],"topic":"services","stem":{"en":"A financial company wants to build workflows for human review of ML predictions. The company wants to\ndefine confidence thresholds for its use case and adjust the thresholds over time.\nWhich AWS service meets these requirements?","zh":"某金融公司希望构建用于人工审核机器学习预测的工作流。该公司希望为其用例定义置信度阈值，并随时间调整这些阈值。哪项 AWS 服务能满足这些要求？"},"options":[{"key":"A","en":"Amazon Personalize","zh":"Amazon Personalize"},{"key":"B","en":"Amazon Augmented AI (Amazon A2I)","zh":"Amazon Augmented AI（Amazon A2I）"},{"key":"C","en":"Amazon Inspector","zh":"Amazon Inspector"},{"key":"D","en":"AWS Audit Manager","zh":"AWS Audit Manager"}],"explanation":{"en":"Amazon Augmented AI (Amazon A2I) enables you to build workflows for human review of machine\nlearning predictions, allowing you to define and adjust confidence thresholds for when human intervention\nis required.","zh":"Amazon Augmented AI（Amazon A2I）使您能够构建用于人工审核机器学习预测的工作流，允许您定义并调整需要人工介入时的置信度阈值。"},"tip":{"zh":"人工审核＋置信度阈值 → A2I；Inspector 查漏洞，Audit Manager 管审计。","en":""},"keywords":["Amazon A2I","人在回路","置信度阈值"]},{"id":249,"type":"single","answer":["D"],"topic":"genai","stem":{"en":"A company wants to develop an AI assistant for employees to query internal data.\nWhich AWS service will meet this requirement?","zh":"某公司希望开发一个 AI 助手，供员工查询内部数据。哪项 AWS 服务能满足此要求？"},"options":[{"key":"A","en":"Amazon Rekognition","zh":"Amazon Rekognition"},{"key":"B","en":"Amazon Textract","zh":"Amazon Textract"},{"key":"C","en":"Amazon Lex","zh":"Amazon Lex"},{"key":"D","en":"Amazon Q Business","zh":"Amazon Q Business"}],"explanation":{"en":"Amazon Q Business is designed to build generative AI assistants for querying and interacting with internal\norganizational data, making it the ideal service for creating an AI assistant for employees to access\ncompany information.","zh":"Amazon Q Business 专为构建用于查询和交互企业内部组织数据的生成式 AI 助手而设计，是创建供员工访问公司信息的 AI 助手的理想服务。"},"tip":{"zh":"企业内部数据问答助手 → Amazon Q Business；Lex 只负责搭对话机器人。","en":""},"keywords":["Amazon Q Business","企业搜索","内部数据"]},{"id":250,"type":"single","answer":["A"],"topic":"sagemaker","stem":{"en":"A company wants to build and deploy ML models on AWS without writing any code.\nWhich AWS service or feature meets these requirements?","zh":"某公司希望在不编写任何代码的情况下在 AWS 上构建和部署机器学习模型。哪项 AWS 服务或功能能满足这些要求？"},"options":[{"key":"A","en":"Amazon SageMaker Canvas","zh":"Amazon SageMaker Canvas"},{"key":"B","en":"Amazon Rekognition","zh":"Amazon Rekognition"},{"key":"C","en":"AWS DeepRacer","zh":"AWS DeepRacer"},{"key":"D","en":"Amazon Comprehend","zh":"Amazon Comprehend"}],"explanation":{"en":"Amazon SageMaker Canvas allows users to build, train, and deploy machine learning models using a no-\ncode visual interface, meeting the requirement to create ML solutions without writing any code.","zh":"Amazon SageMaker Canvas 允许用户通过无代码可视化界面构建、训练和部署机器学习模型，满足无需编写任何代码即可创建机器学习解决方案的要求。"},"tip":{"zh":"无代码、点选式建模型 → SageMaker Canvas；DeepRacer 只是赛车实验。","en":""},"keywords":["SageMaker Canvas","无代码","可视化建模"]},{"id":251,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"A design company is using a foundation model (FM) on Amazon Bedrock to generate images for various\nprojects. The company wants to have control over how detailed or abstract each generated image appears\nWhich model parameter should the company modify?","zh":"某设计公司正在使用 Amazon Bedrock 上的基础模型（FM）为各种项目生成图像。该公司希望控制每张生成图像呈现的细节程度或抽象程度。该公司应修改哪个模型参数？"},"options":[{"key":"A","en":"Model checkpoint","zh":"模型检查点"},{"key":"B","en":"Batch size","zh":"批量大小"},{"key":"C","en":"Generation step","zh":"生成步数"},{"key":"D","en":"Token length","zh":"词元长度"}],"explanation":{"en":"The “generation step” parameter controls how detailed or abstract an image appears during generation. By\nadjusting the number of generation steps, you can influence the level of refinement and detail in the output\n- more steps yield more detailed images, while fewer steps result in more abstract images.","zh":"“生成步数”（generation step）参数控制在生成过程中图像呈现的细节程度或抽象程度。通过调整生成步数，可以影响输出的精细度和细节——步数越多，图像越细致；步数越少，图像越抽象。"},"tip":{"zh":"图像的细节/抽象程度 → 调生成步数（generation step），步数多更精细。","en":""},"keywords":["生成步数","图像生成","模型参数"]},{"id":252,"type":"single","answer":["A"],"topic":"security","stem":{"en":"A financial company has offices in different countries worldwide. The company requires that all API calls\nbetween generative AI applications and foundation models (FM) must not travel across the public internet.\nWhich AWS service should the company use?","zh":"某金融公司在全球不同国家设有办事处。该公司要求生成式 AI 应用程序与基础模型（FM）之间的所有 API 调用都不得经过公共互联网。该公司应使用哪项 AWS 服务？"},"options":[{"key":"A","en":"AWS PrivateLink","zh":"AWS PrivateLink"},{"key":"B","en":"Amazon Q","zh":"Amazon Q"},{"key":"C","en":"Amazon CloudFront","zh":"Amazon CloudFront"},{"key":"D","en":"AWS CloudTrail","zh":"AWS CloudTrail"}],"explanation":{"en":"AWS PrivateLink provides secure, private connectivity between VPCs and AWS services, ensuring that\nAPI calls do not traverse the public internet. This meets the requirement for private communication\nbetween generative AI applications and foundation models across global offices.","zh":"AWS PrivateLink 在 VPC 与 AWS 服务之间提供安全、私有的连接，确保 API 调用不经过公共互联网。这满足了全球办事处之间生成式 AI 应用程序与基础模型之间私有通信的要求。"},"tip":{"zh":"API 调用不能走公网 → PrivateLink；CloudFront 是 CDN，反而靠公网分发。","en":""},"keywords":["AWS PrivateLink","私有连接","不经过公网"]},{"id":253,"type":"single","answer":["A"],"topic":"responsible","stem":{"en":"An ecommerce company is deploying a chatbot. The chatbot will give users the ability to ask questions\nabout the company’s products and receive details on users’ orders. The company must implement\nsafeguards for the chatbot to filter harmful content from the input prompts and chatbot responses.\nWhich AWS feature or resource meets these requirements?","zh":"某电商公司正在部署一个聊天机器人。该聊天机器人将让用户能够询问有关公司产品的问题，并获取用户订单的详细信息。该公司必须为聊天机器人实施保护措施，以过滤输入提示和聊天机器人响应中的有害内容。哪项 AWS 功能或资源能满足这些要求？"},"options":[{"key":"A","en":"Amazon Bedrock Guardrails","zh":"Amazon Bedrock Guardrails"},{"key":"B","en":"Amazon Bedrock Agents","zh":"Amazon Bedrock Agents"},{"key":"C","en":"Amazon Bedrock inference APIs","zh":"Amazon Bedrock inference APIs"},{"key":"D","en":"Amazon Bedrock custom models","zh":"Amazon Bedrock custom models"}],"explanation":{"en":"Amazon Bedrock Guardrails enable you to implement safeguards that filter out harmful or inappropriate\ncontent in both user input prompts and chatbot responses, ensuring safe and compliant chatbot\ninteractions.","zh":"Amazon Bedrock Guardrails 使您能够实施保护措施，过滤用户输入提示和聊天机器人响应中的有害或不适当内容，确保聊天机器人交互安全合规。"},"tip":{"zh":"过滤有害内容、输入输出两头都要拦 → Bedrock Guardrails（护栏）。","en":""},"keywords":["Guardrails","护栏","有害内容过滤"]},{"id":254,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"A company wants to learn about generative AI applications in an experimental environment.\nWhich solution will meet this requirement MOST cost-effectively?","zh":"某公司希望在实验环境中了解生成式 AI 应用程序。哪种解决方案能以最具成本效益的方式满足此要求？"},"options":[{"key":"A","en":"Amazon Q Developer","zh":"Amazon Q Developer"},{"key":"B","en":"Amazon SageMaker JumpStart","zh":"Amazon SageMaker JumpStart"},{"key":"C","en":"Amazon Bedrock PartyRock","zh":"Amazon Bedrock PartyRock"},{"key":"D","en":"Amazon Q Business","zh":"Amazon Q Business"}],"explanation":{"en":"Amazon Bedrock PartyRock provides a highly cost-effective and experimental environment for learning\nabout generative AI applications, allowing users to quickly build, test, and iterate on AI apps without\nincurring significant costs.","zh":"Amazon Bedrock PartyRock 提供了一个极具成本效益的实验环境，用于学习生成式 AI 应用程序，让用户能够快速构建、测试和迭代 AI 应用，而不会产生高昂费用。"},"tip":{"zh":"低成本动手玩生成式 AI → PartyRock，免费低门槛的练手实验场。","en":""},"keywords":["PartyRock","成本效益","实验环境"]},{"id":255,"type":"single","answer":["A"],"topic":"data","stem":{"en":"A company needs to collect a large dataset to train an AI assistant in a specific content area.\nWhich dataset will meet this requirement?","zh":"某公司需要收集一个大型数据集，以训练特定内容领域的 AI 助手。哪个数据集能满足此要求？"},"options":[{"key":"A","en":"Diverse conversations that use relevant terminology","zh":"使用相关术语的多样化对话"},{"key":"B","en":"Time series data of general purpose historical sales","zh":"通用历史销售的时间序列数据"},{"key":"C","en":"Sentiment analysis of news articles","zh":"新闻文章的情感分析"},{"key":"D","en":"Unique product IDs and corresponding user IDs","zh":"唯一产品 ID 及对应的用户 ID"}],"explanation":{"en":"To train an AI assistant for a specific content area, you need a large dataset of diverse conversations that\nincorporate the relevant terminology and context for that area. This enables the assistant to learn how to\nrespond accurately and appropriately within the targeted subject.","zh":"要为特定内容领域训练 AI 助手，需要一个包含该领域相关术语和上下文的大量多样化对话数据集。这使助手能够学习如何在目标主题范围内准确、恰当地响应。"},"tip":{"zh":"训练领域助手 → 要该领域的多样化对话语料，其它数据类型都不对口。","en":""},"keywords":["数据集","多样化对话","领域助手"]},{"id":256,"type":"single","answer":["A"],"topic":"responsible","stem":{"en":"A financial company is developing a generative AI application for loan approval decisions. The company\nneeds the application output to be responsible and fair.\nWhich solution meets these requirements?","zh":"某金融公司正在开发一个用于贷款审批决策的生成式 AI 应用程序。该公司需要应用程序的输出负责任且公平。哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Review the training data to check for biases. Include data from all demographics in the training data.","zh":"检查训练数据是否存在偏见。在训练数据中包含所有人群的数据。"},{"key":"B","en":"Use a deep learning model with many hidden layers.","zh":"使用具有许多隐藏层的深度学习模型。"},{"key":"C","en":"Keep the model’s decision-making process a secret to protect proprietary algorithms.","zh":"对模型的决策过程保密，以保护专有算法。"},{"key":"D","en":"Continuously monitor the model’s performance on a static test dataset","zh":"在静态测试数据集上持续监控模型性能。"}],"explanation":{"en":"Reviewing the training data for biases and ensuring representation from all demographics is essential for\ndeveloping a responsible and fair generative AI application, especially in sensitive domains like loan\napproval decisions. This approach helps reduce bias and supports ethical AI practices.","zh":"检查训练数据是否存在偏见并确保包含所有人群的代表性数据，对于开发负责任且公平的生成式 AI 应用程序至关重要，尤其是在贷款审批决策等敏感领域。这种方法有助于减少偏见并支持合乎道德的 AI 实践。"},"tip":{"zh":"公平＝数据无偏见且覆盖各人群；保密和深层网络都跟公平无关。","en":""},"keywords":["公平性","训练数据偏见","人群代表性"]},{"id":257,"type":"hotspot","answer":[],"topic":"responsible","stem":{"en":"Select the correct AWS service or tool from the following list for each use case. Select each AWS service\nor tool one time or not at all.","zh":"请从以下列表中为每个用例选择正确的 AWS 服务或工具。每个 AWS 服务或工具可选择一次或不选。"},"options":[],"explanation":{"en":"Apply human feedback across the ML lifecycle to improve the accuracy and relevancy of models. ->\nAmazon SageMaker Ground Truth\nImplement safeguards that align with responsible AI policies. -> Amazon Bedrock Guardrails\nDetect potential bias during data preparation and model training. -> Amazon SageMaker Clarify\nAmazon SageMaker Ground Truth is used for human-in-the-loop data labeling and model improvement.\nAmazon Bedrock Guardrails are designed to enforce responsible AI safeguards.\n\nAmazon SageMaker Clarify detects and helps mitigate bias during data preparation and model training.","zh":"在整个 ML 生命周期中应用人工反馈，以提高模型的准确性和相关性 -> Amazon SageMaker Ground Truth\n实施符合负责任 AI 政策的保护措施 -> Amazon Bedrock Guardrails\n在数据准备和模型训练期间检测潜在偏见 -> Amazon SageMaker Clarify\nAmazon SageMaker Ground Truth 用于人在回路的数据标注和模型改进。\nAmazon Bedrock Guardrails 旨在强制执行负责任 AI 的保护措施。\nAmazon SageMaker Clarify 在数据准备和模型训练期间检测并帮助缓解偏见。"},"tip":{"zh":"人工标注＝Ground Truth；护栏＝Guardrails；查偏见＝Clarify，三者别混。","en":""},"keywords":["Ground Truth","Guardrails","Clarify","偏见检测"]},{"id":258,"type":"single","answer":["A"],"topic":"sagemaker","stem":{"en":"An AI practitioner who has minimal ML knowledge wants to predict employee attrition without writing code.\nWhich Amazon SageMaker feature meets this requirement?","zh":"一位机器学习知识很少的 AI 从业者希望在不编写代码的情况下预测员工流失。哪项 Amazon SageMaker 功能能满足此要求？"},"options":[{"key":"A","en":"SageMaker Canvas","zh":"SageMaker Canvas"},{"key":"B","en":"SageMaker Clarify","zh":"SageMaker Clarify"},{"key":"C","en":"SageMaker Model Monitor","zh":"SageMaker Model Monitor"},{"key":"D","en":"SageMaker Data Wrangler","zh":"SageMaker Data Wrangler"}],"explanation":{"en":"SageMaker Canvas provides a no-code visual interface that allows users with minimal ML knowledge to\nbuild, train, and deploy models for predictions, such as employee attrition, without writing any code.","zh":"SageMaker Canvas 提供无代码可视化界面，使机器学习知识很少的用户无需编写任何代码即可构建、训练和部署模型以进行预测，例如员工流失预测。"},"tip":{"zh":"不懂 ML、不写代码 → Canvas；Clarify 查偏见，Monitor 盯漂移。","en":""},"keywords":["SageMaker Canvas","无代码","员工流失预测"]},{"id":259,"type":"single","answer":["C"],"topic":"responsible","stem":{"en":"A company is using AI to improve its services. The company needs to ensure that the AI system is fair and\nexplainable. The company wants to require training for members of the AI system development team.\nWhich training will meet these requirements?","zh":"某公司正在使用 AI 改进其服务。该公司需要确保 AI 系统公平且可解释。该公司希望要求 AI 系统开发团队的成员接受培训。哪项培训能满足这些要求？"},"options":[{"key":"A","en":"Training on advanced coding skills","zh":"高级编码技能培训"},{"key":"B","en":"Training on data privacy and encryption protocols","zh":"数据隐私和加密协议培训"},{"key":"C","en":"Training on bias awareness and responsible AI","zh":"偏见意识与负责任 AI 培训"},{"key":"D","en":"Training on advanced ML algorithms","zh":"高级机器学习算法培训"}],"explanation":{"en":"Training on bias awareness and responsible AI equips the development team with the knowledge and\npractices necessary to ensure that AI systems are fair, unbiased, and explainable, which aligns with the\ncompany’s requirements.","zh":"偏见意识与负责任 AI 培训使开发团队具备确保 AI 系统公平、无偏见且可解释所需的知识和实践，这符合公司的要求。"},"tip":{"zh":"要公平＋可解释 → 培训偏见意识与负责任 AI，不是练算法和编码。","en":""},"keywords":["偏见意识","负责任 AI","团队培训"]},{"id":260,"type":"single","answer":["A"],"topic":"responsible","stem":{"en":"A company has an ML model. The company wants to know how the model makes predictions.\nWhich term refers to understanding model predictions?","zh":"某公司拥有一个机器学习模型。该公司想知道模型是如何做出预测的。哪个术语指的是理解模型预测？"},"options":[{"key":"A","en":"Model interpretability","zh":"模型可解释性"},{"key":"B","en":"Model training","zh":"模型训练"},{"key":"C","en":"Model interoperability","zh":"模型互操作性"},{"key":"D","en":"Model performance","zh":"模型性能"}],"explanation":{"en":"Model interpretability refers to understanding how a model makes its predictions, providing insights into the\nreasoning behind the model’s outputs.","zh":"模型可解释性是指理解模型如何做出预测，从而深入了解模型输出背后的推理过程。"},"tip":{"zh":"问“模型凭什么这么预测” → 模型可解释性（interpretability）。","en":""},"keywords":["可解释性","模型预测","透明度"]},{"id":261,"type":"single","answer":["B"],"topic":"general","stem":{"en":"A company wants to identify groups for its customers based on the customers’ demographics and buying\npatterns.\nWhich algorithm should the company use to meet this requirement?","zh":"某公司希望根据客户的人口统计信息和购买模式为客户识别分组。该公司应使用哪种算法来满足此要求？"},"options":[{"key":"A","en":"K-nearest neighbors (k-NN)","zh":"K 近邻（k-NN）"},{"key":"B","en":"K-means","zh":"K-means"},{"key":"C","en":"Decision tree","zh":"决策树"},{"key":"D","en":"Support vector machine","zh":"支持向量机"}],"explanation":{"en":"K-means is a clustering algorithm commonly used to identify and group customers based on shared\ncharacteristics such as demographics and buying patterns, making it suitable for customer segmentation\ntasks.","zh":"K-means 是一种聚类算法，常用于根据人口统计信息和购买模式等共同特征来识别和分组客户，适合客户细分任务。"},"tip":{"zh":"给客户分组＝聚类，无标签 → K-means；k-NN、决策树、SVM 都是有监督分类。","en":""},"keywords":["K-means","聚类","客户细分"]},{"id":262,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"A company is working on a large language model (LLM) and noticed that the LLM’s outputs are not as\ndiverse as expected.\nWhich parameter should the company adjust?","zh":"某公司正在研究一个大型语言模型（LLM），并注意到该 LLM 的输出多样性不如预期。该公司应调整哪个参数？"},"options":[{"key":"A","en":"Temperature","zh":"温度（temperature）"},{"key":"B","en":"Batch size","zh":"批量大小"},{"key":"C","en":"Learning rate","zh":"学习率"},{"key":"D","en":"Optimizer type","zh":"优化器类型"}],"explanation":{"en":"The “temperature” parameter controls the randomness and diversity of outputs generated by a large\nlanguage model. Increasing the temperature produces more diverse and creative responses, while\nlowering it makes the outputs more focused and deterministic.","zh":"“温度”（temperature）参数控制大型语言模型生成输出的随机性和多样性。提高温度会产生更多样、更有创意的响应，降低温度则使输出更聚焦、更确定。"},"tip":{"zh":"输出不够多样 → 调高温度；学习率、优化器是训练阶段的参数。","en":""},"keywords":["温度参数","输出多样性","随机性"]},{"id":263,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"A company is using an Amazon Nova Canvas model to generate images. The model generates images\nsuccessfully.\nThe company needs to prevent the model from including specific items in the generated images.\nWhich solution will meet this requirement?","zh":"某公司正在使用 Amazon Nova Canvas 模型生成图像。该模型能成功生成图像。该公司需要防止模型在生成的图像中包含特定物品。哪种解决方案能满足此要求？"},"options":[{"key":"A","en":"Use a higher temperature value.","zh":"使用更高的温度值。"},{"key":"B","en":"Use a more detailed prompt.","zh":"使用更详细的提示。"},{"key":"C","en":"Use a negative prompt.","zh":"使用负向提示（negative prompt）。"},{"key":"D","en":"Use another foundation model (FM).","zh":"换用另一个基础模型（FM）。"}],"explanation":{"en":"A negative prompt is used to specify items or characteristics that you want the image generation model to\navoid including in the output, ensuring that specific items are excluded from generated images.","zh":"负向提示（negative prompt）用于指定您希望图像生成模型避免包含在输出中的物品或特征，从而确保特定物品被排除在生成的图像之外。"},"tip":{"zh":"要“别出现某东西” → 用负向提示，正向描述越细反而越容易出现。","en":""},"keywords":["负向提示","图像生成","排除内容"]},{"id":264,"type":"hotspot","answer":[],"topic":"general","stem":{"en":"A company uses ML techniques to build applications.\nSelect the correct ML technique from the following list for each task. Select each ML technique one time.","zh":"某公司使用机器学习技术构建应用程序。请从以下列表中为每个任务选择正确的机器学习技术。每种机器学习技术各选一次。"},"options":[],"explanation":{"en":"Analyze a text question to determine if the answer is correct -> Binary classification\nAnalyze ecological factors to determine the number of species in a certain area -> Regression\n\nAnalyze car attributes to determine the car model -> Multiclass classification\nDetermining if an answer is correct is a yes/no (binary) decision.\nPredicting the number of species (a numeric value) is a regression task.\nIdentifying a car model from attributes involves choosing from multiple possible classes, which is\nmulticlass classification.","zh":"分析文本问题的答案是否正确 -> 二分类\n分析生态因素以确定某地区的物种数量 -> 回归\n分析汽车属性以确定汽车型号 -> 多分类\n判断答案是否正确是一个“是/否”（二元）决策。\n预测物种数量（一个数值）是回归任务。\n根据属性识别汽车型号需要从多个可能的类别中选择，属于多分类。"},"tip":{"zh":"是/否＝二分类；预测数值＝回归；多个类别选一＝多分类。","en":""},"keywords":["二分类","回归","多分类"]},{"id":265,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"A company wants to label training datasets by using human feedback to fine-tune a foundation model\n(FM). The company does not want to develop labeling applications or manage a labeling workforce.\nWhich AWS service or feature meets these requirements?","zh":"某公司希望使用人工反馈标注训练数据集，以微调基础模型（FM）。该公司不想开发标注应用程序，也不想管理标注人员队伍。哪项 AWS 服务或功能能满足这些要求？"},"options":[{"key":"A","en":"Amazon SageMaker Data Wrangler","zh":"Amazon SageMaker Data Wrangler"},{"key":"B","en":"Amazon SageMaker Ground Truth Plus","zh":"Amazon SageMaker Ground Truth Plus"},{"key":"C","en":"Amazon Transcribe","zh":"Amazon Transcribe"},{"key":"D","en":"Amazon Macie","zh":"Amazon Macie"}],"explanation":{"en":"Amazon SageMaker Ground Truth Plus provides managed data labeling services, allowing you to label\ndatasets using human feedback without developing labeling applications or managing a labeling\nworkforce.","zh":"Amazon SageMaker Ground Truth Plus 提供托管式数据标注服务，使您能够使用人工反馈标注数据集，而无需开发标注应用程序或管理标注人员队伍。"},"tip":{"zh":"要人工标注又不想自己搭平台、管人 → Ground Truth Plus 全托管。","en":""},"keywords":["Ground Truth Plus","数据标注","托管服务"]},{"id":266,"type":"single","answer":["D"],"topic":"genai","stem":{"en":"An online media streaming company wants to give its customers the ability to perform natural language-\nbased image search and filtering. The company needs a vector database that can help with similarity\nsearches and nearest neighbor queries.\nWhich AWS service meets these requirements?","zh":"某在线媒体流公司希望让客户能够执行基于自然语言的图像搜索和过滤。该公司需要一个能帮助进行相似性搜索和最近邻查询的向量数据库。哪项 AWS 服务能满足这些要求？"},"options":[{"key":"A","en":"Amazon Comprehend","zh":"Amazon Comprehend"},{"key":"B","en":"Amazon Personalize","zh":"Amazon Personalize"},{"key":"C","en":"Amazon Polly","zh":"Amazon Polly"},{"key":"D","en":"Amazon OpenSearch Service","zh":"Amazon OpenSearch Service"}],"explanation":{"en":"Amazon OpenSearch Service supports vector search capabilities, allowing you to perform similarity\nsearches and nearest neighbor queries - key requirements for natural language-based image search and\nfiltering.","zh":"Amazon OpenSearch Service 支持向量搜索能力，可执行相似性搜索和最近邻查询——这是基于自然语言的图像搜索和过滤的关键要求。"},"tip":{"zh":"向量数据库＋相似度/最近邻检索 → OpenSearch Service，别选 Comprehend。","en":""},"keywords":["OpenSearch Service","向量数据库","相似性搜索"]},{"id":267,"type":"hotspot","answer":[],"topic":"responsible","stem":{"en":"A company is building an AI solution by using Amazon SageMaker AI. The company wants to use\nSageMaker AI features to facilitate application development.\nSelect the correct SageMaker AI feature from the following list for each use case. Select each feature one\ntime.","zh":"某公司正在使用 Amazon SageMaker AI 构建 AI 解决方案。该公司希望使用 SageMaker AI 的功能来促进应用程序开发。请从以下列表中为每个用例选择正确的 SageMaker AI 功能。每个功能各选一次。"},"options":[],"explanation":{"en":"Determine the most suitable model to use for a business case -> Model Cards\nPrepare data through a low-code or no-code interface -> Data Wrangler\nIdentify biases or imbalances in the data -> Clarify\nModel Cards help summarize and communicate model characteristics for selection.\nData Wrangler provides a no-code/low-code interface for data preparation.\nClarify is used to detect bias and imbalances in datasets and models.","zh":"确定最适合某个业务场景的模型 -> Model Cards\n通过低代码或无代码界面准备数据 -> Data Wrangler\n识别数据中的偏见或不平衡 -> Clarify\nModel Cards 有助于汇总和传达模型特征以便选型。\nData Wrangler 提供用于数据准备的无代码/低代码界面。\nClarify 用于检测数据集和模型中的偏见与不平衡。"},"tip":{"zh":"选型看卡片＝Model Cards；数据准备＝Data Wrangler；查偏见＝Clarify。","en":""},"keywords":["Model Cards","Data Wrangler","Clarify"]},{"id":268,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"A company is building a generative AI tool. The company will use internal documents to customize a\nfoundation model (FM).\nWhich approach will meet this requirement?","zh":"某公司正在构建一个生成式 AI 工具。该公司将使用内部文档来自定义基础模型（FM）。哪种方法能满足此要求？"},"options":[{"key":"A","en":"Classification","zh":"分类"},{"key":"B","en":"Continued pre-training","zh":"持续预训练"},{"key":"C","en":"Distillation","zh":"蒸馏"},{"key":"D","en":"Regression","zh":"回归"}],"explanation":{"en":"Continued pre-training involves further training a foundation model (FM) on internal documents, allowing\nthe model to better understand and generate content specific to the company's context and requirements.\nThis approach customizes the FM using the company’s own data.","zh":"持续预训练是指使用内部文档对基础模型（FM）进行进一步训练，使模型更好地理解和生成与公司背景和需求相关的内容。这种方法使用公司自有数据来自定义 FM。"},"tip":{"zh":"用大批内部文档让模型“继续学习” → 持续预训练，不是分类回归。","en":""},"keywords":["持续预训练","自定义 FM","内部文档"]},{"id":269,"type":"single","answer":["C"],"topic":"eval","stem":{"en":"A company is monitoring a predictive model by using Amazon SageMaker Model Monitor. The company\nnotices data drift beyond a defined threshold. The company wants to mitigate a potentially adverse impact\non the predictive model.\nWhich solution will meet these requirements?","zh":"某公司正在使用 Amazon SageMaker Model Monitor 监控预测模型。该公司注意到数据漂移超出了定义的阈值。该公司希望减轻对预测模型的潜在不利影响。哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Restart the SageMaker AI endpoint.","zh":"重启 SageMaker AI 端点。"},{"key":"B","en":"Adjust the monitoring sensitivity.","zh":"调整监控灵敏度。"},{"key":"C","en":"Re-train the model with fresh data.","zh":"使用新数据重新训练模型。"},{"key":"D","en":"Set up experiments tracking.","zh":"设置实验跟踪。"}],"explanation":{"en":"When Amazon SageMaker Model Monitor detects data drift beyond a defined threshold, it indicates that\nthe current data differs from what the model was trained on. Retraining the model with recent data ensures\nit adapts to new patterns and maintains predictive accuracy.","zh":"当 Amazon SageMaker Model Monitor 检测到数据漂移超出定义的阈值时，表明当前数据与模型训练时所用的数据存在差异。使用最新数据重新训练模型可确保模型适应新模式并保持预测准确性。"},"tip":{"zh":"检测到数据漂移 → 用新数据重训；重启端点、调灵敏度都不解决根因。","en":""},"keywords":["数据漂移","Model Monitor","重新训练"]},{"id":270,"type":"single","answer":["B"],"topic":"responsible","stem":{"en":"A financial company uses a generative AI model to assign credit limits to new customers. The company\nwants to make the decision-making process of the model more transparent to its customers.\nWhich solution meets these requirements?","zh":"某金融公司使用生成式 AI 模型为新客户分配信用额度。该公司希望使模型的决策过程对客户更加透明。哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Use a rule-based system instead of an ML model.","zh":"使用基于规则的系统代替机器学习模型。"},{"key":"B","en":"Apply explainable AI techniques to show customers which factors influenced the model’s decision.","zh":"应用可解释 AI 技术，向客户展示哪些因素影响了模型的决策。"},{"key":"C","en":"Develop an interactive UI for customers and provide clear technical explanations about the system.","zh":"为客户开发交互式 UI，并提供关于系统的清晰技术说明。"},{"key":"D","en":"Increase the accuracy of the model to reduce the need for transparency.","zh":"提高模型的准确率，以减少对透明度的需求。"}],"explanation":{"en":"Explainable AI techniques provide transparency by identifying and displaying the specific factors that\ninfluenced the generative AI model’s credit limit decisions, making the decision-making process\nunderstandable to customers.","zh":"可解释 AI 技术通过识别并展示影响生成式 AI 模型信用额度决策的具体因素来提供透明度，使决策过程对客户而言可理解。"},"tip":{"zh":"要透明 → 用可解释 AI 展示影响决策的因素；准确率高不等于透明。","en":""},"keywords":["可解释 AI","透明度","信用额度决策"]},{"id":271,"type":"single","answer":["B"],"topic":"sagemaker","stem":{"en":"A company deployed a model to production. After 4 months, the model inference quality degraded. The\ncompany wants to receive a notification if the model inference quality degrades. The company also wants\nto ensure that the problem does not happen again.\nWhich solution will meet these requirements?","zh":"某公司将模型部署到了生产环境。4 个月后，模型推理质量下降。该公司希望在模型推理质量下降时收到通知。该公司还希望确保该问题不再发生。哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Retrain the model. Monitor model drift by using Amazon SageMaker Clarify.","zh":"重新训练模型。使用 Amazon SageMaker Clarify 监控模型漂移。"},{"key":"B","en":"Retrain the model. Monitor model drift by using Amazon SageMaker Model Monitor.","zh":"重新训练模型。使用 Amazon SageMaker Model Monitor 监控模型漂移。"},{"key":"C","en":"Build a new model. Monitor model drift by using Amazon SageMaker Feature Store.","zh":"构建新模型。使用 Amazon SageMaker Feature Store 监控模型漂移。"},{"key":"D","en":"Build a new model. Monitor model drift by using Amazon SageMaker JumpStart.","zh":"构建新模型。使用 Amazon SageMaker JumpStart 监控模型漂移。"}],"explanation":{"en":"Amazon SageMaker Model Monitor enables continuous monitoring of model inference quality and detects\ndata/model drift in production. Setting up notifications ensures the company is alerted if quality degrades\nagain, allowing timely intervention and retraining as needed.","zh":"Amazon SageMaker Model Monitor 可对模型推理质量进行持续监控，并检测生产环境中的数据/模型漂移。设置通知可确保在公司质量再次下降时收到告警，从而及时介入并在需要时重新训练。"},"tip":{"zh":"监控生产漂移＋告警 → Model Monitor；Clarify 管偏见解释，不管漂移。","en":""},"keywords":["Model Monitor","模型漂移","质量告警"]},{"id":272,"type":"single","answer":["A"],"topic":"data","stem":{"en":"Which option is an example of unsupervised learning?","zh":"哪个选项是无监督学习的示例？"},"options":[{"key":"A","en":"A model that groups customers based on their purchase history","zh":"根据客户的购买历史对客户进行分组的模型"},{"key":"B","en":"A model that classifies images as dogs or cats","zh":"将图像分类为狗或猫的模型"},{"key":"C","en":"A model that predicts a house’s price based on various features","zh":"根据各种特征预测房屋价格的模型"},{"key":"D","en":"A model that learns to play chess by using trial and error","zh":"通过试错学习下棋的模型"}],"explanation":{"en":"Grouping customers based on purchase history is an example of unsupervised learning, where the model\ndiscovers patterns or clusters in the data without using labeled outputs.","zh":"根据购买历史对客户进行分组是无监督学习的示例，模型在不使用标注输出的情况下发现数据中的模式或聚类。"},"tip":{"zh":"无监督＝没有标签，靠聚类自己找结构；分类、回归、强化学习都不是。","en":""},"keywords":["无监督学习","客户分组","聚类"]},{"id":273,"type":"single","answer":["C"],"topic":"eval","stem":{"en":"A company is evaluating several large language models (LLMs) for a text summarization task. The\ncompany needs to select a metric to evaluate the quality of the summaries that the LLMs generate.\nWhich metric will meet this requirement?","zh":"某公司正在为文本摘要任务评估多个大型语言模型（LLM）。该公司需要选择一个指标来评估 LLM 生成摘要的质量。哪个指标能满足此要求？"},"options":[{"key":"A","en":"Recall","zh":"召回率"},{"key":"B","en":"Area under the ROC curve (AUC)","zh":"ROC 曲线下面积（AUC）"},{"key":"C","en":"Recall-Oriented Understudy for Gisting Evaluation (ROUGE)","zh":"面向召回率的摘要评估替身（ROUGE）"},{"key":"D","en":"Mean squared error (MSE)","zh":"均方误差（MSE）"}],"explanation":{"en":"The ROUGE metric is widely used to evaluate the quality of summaries generated by language models, as\nit measures the overlap between the generated summary and reference summaries in terms of recall,\nprecision, and F1-score for n-grams and sequences.","zh":"ROUGE 指标广泛用于评估语言模型生成的摘要质量，它通过 n-gram 和序列的召回率、精确率和 F1 分数来衡量生成摘要与参考摘要之间的重叠程度。"},"tip":{"zh":"评摘要质量 → ROUGE；召回率、AUC、MSE 都是分类或回归指标。","en":""},"keywords":["ROUGE","摘要评估","文本生成指标"]},{"id":274,"type":"single","answer":["C"],"topic":"responsible","stem":{"en":"A research group wants to test different generative AI models to create research papers. The research\ngroup has defined a prompt and needs a method to assess the models’ output. The research group wants\nto use a team of scientists to perform the output assessments.\nWhich solution will meet these requirements?","zh":"某研究小组希望测试不同的生成式 AI 模型来撰写研究论文。该研究小组已定义了一个提示，并需要一种方法来评估模型的输出。该研究小组希望由一组科学家来执行输出评估。哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Use automatic evaluation on Amazon Personalize.","zh":"在 Amazon Personalize 上使用自动评估。"},{"key":"B","en":"Use content moderation on Amazon Rekognition.","zh":"在 Amazon Rekognition 上使用内容审核。"},{"key":"C","en":"Use model evaluation on Amazon Bedrock.","zh":"在 Amazon Bedrock 上使用模型评估。"},{"key":"D","en":"Use sentiment analysis on Amazon Comprehend.","zh":"在 Amazon Comprehend 上使用情感分析。"}],"explanation":{"en":"Amazon Bedrock provides model evaluation capabilities, allowing a team of scientists to manually assess\nand compare the outputs of different generative AI models based on defined prompts and criteria. This\nmeets the requirement for human-in-the-loop model output evaluation.","zh":"Amazon Bedrock 提供模型评估能力，允许一组科学家根据定义的提示和标准手动评估并比较不同生成式 AI 模型的输出。这满足了人在回路的模型输出评估要求。"},"tip":{"zh":"要人工评生成式模型输出 → Bedrock 模型评估（支持人工评审）。","en":""},"keywords":["模型评估","Amazon Bedrock","人在回路"]},{"id":275,"type":"hotspot","answer":[],"topic":"eval","stem":{"en":"An ecommerce company is developing a generative AI solution to create personalized product\nrecommendations for its application users. The company wants to track how effectively the AI solution\nincreases product sales and user engagement in the application.\nSelect the correct business metric from the following list for each business goal. Each business metric\nshould be selected one time.","zh":"某电商公司正在开发一个生成式 AI 解决方案，为其应用程序用户创建个性化产品推荐。该公司希望跟踪该 AI 解决方案在多大程度上有效提升了应用程序中的产品销售和用户参与度。请从以下列表中为每个业务目标选择正确的业务指标。每个业务指标各选一次。"},"options":[],"explanation":{"en":"Measure how engaging the product recommendations are to users -> Click-through rate (CTR)\nDetermine the effect of the AI solution on the total value of user purchases -> Average order value (AOV)\nAssess the AI solution's ability to encourage users to return to the platform -> Retention rate\nCTR reflects engagement with recommendations.\nAOV measures the impact on purchase value.\nRetention rate evaluates if users are returning due to the AI solution.","zh":"衡量产品推荐对用户的吸引力 -> 点击率（CTR）\n确定 AI 解决方案对用户购买总价值的影响 -> 平均订单价值（AOV）\n评估 AI 解决方案促使用户回访平台的能力 -> 留存率\nCTR 反映用户对推荐的参与程度。\nAOV 衡量对购买价值的影响。\n留存率评估用户是否因该 AI 解决方案而回访。"},"tip":{"zh":"吸引力＝CTR；客单价＝AOV；回访＝留存率，三个指标对应三个目标。","en":""},"keywords":["CTR","AOV","留存率","业务指标"]},{"id":276,"type":"single","answer":["D"],"topic":"responsible","stem":{"en":"An AI practitioner wants to evaluate ML models. The AI practitioner wants to provide explanations of model\npredictions to customers and stakeholders.\nWhich AWS service or feature will meet these requirements?","zh":"一位 AI 从业者希望评估机器学习模型。该 AI 从业者希望向客户和利益相关者提供模型预测的解释。哪项 AWS 服务或功能能满足这些要求？"},"options":[{"key":"A","en":"Amazon QuickSight","zh":"Amazon QuickSight"},{"key":"B","en":"Amazon Comprehend","zh":"Amazon Comprehend"},{"key":"C","en":"AWS Trusted Advisor","zh":"AWS Trusted Advisor"},{"key":"D","en":"Amazon SageMaker Clarify","zh":"Amazon SageMaker Clarify"}],"explanation":{"en":"Amazon SageMaker Clarify provides tools to explain model predictions, allowing practitioners to generate\nand share interpretability reports with customers and stakeholders, improving transparency and trust in ML\nmodels.","zh":"Amazon SageMaker Clarify 提供解释模型预测的工具，使从业者能够生成可解释性报告并与客户和利益相关者共享，从而提高机器学习模型的透明度和信任度。"},"tip":{"zh":"要解释模型预测、出可解释性报告 → SageMaker Clarify。","en":""},"keywords":["SageMaker Clarify","可解释性","预测解释"]},{"id":277,"type":"single","answer":["C"],"topic":"general","stem":{"en":"Sentiment analysis is a subset of which broader field of AI?","zh":"情感分析是哪个更广泛 AI 领域的子集？"},"options":[{"key":"A","en":"Computer vision","zh":"计算机视觉"},{"key":"B","en":"Robotics","zh":"机器人技术"},{"key":"C","en":"Natural language processing (NLP)","zh":"自然语言处理（NLP）"},{"key":"D","en":"Time series forecasting","zh":"时间序列预测"}],"explanation":{"en":"Sentiment analysis is a subset of natural language processing (NLP), which focuses on analyzing and\ninterpreting human language, including the detection of sentiment within text.","zh":"情感分析是自然语言处理（NLP）的子集，NLP 侧重于分析和解释人类语言，包括检测文本中的情感。"},"tip":{"zh":"情感分析处理文本语言 → 属于 NLP，不是计算机视觉。","en":""},"keywords":["情感分析","NLP","AI 领域划分"]},{"id":278,"type":"single","answer":["D"],"topic":"security","stem":{"en":"A company wants to set up private access to Amazon Bedrock APIs from the company’s AWS account.\nThe company also wants to protect its data from internet exposure. Which solution meets these\nrequirements?","zh":"某公司希望从其 AWS 账户建立对 Amazon Bedrock API 的私有访问。该公司还希望保护其数据免遭互联网暴露。哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Use Amazon CloudFront to restrict access to the company’s private content.","zh":"使用 Amazon CloudFront 限制对公司私有内容的访问。"},{"key":"B","en":"Use AWS Glue to set up data encryption across the company’s data catalog.","zh":"使用 AWS Glue 在公司数据目录中设置数据加密。"},{"key":"C","en":"Use AWS Lake Formation to manage centralized data governance and cross-account data sharing.","zh":"使用 AWS Lake Formation 管理集中式数据治理和跨账户数据共享。"},{"key":"D","en":"Use AWS PrivateLink to configure a private connection between the company’s VPC and Amazon Bedrock.","zh":"使用 AWS PrivateLink 在公司 VPC 与 Amazon Bedrock 之间配置私有连接。"}],"explanation":{"en":"AWS PrivateLink enables private connectivity between your VPC and Amazon Bedrock APIs without\nexposing data to the public internet, ensuring that all API calls and data transfers remain secure and\nprivate within your AWS account.","zh":"AWS PrivateLink 在您的 VPC 与 Amazon Bedrock API 之间实现私有连接，而不会将数据暴露到公共互联网，确保所有 API 调用和数据传输在您的 AWS 账户内保持安全私密。"},"tip":{"zh":"私有访问 Bedrock API、数据不出公网 → PrivateLink 建 VPC 私有连接。","en":""},"keywords":["AWS PrivateLink","私有访问","Amazon Bedrock"]},{"id":279,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"A company receives a large amount of unstructured user feedback in text format. The company wants to\nanalyze the sentiment of the user feedback. Which solution will meet these requirements?","zh":"某公司收到大量文本格式的非结构化用户反馈。该公司希望分析用户反馈的情感。哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Use a large language model (LLM) to perform natural language processing (NLP) for sentiment analysis.","zh":"使用大型语言模型（LLM）执行自然语言处理（NLP）以进行情感分析。"},{"key":"B","en":"Use a regression algorithm to classify the feedback based on predefined categories. Then, analyze user sentiment.","zh":"使用回归算法根据预定义类别对反馈进行分类。然后分析用户情感。"},{"key":"C","en":"Use a recommendation engine algorithm to detect user sentiment.","zh":"使用推荐引擎算法检测用户情感。"},{"key":"D","en":"Use a time series algorithm to predict user sentiment based on past feedback.","zh":"使用时间序列算法根据过去的反馈预测用户情感。"}],"explanation":{"en":"A large language model (LLM) can analyze unstructured text using NLP techniques to accurately\ndetermine the sentiment (positive, negative, or neutral) of user feedback. This approach is well-suited for\nhandling large volumes of text data.","zh":"大型语言模型（LLM）可以使用 NLP 技术分析非结构化文本，准确判断用户反馈的情感（正面、负面或中性）。这种方法非常适合处理大量文本数据。"},"tip":{"zh":"非结构化文本判情感 → LLM＋NLP；回归、推荐、时间序列都不对口。","en":""},"keywords":["情感分析","LLM","非结构化文本"]},{"id":280,"type":"hotspot","answer":[],"topic":"genai","stem":{"en":"A company wants to improve multiple ML models.\nSelect the correct technique from the following list of use cases. Each technique should be selected one\ntime or not at all.","zh":"某公司希望改进多个机器学习模型。请从以下用例列表中为每个用例选择正确的技术。每种技术各选一次或不选。"},"options":[],"explanation":{"en":"Enhancing the capabilities of a large language model (LLM) by using external sources -> Retrieval\nAugmented Generation (RAG)\nQuerying a model to generalize and make predictions on unseen tasks -> Zero-shot learning\nQuerying a model with a limited amount of data for new tasks -> Few-shot learning\nRAG improves LLMs by incorporating information from external data sources at query time.\nZero-shot learning allows a model to perform tasks it wasn't explicitly trained on, using generalization.\nFew-shot learning enables a model to handle new tasks with only a small number of examples.","zh":"通过外部来源增强大型语言模型（LLM）的能力 -> 检索增强生成（RAG）\n查询模型以泛化并对未见任务做出预测 -> 零样本学习\n用有限的数据查询模型以完成新任务 -> 少样本学习\nRAG 通过在查询时引入来自外部数据源的信息来改进 LLM。\n零样本学习允许模型通过泛化执行其未明确训练过的任务。\n少样本学习使模型仅用少量示例即可处理新任务。"},"tip":{"zh":"接外部知识＝RAG；一个例子都不给＝零样本；给几个例子＝少样本。","en":""},"keywords":["RAG","零样本学习","少样本学习"]},{"id":281,"type":"single","answer":["D"],"topic":"eval","stem":{"en":"A company wants to create an AI solution to generate images and descriptions for a product catalog. The\ncompany needs to select a foundation model (FM) for this solution.\nThe company must consider the output types of each FM.\nWhich FM characteristic is the company evaluating?","zh":"某公司希望创建一个 AI 解决方案，为产品目录生成图像和描述。该公司需要为此解决方案选择基础模型（FM）。该公司必须考虑每个 FM 的输出类型。该公司正在评估哪个 FM 特征？"},"options":[{"key":"A","en":"Latency","zh":"延迟"},{"key":"B","en":"Model size","zh":"模型大小"},{"key":"C","en":"Model customization","zh":"模型自定义"},{"key":"D","en":"Modality","zh":"模态（modality）"}],"explanation":{"en":"Modality refers to the types of input and output data a foundation model can handle, such as text, images,\nor both. Evaluating modality ensures the selected FM can generate both images and text descriptions for\nthe product catalog.","zh":"模态（modality）指基础模型可以处理的输入和输出数据类型，例如文本、图像或两者兼有。评估模态可确保所选的 FM 能够为产品目录生成图像和文本描述。"},"tip":{"zh":"看模型能输入输出什么类型（文本/图像） → 就是模态（modality）。","en":""},"keywords":["模态","FM 特征","输入输出类型"]},{"id":282,"type":"single","answer":["D"],"topic":"eval","stem":{"en":"A company wants to use an ML model to analyze customer reviews on social media. The model must\ndetermine if each review has a neutral, positive, or negative sentiment.\nWhich model evaluation strategy will meet these requirements?","zh":"某公司希望使用机器学习模型分析社交媒体上的客户评论。该模型必须判断每条评论的情感是中性、正面还是负面。哪种模型评估策略能满足这些要求？"},"options":[{"key":"A","en":"Open-ended generation","zh":"开放式生成"},{"key":"B","en":"Text summarization","zh":"文本摘要"},{"key":"C","en":"Machine translation","zh":"机器翻译"},{"key":"D","en":"Classification","zh":"分类"}],"explanation":{"en":"Classification is the evaluation strategy that assigns input data (such as customer reviews) to predefined\ncategories - in this case, neutral, positive, or negative sentiment. This approach is standard for sentiment\nanalysis tasks.","zh":"分类是将输入数据（例如客户评论）分配到预定义类别的评估策略——在本例中为中性、正面或负面情感。这是情感分析任务的标准方法。"},"tip":{"zh":"输出固定几类（中性/正面/负面） → 分类任务，不是生成。","en":""},"keywords":["分类","情感分析","评估策略"]},{"id":283,"type":"hotspot","answer":[],"topic":"general","stem":{"en":"Select the correct AI term from the following list for each statement. Each AI term should be selected one\ntime.","zh":"请从以下列表中为每个陈述选择正确的 AI 术语。每个 AI 术语各选一次。"},"options":[],"explanation":{"en":"Simulates human problem-solving capabilities -> AI\nApplies data-driven learning techniques to make predictions -> ML\nFocuses on processing data through intricate neural networks -> Deep learning\nAI (Artificial Intelligence) is the broadest concept and includes simulating human-like reasoning and\nproblem-solving.\nML (Machine Learning) is a subset of AI focused on learning from data to make predictions or decisions.\nDeep learning is a subset of ML that uses neural networks with many layers to process complex data.","zh":"模拟人类解决问题的能力 -> AI\n应用数据驱动的学习技术来做出预测 -> ML\n侧重于通过复杂的神经网络处理数据 -> 深度学习\nAI（人工智能）是范围最广的概念，包含模拟类人推理与问题解决。\nML（机器学习）是 AI 的子集，侧重于从数据中学习以做出预测或决策。\n深度学习是 ML 的子集，使用具有多层的神经网络来处理复杂数据。"},"tip":{"zh":"范围：AI ⊃ ML ⊃ 深度学习；模拟人类能力＝AI，数据学习＝ML，深网络＝DL。","en":""},"keywords":["AI","机器学习","深度学习","概念层级"]},{"id":284,"type":"single","answer":["A"],"topic":"data","stem":{"en":"Which option is an example of unsupervised learning?","zh":"哪个选项是无监督学习的示例？"},"options":[{"key":"A","en":"Clustering data points into groups based on their similarity","zh":"根据数据点的相似性将其聚类分组"},{"key":"B","en":"Training a model to recognize images of animals","zh":"训练模型识别动物图像"},{"key":"C","en":"Predicting the price of a house based on the house’s features","zh":"根据房屋特征预测房屋价格"},{"key":"D","en":"Generating human-like text based on a given prompt","zh":"根据给定提示生成类人文本"}],"explanation":{"en":"Clustering data points based on similarity is an example of unsupervised learning, where the algorithm\ngroups data without using labeled examples.","zh":"根据相似性对数据点进行聚类是无监督学习的示例，算法在不使用标注示例的情况下对数据进行分组。"},"tip":{"zh":"无监督＝无标签，靠相似度聚类；识别图像、预测价格都是有监督。","en":""},"keywords":["无监督学习","聚类","相似性"]},{"id":285,"type":"single","answer":["C"],"topic":"services","stem":{"en":"An online learning company with large volumes of education materials wants to use enterprise search.\nWhich AWS service meets these requirements?","zh":"某在线学习公司拥有大量教育资料，希望使用企业搜索。哪项 AWS 服务能满足这些要求？"},"options":[{"key":"A","en":"Amazon Comprehend","zh":"Amazon Comprehend"},{"key":"B","en":"Amazon Textract","zh":"Amazon Textract"},{"key":"C","en":"Amazon Kendra","zh":"Amazon Kendra"},{"key":"D","en":"Amazon Personalize","zh":"Amazon Personalize"}],"explanation":{"en":"Amazon Kendra is an intelligent enterprise search service that enables organizations to search large\nvolumes of unstructured data, such as educational materials, making it ideal for enterprise search needs.","zh":"Amazon Kendra 是一项智能企业搜索服务，使组织能够搜索大量非结构化数据（例如教育资料），非常适合企业搜索需求。"},"tip":{"zh":"企业搜索、非结构化文档检索 → Amazon Kendra。","en":""},"keywords":["Amazon Kendra","企业搜索","非结构化数据"]},{"id":286,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"A company creates video content. The company wants to use generative AI to generate new creative\ncontent and to reduce video creation time.\nWhich solution will meet these requirements in the MOST operationally efficient way?","zh":"某公司制作视频内容。该公司希望使用生成式 AI 生成新的创意内容并缩短视频制作时间。哪种解决方案能以最具运营效率的方式满足这些要求？"},"options":[{"key":"A","en":"Use the Amazon Titan Image Generator model on Amazon Bedrock to generate intermediate images. Use video editing software to create videos.","zh":"使用 Amazon Bedrock 上的 Amazon Titan Image Generator 模型生成中间图像。使用视频编辑软件制作视频。"},{"key":"B","en":"Use the Amazon Nova Canvas model on Amazon Bedrock to generate intermediate images. Use video editing software to create videos.","zh":"使用 Amazon Bedrock 上的 Amazon Nova Canvas 模型生成中间图像。使用视频编辑软件制作视频。"},{"key":"C","en":"Use the Amazon Nova Reel model on Amazon Bedrock to generate videos.","zh":"使用 Amazon Bedrock 上的 Amazon Nova Reel 模型生成视频。"},{"key":"D","en":"Use the Amazon Nova Pro model on Amazon Bedrock to generate videos.","zh":"使用 Amazon Bedrock 上的 Amazon Nova Pro 模型生成视频。"}],"explanation":{"en":"The Amazon Nova Reel model on Amazon Bedrock is specifically designed for generative video creation,\nenabling the company to efficiently generate new creative content and significantly reduce video creation\ntime in an operationally efficient manner.","zh":"Amazon Bedrock 上的 Amazon Nova Reel 模型专为生成式视频创作而设计，使公司能够以运营高效的方式高效生成新的创意内容并显著缩短视频制作时间。"},"tip":{"zh":"直接生成视频 → Nova Reel；Canvas 出图，Pro 出文本，都要再剪辑。","en":""},"keywords":["Nova Reel","视频生成","运营效率"]},{"id":287,"type":"single","answer":["D"],"topic":"eval","stem":{"en":"A company is training ML models on datasets. The datasets contain some classes that have more\nexamples than other classes. The company wants to measure how well the model balances detecting and\nlabeling the classes.\nWhich metric should the company use?","zh":"某公司正在数据集上训练机器学习模型。数据集中某些类别的样本多于其他类别。该公司希望衡量模型在检测和标注各类别方面的平衡程度。该公司应使用哪个指标？"},"options":[{"key":"A","en":"Accuracy","zh":"准确率"},{"key":"B","en":"Recall","zh":"召回率"},{"key":"C","en":"Precision","zh":"精确率"},{"key":"D","en":"F1 score","zh":"F1 分数"}],"explanation":{"en":"The F1 score is the harmonic mean of precision and recall, making it especially useful for evaluating model\nperformance on datasets with class imbalance. It measures how well the model balances detecting (recall)\nand correctly labeling (precision) all classes.","zh":"F1 分数是精确率和召回率的调和平均值，因此特别适用于评估类别不平衡数据集上的模型性能。它衡量模型在检测（召回率）和正确标注（精确率）所有类别方面的平衡程度。"},"tip":{"zh":"类别不平衡＋兼顾检出与标注 → F1（精确率与召回率的调和均值）。","en":""},"keywords":["F1 分数","类别不平衡","精确率与召回率"]},{"id":288,"type":"single","answer":["B"],"topic":"data","stem":{"en":"A company is analyzing financial transaction records. The company categorizes the records as either\npersonal or business. The company inserts the categories into the transaction records.\nWhich data preparation step does this describe?","zh":"某公司正在分析财务交易记录。该公司将记录归类为个人或企业。该公司将类别插入到交易记录中。这描述的是哪个数据准备步骤？"},"options":[{"key":"A","en":"Data encoding","zh":"数据编码"},{"key":"B","en":"Data labeling","zh":"数据标注"},{"key":"C","en":"Data normalization","zh":"数据归一化"},{"key":"D","en":"Data balancing","zh":"数据平衡"}],"explanation":{"en":"Assigning categories such as \"personal\" or \"business\" to financial transaction records is an example of\ndata labeling, where each data point is tagged with a specific label for use in machine learning or data\nanalysis tasks.","zh":"为财务交易记录指定“个人”或“企业”等类别是数据标注的示例，即给每个数据点打上特定标签，以便用于机器学习或数据分析任务。"},"tip":{"zh":"给数据打上类别标签 → 数据标注（labeling）；编码是转成数值。","en":""},"keywords":["数据标注","打标签","数据准备"]},{"id":289,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"A company wants to extract key insights from large policy documents to increase employee efficiency.\nWhich generative AI strategy meets this requirement?","zh":"某公司希望从大量政策文档中提取关键洞察，以提高员工效率。哪种生成式 AI 策略能满足此要求？"},"options":[{"key":"A","en":"Regression","zh":"回归"},{"key":"B","en":"Clustering","zh":"聚类"},{"key":"C","en":"Summarization","zh":"摘要"},{"key":"D","en":"Classification","zh":"分类"}],"explanation":{"en":"Summarization is a generative AI strategy that extracts and condenses the key insights from large\ndocuments, such as policy documents, making it easier for employees to quickly understand and act on\nessential information.","zh":"摘要是一种生成式 AI 策略，可提取并浓缩大型文档（例如政策文档）中的关键洞察，使员工更容易快速理解并依据关键信息采取行动。"},"tip":{"zh":"长文档提炼要点 → 摘要（summarization），回归聚类分类都不生成内容。","en":""},"keywords":["摘要","生成式 AI 策略","长文档"]},{"id":290,"type":"single","answer":["B"],"topic":"responsible","stem":{"en":"A company is using Amazon SageMaker to deploy a model that identifies if social media posts contain\ncertain topics. The company needs to show how different input features influence model behavior.\nWhich SageMaker feature meets these requirements?","zh":"某公司正在使用 Amazon SageMaker 部署一个模型，用于识别社交媒体帖子是否包含某些主题。该公司需要展示不同输入特征如何影响模型行为。哪项 SageMaker 功能能满足这些要求？"},"options":[{"key":"A","en":"SageMaker Canvas","zh":"SageMaker Canvas"},{"key":"B","en":"SageMaker Clarify","zh":"SageMaker Clarify"},{"key":"C","en":"SageMaker Feature Store","zh":"SageMaker Feature Store"},{"key":"D","en":"SageMaker Ground Truth","zh":"SageMaker Ground Truth"}],"explanation":{"en":"SageMaker Clarify provides tools for model interpretability, allowing you to visualize and understand how\ndifferent input features influence the behavior and predictions of your deployed model.","zh":"SageMaker Clarify 提供模型可解释性工具，使您能够可视化并理解不同输入特征如何影响已部署模型的行为和预测。"},"tip":{"zh":"看特征对模型行为的影响 → SageMaker Clarify（可解释性）。","en":""},"keywords":["SageMaker Clarify","特征影响","可解释性"]},{"id":291,"type":"hotspot","answer":[],"topic":"services","stem":{"en":"An AI practitioner is determining the appropriate data type for various use cases.\nSelect the correct data type from the following list for each use case. Select each data type one time.","zh":"一位 AI 从业者正在为各种用例确定合适的数据类型。请从以下列表中为每个用例选择正确的数据类型。每种数据类型各选一次。"},"options":[],"explanation":{"en":"Build a sentiment analysis model for social media posts -> Text data\nTrain a self-driving car to recognize traffic signs -> Image data\nOptimize ad campaigns by using customer demographic data and purchase history -> Tabular data\nForecast stock prices by using historical price data -> Time series data\nSentiment analysis deals with text data from social media posts.\nRecognizing traffic signs requires processing image data.\nOptimizing ad campaigns uses structured (tabular) customer and purchase data.\nStock price forecasting uses time series data, which captures trends over time.","zh":"为社交媒体帖子构建情感分析模型 -> 文本数据\n训练自动驾驶汽车识别交通标志 -> 图像数据\n使用客户人口统计数据和购买历史优化广告活动 -> 表格数据\n使用历史价格数据预测股票价格 -> 时间序列数据\n情感分析处理来自社交媒体帖子的文本数据。\n识别交通标志需要处理图像数据。\n优化广告活动使用结构化（表格）客户和购买数据。\n股票价格预测使用时间序列数据，它捕捉随时间变化的趋势。"},"tip":{"zh":"帖子＝文本；交通标志＝图像；人口统计表＝表格；股价按时间＝时间序列。","en":""},"keywords":["数据类型","文本数据","图像数据","时间序列数据"]},{"id":292,"type":"single","answer":["C"],"topic":"general","stem":{"en":"A company wants to assess internet quality in remote areas of the world. The company needs to collect\ninternet speed data and store the data in Amazon RDS. The company will analyze internet speed variation\nthroughout each day. The company wants to create an AI model to predict potential internet disruptions.\nWhich type of data should the company collect for this task?","zh":"某公司希望评估世界偏远地区的互联网质量。该公司需要收集互联网速度数据，并将数据存储在 Amazon RDS 中。该公司将分析一天中互联网速度的变化。该公司希望创建一个 AI 模型来预测潜在的互联网中断。该公司应为此任务收集哪种类型的数据？"},"options":[{"key":"A","en":"Tabular data","zh":"表格数据"},{"key":"B","en":"Text data","zh":"文本数据"},{"key":"C","en":"Time series data","zh":"时间序列数据"},{"key":"D","en":"Audio data","zh":"音频数据"}],"explanation":{"en":"Time series data consists of measurements (such as internet speed) collected over time, which is\nessential for analyzing variations throughout the day and for building predictive models of potential internet\ndisruptions.","zh":"时间序列数据由随时间收集的测量值（例如互联网速度）组成，这对于分析一天中的变化以及构建预测潜在互联网中断的模型至关重要。"},"tip":{"zh":"按时间连续采集的速度值 → 时间序列数据，才能看出一日变化趋势。","en":""},"keywords":["时间序列数据","随时间测量","趋势分析"]},{"id":293,"type":"single","answer":["D"],"topic":"data","stem":{"en":"A company wants to build an ML model to detect abnormal patterns in sensor data. The company does not\nhave labeled data for training.\nWhich ML method will meet these requirements?","zh":"某公司希望构建一个机器学习模型来检测传感器数据中的异常模式。该公司没有用于训练的标注数据。哪种机器学习方法能满足这些要求？"},"options":[{"key":"A","en":"Linear regression","zh":"线性回归"},{"key":"B","en":"Classification","zh":"分类"},{"key":"C","en":"Decision tree","zh":"决策树"},{"key":"D","en":"Autoencoders","zh":"自编码器"}],"explanation":{"en":"Autoencoders are a type of unsupervised learning method used to detect abnormal patterns (anomalies) in\nsensor data when labeled data is not available. They learn to reconstruct normal patterns, making\ndeviations (anomalies) easily detectable.","zh":"自编码器是一种无监督学习方法，用于在没有标注数据时检测传感器数据中的异常模式（异常）。它们学习重建正常模式，使偏差（异常）易于检测。"},"tip":{"zh":"没有标注＋找异常 → 自编码器（无监督），学会重建正常样本。","en":""},"keywords":["自编码器","异常检测","无监督学习"]},{"id":294,"type":"single","answer":["A"],"topic":"eval","stem":{"en":"A company uses Amazon Bedrock to implement a generative AI assistant on a website. The AI assistant\nhelps customers with product recommendations and purchasing decisions.\nThe company wants to measure the direct impact of the AI assistant on sales performance.\nWhich metric will meet these requirements?","zh":"某公司使用 Amazon Bedrock 在网站上实现生成式 AI 助手。该 AI 助手帮助客户进行产品推荐和购买决策。该公司希望衡量该 AI 助手对销售业绩的直接影响力。哪个指标能满足这些要求？"},"options":[{"key":"A","en":"The conversion rate of customers who purchase products after AI assistant interactions.","zh":"与 AI 助手交互后购买产品的客户转化率。"},{"key":"B","en":"The number of customer interactions with the AI assistant","zh":"客户与 AI 助手的交互次数"},{"key":"C","en":"Sentiment analysis scores from customer feedback after AI assistant interactions","zh":"AI 助手交互后客户反馈的情感分析得分"},{"key":"D","en":"Natural language understanding accuracy rates","zh":"自然语言理解准确率"}],"explanation":{"en":"Conversion rate directly measures the impact of the AI assistant on sales performance by quantifying the\npercentage of customers who make a purchase after interacting with the assistant. This metric links AI\nengagement to actual sales outcomes.","zh":"转化率通过量化在与助手交互后完成购买的客户百分比，直接衡量 AI 助手对销售业绩的影响。该指标将 AI 参与度与实际销售成果联系起来。"},"tip":{"zh":"要衡量对销售额的直接拉动 → 看交互后的购买转化率，交互量只是过程指标。","en":""},"keywords":["转化率","销售业绩","业务指标"]},{"id":295,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"Which AWS service or feature stores embeddings in a vector database for use with foundation models\n(FMs) and Retrieval Augmented Generation (RAG)?","zh":"哪项 AWS 服务或功能将嵌入向量存储在向量数据库中，以供基础模型（FM）和检索增强生成（RAG）使用？"},"options":[{"key":"A","en":"Amazon SageMaker Ground Truth","zh":"Amazon SageMaker Ground Truth"},{"key":"B","en":"Amazon OpenSearch Service","zh":"Amazon OpenSearch Service"},{"key":"C","en":"Amazon Transcribe","zh":"Amazon Transcribe"},{"key":"D","en":"Amazon Textract","zh":"Amazon Textract"}],"explanation":{"en":"Amazon OpenSearch Service provides a vector database capability to store and search embeddings,\nwhich are essential for powering Retrieval Augmented Generation (RAG) workflows and integrating with\nfoundation models (FMs) in generative AI solutions.","zh":"Amazon OpenSearch Service 提供向量数据库能力来存储和搜索嵌入向量，这对于支撑检索增强生成（RAG）工作流以及集成生成式 AI 解决方案中的基础模型（FM）至关重要。"},"tip":{"zh":"存嵌入向量＋做向量检索供 RAG 用 → Amazon OpenSearch Service。","en":""},"keywords":["OpenSearch Service","嵌入向量","RAG"]},{"id":296,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"Which scenario represents a practical use case for generative AI?","zh":"哪个场景代表了生成式 AI 的实际用例？"},"options":[{"key":"A","en":"Using an ML model to forecast product demand","zh":"使用机器学习模型预测产品需求"},{"key":"B","en":"Employing a chatbot to provide human-like responses to customer queries in real time","zh":"采用聊天机器人实时为客户查询提供类人响应"},{"key":"C","en":"Using an analytics dashboard to track website traffic and user behavior","zh":"使用分析仪表板跟踪网站流量和用户行为"},{"key":"D","en":"Implementing a rule-based recommendation engine to suggest products to customers","zh":"实施基于规则的推荐引擎向客户推荐产品"}],"explanation":{"en":"A generative AI use case involves generating new content, such as natural language responses. A chatbot\nthat provides human-like responses to customer queries uses generative AI models (like large language\nmodels) to dynamically create relevant answers, making this a practical example.","zh":"生成式 AI 用例涉及生成新内容，例如自然语言响应。为客户查询提供类人响应的聊天机器人使用生成式 AI 模型（如大型语言模型）动态创建相关答案，因此这是一个实际示例。"},"tip":{"zh":"生成式 AI 的关键是“生成新内容”，如实时生成类人回答；预测需求不算。","en":""},"keywords":["生成式 AI","内容生成","聊天机器人"]},{"id":297,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"A company is using Amazon Bedrock for a generative AI solution. The solution must integrate a service\nwith vector database storage and vector search capabilities.\nWhich AWS service will meet these requirements?","zh":"某公司正在使用 Amazon Bedrock 构建生成式 AI 解决方案。该解决方案必须集成一个具有向量数据库存储和向量搜索能力的服务。哪项 AWS 服务能满足这些要求？"},"options":[{"key":"A","en":"Amazon DynamoDB","zh":"Amazon DynamoDB"},{"key":"B","en":"Amazon OpenSearch Service","zh":"Amazon OpenSearch Service"},{"key":"C","en":"Amazon ElastiCache","zh":"Amazon ElastiCache"},{"key":"D","en":"Amazon Redshift","zh":"Amazon Redshift"}],"explanation":{"en":"Amazon OpenSearch Service supports vector database storage and vector search capabilities, which are\nessential for integrating with generative AI solutions like those on Amazon Bedrock that require efficient\nsimilarity search over embeddings.","zh":"Amazon OpenSearch Service 支持向量数据库存储和向量搜索能力，这对于与 Amazon Bedrock 上需要高效嵌入向量相似性搜索的生成式 AI 解决方案集成至关重要。"},"tip":{"zh":"向量存储＋向量搜索 → OpenSearch Service；DynamoDB、Redshift 不是向量库。","en":""},"keywords":["OpenSearch Service","向量搜索","Bedrock 集成"]},{"id":298,"type":"single","answer":["D"],"topic":"services","stem":{"en":"A media streaming platform wants to provide movie recommendations to users based on the users’\naccount history.\nWhich AWS service meets these requirements?","zh":"某媒体流平台希望根据用户的账户历史向用户提供电影推荐。哪项 AWS 服务能满足这些要求？"},"options":[{"key":"A","en":"Amazon Polly","zh":"Amazon Polly"},{"key":"B","en":"Amazon Comprehend","zh":"Amazon Comprehend"},{"key":"C","en":"Amazon Transcribe","zh":"Amazon Transcribe"},{"key":"D","en":"Amazon Personalize","zh":"Amazon Personalize"}],"explanation":{"en":"Amazon Personalize is an AWS service designed to deliver personalized recommendations, such as\nmovie suggestions, to users based on their account history and preferences.","zh":"Amazon Personalize 是一项 AWS 服务，旨在根据用户的账户历史和偏好向用户提供个性化推荐，例如电影建议。"},"tip":{"zh":"个性化推荐（电影、商品） → Amazon Personalize。","en":""},"keywords":["Amazon Personalize","个性化推荐","推荐系统"]},{"id":299,"type":"single","answer":["B"],"topic":"responsible","stem":{"en":"A company has developed an ML model to approve or reject loan applications. The model’s decision-\nmaking process must be transparent and explainable to comply with regulatory requirements. The\ncompany must document the decision-making process for audit purposes.\nWhich solution will meet these requirements?","zh":"某公司开发了一个机器学习模型来批准或拒绝贷款申请。该模型的决策过程必须透明且可解释，以符合监管要求。该公司必须记录决策过程以供审计。哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Amazon Textract","zh":"Amazon Textract"},{"key":"B","en":"Amazon SageMaker Model Card","zh":"Amazon SageMaker Model Card"},{"key":"C","en":"AWS Cloud Formation","zh":"AWS Cloud Formation"},{"key":"D","en":"Amazon Comprehend","zh":"Amazon Comprehend"}],"explanation":{"en":"Amazon SageMaker Model Card enables you to document a model’s decision-making process, including\ntransparency and explainability details, which helps meet regulatory and audit requirements for AI-driven\ndecisions such as loan approvals.","zh":"Amazon SageMaker Model Card 使您能够记录模型的决策过程，包括透明度和可解释性细节，有助于满足 AI 驱动决策（例如贷款审批）的监管和审计要求。"},"tip":{"zh":"要记录模型信息供审计与合规 → SageMaker Model Card（模型卡片）。","en":""},"keywords":["Model Card","模型文档","审计合规"]},{"id":300,"type":"hotspot","answer":[],"topic":"genai","stem":{"en":"A company is building a generative AI application and is reviewing foundation models (FMs). The company\nneeds to consider multiple FM characteristics.\nSelect the correct FM characteristic from the following list for each definition. Each FM characteristic\nshould be selected one time.","zh":"某公司正在构建一个生成式 AI 应用程序，并正在评估基础模型（FM）。该公司需要考虑多个 FM 特征。请从以下列表中为每个定义选择正确的 FM 特征。每个 FM 特征各选一次。"},"options":[],"explanation":{"en":"Amount of information that can fit in a single prompt -> Context windows\nLength of time it takes for a model to generate an output -> Latency\nMultiple users invoking an application endpoint simultaneously -> Concurrency\nContext windows determine how much information the model can process at once.\nLatency is the response time for generating output.\nConcurrency measures how many users or requests the endpoint can handle at the same time.","zh":"单个提示中能容纳的信息量 -> 上下文窗口\n模型生成输出所需的时间长度 -> 延迟\n多个用户同时调用应用程序端点 -> 并发\n上下文窗口决定模型一次能处理多少信息。\n延迟是生成输出的响应时间。\n并发衡量端点同时能处理多少用户或请求。"},"tip":{"zh":"提示能装多少＝上下文窗口；出结果多快＝延迟；同时多少人用＝并发。","en":""},"keywords":["上下文窗口","延迟","并发","FM 特征"]},{"id":301,"type":"single","answer":["C"],"topic":"responsible","stem":{"en":"A company is using large language models (LLMs) to develop online tutoring applications. The company\nneeds to apply configurable safeguards to the LLMs. These safeguards must ensure that the LLMs follow\nstandard safety rules when creating applications.\nWhich solution will meet these requirements with the LEAST effort?","zh":"某公司正在使用大型语言模型（LLM）开发在线辅导应用。公司需要为这些 LLM 应用可配置的防护措施。这些防护措施必须确保 LLM 在创建应用时遵守标准安全规则。哪种解决方案能以最少的工作量满足这些要求？"},"options":[{"key":"A","en":"Amazon Bedrock playgrounds","zh":"Amazon Bedrock playgrounds"},{"key":"B","en":"Amazon SageMaker Clarify","zh":"Amazon SageMaker Clarify"},{"key":"C","en":"Amazon Bedrock Guardrails","zh":"Amazon Bedrock Guardrails"},{"key":"D","en":"Amazon SageMaker Jumpstart","zh":"Amazon SageMaker Jumpstart"}],"explanation":{"en":"Amazon Bedrock Guardrails provide configurable safeguards that enforce standard safety rules on large\nlanguage models (LLMs) with minimal effort, making it easy to ensure safe and compliant AI application\ndevelopment.","zh":"Amazon Bedrock Guardrails 提供可配置的防护措施，能以最少的工作量对大型语言模型（LLM）强制执行标准安全规则，从而轻松确保 AI 应用开发的安全性与合规性。"},"tip":{"zh":"要可配置的安全护栏又最省事，直接选 Bedrock Guardrails，不用重训模型。","en":""},"keywords":["护栏","内容过滤","最少工作量"]},{"id":302,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"A company is exploring Amazon Nova models in Amazon Bedrock. The company needs a multimodal\nmodel that supports multiple languages.\nWhich Nova model will meet these requirements MOST cost-effectively?","zh":"某公司正在探索 Amazon Bedrock 中的 Amazon Nova 模型。公司需要一个支持多种语言的多模态模型。哪种 Nova 模型能以最具成本效益的方式满足这些要求？"},"options":[{"key":"A","en":"Nova Lite","zh":"Nova Lite"},{"key":"B","en":"Nova Pro","zh":"Nova Pro"},{"key":"C","en":"Nova Canvas","zh":"Nova Canvas"},{"key":"D","en":"Nova Reel","zh":"Nova Reel"}],"explanation":{"en":"Nova Lite is a multimodal model in Amazon Bedrock that supports multiple languages and is designed to\nbe the most cost-effective option among the Nova models, making it suitable for organizations seeking\nefficient, scalable, and economical AI solutions.","zh":"Nova Lite 是 Amazon Bedrock 中的多模态模型，支持多种语言，并且是 Nova 系列中设计为最具成本效益的选项，适合寻求高效、可扩展且经济的 AI 解决方案的组织。"},"tip":{"zh":"Nova Lite＝便宜的多模态多语言模型；Canvas 出图、Reel 出视频，别选错。","en":""},"keywords":["Nova Lite","多模态","成本效益"]},{"id":303,"type":"single","answer":["B"],"topic":"responsible","stem":{"en":"A company is building a new generative AI chatbot. The chatbot uses an Amazon Bedrock foundation\nmodel (FM) to generate responses. During testing, the company notices that the chatbot is prone to\nprompt injection attacks.\nWhat can the company do to secure the chatbot with the LEAST implementation effort?","zh":"某公司正在构建一个新的生成式 AI 聊天机器人。该聊天机器人使用 Amazon Bedrock 基础模型（FM）生成回复。测试期间，公司发现该聊天机器人容易受到提示注入攻击。公司可以采取什么措施以最少的实施工作量保护该聊天机器人？"},"options":[{"key":"A","en":"Fine-tune the FM to avoid harmful responses.","zh":"微调 FM，以避免产生有害回复。"},{"key":"B","en":"Use Amazon Bedrock Guardrails content filters and denied topics.","zh":"使用 Amazon Bedrock Guardrails 的内容过滤器和被拒绝主题。"},{"key":"C","en":"Change the FM to a more secure FM.","zh":"将 FM 更换为更安全的 FM。"},{"key":"D","en":"Use chain-of-thought prompting to produce secure responses.","zh":"使用思维链提示来生成安全的回复。"}],"explanation":{"en":"Using Amazon Bedrock Guardrails' content filters and denied topics is the quickest and least effort solution\nto mitigate prompt injection attacks. These guardrails can be configured without model retraining, helping\nto automatically filter or block unsafe prompts and responses.","zh":"使用 Amazon Bedrock Guardrails 的内容过滤器和被拒绝主题是缓解提示注入攻击最快、工作量最少的方案。这些护栏无需重新训练模型即可配置，可自动过滤或阻止不安全的提示与回复。"},"tip":{"zh":"提示注入最省事的挡法：Guardrails 内容过滤＋被拒绝主题，无需微调。","en":""},"keywords":["提示注入","护栏","内容过滤器"]},{"id":304,"type":"single","answer":["B"],"topic":"sagemaker","stem":{"en":"What does inference refer to in the context of AI?","zh":"在 AI 语境中，推理（inference）指的是什么？"},"options":[{"key":"A","en":"The process of creating new AI algorithms","zh":"创建新 AI 算法的过程"},{"key":"B","en":"The use of a trained model to make predictions or decisions on unseen data","zh":"使用已训练的模型对未见过的数据进行预测或决策"},{"key":"C","en":"The process of combining multiple AI models into one model","zh":"将多个 AI 模型合并为一个模型的过程"},{"key":"D","en":"The method of collecting training data for AI systems","zh":"为 AI 系统收集训练数据的方法"}],"explanation":{"en":"Inference in AI refers to applying a trained model to new, unseen data to generate predictions or decisions,\nleveraging the patterns learned during training.","zh":"AI 中的推理是指将已训练的模型应用于新的、未见过的数据，以生成预测或决策，并利用训练期间学到的模式。"},"tip":{"zh":"训练是学模式，推理是用已训练模型对未见数据做预测，别搞混。","en":""},"keywords":["推理","预测","已训练模型"]},{"id":305,"type":"single","answer":["D"],"topic":"eval","stem":{"en":"A company wants to build an AI assistant to provide responses to user queries. The AI assistant must\nevaluate specific data sources, query external APIs, generate response options, and compare and\nprioritize response options.\nWhich Amazon Bedrock feature or resource will meet these requirements?","zh":"某公司想要构建一个 AI 助手来回复用户查询。该 AI 助手必须评估特定数据源、查询外部 API、生成回复选项，并对回复选项进行比较和优先级排序。哪种 Amazon Bedrock 功能或资源能满足这些要求？"},"options":[{"key":"A","en":"Prompt Management","zh":"Prompt Management"},{"key":"B","en":"Response streaming","zh":"Response streaming"},{"key":"C","en":"Knowledge Bases","zh":"Knowledge Bases"},{"key":"D","en":"Agents","zh":"Agents"}],"explanation":{"en":"Amazon Bedrock Agents enable AI assistants to interact with specific data sources, query external APIs,\ngenerate and compare response options, and prioritize results, making them the ideal feature for building\nadvanced, task-oriented chatbots with decision-making and orchestration capabilities.","zh":"Amazon Bedrock Agents 使 AI 助手能够与特定数据源交互、查询外部 API、生成并比较回复选项并对结果排优先级，是构建具备决策与编排能力的高级任务型聊天机器人的理想功能。"},"tip":{"zh":"要调外部 API、多步编排、比较方案就选 Agents；只查文档选知识库。","en":""},"keywords":["Agents","编排","外部 API"]},{"id":306,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"An AI practitioner notices a large language model (LLM) is generating different responses for the same\ninput across multiple invocations.\nWhich risk of AI does this describe?","zh":"某 AI 从业者发现，大型语言模型（LLM）在多次调用中对同一输入生成了不同的回复。这描述的是哪种 AI 风险？"},"options":[{"key":"A","en":"Hallucinations","zh":"幻觉"},{"key":"B","en":"Nondeterminism","zh":"不确定性（Nondeterminism）"},{"key":"C","en":"Accuracy","zh":"准确率"},{"key":"D","en":"Multimodality","zh":"多模态"}],"explanation":{"en":"Nondeterminism refers to the property where a large language model generates different responses for the\nsame input due to inherent randomness or stochasticity in the generation process. This can lead to varying\noutputs on multiple invocations with identical inputs.","zh":"不确定性（Nondeterminism）是指由于生成过程中固有的随机性，大型语言模型对同一输入生成不同回复的特性。这会导致在输入完全相同的情况下，多次调用产生不同的输出。"},"tip":{"zh":"同一输入多次调用却输出不同＝不确定性；编造不存在的事实才叫幻觉。","en":""},"keywords":["不确定性","随机性","同一输入"]},{"id":307,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"A company is building a generative AI application on AWS. The application will help improve reading\ncomprehension for students. The application must give students the ability to add illustrations to stories.\nWhich solution will meet this requirement?","zh":"某公司正在 AWS 上构建生成式 AI 应用。该应用将帮助学生提高阅读理解能力。该应用必须让学生能够为故事添加插图。哪种解决方案能满足此要求？"},"options":[{"key":"A","en":"Use Amazon Bedrock Stable Diffusion 3.5 Large to generate images based on text inputs.","zh":"使用 Amazon Bedrock Stable Diffusion 3.5 Large 根据文本输入生成图像。"},{"key":"B","en":"Use Amazon Polly to create an audiobook based on story texts.","zh":"使用 Amazon Polly 根据故事文本制作有声书。"},{"key":"C","en":"Use Amazon Rekognition to analyze image contents and detect text attributes.","zh":"使用 Amazon Rekognition 分析图像内容并检测文本属性。"},{"key":"D","en":"Create a standard prompt template. Use Amazon Q Business to illustrate stories.","zh":"创建标准提示模板。使用 Amazon Q Business 为故事配插图。"}],"explanation":{"en":"Amazon Bedrock Stable Diffusion 3.5 Large is a generative AI model designed to create high-quality\nimages from text prompts, allowing students to add custom illustrations to their stories and enhancing\nreading comprehension through visual aids.","zh":"Amazon Bedrock Stable Diffusion 3.5 Large 是专为根据文本提示创建高质量图像而设计的生成式 AI 模型，可让学生为自己的故事添加自定义插图，通过视觉辅助提升阅读理解。"},"tip":{"zh":"要生成图片就用文生图模型 Stable Diffusion；Rekognition 只做识别。","en":""},"keywords":["文生图","Stable Diffusion","插图"]},{"id":308,"type":"single","answer":["B"],"topic":"sagemaker","stem":{"en":"A healthcare company wants to analyze patient data. The data was gathered over the previous year to\ndetect patterns in disease outbreaks. The company needs to create a trend analysis report for each month\nto present to public health officials. The company must provide insights into patient data from the most\nrecent month of the current year.\nWhich inference method will meet these requirements MOST cost-effectively?","zh":"某医疗公司想要分析患者数据。这些数据是过去一年收集的，用于发现疾病暴发的模式。公司需要为每个月创建趋势分析报告，以提交给公共卫生官员。公司必须提供本年度最近一个月患者数据的洞察。哪种推理方法能以最具成本效益的方式满足这些要求？"},"options":[{"key":"A","en":"Real-time inference","zh":"实时推理"},{"key":"B","en":"Batch transform","zh":"批量转换"},{"key":"C","en":"Serverless inference","zh":"无服务器推理"},{"key":"D","en":"Asynchronous inference","zh":"异步推理"}],"explanation":{"en":"Batch transform is the most cost-effective inference method for analyzing large amounts of data collected\nover a period (such as monthly patient data). It allows you to process and generate reports on all historical\ndata in batches, rather than incurring the higher costs of real-time or serverless inference.","zh":"对于分析一段时间内收集的大量数据（例如每月的患者数据），批量转换是最具成本效益的推理方法。它允许以批处理方式处理全部历史数据并生成报告，而无需承担实时推理或无服务器推理的较高成本。"},"tip":{"zh":"大批量离线跑月度报告＝批量转换最省钱，实时和无服务器按调用更贵。","en":""},"keywords":["批量转换","成本效益","离线批处理"]},{"id":309,"type":"hotspot","answer":[],"topic":"general","stem":{"en":"Select and order the steps from the following list to correctly describe the ML lifecycle for a new custom\nmodel. Select each step one time.","zh":"请从下面的列表中选择并排序各步骤，以正确描述一个新自定义模型的 ML 生命周期。每个步骤只选一次。"},"options":[],"explanation":{"en":"","zh":""},"tip":{"zh":"这题考 ML 生命周期排序：数据收集→预处理→特征工程→训练→评估→部署。","en":""},"keywords":["ML 生命周期","步骤排序","特征工程"]},{"id":310,"type":"single","answer":["D"],"topic":"general","stem":{"en":"A company acquires International Organization for Standardization (ISO) accreditation to manage AI risks\nand to use AI responsibly.\nWhat does this accreditation reflect about the company?","zh":"某公司获得了国际标准化组织（ISO）认证，用于管理 AI 风险并负责任地使用 AI。该认证反映了公司的什么情况？"},"options":[{"key":"A","en":"All members of the company are ISO certified.","zh":"公司所有成员都通过了 ISO 认证。"},{"key":"B","en":"All AI systems that the company uses are ISO certified.","zh":"公司使用的所有 AI 系统都通过了 ISO 认证。"},{"key":"C","en":"All AI application team members are ISO certified.","zh":"所有 AI 应用团队成员都通过了 ISO 认证。"},{"key":"D","en":"The company’s development framework is ISO certified.","zh":"公司的开发框架通过了 ISO 认证。"}],"explanation":{"en":"ISO accreditation for managing AI risks means that the company’s development processes, controls, and\nframeworks for AI are certified to meet ISO standards. It does not certify individual employees or AI\nsystems, but rather the organizational framework and practices.","zh":"用于管理 AI 风险的 ISO 认证意味着公司的 AI 开发流程、控制措施和框架已通过认证，符合 ISO 标准。它认证的不是单个员工或 AI 系统，而是组织层面的框架与实践。"},"tip":{"zh":"ISO 认证的是公司的流程与开发框架，不是员工个人或某个 AI 系统。","en":""},"keywords":["ISO 认证","治理框架","AI 风险"]},{"id":311,"type":"hotspot","answer":[],"topic":"genai","stem":{"en":"Select the correct prompt engineering technique from the following list for each description. Select each\nprompt engineering technique one time or not at all.","zh":"请从下面的列表中为每个描述选择正确的提示工程技术。每种提示工程技术只选一次或不选。"},"options":[],"explanation":{"en":"Provide a small number of examples to the model to understand the desired task before generating\noutputs -> Few-shot prompting\nPrompt a model to break down the step-by-step process that the model took to arrive at a final answer ->\nChain-of-thought prompting\nPrompt a model to perform a task without providing examples -> Zero-shot prompting\nFew-shot prompting uses a few examples to guide the model’s outputs.\nChain-of-thought prompting asks the model to explain its reasoning step-by-step.\nZero-shot prompting asks the model to perform a task without any examples.","zh":"向模型提供少量示例，让其在生成输出前理解期望任务 → 少样本提示（Few-shot prompting）\n提示模型逐步拆解其得出最终答案的推理过程 → 思维链提示（Chain-of-thought prompting）\n在不提供示例的情况下提示模型执行任务 → 零样本提示（Zero-shot prompting）\n少样本提示用少量示例引导模型的输出。\n思维链提示要求模型逐步解释其推理过程。\n零样本提示要求模型在没有任何示例的情况下执行任务。"},"tip":{"zh":"给例子＝少样本，要推理步骤＝思维链，什么示例都不给＝零样本。","en":""},"keywords":["少样本提示","思维链","零样本提示"]},{"id":312,"type":"single","answer":["B"],"topic":"data","stem":{"en":"A company is developing an ML model to predict heart disease risk. The model uses patient data, such as\nage, cholesterol, blood pressure, smoking status, and exercise habits. The dataset includes a target value\nthat indicates whether a patient has heart disease.\nWhich ML technique will meet these requirements?","zh":"某公司正在开发一个预测心脏病风险的 ML 模型。该模型使用患者数据，例如年龄、胆固醇、血压、吸烟状况和运动习惯。数据集包含一个目标值，用于表示患者是否患有心脏病。哪种 ML 技术能满足这些要求？"},"options":[{"key":"A","en":"Unsupervised learning","zh":"无监督学习"},{"key":"B","en":"Supervised learning","zh":"监督式学习"},{"key":"C","en":"Reinforcement learning","zh":"强化学习"},{"key":"D","en":"Semi-supervised learning","zh":"半监督学习"}],"explanation":{"en":"Supervised learning is used when the dataset includes both input features (like age, cholesterol, blood\npressure, etc.) and a target value indicating the presence of heart disease. The model learns to predict the\ntarget value from labeled examples.","zh":"当数据集既包含输入特征（如年龄、胆固醇、血压等），又包含表示是否患有心脏病的目标值时，使用监督式学习。模型从带标签的示例中学习预测目标值。"},"tip":{"zh":"既有特征又有标签就选监督式学习；只有特征、没有标签才是无监督。","en":""},"keywords":["监督式学习","标签","分类"]},{"id":313,"type":"hotspot","answer":[],"topic":"genai","stem":{"en":"A company periodically updates its product database by manually uploading digital product guides. The\nproduct guides contain text and images. The company wants to automate this task by using generative AI.\nSelect and order the steps from the following list to automate the database update task by using\ngenerative AI. Select each step one time.","zh":"某公司定期手动上传数字产品指南来更新其产品数据库。产品指南包含文本和图像。公司希望使用生成式 AI 自动完成这项任务。请从下面的列表中选择并排序各步骤，以使用生成式 AI 自动完成数据库更新任务。每个步骤只选一次。"},"options":[],"explanation":{"en":"","zh":""},"tip":{"zh":"这题考文档自动化对应关系：S3 存储→Textract 抽取→Bedrock 生成→写库。","en":""},"keywords":["Textract","文档处理","流程排序"]},{"id":314,"type":"single","answer":["C"],"topic":"security","stem":{"en":"A company has guidelines for data storage and deletion.\nWhich data governance strategy does this describe?","zh":"某公司制定了数据存储和删除的准则。这描述的是哪种数据治理策略？"},"options":[{"key":"A","en":"Data de-identification","zh":"数据去标识化"},{"key":"B","en":"Data quality standards","zh":"数据质量标准"},{"key":"C","en":"Data retention","zh":"数据保留"},{"key":"D","en":"Log storage","zh":"日志存储"}],"explanation":{"en":"Data retention refers to the policies and practices that define how long data is stored and when it should\nbe deleted, ensuring compliance with organizational guidelines and regulatory requirements.","zh":"数据保留是指规定数据存储多长时间以及何时应删除的策略与实践，确保符合组织准则和监管要求。"},"tip":{"zh":"规定数据存多久、何时删除＝数据保留；去标识化是脱敏，不是删除。","en":""},"keywords":["数据保留","删除策略","合规"]},{"id":315,"type":"single","answer":["B"],"topic":"ops","stem":{"en":"A company needs to apply numerical transformations to a set of images to transpose and rotate the\nimages.\nWhich solution will meet these requirements in the MOST operationally efficient way?","zh":"某公司需要对一组图像应用数值变换，以对图像进行转置和旋转。哪种解决方案能以最高的运营效率满足这些要求？"},"options":[{"key":"A","en":"Create a deep neural network by using the images as input.","zh":"以这些图像作为输入创建深度神经网络。"},{"key":"B","en":"Create an AWS Lambda function to perform the transformations.","zh":"创建 AWS Lambda 函数来执行这些变换。"},{"key":"C","en":"Use an Amazon Bedrock large language model (LLM) with a high temperature.","zh":"使用高温度值的 Amazon Bedrock 大型语言模型（LLM）。"},{"key":"D","en":"Use AWS Glue Data Quality to make corrections to each image.","zh":"使用 AWS Glue Data Quality 对每张图像进行修正。"}],"explanation":{"en":"An AWS Lambda function can efficiently perform numerical image transformations such as transposing\nand rotating images at scale without the need to build or train a neural network, making it the most\noperationally efficient solution.","zh":"AWS Lambda 函数可以大规模高效地执行转置和旋转等数值图像变换，无需构建或训练神经网络，因此是运营效率最高的解决方案。"},"tip":{"zh":"确定性的图像转置旋转用 Lambda 跑代码最省事，别上神经网络或 LLM。","en":""},"keywords":["Lambda","图像变换","运营效率"]},{"id":316,"type":"single","answer":["C"],"topic":"services","stem":{"en":"An AI practitioner is writing software code. The AI practitioner wants to quickly develop a test case and\ncreate documentation for the code.\nWhich solution will meet these requirements with the LEAST effort?","zh":"某 AI 从业者正在编写软件代码。该从业者希望快速开发测试用例并为代码创建文档。哪种解决方案能以最少的工作量满足这些要求？"},"options":[{"key":"A","en":"Upload the code to an online coding assistant.","zh":"将代码上传到在线编码助手。"},{"key":"B","en":"Develop an application to use foundation models (FMs).","zh":"开发一个使用基础模型（FM）的应用程序。"},{"key":"C","en":"Use Amazon Q Developer in an integrated development environment (IDE).","zh":"在集成开发环境（IDE）中使用 Amazon Q Developer。"},{"key":"D","en":"Research and write test cases. Then, create test cases and add documentation.","zh":"研究并编写测试用例，然后创建测试用例并添加文档。"}],"explanation":{"en":"Amazon Q Developer integrated with an IDE can automatically generate test cases and create\ndocumentation for code, minimizing manual effort and accelerating development compared with building\ncustom solutions or manual research.","zh":"与 IDE 集成的 Amazon Q Developer 可以自动为代码生成测试用例并创建文档，与构建自定义解决方案或手动研究相比，可最大限度减少人工工作量并加速开发。"},"tip":{"zh":"IDE 里要自动生成测试用例和文档，就用 Amazon Q Developer。","en":""},"keywords":["Amazon Q Developer","测试用例","IDE"]},{"id":317,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"A company is developing a generative AI application to automatically generate product descriptions for an\necommerce website. The product descriptions must consist of paragraphs of text that are consistent in\nstyle and tone. The application must generate thousands of unique descriptions each day.\nWhich type of generative model will meet these requirements?","zh":"某公司正在开发一个生成式 AI 应用，为电商网站自动生成产品描述。产品描述必须由风格和语气一致的段落文本组成。该应用每天必须生成数千条独特的描述。哪种生成式模型能满足这些要求？"},"options":[{"key":"A","en":"A variational autoencoder (VAE) model","zh":"变分自编码器（VAE）模型"},{"key":"B","en":"A transformer-based model","zh":"基于 Transformer 的模型"},{"key":"C","en":"A diffusion model","zh":"扩散模型"},{"key":"D","en":"A generative adversarial network (GAN) model","zh":"生成对抗网络（GAN）模型"}],"explanation":{"en":"Transformer-based models, such as large language models, are designed to generate coherent and\ncontextually consistent text at scale. They are well-suited for creating thousands of unique, styled product\ndescriptions daily.","zh":"基于 Transformer 的模型（例如大型语言模型）旨在规模化生成连贯且上下文一致的文本，非常适合每天创建数千条风格统一的独特产品描述。"},"tip":{"zh":"长文本、风格统一、量大选 Transformer 系 LLM；扩散模型做图不做文。","en":""},"keywords":["Transformer","文本生成","一致性"]},{"id":318,"type":"single","answer":["D"],"topic":"eval","stem":{"en":"An AI practitioner has trained a model on a training dataset. The model performs well on the training data.\nHowever, the model does not perform well on evaluation data.\nWhat is the MOST likely cause of this issue?","zh":"某 AI 从业者在训练数据集上训练了一个模型。该模型在训练数据上表现良好，但在评估数据上表现不佳。造成此问题最可能的原因是什么？"},"options":[{"key":"A","en":"The model is underfit.","zh":"模型欠拟合。"},{"key":"B","en":"The model requires prompt engineering.","zh":"模型需要提示工程。"},{"key":"C","en":"The model is biased.","zh":"模型存在偏见。"},{"key":"D","en":"The model is overfit.","zh":"模型过拟合。"}],"explanation":{"en":"Overfitting occurs when a model learns the training data too well, including noise and details that do not\ngeneralize. As a result, it performs well on training data but poorly on unseen evaluation data.","zh":"当模型过度学习训练数据（包括无法泛化的噪声和细节）时，就会发生过拟合。结果是模型在训练数据上表现良好，但在未见过的评估数据上表现不佳。"},"tip":{"zh":"训练集表现好、评估集表现差＝过拟合；两边都差才是欠拟合。","en":""},"keywords":["过拟合","泛化","评估数据"]},{"id":319,"type":"single","answer":["B"],"topic":"responsible","stem":{"en":"A company wants to develop an interpretable ML model to assess the risk of loan applications.\nWhich type of ML model or algorithm will meet these requirements?","zh":"某公司想要开发一个可解释的 ML 模型来评估贷款申请的风险。哪种类型的 ML 模型或算法能满足这些要求？"},"options":[{"key":"A","en":"Deep learning model","zh":"深度学习模型"},{"key":"B","en":"Logistic regression model","zh":"逻辑回归模型"},{"key":"C","en":"K-means algorithm","zh":"K-means 算法"},{"key":"D","en":"Random cut forest algorithm","zh":"随机砍伐森林（Random Cut Forest）算法"}],"explanation":{"en":"Logistic regression is a simple, interpretable ML model that provides clear relationships between input\nfeatures and predicted outcomes. It is widely used for risk assessment tasks like loan applications, where\ntransparency and explainability are critical.","zh":"逻辑回归是一种简单、可解释的 ML 模型，能清晰呈现输入特征与预测结果之间的关系。它广泛用于贷款申请等风险评估任务，因为此类任务对透明度和可解释性要求很高。"},"tip":{"zh":"要可解释就选逻辑回归这类线性模型；深度学习和聚类说不清理由。","en":""},"keywords":["可解释性","逻辑回归","风险评估"]},{"id":320,"type":"single","answer":["B"],"topic":"security","stem":{"en":"A company stores customer personally identifiable information (PII) data. The company must store the PII\ndata within the company's AWS Region.\nWhich aspect of governance does this describe?","zh":"某公司存储客户的个人身份信息（PII）数据。公司必须将 PII 数据存储在公司所在的 AWS 区域内。这描述的是治理的哪个方面？"},"options":[{"key":"A","en":"Data mining","zh":"数据挖掘"},{"key":"B","en":"Data residency","zh":"数据驻留"},{"key":"C","en":"Pre-training bias","zh":"预训练偏见"},{"key":"D","en":"Geolocation routing","zh":"地理位置路由"}],"explanation":{"en":"Data residency refers to the requirement that data, such as PII, must remain within a specific geographic\nlocation or region, ensuring compliance with local regulations and governance policies.","zh":"数据驻留是指数据（例如 PII）必须保留在特定地理位置或区域内的要求，以确保符合当地法规和治理策略。"},"tip":{"zh":"数据必须留在指定区域＝数据驻留；地理位置路由只是流量调度。","en":""},"keywords":["数据驻留","PII","合规"]},{"id":321,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"A company wants to implement a generative AI solution to improve its marketing operations. The company\nwants to increase its revenue in the next 6 months.\nWhich approach will meet these requirements?","zh":"某公司想要实施生成式 AI 解决方案以改进其营销运营。公司希望在未来 6 个月内提高收入。哪种方法能满足这些要求？"},"options":[{"key":"A","en":"Immediately start training a custom FM by using the company's existing data.","zh":"立即使用公司现有数据开始训练自定义 FM。"},{"key":"B","en":"Conduct stakeholder interviews to refine use cases and set measurable goals.","zh":"开展利益相关者访谈，以细化用例并设定可衡量的目标。"},{"key":"C","en":"Implement a prebuilt AI assistant solution and measure its impact on customer satisfaction.","zh":"实施预构建的 AI 助手解决方案，并衡量其对客户满意度的影响。"},{"key":"D","en":"Analyze industry AI implementations and replicate the most successful features.","zh":"分析行业中的 AI 实施案例，并复制最成功的功能。"}],"explanation":{"en":"Using a prebuilt AI assistant allows the company to deploy generative AI quickly without the time and cost\nof training custom models. This accelerates implementation, enabling measurable business impact such\n\nas improved customer engagement and increased revenue within the short 6-month timeframe.","zh":"使用预构建的 AI 助手可以让公司在无需承担训练自定义模型的时间和成本的情况下快速部署生成式 AI。这加快了实施速度，从而在 6 个月的短周期内实现可衡量的业务影响，例如提升客户互动并增加收入。"},"tip":{"zh":"6 个月就要见效就别自训模型，用预构建 AI 助手最快落地。","en":""},"keywords":["预构建解决方案","快速上线","业务价值"]},{"id":322,"type":"single","answer":["B"],"topic":"data","stem":{"en":"A healthcare company wants to create a model to improve disease diagnostics by analyzing patient\nvoices. The company has recorded hundreds of patient voices for this project.\nThe company is currently filtering voice recordings according to duration and language.\nWhich phase of the ML lifecycle describes the current project phase?","zh":"某医疗公司想要创建一个模型，通过分析患者声音来改进疾病诊断。公司已为此项目录制了数百名患者的声音。公司目前正按时长和语言筛选录音。当前项目阶段属于 ML 生命周期的哪个阶段？"},"options":[{"key":"A","en":"Data collection","zh":"数据收集"},{"key":"B","en":"Data preprocessing","zh":"数据预处理"},{"key":"C","en":"Feature engineering","zh":"特征工程"},{"key":"D","en":"Model training","zh":"模型训练"}],"explanation":{"en":"Filtering voice recordings by duration and language is part of data preprocessing, where raw data is\ncleaned and prepared to ensure quality and consistency before moving to feature engineering and model\ntraining.","zh":"按时长和语言筛选录音属于数据预处理，即对原始数据进行清洗和整理，以确保在进入特征工程和模型训练之前的质量与一致性。"},"tip":{"zh":"筛选、清洗、格式化原始数据＝数据预处理；造特征才叫特征工程。","en":""},"keywords":["数据预处理","数据清洗","ML 生命周期"]},{"id":323,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"A company is using Amazon Bedrock to build an AI assistant. The AI assistant helps customers find\nrelevant products by making suggestions. However, the AI assistant's responses are often generic and\nirrelevant. The company wants to use prompt engineering to improve the AI assistant's responses.\nWhich solution will meet these requirements?","zh":"某公司使用 Amazon Bedrock 构建 AI 助手。该 AI 助手通过提供建议帮助客户找到相关产品。然而，AI 助手的回复往往笼统且不相关。公司希望使用提示工程来改进 AI 助手的回复。哪种解决方案能满足这些要求？"},"options":[{"key":"A","en":"Use few-shot prompting to add domain-specific context and explicit instructions.","zh":"使用少样本提示，加入领域特定的上下文和明确指令。"},{"key":"B","en":"Use chain-of-thought prompting with hidden reasoning steps to ignore explicit domain instructions.","zh":"使用带有隐藏推理步骤的思维链提示，忽略明确的领域指令。"},{"key":"C","en":"Modify the AI assistant's conversational style to use more formal language and include technical product specifications.","zh":"修改 AI 助手的对话风格，使用更正式的语言并加入技术产品规格。"},{"key":"D","en":"Use zero-shot prompting to augment retrieval from a product database.","zh":"使用零样本提示增强从产品数据库的检索。"}],"explanation":{"en":"Few-shot prompting provides the model with examples and domain-specific context, guiding it to generate\nmore accurate and relevant responses. This improves the quality of product suggestions compared to\ngeneric outputs.","zh":"少样本提示为模型提供示例和领域特定上下文，引导其生成更准确、更相关的回复。与笼统的输出相比，这能提升产品建议的质量。"},"tip":{"zh":"回复太笼统 → 少样本提示加领域示例和明确指令，最直接有效。","en":""},"keywords":["少样本提示","领域上下文","相关性"]},{"id":324,"type":"single","answer":["D"],"topic":"genai","stem":{"en":"A company runs a website for users to make travel reservations. The company wants an AI solution to\nhelp create consistent branding for hotels on the website.\nThe AI solution needs to generate hotel descriptions for the website in a consistent writing style.\nWhich AWS service will meet these requirements?","zh":"某公司运营一个供用户进行旅行预订的网站。公司希望有一个 AI 解决方案来帮助为网站上的酒店建立一致的品牌形象。该 AI 解决方案需要以一致的写作风格为网站生成酒店描述。哪种 AWS 服务能满足这些要求？"},"options":[{"key":"A","en":"Amazon Comprehend","zh":"Amazon Comprehend"},{"key":"B","en":"Amazon Personalize","zh":"Amazon Personalize"},{"key":"C","en":"Amazon Rekognition","zh":"Amazon Rekognition"},{"key":"D","en":"Amazon Bedrock","zh":"Amazon Bedrock"}],"explanation":{"en":"Amazon Bedrock provides access to foundation models for generative AI tasks such as creating text in a\nconsistent style. It is the correct service to generate hotel descriptions with uniform branding for the\nwebsite.","zh":"Amazon Bedrock 提供对基础模型的访问，可用于创建风格一致文本等生成式 AI 任务。它是在网站上生成具有统一品牌形象的酒店描述的正确服务。"},"tip":{"zh":"要生成文案就用 Bedrock 的 FM；Comprehend 分析文本、Personalize 做推荐。","en":""},"keywords":["Bedrock","文本生成","品牌一致性"]},{"id":325,"type":"single","answer":["C"],"topic":"genai","stem":{"en":"A company is using a pre-trained large language model (LLM). The LLM must perform multiple tasks that\nrequire specific domain knowledge. The LLM does not have information about several technical topics in\nthe domain. The company has unlabeled data that the company can use to fine-tune the model.\nWhich fine-tuning method will meet these requirements?","zh":"某公司正在使用一个预训练的大型语言模型（LLM）。该 LLM 必须执行多项需要特定领域知识的任务。该 LLM 不具备该领域中若干技术主题的信息。公司拥有可用于微调该模型的未标注数据。哪种微调方法能满足这些要求？"},"options":[{"key":"A","en":"Full training","zh":"全量训练"},{"key":"B","en":"Supervised fine-tuning","zh":"监督式微调"},{"key":"C","en":"Continued pre-training","zh":"持续预训练"},{"key":"D","en":"Retrieval Augmented Generation (RAG)","zh":"检索增强生成（RAG）"}],"explanation":{"en":"Continued pre-training uses the company’s unlabeled domain data to further train a pre-trained LLM,\nexpanding its knowledge in specific technical areas without requiring labeled datasets. This makes it the\nbest fit for the scenario.","zh":"持续预训练使用公司的未标注领域数据进一步训练预训练的 LLM，在无需标注数据集的情况下扩展其在特定技术领域的知识。这使其成为该场景的最佳选择。"},"tip":{"zh":"未标注数据＋补领域知识＝持续预训练；有标注配对才用监督式微调。","en":""},"keywords":["持续预训练","未标注数据","领域知识"]},{"id":326,"type":"single","answer":["B"],"topic":"data","stem":{"en":"A company wants to classify images of different objects based on custom features extracted from a\ndataset.\nWhich solution will meet this requirement with the LEAST development effort?","zh":"某公司想要根据从数据集中提取的自定义特征，对不同物体的图像进行分类。哪种解决方案能以最少的开发工作量满足此要求？"},"options":[{"key":"A","en":"Use traditional ML algorithms with custom features extracted from the dataset.","zh":"使用传统 ML 算法，并从数据集中提取自定义特征。"},{"key":"B","en":"Use a pre-trained deep learning model. Fine-tune the model on the dataset.","zh":"使用预训练的深度学习模型，并在数据集上微调该模型。"},{"key":"C","en":"Use a generative adversarial network (GAN) model to classify the images.","zh":"使用生成对抗网络（GAN）模型对图像进行分类。"},{"key":"D","en":"Use a support vector machine (SVM) with manually engineered features for classification.","zh":"使用支持向量机（SVM），配合人工构造的特征进行分类。"}],"explanation":{"en":"Fine-tuning a pre-trained deep learning model leverages transfer learning, reducing development effort\nbecause the model already captures general image features. Only minimal adjustments with the custom\ndataset are needed to achieve accurate classification.","zh":"微调预训练的深度学习模型可利用迁移学习，减少开发工作量，因为该模型已经掌握了通用的图像特征。只需用自定义数据集做少量调整，即可实现准确的分类。"},"tip":{"zh":"图像分类最省力＝预训练模型＋微调（迁移学习），别手工提特征。","en":""},"keywords":["迁移学习","微调","图像分类"]},{"id":327,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"A company wants to customize Amazon Bedrock foundation models (FMs) to improve an application's\nperformance. The company must prepare a training dataset for text-to-text model fine-tuning.\nWhich dataset format should the company use to train the models?","zh":"某公司想要自定义 Amazon Bedrock 基础模型（FM）以提升应用性能。公司必须为文本到文本模型的微调准备训练数据集。公司应使用哪种数据集格式来训练模型？"},"options":[{"key":"A","en":"A JSON file with labeled data","zh":"带标签数据的 JSON 文件"},{"key":"B","en":"A CSV file with unlabeled data","zh":"带未标注数据的 CSV 文件"},{"key":"C","en":"A CSV file with tabular data","zh":"带表格数据的 CSV 文件"},{"key":"D","en":"A text file with unlabeled data","zh":"带未标注数据的文本文件"}],"explanation":{"en":"","zh":""},"tip":{"zh":"Bedrock 微调只认带标签的 JSON（JSONL），prompt 与 completion 成对。","en":""},"keywords":["微调","JSON 数据集","带标签数据"]},{"id":328,"type":"hotspot","answer":[],"topic":"genai","stem":{"en":"A company wants to build generative AI applications by using Amazon Bedrock. The company wants to\nminimize development effort.\nSelect and order the model development techniques from the following list from the LEAST development\neffort to the MOST development effort. Each model development technique should be selected one time.","zh":"某公司想要使用 Amazon Bedrock 构建生成式 AI 应用。公司希望尽量减少开发工作量。请从下面的列表中选择并排序各模型开发技术，从开发工作量最少到最多。每种模型开发技术只选一次。"},"options":[],"explanation":{"en":"1. Prompt engineering\n2. Retrieval Augmented Generation (RAG)\n3. Fine-tuning\n4. Continued pre-training\nPrompt engineering requires minimal effort as it only involves designing effective prompts. RAG adds\nmoderate effort by integrating retrieval mechanisms with the model. Fine-tuning requires labeled data and\nretraining, demanding more resources. Continued pre-training is the most effort-intensive because it\ninvolves large-scale training with unlabeled domain data.","zh":"1. 提示工程\n2. 检索增强生成（RAG）\n3. 微调\n4. 持续预训练\n提示工程只需设计有效的提示，工作量最小。RAG 通过将检索机制与模型集成，增加了中等工作量。微调需要标注数据和重新训练，资源需求更高。持续预训练的工作量最大，因为它涉及使用未标注领域数据进行大规模训练。"},"tip":{"zh":"工作量从小到大：提示工程 < RAG < 微调 < 持续预训练。","en":""},"keywords":["模型定制","工作量排序","提示工程"]},{"id":329,"type":"single","answer":["A"],"topic":"genai","stem":{"en":"An airline company wants to use a generative AI model to convert a flight booking system from one coding\nlanguage into another coding language. The company must select a model for this task.\nWhich criteria should the company use to select the correct generative AI model for this task?","zh":"某航空公司想要使用生成式 AI 模型将航班预订系统从一种编程语言转换为另一种编程语言。公司必须为此任务选择一个模型。公司应使用什么标准来选择适合此任务的生成式 AI 模型？"},"options":[{"key":"A","en":"Syntax, semantic understanding, and code optimization capabilities","zh":"语法、语义理解以及代码优化能力"},{"key":"B","en":"Code generation speed and error handling capabilities","zh":"代码生成速度和错误处理能力"},{"key":"C","en":"Ability to generate creative content","zh":"生成创意内容的能力"},{"key":"D","en":"Model size and resource requirements","zh":"模型规模和资源需求"}],"explanation":{"en":"Converting code from one programming language to another requires a generative AI model that can\nunderstand both the syntax (rules of the language) and semantics (logic and meaning of the code). Code\noptimization ensures the translated code is efficient and functional in the target language.","zh":"将代码从一种编程语言转换为另一种语言，需要生成式 AI 模型既能理解语法（语言规则），又能理解语义（代码的逻辑与含义）。代码优化则确保转换后的代码在目标语言中高效且可运行。"},"tip":{"zh":"代码翻译要看得懂语法＋语义，还能优化代码，所以选 A。","en":""},"keywords":["代码转换","语义理解","模型选型"]},{"id":330,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"An AI practitioner is using Amazon Bedrock Prompt Management to create a reusable prompt. The prompt\nmust be able to interact with external services by calling an external API.\nWhich solution will meet this requirement?","zh":"某 AI 从业者正在使用 Amazon Bedrock Prompt Management 创建可复用的提示。该提示必须能够通过调用外部 API 与外部服务交互。哪种解决方案能满足此要求？"},"options":[{"key":"A","en":"Use special tokens.","zh":"使用特殊词元（special tokens）。"},{"key":"B","en":"Use a tools configuration.","zh":"使用工具（tools）配置。"},{"key":"C","en":"Use prompt variables.","zh":"使用提示变量。"},{"key":"D","en":"Use a stop sequence.","zh":"使用停止序列。"}],"explanation":{"en":"In Amazon Bedrock Prompt Management, a tools configuration allows prompts to call external APIs and\nservices. This enables the AI assistant to extend functionality beyond static responses and interact with\nexternal systems.","zh":"在 Amazon Bedrock Prompt Management 中，工具（tools）配置允许提示调用外部 API 和服务。这使 AI 助手能够将功能扩展到静态回复之外，并与外部系统交互。"},"tip":{"zh":"提示要调外部 API 就用 tools 配置；提示变量只做参数替换。","en":""},"keywords":["tools 配置","Prompt Management","外部 API"]},{"id":331,"type":"multi","answer":["A","E"],"topic":"security","stem":{"en":"A company wants to use Amazon Q Business for its data. The company needs to ensure the security and\nprivacy of the data.\nWhich combination of steps will meet these requirements? (Choose two.)","zh":"某公司想要为 Amazon Q Business 使用其数据。公司需要确保数据的安全性和隐私性。哪种步骤组合能满足这些要求？（选择两项。）"},"options":[{"key":"A","en":"Enable AWS Key Management Service (AWS KMS) keys for the Amazon Q Business Enterprise index.","zh":"为 Amazon Q Business Enterprise 索引启用 AWS Key Management Service（AWS KMS）密钥。"},{"key":"B","en":"Set up cross-account access to the Amazon Q index.","zh":"设置对 Amazon Q 索引的跨账户访问。"},{"key":"C","en":"Configure Amazon Inspector for authentication.","zh":"为身份验证配置 Amazon Inspector。"},{"key":"D","en":"Allow public access to the Amazon Q index.","zh":"允许对 Amazon Q 索引的公开访问。"},{"key":"E","en":"Configure AWS Identity and Access Management (IAM) for authentication.","zh":"为身份验证配置 AWS Identity and Access Management（IAM）。"}],"explanation":{"en":"Enabling AWS KMS keys ensures encryption of data at rest for the Amazon Q Business Enterprise index,\nprotecting sensitive data.\nConfiguring IAM provides secure authentication and access control, ensuring only authorized users and\napplications can access the data.","zh":"启用 AWS KMS 密钥可确保 Amazon Q Business Enterprise 索引的静态数据加密，保护敏感数据。\n配置 IAM 可提供安全的身份验证和访问控制，确保只有经过授权的用户和应用才能访问数据。"},"tip":{"zh":"Q Business 数据安全两手抓：KMS 加密静态数据＋IAM 做认证授权。","en":""},"keywords":["KMS","IAM","数据安全"]},{"id":332,"type":"single","answer":["B"],"topic":"eval","stem":{"en":"A company uses Amazon Comprehend to analyze customer feedback. A customer has several unique\ntrained models. The company uses Comprehend to assign each model an endpoint. The company wants\nto automate a report on each endpoint that is not used for more than 15 days.\nWhich service will meet these requirements?","zh":"某公司使用 Amazon Comprehend 分析客户反馈。某客户拥有若干独特的已训练模型。公司使用 Comprehend 为每个模型分配一个端点。公司希望自动生成一份关于超过 15 天未被使用的每个端点的报告。哪种服务能满足这些要求？"},"options":[{"key":"A","en":"AWS Trusted Advisor","zh":"AWS Trusted Advisor"},{"key":"B","en":"Amazon CloudWatch","zh":"Amazon CloudWatch"},{"key":"C","en":"AWS CloudTrail","zh":"AWS CloudTrail"},{"key":"D","en":"AWS Config","zh":"AWS Config"}],"explanation":{"en":"Amazon CloudWatch can monitor Amazon Comprehend endpoint metrics, such as invocations. By\ntracking usage and setting alarms or automated checks, it can generate reports for endpoints that have not\nbeen used in the last 15 days.","zh":"Amazon CloudWatch 可以监控 Amazon Comprehend 端点指标（例如调用次数）。通过跟踪使用情况并设置告警或自动检查，它可以为过去 15 天内未被使用的端点生成报告。"},"tip":{"zh":"要看指标、用量并触发告警＝CloudWatch；CloudTrail 只记 API 调用日志。","en":""},"keywords":["CloudWatch","端点监控","指标告警"]},{"id":333,"type":"single","answer":["D"],"topic":"genai","stem":{"en":"A company plans to use a generative AI model to provide real-time service quotes to users.\nWhich criteria should the company use to select the correct model for this use case?","zh":"某公司计划使用生成式 AI 模型向用户提供实时服务报价。公司应使用什么标准来选择适合此用例的模型？"},"options":[{"key":"A","en":"Model size","zh":"模型规模"},{"key":"B","en":"Training data quality","zh":"训练数据质量"},{"key":"C","en":"General-purpose use and high-powered GPU availability","zh":"通用用途及高功率 GPU 可用性"},{"key":"D","en":"Model latency and optimized inference speed","zh":"模型延迟和优化后的推理速度"}],"explanation":{"en":"For real-time service quotes, the critical requirement is low response time. A model with optimized\ninference speed and low latency ensures fast and efficient user interactions, making it the correct selection\ncriterion.","zh":"对于实时服务报价，关键要求是低响应时间。具有优化推理速度和低延迟的模型可确保快速、高效的用户交互，因此是正确的选择标准。"},"tip":{"zh":"实时场景看延迟和推理速度；模型规模大反而更慢，别选 A。","en":""},"keywords":["低延迟","实时推理","模型选型"]},{"id":334,"type":"single","answer":["B"],"topic":"genai","stem":{"en":"An AI practitioner must fine-tune an open source large language model (LLM) for text categorization. The\ndataset is already prepared.\nWhich solution will meet these requirements with the LEAST operational effort?","zh":"某 AI 从业者必须微调一个开源大型语言模型（LLM）用于文本分类。数据集已准备就绪。哪种解决方案能以最少的运营工作量满足这些要求？"},"options":[{"key":"A","en":"Create a custom model training job in PartyRock on Amazon Bedrock.","zh":"在 Amazon Bedrock 上的 PartyRock 中创建自定义模型训练作业。"},{"key":"B","en":"Use Amazon SageMaker JumpStart to create a training job.","zh":"使用 Amazon SageMaker JumpStart 创建训练作业。"},{"key":"C","en":"Use a custom script to run an Amazon SageMaker AI model training job.","zh":"使用自定义脚本运行 Amazon SageMaker AI 模型训练作业。"},{"key":"D","en":"Create a Jupyter notebook on an Amazon EC2 instance. Use the notebook to train the model.","zh":"在 Amazon EC2 实例上创建 Jupyter notebook，并使用该 notebook 训练模型。"}],"explanation":{"en":"SageMaker JumpStart provides prebuilt solutions and workflows for fine-tuning open source models with\nminimal setup. It reduces operational effort compared to custom scripts, EC2 notebooks, or PartyRock,\nmaking it the most efficient choice.","zh":"SageMaker JumpStart 提供预构建的解决方案和工作流，只需极少配置即可微调开源模型。与自定义脚本、EC2 notebook 或 PartyRock 相比，它减少了运营工作量，因此是最高效的选择。"},"tip":{"zh":"微调开源模型最省运维＝SageMaker JumpStart 开箱即用；PartyRock 不能训练。","en":""},"keywords":["SageMaker JumpStart","开源模型","微调"]}];
